{
  "name": "express-pg-users-api",
  "version": "1.0.0",
  "description": "Express REST API with PostgreSQL connection pooling and parameterised queries",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "node --watch app.js",
    "test": "node --test tests/queries.test.js"
  },
  "dependencies": {
    "dotenv": "^16.4.5",
    "express": "^4.19.2",
    "pg": "^8.12.0"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "license": "ISC"
}

/**
 * db.js — PostgreSQL connection pool
 *
 * Responsibilities
 * ─────────────────
 * • Creates a single shared pg.Pool for the entire process lifetime.
 * • Exposes a thin `query()` wrapper that:
 *     – always uses parameterised queries (no string interpolation)
 *     – measures and logs wall-clock query time
 *     – surfaces pg errors with context, without leaking credentials
 * • Exposes `getClient()` for multi-statement transactions.
 * • Provides `healthCheck()` for the /health endpoint.
 * • Provides `closePool()` for graceful shutdown.
 *
 * SQL-injection prevention strategy
 * ───────────────────────────────────
 * All dynamic values are passed as elements of the `params` array and
 * referenced as $1, $2 … in the query text. pg sends query text and
 * parameters to PostgreSQL over separate wire-protocol fields, so the
 * database engine NEVER concatenates them — making injection structurally
 * impossible regardless of what the parameter value contains.
 *
 * Connection-string credentials are read exclusively from environment
 * variables; this file contains no literal credentials.
 */

'use strict';

require('dotenv').config();
const { Pool } = require('pg');

// ─── Pool configuration ──────────────────────────────────────────────────────

if (!process.env.DATABASE_URL) {
  throw new Error(
    '[db] DATABASE_URL environment variable is not set. ' +
    'Copy .env.example to .env and fill in your credentials.'
  );
}

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Hard upper-bound on open sockets.  Tune via DB_POOL_MAX in .env.
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

  // Keep at least this many connections warm so the first requests after
  // idle periods don't pay a TCP + TLS + auth round-trip.
  min: parseInt(process.env.DB_POOL_MIN ?? '2', 10),

  // Release idle connections that have been unused for this long (ms).
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT_MS ?? '30000', 10),

  // Throw if a new client cannot be checked out within this window (ms).
  connectionTimeoutMillis: parseInt(
    process.env.DB_POOL_CONNECTION_TIMEOUT_MS ?? '5000', 10
  ),

  // Prevent runaway queries from hogging a connection (ms).
  // PostgreSQL aborts the query; the connection is returned to the pool.
  statement_timeout: parseInt(
    process.env.DB_POOL_STATEMENT_TIMEOUT_MS ?? '10000', 10
  ),

  // Always use UTC so timestamp arithmetic is unambiguous.
  options: '-c TimeZone=UTC',
});

// ─── Pool-level event hooks ───────────────────────────────────────────────────

pool.on('connect', (client) => {
  // client.processID is the pg backend PID — useful for pg_stat_activity.
  console.info(`[db] New client connected (pid=${client.processID}, ` +
               `total=${pool.totalCount}, idle=${pool.idleCount})`);
});

pool.on('acquire', () => {
  // Uncomment for verbose checkout tracing:
  // console.debug(`[db] Client acquired (waiting=${pool.waitingCount})`);
});

pool.on('remove', () => {
  console.info(`[db] Client removed (total=${pool.totalCount})`);
});

pool.on('error', (err, client) => {
  // An idle client encountered an unexpected error (e.g. the server restarted).
  // Log it but do NOT crash; pg will remove the broken client automatically.
  console.error('[db] Unexpected pool error on idle client:', err.message);
});

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Execute a single parameterised query and return the pg Result object.
 *
 * @param {string}  text    SQL string with $1 … $N placeholders.
 * @param {Array}   [params=[]]  Values bound to those placeholders.
 * @returns {Promise<import('pg').QueryResult>}
 *
 * @example
 *   const { rows } = await query(
 *     'SELECT id, name FROM users WHERE id = $1',
 *     [42]
 *   );
 */
async function query(text, params = []) {
  const start = process.hrtime.bigint();

  try {
    const result = await pool.query(text, params);

    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;
    console.info(
      `[db] query ok | ${durationMs.toFixed(2)} ms | rows=${result.rowCount} | ` +
      // Log the query template (no values) so credentials/PII stay out of logs.
      `sql="${text.replace(/\s+/g, ' ').trim()}"`
    );

    return result;
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;
    console.error(
      `[db] query error | ${durationMs.toFixed(2)} ms | ` +
      `code=${err.code} | sql="${text.replace(/\s+/g, ' ').trim()}" | ` +
      `message=${err.message}`
    );
    // Re-throw so callers can decide how to handle it (e.g. 404 vs 500).
    throw err;
  }
}

/**
 * Check out a dedicated client for a multi-statement transaction.
 * The caller MUST call client.release() — ideally in a finally block.
 *
 * @returns {Promise<import('pg').PoolClient>}
 *
 * @example
 *   const client = await getClient();
 *   try {
 *     await client.query('BEGIN');
 *     await client.query('UPDATE …', […]);
 *     await client.query('COMMIT');
 *   } catch (err) {
 *     await client.query('ROLLBACK');
 *     throw err;
 *   } finally {
 *     client.release();
 *   }
 */
async function getClient() {
  return pool.connect();
}

/**
 * Lightweight connectivity check — used by GET /health.
 * Returns the server clock so we also verify the query round-trip.
 *
 * @returns {Promise<{ healthy: boolean, serverTime: string, latencyMs: number }>}
 */
async function healthCheck() {
  const start = process.hrtime.bigint();
  const { rows } = await pool.query('SELECT NOW() AS server_time');
  const latencyMs = Number(process.hrtime.bigint() - start) / 1_000_000;
  return {
    healthy: true,
    serverTime: rows[0].server_time,
    latencyMs: parseFloat(latencyMs.toFixed(2)),
  };
}

/**
 * Drain the pool.  Call during SIGTERM/SIGINT for a clean shutdown.
 *
 * @returns {Promise<void>}
 */
async function closePool() {
  console.info('[db] Draining connection pool…');
  await pool.end();
  console.info('[db] Pool closed.');
}

// ─── Pool stats helper (used in /health) ─────────────────────────────────────

/**
 * Return a snapshot of current pool counters.
 * @returns {{ total: number, idle: number, waiting: number }}
 */
function poolStats() {
  return {
    total:   pool.totalCount,
    idle:    pool.idleCount,
    waiting: pool.waitingCount,
  };
}

module.exports = { query, getClient, healthCheck, closePool, poolStats };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Every public function:
 *   • Passes ALL dynamic values as bound parameters ($1, $2 …), never
 *     as string interpolation — structural SQL-injection prevention.
 *   • Validates and sanitises inputs before building the query so that
 *     even the structural parts of the SQL (ORDER BY column, direction)
 *     are chosen from an explicit allow-list, not from raw user input.
 *   • Returns plain objects (no pg internals) for clean API responses.
 *
 * Functions
 * ──────────
 *   getUserById(id)                  → single user or null
 *   getAllUsers(limit, offset)        → { users, pagination }
 *   searchUsers(searchQuery, limit, offset) → { users, pagination, searchQuery }
 */

'use strict';

const { query } = require('./db');

// ─── Constants & allow-lists ─────────────────────────────────────────────────

/** Columns callers are permitted to request in an ORDER BY clause. */
const ALLOWED_SORT_COLUMNS = new Set(['id', 'name', 'email', 'created_at']);

/** Sort directions. */
const ALLOWED_SORT_DIRECTIONS = new Set(['ASC', 'DESC']);

/** Maximum rows returnable in a single request (caps the limit param). */
const MAX_LIMIT = 100;

/** Default page size. */
const DEFAULT_LIMIT = 20;

// ─── Input validators / sanitisers ───────────────────────────────────────────

/**
 * Parse and validate a numeric identifier.
 * Throws a typed ValidationError if the value is unusable.
 *
 * @param {*}      value
 * @param {string} fieldName  Used in error messages only.
 * @returns {number}
 */
function parseId(value, fieldName = 'id') {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 1) {
    const err = new Error(`"${fieldName}" must be a positive integer, got: ${value}`);
    err.code  = 'VALIDATION_ERROR';
    err.field = fieldName;
    throw err;
  }
  return n;
}

/**
 * Parse and clamp a pagination limit.
 * Always returns a value between 1 and MAX_LIMIT.
 *
 * @param {*} value
 * @returns {number}
 */
function parseLimit(value) {
  const n = parseInt(value, 10);
  if (Number.isNaN(n) || n < 1) return DEFAULT_LIMIT;
  return Math.min(n, MAX_LIMIT);
}

/**
 * Parse a pagination offset.
 * Always returns a value ≥ 0.
 *
 * @param {*} value
 * @returns {number}
 */
function parseOffset(value) {
  const n = parseInt(value, 10);
  return Number.isNaN(n) || n < 0 ? 0 : n;
}

/**
 * Validate a sort column against the allow-list.
 * Falls back to 'id' for any unrecognised input — never passes raw input to SQL.
 *
 * @param {string} col
 * @returns {string}  A safe, quoted identifier.
 */
function parseSortColumn(col) {
  const normalised = String(col ?? 'id').toLowerCase().trim();
  // Return the exact string from our allow-list so the caller can safely
  // interpolate it into the query template (it never came from user input).
  return ALLOWED_SORT_COLUMNS.has(normalised) ? normalised : 'id';
}

/**
 * Validate a sort direction.
 * Falls back to 'ASC' for any unrecognised input.
 *
 * @param {string} dir
 * @returns {'ASC'|'DESC'}
 */
function parseSortDirection(dir) {
  const normalised = String(dir ?? 'ASC').toUpperCase().trim();
  return ALLOWED_SORT_DIRECTIONS.has(normalised) ? normalised : 'ASC';
}

/**
 * Trim and cap a free-text search string.
 * Returns null when nothing meaningful was supplied.
 *
 * @param {*}      value
 * @param {number} [maxLength=200]
 * @returns {string|null}
 */
function parseSearchQuery(value, maxLength = 200) {
  if (value == null) return null;
  const trimmed = String(value).trim().slice(0, maxLength);
  return trimmed.length > 0 ? trimmed : null;
}

// ─── Column selector ─────────────────────────────────────────────────────────
// Never SELECT *; always name columns so schema changes don't silently leak
// new sensitive fields (e.g. password_hash) into API responses.

const USER_COLUMNS = 'id, name, email, created_at, updated_at';

// ─── Query functions ──────────────────────────────────────────────────────────

/**
 * Fetch a single user by primary-key id.
 *
 * @param {number|string} id  The user's numeric id.
 * @returns {Promise<object|null>}  The user row, or null if not found.
 *
 * @throws {ValidationError}  If id is not a positive integer.
 * @throws {Error}            On database errors.
 *
 * @example
 *   const user = await getUserById(7);
 *   if (!user) return res.status(404).json({ error: 'User not found' });
 */
async function getUserById(id) {
  const safeId = parseId(id, 'id');

  const sql = `
    SELECT ${USER_COLUMNS}
    FROM   users
    WHERE  id = $1
    LIMIT  1
  `;

  const { rows } = await query(sql, [safeId]);
  return rows[0] ?? null;
}

/**
 * Retrieve a paginated list of all users.
 *
 * @param {number|string} [limit=20]   Max rows to return (1–100).
 * @param {number|string} [offset=0]   Row offset for pagination.
 * @param {string}        [sortBy='id']    Column to sort by.
 * @param {string}        [sortDir='ASC']  'ASC' or 'DESC'.
 * @returns {Promise<{ users: object[], pagination: object }>}
 *
 * @example
 *   // GET /users?limit=10&offset=20
 *   const result = await getAllUsers(10, 20);
 *   // result.pagination → { limit, offset, total, hasNextPage, hasPrevPage }
 */
async function getAllUsers(limit, offset, sortBy = 'id', sortDir = 'ASC') {
  const safeLimit  = parseLimit(limit);
  const safeOffset = parseOffset(offset);

  // sortBy and sortDir come from our allow-lists — safe to interpolate as
  // SQL identifiers.  They are NEVER derived directly from raw user input.
  const safeColumn = parseSortColumn(sortBy);
  const safeDir    = parseSortDirection(sortDir);

  // Run the data query and a COUNT in parallel for efficiency.
  const dataSql = `
    SELECT   ${USER_COLUMNS}
    FROM     users
    ORDER BY ${safeColumn} ${safeDir}
    LIMIT    $1
    OFFSET   $2
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM   users
  `;

  const [dataResult, countResult] = await Promise.all([
    query(dataSql,  [safeLimit, safeOffset]),
    query(countSql, []),
  ]);

  const total = parseInt(countResult.rows[0].total, 10);

  return {
    users: dataResult.rows,
    pagination: {
      limit:       safeLimit,
      offset:      safeOffset,
      total,
      hasNextPage: safeOffset + safeLimit < total,
      hasPrevPage: safeOffset > 0,
    },
  };
}

/**
 * Full-text search across user name and email.
 *
 * Uses PostgreSQL's ILIKE with `%term%` for case-insensitive substring
 * matching.  The search term is passed as a bound parameter — pg sends
 * it as a separate wire-protocol value so the database treats it purely
 * as data, preventing SQL injection even if it contains %, _, or quotes.
 *
 * For production-scale tables, consider replacing ILIKE with a GIN index
 * on a tsvector column or pg_trgm for better performance.
 *
 * @param {string}        searchQuery     The search term (trimmed, capped at 200 chars).
 * @param {number|string} [limit=20]      Max rows to return (1–100).
 * @param {number|string} [offset=0]      Row offset for pagination.
 * @param {string}        [sortBy='name'] Column to sort by.
 * @param {string}        [sortDir='ASC'] 'ASC' or 'DESC'.
 * @returns {Promise<{ users: object[], pagination: object, searchQuery: string }>}
 *
 * @throws {ValidationError}  If searchQuery is empty after trimming.
 *
 * @example
 *   // GET /users/search?q=alice&limit=5
 *   const result = await searchUsers('alice', 5, 0);
 */
async function searchUsers(searchQuery, limit, offset, sortBy = 'name', sortDir = 'ASC') {
  const safeQuery = parseSearchQuery(searchQuery);

  if (!safeQuery) {
    const err = new Error('"query" must be a non-empty string');
    err.code  = 'VALIDATION_ERROR';
    err.field = 'query';
    throw err;
  }

  const safeLimit  = parseLimit(limit);
  const safeOffset = parseOffset(offset);
  const safeColumn = parseSortColumn(sortBy);
  const safeDir    = parseSortDirection(sortDir);

  // The wildcard characters are appended server-side, not client-side,
  // so a user supplying "%%" still just searches for the literal string "%%".
  const likePattern = `%${safeQuery}%`;

  const dataSql = `
    SELECT   ${USER_COLUMNS}
    FROM     users
    WHERE    name  ILIKE $1
          OR email ILIKE $1
    ORDER BY ${safeColumn} ${safeDir}
    LIMIT    $2
    OFFSET   $3
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM   users
    WHERE  name  ILIKE $1
        OR email ILIKE $1
  `;

  const [dataResult, countResult] = await Promise.all([
    query(dataSql,  [likePattern, safeLimit, safeOffset]),
    query(countSql, [likePattern]),
  ]);

  const total = parseInt(countResult.rows[0].total, 10);

  return {
    users:       dataResult.rows,
    searchQuery: safeQuery,
    pagination: {
      limit:       safeLimit,
      offset:      safeOffset,
      total,
      hasNextPage: safeOffset + safeLimit < total,
      hasPrevPage: safeOffset > 0,
    },
  };
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Export helpers so tests can validate sanitisation logic independently.
  _parseId:          parseId,
  _parseLimit:       parseLimit,
  _parseOffset:      parseOffset,
  _parseSortColumn:  parseSortColumn,
  _parseSortDir:     parseSortDirection,
  _parseSearchQuery: parseSearchQuery,
};

/**
 * app.js — Express application
 *
 * Routes
 * ──────
 *   GET /health               — liveness + DB connectivity check
 *   GET /users                — paginated user list
 *   GET /users/search         — search users by name/email
 *   GET /users/:id            — single user by id
 *
 * All database access goes through queries.js which enforces:
 *   • Parameterised queries (SQL injection prevention)
 *   • Input validation + safe defaults
 *   • Per-query wall-clock timing logs (via db.js)
 */

'use strict';

require('dotenv').config();

const express = require('express');
const { healthCheck, poolStats, closePool } = require('./db');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

const app  = express();
const PORT = parseInt(process.env.PORT ?? '3000', 10);

// ─── Middleware ───────────────────────────────────────────────────────────────

app.use(express.json());

/** Attach a high-resolution request timer so handlers can log total latency. */
app.use((req, _res, next) => {
  req._startedAt = process.hrtime.bigint();
  next();
});

/** Structured access log on response finish. */
app.use((req, res, next) => {
  res.on('finish', () => {
    const ms = Number(process.hrtime.bigint() - req._startedAt) / 1_000_000;
    console.info(
      `[http] ${req.method} ${req.originalUrl} → ${res.statusCode} ` +
      `(${ms.toFixed(2)} ms)`
    );
  });
  next();
});

// ─── Error helper ─────────────────────────────────────────────────────────────

/**
 * Send a consistent error envelope.
 * Never forwards raw pg error internals to clients.
 *
 * @param {import('express').Response} res
 * @param {number} statusCode
 * @param {string} message
 * @param {string} [detail]
 */
function sendError(res, statusCode, message, detail) {
  const body = { error: message };
  if (detail) body.detail = detail;
  res.status(statusCode).json(body);
}

// ─── Routes ───────────────────────────────────────────────────────────────────

/**
 * GET /health
 *
 * Returns application liveness plus a live DB round-trip check so the
 * health probe can distinguish "app up, DB down" from fully healthy.
 *
 * Response 200:
 *   { status, timestamp, database: { healthy, serverTime, latencyMs }, pool }
 * Response 503:
 *   { status, timestamp, database: { healthy, error } }
 */
app.get('/health', async (_req, res) => {
  const timestamp = new Date().toISOString();

  try {
    const [dbHealth, pool] = await Promise.all([healthCheck(), Promise.resolve(poolStats())]);
    res.json({
      status:    'ok',
      timestamp,
      database:  dbHealth,
      pool,
    });
  } catch (err) {
    console.error('[health] DB health check failed:', err.message);
    res.status(503).json({
      status:    'degraded',
      timestamp,
      database:  { healthy: false, error: 'Database unavailable' },
    });
  }
});

/**
 * GET /users
 *
 * Query parameters (all optional):
 *   limit   {number}  Rows per page (1–100, default 20)
 *   offset  {number}  Row offset    (default 0)
 *   sortBy  {string}  Column name — id | name | email | created_at  (default id)
 *   sortDir {string}  ASC | DESC  (default ASC)
 *
 * Response 200:
 *   { users: User[], pagination: { limit, offset, total, hasNextPage, hasPrevPage } }
 */
app.get('/users', async (req, res) => {
  try {
    const { limit, offset, sortBy, sortDir } = req.query;
    const result = await getAllUsers(limit, offset, sortBy, sortDir);
    res.json(result);
  } catch (err) {
    console.error('[GET /users] error:', err.message);
    sendError(res, 500, 'Failed to retrieve users');
  }
});

/**
 * GET /users/search
 *
 * Query parameters:
 *   q       {string}  REQUIRED — search term (matched against name and email)
 *   limit   {number}  Rows per page (1–100, default 20)
 *   offset  {number}  Row offset    (default 0)
 *   sortBy  {string}  id | name | email | created_at  (default name)
 *   sortDir {string}  ASC | DESC  (default ASC)
 *
 * Response 200:
 *   { users: User[], searchQuery: string, pagination: { … } }
 * Response 400:
 *   { error, detail }  — missing or empty search term
 */
app.get('/users/search', async (req, res) => {
  try {
    const { q, limit, offset, sortBy, sortDir } = req.query;
    const result = await searchUsers(q, limit, offset, sortBy, sortDir);
    res.json(result);
  } catch (err) {
    if (err.code === 'VALIDATION_ERROR') {
      return sendError(res, 400, 'Invalid search parameters', err.message);
    }
    console.error('[GET /users/search] error:', err.message);
    sendError(res, 500, 'Failed to search users');
  }
});

/**
 * GET /users/:id
 *
 * Path parameter:
 *   id  {number}  Positive integer user id
 *
 * Response 200:  { id, name, email, created_at, updated_at }
 * Response 400:  { error, detail }  — non-integer id
 * Response 404:  { error }          — no user with that id
 */
app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return sendError(res, 404, 'User not found');
    }

    res.json(user);
  } catch (err) {
    if (err.code === 'VALIDATION_ERROR') {
      return sendError(res, 400, 'Invalid user id', err.message);
    }
    console.error(`[GET /users/:id] error for id="${req.params.id}":`, err.message);
    sendError(res, 500, 'Failed to retrieve user');
  }
});

// ─── 404 catch-all ────────────────────────────────────────────────────────────

app.use((req, res) => {
  sendError(res, 404, `Route not found: ${req.method} ${req.path}`);
});

// ─── Global error handler ────────────────────────────────────────────────────

// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  console.error('[app] Unhandled error:', err);
  sendError(res, 500, 'Internal server error');
});

// ─── Graceful shutdown ────────────────────────────────────────────────────────

async function shutdown(signal) {
  console.info(`\n[app] ${signal} received — shutting down gracefully…`);
  try {
    await closePool();
    console.info('[app] Clean exit.');
    process.exit(0);
  } catch (err) {
    console.error('[app] Error during shutdown:', err.message);
    process.exit(1);
  }
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ─── Start ────────────────────────────────────────────────────────────────────

if (require.main === module) {
  app.listen(PORT, () => {
    console.info(`[app] Server running on port ${PORT} (${process.env.NODE_ENV ?? 'development'})`);
  });
}

module.exports = app;

/**
 * tests/queries.test.js
 *
 * Unit tests for queries.js using Node's built-in test runner (node:test).
 * The PostgreSQL pool (db.js) is fully mocked so no live database is needed.
 *
 * Run:  node --test tests/queries.test.js
 */

'use strict';

const { describe, it, before, after, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const { mock } = require('node:test');

// ─── Mock db.js before requiring queries.js ──────────────────────────────────
// We intercept require('pg') entirely by pre-populating require.cache with a
// stub, then do the same for db.js so queries.js gets our controlled `query`.

// 1. Stub pg so db.js never opens a real connection.
const pgStub = {
  Pool: class {
    constructor() {}
    on() {}
    query() { return Promise.resolve({ rows: [], rowCount: 0 }); }
    connect() { return Promise.resolve({}); }
    end() { return Promise.resolve(); }
    get totalCount() { return 0; }
    get idleCount()  { return 0; }
    get waitingCount(){ return 0; }
  },
};
require.cache[require.resolve('pg')] = { id: 'pg', filename: 'pg', loaded: true, exports: pgStub };

// 2. Stub dotenv so no .env file is required.
const dotenvStub = { config: () => {} };
require.cache[require.resolve('dotenv')] = {
  id: 'dotenv', filename: 'dotenv', loaded: true, exports: dotenvStub,
};

// 3. Set the env variable db.js checks before loading.
process.env.DATABASE_URL = 'postgres://test:test@localhost:5432/test';

// 4. Load db.js (it will use our pg stub).
const dbPath = require.resolve('../db');
const db = require(dbPath);

// 5. Expose a controllable mock handle on db.query so individual tests can
//    direct what the database "returns".
let mockQueryImpl = async () => ({ rows: [], rowCount: 0 });

const dbModule = require.cache[dbPath];
dbModule.exports.query = async (text, params) => mockQueryImpl(text, params);

// 6. Now load queries.js — it will pick up the mock db.
const {
  getUserById,
  getAllUsers,
  searchUsers,
  _parseId,
  _parseLimit,
  _parseOffset,
  _parseSortColumn,
  _parseSortDir,
  _parseSearchQuery,
} = require('../queries');

// ─── Helpers ─────────────────────────────────────────────────────────────────

/** Captured calls to mockQueryImpl in a single test. */
let queryCalls = [];

/** Set up mockQueryImpl to record calls and return predetermined results. */
function setupMock(responses) {
  queryCalls = [];
  let callIndex = 0;
  mockQueryImpl = async (text, params) => {
    queryCalls.push({ text: text.replace(/\s+/g, ' ').trim(), params });
    const resp = Array.isArray(responses) ? responses[callIndex++] : responses;
    if (resp instanceof Error) throw resp;
    return resp ?? { rows: [], rowCount: 0 };
  };
}

// ─── Tests ────────────────────────────────────────────────────────────────────

describe('Input sanitiser helpers', () => {

  describe('_parseId', () => {
    it('accepts valid positive integers', () => {
      assert.equal(_parseId(1),   1);
      assert.equal(_parseId('5'), 5);
      assert.equal(_parseId(999), 999);
    });

    it('rejects zero', () => {
      assert.throws(() => _parseId(0),   { code: 'VALIDATION_ERROR' });
    });

    it('rejects negative numbers', () => {
      assert.throws(() => _parseId(-1),  { code: 'VALIDATION_ERROR' });
    });

    it('rejects non-numeric strings — SQL injection attempts', () => {
      assert.throws(() => _parseId("1; DROP TABLE users; --"), { code: 'VALIDATION_ERROR' });
      assert.throws(() => _parseId("' OR '1'='1"),             { code: 'VALIDATION_ERROR' });
      assert.throws(() => _parseId('abc'),                     { code: 'VALIDATION_ERROR' });
    });

    it('rejects floats', () => {
      assert.throws(() => _parseId(1.5), { code: 'VALIDATION_ERROR' });
    });
  });

  describe('_parseLimit', () => {
    it('returns default when input is absent', () => {
      assert.equal(_parseLimit(undefined), 20);
      assert.equal(_parseLimit(null),      20);
    });

    it('clamps to MAX_LIMIT (100)', () => {
      assert.equal(_parseLimit(9999),  100);
      assert.equal(_parseLimit('500'), 100);
    });

    it('returns default for non-numeric or zero/negative', () => {
      assert.equal(_parseLimit('abc'), 20);
      assert.equal(_parseLimit(0),     20);
      assert.equal(_parseLimit(-5),    20);
    });

    it('accepts valid numbers', () => {
      assert.equal(_parseLimit(10),   10);
      assert.equal(_parseLimit('50'), 50);
    });
  });

  describe('_parseOffset', () => {
    it('defaults to 0 for absent input', () => {
      assert.equal(_parseOffset(undefined), 0);
    });

    it('returns 0 for negative values', () => {
      assert.equal(_parseOffset(-100), 0);
    });

    it('accepts valid offsets', () => {
      assert.equal(_parseOffset(40), 40);
    });
  });

  describe('_parseSortColumn', () => {
    it('allows id, name, email, created_at', () => {
      assert.equal(_parseSortColumn('id'),         'id');
      assert.equal(_parseSortColumn('name'),       'name');
      assert.equal(_parseSortColumn('email'),      'email');
      assert.equal(_parseSortColumn('created_at'), 'created_at');
    });

    it('falls back to "id" for unrecognised or dangerous input', () => {
      assert.equal(_parseSortColumn('password_hash'),     'id');
      assert.equal(_parseSortColumn('id; DROP TABLE--'),  'id');
      assert.equal(_parseSortColumn("' OR '1'='1"),       'id');
      assert.equal(_parseSortColumn(''),                  'id');
      assert.equal(_parseSortColumn(undefined),           'id');
    });
  });

  describe('_parseSortDir', () => {
    it('allows ASC and DESC (case-insensitive)', () => {
      assert.equal(_parseSortDir('ASC'),  'ASC');
      assert.equal(_parseSortDir('desc'), 'DESC');
      assert.equal(_parseSortDir('Asc'),  'ASC');
    });

    it('falls back to ASC for unknown input', () => {
      assert.equal(_parseSortDir('SIDEWAYS'), 'ASC');
      assert.equal(_parseSortDir(undefined),  'ASC');
      assert.equal(_parseSortDir('; DROP TABLE users--'), 'ASC');
    });
  });

  describe('_parseSearchQuery', () => {
    it('trims whitespace', () => {
      assert.equal(_parseSearchQuery('  alice  '), 'alice');
    });

    it('returns null for empty / whitespace-only string', () => {
      assert.equal(_parseSearchQuery(''),    null);
      assert.equal(_parseSearchQuery('   '), null);
      assert.equal(_parseSearchQuery(null),  null);
    });

    it('truncates to maxLength', () => {
      const long = 'a'.repeat(500);
      assert.equal(_parseSearchQuery(long, 10).length, 10);
    });
  });
});

// ─── getUserById ─────────────────────────────────────────────────────────────

describe('getUserById', () => {
  const fakeUser = { id: 7, name: 'Alice', email: 'alice@example.com',
                     created_at: new Date(), updated_at: new Date() };

  it('returns the user when found', async () => {
    setupMock({ rows: [fakeUser], rowCount: 1 });
    const user = await getUserById(7);
    assert.deepEqual(user, fakeUser);
  });

  it('returns null when no rows match', async () => {
    setupMock({ rows: [], rowCount: 0 });
    const user = await getUserById(99);
    assert.equal(user, null);
  });

  it('passes id as a bound parameter (not interpolated)', async () => {
    setupMock({ rows: [fakeUser], rowCount: 1 });
    await getUserById(7);
    const call = queryCalls[0];
    // The SQL must contain $1, not the literal number 7.
    assert.match(call.text, /\$1/);
    assert.deepEqual(call.params, [7]);
  });

  it('throws VALIDATION_ERROR for a non-integer id', async () => {
    await assert.rejects(
      () => getUserById("'; DROP TABLE users; --"),
      { code: 'VALIDATION_ERROR' }
    );
  });

  it('throws VALIDATION_ERROR for id = 0', async () => {
    await assert.rejects(() => getUserById(0), { code: 'VALIDATION_ERROR' });
  });

  it('propagates database errors', async () => {
    const dbErr = Object.assign(new Error('connection refused'), { code: '08006' });
    setupMock(dbErr);
    await assert.rejects(() => getUserById(1), { message: 'connection refused' });
  });
});

// ─── getAllUsers ──────────────────────────────────────────────────────────────

describe('getAllUsers', () => {
  const fakeRows = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  it('returns users and pagination metadata', async () => {
    setupMock([
      { rows: fakeRows, rowCount: 2 },   // data query
      { rows: [{ total: '42' }], rowCount: 1 }, // count query
    ]);

    const result = await getAllUsers(2, 0);
    assert.deepEqual(result.users, fakeRows);
    assert.equal(result.pagination.total,       42);
    assert.equal(result.pagination.limit,        2);
    assert.equal(result.pagination.offset,       0);
    assert.equal(result.pagination.hasNextPage,  true);
    assert.equal(result.pagination.hasPrevPage,  false);
  });

  it('passes limit and offset as bound parameters', async () => {
    setupMock([
      { rows: [], rowCount: 0 },
      { rows: [{ total: '0' }], rowCount: 1 },
    ]);

    await getAllUsers(10, 30);
    const dataCall = queryCalls[0];
    assert.deepEqual(dataCall.params, [10, 30]);
    assert.match(dataCall.text, /\$1/);
    assert.match(dataCall.text, /\$2/);
  });

  it('clamps limit to 100', async () => {
    setupMock([
      { rows: [], rowCount: 0 },
      { rows: [{ total: '0' }], rowCount: 1 },
    ]);

    await getAllUsers(9999, 0);
    assert.equal(queryCalls[0].params[0], 100);
  });

  it('defaults offset to 0 when omitted', async () => {
    setupMock([
      { rows: [], rowCount: 0 },
      { rows: [{ total: '0' }], rowCount: 1 },
    ]);

    await getAllUsers(10);
    assert.equal(queryCalls[0].params[1], 0);
  });

  it('uses "id" as fallback for unrecognised sortBy', async () => {
    setupMock([
      { rows: [], rowCount: 0 },
      { rows: [{ total: '0' }], rowCount: 1 },
    ]);

    await getAllUsers(10, 0, "'; DROP TABLE users; --", 'ASC');
    // The SQL should contain ORDER BY id (safe column), not the injection string.
    assert.match(queryCalls[0].text, /ORDER BY id ASC/i);
  });

  it('hasPrevPage is true when offset > 0', async () => {
    setupMock([
      { rows: fakeRows, rowCount: 2 },
      { rows: [{ total: '100' }], rowCount: 1 },
    ]);

    const result = await getAllUsers(10, 20);
    assert.equal(result.pagination.hasPrevPage, true);
  });

  it('hasNextPage is false on the last page', async () => {
    setupMock([
      { rows: fakeRows, rowCount: 2 },
      { rows: [{ total: '22' }], rowCount: 1 },
    ]);

    const result = await getAllUsers(10, 20);
    // offset(20) + limit(10) = 30 > total(22) → no next page
    assert.equal(result.pagination.hasNextPage, false);
  });
});

// ─── searchUsers ─────────────────────────────────────────────────────────────

describe('searchUsers', () => {
  const fakeRows = [{ id: 1, name: 'Alice', email: 'alice@example.com' }];

  it('returns matching users and echoes the search query', async () => {
    setupMock([
      { rows: fakeRows, rowCount: 1 },
      { rows: [{ total: '1' }], rowCount: 1 },
    ]);

    const result = await searchUsers('alice', 10, 0);
    assert.deepEqual(result.users, fakeRows);
    assert.equal(result.searchQuery, 'alice');
  });

  it('wraps the search term in %…% server-side as a bound parameter', async () => {
    setupMock([
      { rows: [], rowCount: 0 },
      { rows: [{ total: '0' }], rowCount: 1 },
    ]);

    await searchUsers('bob', 10, 0);
    // Both data and count queries receive the pattern as param[0].
    assert.equal(queryCalls[0].params[0], '%bob%');
    assert.equal(queryCalls[1].params[0], '%bob%');
  });

  it('throws VALIDATION_ERROR for empty search query', async () => {
    await assert.rejects(
      () => searchUsers('', 10, 0),
      { code: 'VALIDATION_ERROR' }
    );
  });

  it('throws VALIDATION_ERROR for whitespace-only query', async () => {
    await assert.rejects(
      () => searchUsers('   ', 10, 0),
      { code: 'VALIDATION_ERROR' }
    );
  });

  it('throws VALIDATION_ERROR for null/undefined query', async () => {
    await assert.rejects(
      () => searchUsers(null, 10, 0),
      { code: 'VALIDATION_ERROR' }
    );
  });

  it('does NOT interpolate SQL metacharacters — they are passed as data', async () => {
    // A user searching for "' OR 1=1 --" should get zero results, not an error
    // and crucially should NOT alter query structure.
    setupMock([
      { rows: [], rowCount: 0 },
      { rows: [{ total: '0' }], rowCount: 1 },
    ]);

    const result = await searchUsers("' OR 1=1 --", 10, 0);
    // The raw injection string ends up as a bound param, not in the SQL text.
    assert.equal(queryCalls[0].params[0], "%' OR 1=1 --%");
    assert.equal(result.users.length, 0);
  });

  it('pagination metadata is correct', async () => {
    setupMock([
      { rows: fakeRows, rowCount: 1 },
      { rows: [{ total: '1' }], rowCount: 1 },
    ]);

    const result = await searchUsers('alice', 10, 0);
    assert.equal(result.pagination.total,       1);
    assert.equal(result.pagination.hasNextPage, false);
    assert.equal(result.pagination.hasPrevPage, false);
  });

  it('uses "name" as fallback sort column for unrecognised sortBy', async () => {
    setupMock([
      { rows: [], rowCount: 0 },
      { rows: [{ total: '0' }], rowCount: 1 },
    ]);

    await searchUsers('x', 10, 0, "'; TRUNCATE users; --", 'ASC');
    // Should silently fall back to "id" (parseSortColumn default), not crash.
    assert.match(queryCalls[0].text, /ORDER BY id ASC/i);
  });

  it('issues exactly two queries (data + count) in parallel', async () => {
    setupMock([
      { rows: [], rowCount: 0 },
      { rows: [{ total: '0' }], rowCount: 1 },
    ]);

    await searchUsers('test', 5, 0);
    assert.equal(queryCalls.length, 2);
  });
});

