// ─── Mock db.js before requiring queries.js ──────────────────────────────────
// We intercept require('pg') entirely by pre-populating require.cache with a
// stub, then do the same for db.js so queries.js gets our controlled `query`.

/**
 * Safely resolve a module path, returning a synthetic fallback key when the
 * package is not installed (i.e. in a sandboxed environment without npm).
 */
function safeResolve(id) {
  try { return require.resolve(id); } catch { return id; }
}

// 1. Stub pg so db.js never opens a real connection.
const pgStub = {
  Pool: class {
    constructor() {}
    on() {}
    query() { return Promise.resolve({ rows: [], rowCount: 0 }); }
    connect() { return Promise.resolve({}); }
    end() { return Promise.resolve(); }
    get totalCount() { return 0; }
    get idleCount()  { return 0; }
    get waitingCount(){ return 0; }
  },
};
const pgKey = safeResolve('pg');
require.cache[pgKey] = { id: pgKey, filename: pgKey, loaded: true, exports: pgStub };

// 2. Stub dotenv so no .env file is required.
const dotenvStub = { config: () => {} };
const dotenvKey = safeResolve('dotenv');
require.cache[dotenvKey] = {
  id: dotenvKey, filename: dotenvKey, loaded: true, exports: dotenvStub,
};

/**
 * db.js — PostgreSQL connection pool
 *
 * Responsibilities
 * ─────────────────
 * • Creates a single shared pg.Pool for the entire process lifetime.
 * • Exposes a thin `query()` wrapper that:
 *     – always uses parameterised queries (no string interpolation)
 *     – measures and logs wall-clock query time
 *     – surfaces pg errors with context, without leaking credentials
 * • Exposes `getClient()` for multi-statement transactions.
 * • Provides `healthCheck()` for the /health endpoint.
 * • Provides `closePool()` for graceful shutdown.
 *
 * SQL-injection prevention strategy
 * ───────────────────────────────────
 * All dynamic values are passed as elements of the `params` array and
 * referenced as $1, $2 … in the query text. pg sends query text and
 * parameters to PostgreSQL over separate wire-protocol fields, so the
 * database engine NEVER concatenates them — making injection structurally
 * impossible regardless of what the parameter value contains.
 *
 * Connection-string credentials are read exclusively from environment
 * variables; this file contains no literal credentials.
 *
 * Testability
 * ────────────
 * `query` is exported as a plain property on module.exports so tests can
 * replace it with a mock: require('./db').query = mockFn.
 * No monkey-patching of require.cache is needed.
 */

'use strict';

// dotenv is optional — if the package is absent (e.g. in some CI envs that
// inject variables directly) we simply skip it.
try { require('dotenv').config(); } catch { /* dotenv not installed */ }

// pg is required at runtime.  A clear error is thrown if it is missing.
let Pool;
try {
  ({ Pool } = require('pg'));
} catch {
  throw new Error(
    '[db] The "pg" package is not installed. Run: npm install pg'
  );
}

