/**
 * tests/queries.test.js
 *
 * Unit tests for queries.js using Node's built-in test runner (node:test).
 * The PostgreSQL pool (db.js) is fully mocked so no live database is needed.
 *
 * Run:  node --test tests/queries.test.js
 *
 * Mocking strategy
 * ─────────────────
 * queries.js depends on db.js only through the exported `query` function.
 * We load db.js first (it gracefully swallows missing pg/dotenv), then
 * replace the exported `query` property on its module.exports object before
 * loading queries.js.  Because Node caches modules by resolved path, both
 * db.js and queries.js share the same exports object, so our replacement is
 * visible to every call made from queries.js without touching require.cache
 * internals or installing any packages.
 */

'use strict';

const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const path   = require('node:path');

// ─── Bootstrap mock BEFORE loading queries.js ────────────────────────────────

// Tell db.js not to blow up when pg / dotenv aren't installed.
process.env.DATABASE_URL = 'postgres://test:test@localhost:5432/testdb';

// Load db — it exports `query` as a plain writable property.
const db = require('../db');

// ── Controllable mock state ──────────────────────────────────────────────────

/** Every (text, params) pair passed to db.query within the current test. */
let queryCalls = [];

/**
 * Queue of results to return on successive db.query invocations.
 * Each element may be a { rows, rowCount } object or an Error instance.
 */
let responseQueue = [];

// Install the mock once, permanently — individual tests prime responseQueue.
db.query = async function mockQuery(text, params = []) {
  queryCalls.push({ text: text.replace(/\s+/g, ' ').trim(), params });
  const next = responseQueue.shift();
  if (!next)       return { rows: [], rowCount: 0 };
  if (next instanceof Error) throw next;
  return next;
};

/**
 * Prime the mock with an ordered list of responses and reset the call log.
 * @param {...({ rows: object[], rowCount: number }|Error)} responses
 */
function setup(...responses) {
  queryCalls    = [];
  responseQueue = responses;
}

// Load queries.js AFTER the mock is in place so it picks up db.query = mockQuery.
const {
  getUserById,
  getAllUsers,
  searchUsers,
  _parseId,
  _parseLimit,
  _parseOffset,
  _parseSortColumn,
  _parseSortDir,
  _parseSearchQuery,
} = require('../queries');

// ─── Shared fixtures ─────────────────────────────────────────────────────────

const ALICE = { id: 1, name: 'Alice', email: 'alice@example.com',
                created_at: new Date(), updated_at: new Date() };
const BOB   = { id: 2, name: 'Bob',   email: 'bob@example.com',
                created_at: new Date(), updated_at: new Date() };

const EMPTY_COUNT = { rows: [{ total: '0' }], rowCount: 1 };
const count = (n) => ({ rows: [{ total: String(n) }], rowCount: 1 });
const rows  = (...r) => ({ rows: r, rowCount: r.length });

// ─── _parseId ─────────────────────────────────────────────────────────────────

describe('_parseId', () => {
  it('accepts valid positive integers', () => {
    assert.equal(_parseId(1),     1);
    assert.equal(_parseId('42'), 42);
    assert.equal(_parseId(999), 999);
  });

  it('rejects 0', () => {
    assert.throws(() => _parseId(0), { code: 'VALIDATION_ERROR' });
  });

  it('rejects negative numbers', () => {
    assert.throws(() => _parseId(-5), { code: 'VALIDATION_ERROR' });
  });

  it('rejects floats', () => {
    assert.throws(() => _parseId(1.5), { code: 'VALIDATION_ERROR' });
  });

  it('rejects SQL-injection strings', () => {
    assert.throws(() => _parseId("1; DROP TABLE users; --"), { code: 'VALIDATION_ERROR' });
    assert.throws(() => _parseId("' OR '1'='1"),             { code: 'VALIDATION_ERROR' });
    assert.throws(() => _parseId('abc'),                     { code: 'VALIDATION_ERROR' });
  });
});

// ─── _parseLimit ─────────────────────────────────────────────────────────────

describe('_parseLimit', () => {
  it('returns default (20) for absent input', () => {
    assert.equal(_parseLimit(undefined), 20);
    assert.equal(_parseLimit(null),      20);
  });

  it('clamps to MAX_LIMIT (100)', () => {
    assert.equal(_parseLimit(101),  100);
    assert.equal(_parseLimit(9999), 100);
  });

  it('returns default for non-numeric / zero / negative values', () => {
    assert.equal(_parseLimit('abc'), 20);
    assert.equal(_parseLimit(0),     20);
    assert.equal(_parseLimit(-1),    20);
  });

  it('accepts valid limits', () => {
    assert.equal(_parseLimit(1),    1);
    assert.equal(_parseLimit('50'), 50);
    assert.equal(_parseLimit(100),  100);
  });
});

// ─── _parseOffset ────────────────────────────────────────────────────────────

describe('_parseOffset', () => {
  it('defaults to 0 for absent input', () => {
    assert.equal(_parseOffset(undefined), 0);
    assert.equal(_parseOffset(null),      0);
  });

  it('defaults to 0 for negative values', () => {
    assert.equal(_parseOffset(-1),   0);
    assert.equal(_parseOffset(-100), 0);
  });

  it('accepts valid offsets', () => {
    assert.equal(_parseOffset(0),    0);
    assert.equal(_parseOffset(40),  40);
    assert.equal(_parseOffset('20'), 20);
  });
});

// ─── _parseSortColumn ────────────────────────────────────────────────────────

describe('_parseSortColumn', () => {
  it('allows known columns', () => {
    assert.equal(_parseSortColumn('id'),         'id');
    assert.equal(_parseSortColumn('name'),       'name');
    assert.equal(_parseSortColumn('email'),      'email');
    assert.equal(_parseSortColumn('created_at'), 'created_at');
  });

  it('falls back to "id" for unknown or dangerous input', () => {
    assert.equal(_parseSortColumn('password_hash'),    'id');
    assert.equal(_parseSortColumn("'; DROP TABLE--"),  'id');
    assert.equal(_parseSortColumn(''),                 'id');
    assert.equal(_parseSortColumn(undefined),          'id');
  });
});

// ─── _parseSortDir ───────────────────────────────────────────────────────────

describe('_parseSortDir', () => {
  it('allows ASC and DESC (case-insensitive)', () => {
    assert.equal(_parseSortDir('ASC'),  'ASC');
    assert.equal(_parseSortDir('desc'), 'DESC');
    assert.equal(_parseSortDir('Asc'),  'ASC');
  });

  it('falls back to ASC for unknown input', () => {
    assert.equal(_parseSortDir('RANDOM'),                   'ASC');
    assert.equal(_parseSortDir(undefined),                  'ASC');
    assert.equal(_parseSortDir('; DROP TABLE users--'),     'ASC');
  });
});

// ─── _parseSearchQuery ───────────────────────────────────────────────────────

describe('_parseSearchQuery', () => {
  it('trims surrounding whitespace', () => {
    assert.equal(_parseSearchQuery('  alice  '), 'alice');
  });

  it('returns null for empty / whitespace-only / null input', () => {
    assert.equal(_parseSearchQuery(''),    null);
    assert.equal(_parseSearchQuery('   '), null);
    assert.equal(_parseSearchQuery(null),  null);
  });

  it('truncates to the given maxLength', () => {
    const long = 'x'.repeat(500);
    assert.equal(_parseSearchQuery(long, 10).length, 10);
  });
});

// ─── getUserById ─────────────────────────────────────────────────────────────

describe('getUserById', () => {
  it('returns the user when a row is found', async () => {
    setup(rows(ALICE));
    assert.deepEqual(await getUserById(1), ALICE);
  });

  it('returns null when no row matches', async () => {
    setup({ rows: [], rowCount: 0 });
    assert.equal(await getUserById(99), null);
