    assert.equal(queryCalls[0].params[0], '%bob%');
    assert.equal(queryCalls[1].params[0], '%bob%');
    // The raw string "bob" must NOT appear literally in the SQL template.
    assert.doesNotMatch(queryCalls[0].text, /ILIKE\s+['%]bob/i);
  });

  it('treats SQL-metacharacter search terms as plain data', async () => {
    setup(rows(), count(0));
