    const result = await searchUsers(injection, 10, 0);
    // Bound parameter carries the safe pattern; query structure is unaffected.
    assert.equal(queryCalls[0].params[0], `%${injection}%`);
    assert.equal(result.users.length, 0);
  });

  it('throws VALIDATION_ERROR for an empty search query', async () => {
    await assert.rejects(
      () => searchUsers('', 10, 0),
      { code: 'VALIDATION_ERROR' }
    );
  });

  it('throws VALIDATION_ERROR for whitespace-only query', async () => {
    await assert.rejects(
      () => searchUsers('   ', 10, 0),
      { code: 'VALIDATION_ERROR' }
    );
  });

  it('throws VALIDATION_ERROR for null / undefined query', async () => {
    await assert.rejects(
      () => searchUsers(null),
      { code: 'VALIDATION_ERROR' }
    );
  });

  it('returns correct pagination', async () => {
    setup(rows(ALICE), count(1));
    const { pagination } = await searchUsers('alice', 10, 0);
    assert.equal(pagination.total,       1);
    assert.equal(pagination.limit,       10);
    assert.equal(pagination.hasNextPage, false);
    assert.equal(pagination.hasPrevPage, false);
  });

  it('falls back to "id" for a dangerous sortBy value', async () => {
    setup(rows(), count(0));
    await searchUsers('x', 10, 0, "'; TRUNCATE users; --", 'ASC');
    assert.match(queryCalls[0].text, /ORDER BY id ASC/i);
  });

  it('issues exactly two queries (data + count) per call', async () => {
    setup(rows(), count(0));
    await searchUsers('test', 5, 0);
    assert.equal(queryCalls.length, 2);
  });
});

