/**
 * GET /users/:id
 *
 * Fetch a single user by numeric ID.
 *
 * Responses
 * ─────────
 *   200  User
 *   400  { error: string }  – non-integer id
 *   404  { error: string }  – user not found
 *   500  { error: string }  – unexpected database error
 *
 * @example
 *   GET /users/42
 */
app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);
    return res.json({ data: user });
  } catch (err) {
