/**
 * db.js — PostgreSQL connection pool
 *
 * Centralises pool creation so the same pool instance is reused across every
 * module that imports this file (Node's module cache guarantees a singleton).
 *
 * Configuration is read exclusively from environment variables so no
 * credentials ever appear in source code.
 */

'use strict';

require('dotenv').config();
const { Pool } = require('pg');

// ── Build pool config ─────────────────────────────────────────────────────────

/**
 * Parse an integer env-var with a fallback default.
 * Returns the default when the variable is absent or not a valid integer.
 *
 * @param {string} name - Environment variable name
 * @param {number} defaultValue
 * @returns {number}
 */
function envInt(name, defaultValue) {
  const raw = process.env[name];
  if (raw === undefined || raw === '') return defaultValue;
  const parsed = parseInt(raw, 10);
  return Number.isFinite(parsed) ? parsed : defaultValue;
}

const poolConfig = process.env.DATABASE_URL
  ? {
      // Single connection-string path (e.g. Heroku / Railway / Render)
      connectionString: process.env.DATABASE_URL,
      ssl:
        process.env.NODE_ENV === 'production'
          ? { rejectUnauthorized: true }
          : false,
    }
  : {
      // Individual credential path
      host:     process.env.DB_HOST     || 'localhost',
      port:     envInt('DB_PORT', 5432),
      database: process.env.DB_NAME     || 'myapp',
      user:     process.env.DB_USER     || 'myuser',
      password: process.env.DB_PASSWORD || '',
    };

// Shared pool-sizing options applied on top of either config path
Object.assign(poolConfig, {
  max:              envInt('DB_POOL_MAX', 10),
  idleTimeoutMillis: envInt('DB_POOL_IDLE_TIMEOUT_MS', 30_000),
  connectionTimeoutMillis: envInt('DB_POOL_CONNECTION_TIMEOUT_MS', 2_000),
});

// ── Create pool ───────────────────────────────────────────────────────────────

const pool = new Pool(poolConfig);

// Emit a warning for background (idle) errors rather than crashing the process.
// These can happen when the DB restarts or a long-lived idle connection is
// dropped by a firewall.
pool.on('error', (err) => {
  console.error('[db] Unexpected pool error — idle client lost:', err.message);
});

pool.on('connect', () => {
  if (process.env.NODE_ENV !== 'test') {
    console.log('[db] New client connected to pool');
  }
});

// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Execute a single parameterised query against the pool.
 *
 * This is the **only** function in the codebase that should touch `pool.query`
 * directly; everything else goes through `queries.js`.
 *
 * @param {string}  sql    - Parameterised SQL string (e.g. `SELECT … WHERE id = $1`)
 * @param {Array}   [params=[]] - Bound parameter values
 * @returns {Promise<import('pg').QueryResult>}
 */
async function query(sql, params = []) {
  return pool.query(sql, params);
}

/**
 * Borrow a dedicated client from the pool for multi-statement transactions.
 *
 * Caller MUST call `client.release()` in a finally block.
 *
 * @returns {Promise<import('pg').PoolClient>}
 */
async function getClient() {
  return pool.connect();
}

/**
 * Gracefully drain and close all pool connections.
 * Call this once during application shutdown (SIGTERM/SIGINT handler).
 *
 * @returns {Promise<void>}
 */
async function closePool() {
  await pool.end();
  console.log('[db] Pool closed');
}

module.exports = { pool, query, getClient, closePool };

/**
 * queries.js — Parameterised query functions for the /users resource
 *
 * Design principles
 * ─────────────────
 * 1. SQL injection prevention
 *    Every user-supplied value is passed as a bound parameter ($1, $2 …),
 *    never interpolated into the query string. pg's wire protocol sends
 *    parameters separately from the query text, so the database driver
 *    never performs string substitution — this eliminates the injection
 *    surface entirely, even for values that contain quotes, semicolons,
 *    or SQL keywords.
 *
 *    For the searchUsers function the LIKE wildcard characters (%, _) that
 *    exist inside the *search term itself* are also escaped before the term
 *    is forwarded to the database, preventing pattern injection.
 *
 * 2. Pagination safety
 *    `limit` is clamped to [1, MAX_LIMIT] and `offset` to [0, ∞) so a
 *    caller cannot request an unbounded result set or a negative offset.
 *
 * 3. Query timing
 *    Every function records wall-clock duration via `performance.now()` and
 *    emits a structured log line that includes the function name, duration,
 *    and the row count returned.  Slow queries (> SLOW_QUERY_THRESHOLD_MS)
 *    are flagged at WARN level so they surface in log aggregators without
 *    requiring a separate APM tool.
 *
 * 4. No raw pool access
 *    All functions delegate to the `query` helper from db.js rather than
 *    calling `pool.query` directly, keeping connection-pool logic in one
 *    place.
 */

'use strict';

const { performance } = require('perf_hooks');
const { query }       = require('./db');

// ── Constants ─────────────────────────────────────────────────────────────────

/** Hard ceiling on the number of rows a single page can return. */
const MAX_LIMIT = 100;

/** Queries that take longer than this many milliseconds are logged as WARN. */
const SLOW_QUERY_THRESHOLD_MS = 200;

// ── Internal helpers ──────────────────────────────────────────────────────────

/**
 * Emit a structured timing log line.
 *
 * @param {string} fnName     - Query function name (for correlation)
 * @param {number} durationMs - Elapsed time in milliseconds
 * @param {number} rowCount   - Number of rows returned / affected
 * @param {string} [extra]    - Optional extra context (e.g. id, search term)
 */
function logQueryTiming(fnName, durationMs, rowCount, extra = '') {
  const level  = durationMs > SLOW_QUERY_THRESHOLD_MS ? 'WARN ' : 'INFO ';
  const suffix = durationMs > SLOW_QUERY_THRESHOLD_MS ? ' ⚠ slow query' : '';
  const ctx    = extra ? ` | ctx="${extra}"` : '';
  console.log(
    `[query] ${level}| ${fnName} | ${durationMs.toFixed(2)} ms` +
    ` | rows=${rowCount}${ctx}${suffix}`,
  );
}

/**
 * Escape LIKE pattern metacharacters (\, %, _) inside a user-supplied search
 * term.  The escaped string is still passed as a bound parameter — this step
 * only prevents the user from accidentally (or deliberately) turning their
 * search term into a wildcard glob.
 *
 * @param {string} raw - Unsanitised search term
 * @returns {string}   - Safe LIKE operand (wildcards added by the caller)
 */
function escapeLike(raw) {
  // Escape the escape char first, then % and _
  return raw.replace(/\\/g, '\\\\').replace(/%/g, '\\%').replace(/_/g, '\\_');
}

/**
 * Coerce `value` to an integer, returning `fallback` when the value is not a
 * finite integer.
 *
 * @param {*}      value
 * @param {number} fallback
 * @returns {number}
 */
function toInt(value, fallback) {
  const n = parseInt(value, 10);
  return Number.isFinite(n) ? n : fallback;
}

// ── Public query functions ────────────────────────────────────────────────────

/**
 * Fetch a single user row by primary key.
 *
 * @param {number|string} id - The user's numeric primary key.
 *                             A non-numeric value will cause a deliberate early
 *                             return (no DB round-trip) with a null result.
 * @returns {Promise<Object|null>} The user row, or null if not found.
 *
 * @example
 * const user = await getUserById(42);
 * // { id: 42, name: 'Alice', email: 'alice@example.com', created_at: Date }
 */
async function getUserById(id) {
  // Validate before touching the DB — guards against NaN / objects / arrays.
  const numericId = toInt(id, NaN);
  if (!Number.isFinite(numericId) || numericId < 1) {
    console.log(`[query] INFO | getUserById | 0.00 ms | rows=0 | ctx="id=${id}" | invalid id — skipped`);
    return null;
  }

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const t0 = performance.now();
  const result = await query(sql, [numericId]);
  const durationMs = performance.now() - t0;

  logQueryTiming('getUserById', durationMs, result.rowCount, `id=${numericId}`);

  return result.rows[0] ?? null;
}

/**
 * Return a paginated slice of all users, ordered by id ascending.
 *
 * @param {number} [limit=20]  - Rows per page (clamped to 1–MAX_LIMIT).
 * @param {number} [offset=0]  - Zero-based row offset (floored at 0).
 * @returns {Promise<{ users: Object[], total: number, limit: number, offset: number }>}
 *
 * @example
 * const page = await getAllUsers(10, 20);
 * // { users: [...], total: 150, limit: 10, offset: 20 }
 */
async function getAllUsers(limit = 20, offset = 0) {
  // Clamp to safe bounds — prevents "LIMIT -1" or absurdly large pages.
  const safeLimit  = Math.min(Math.max(toInt(limit,  20), 1), MAX_LIMIT);
  const safeOffset = Math.max(toInt(offset, 0), 0);

  // A single round-trip fetches the page AND the total count using a window
  // function, avoiding a separate COUNT(*) query.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER() AS total_count
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const t0 = performance.now();
  const result = await query(sql, [safeLimit, safeOffset]);
  const durationMs = performance.now() - t0;

  logQueryTiming(
    'getAllUsers',
    durationMs,
    result.rowCount,
    `limit=${safeLimit} offset=${safeOffset}`,
  );

  const total = result.rows.length > 0
    ? parseInt(result.rows[0].total_count, 10)
    : 0;

  // Strip the internal total_count column from the returned rows.
  const users = result.rows.map(({ total_count, ...rest }) => rest);

  return { users, total, limit: safeLimit, offset: safeOffset };
}

/**
 * Full-text search across users' names and email addresses.
 *
 * The search term is:
 *  1. Trimmed of leading/trailing whitespace.
 *  2. LIKE-escaped so the user cannot inject wildcards.
 *  3. Wrapped in % … % for a contains-style match.
 *  4. Passed as a bound parameter — never string-interpolated.
 *
 * @param {string} searchQuery      - Free-text search term (min 1 char after trim).
 * @param {number} [limit=20]       - Rows per page (clamped to 1–MAX_LIMIT).
 * @param {number} [offset=0]       - Zero-based row offset (floored at 0).
 * @returns {Promise<{ users: Object[], total: number, limit: number, offset: number, query: string }>}
 *
 * @example
 * const results = await searchUsers('alice', 10, 0);
 * // { users: [...], total: 3, limit: 10, offset: 0, query: 'alice' }
 */
async function searchUsers(searchQuery, limit = 20, offset = 0) {
  if (typeof searchQuery !== 'string' || searchQuery.trim().length === 0) {
    throw new TypeError('searchUsers: `query` must be a non-empty string');
  }

  const safeLimit  = Math.min(Math.max(toInt(limit,  20), 1), MAX_LIMIT);
  const safeOffset = Math.max(toInt(offset, 0), 0);

  // Escape LIKE metacharacters *within* the term, then wrap with wildcards.
  const safeTerm = `%${escapeLike(searchQuery.trim())}%`;

  // ILIKE performs case-insensitive matching natively in PostgreSQL.
  // Both name and email are searched; results are ranked by relevance
  // (exact name prefix match first, then email, then partial name).
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE
      name  ILIKE $1  ESCAPE '\\'
      OR
      email ILIKE $1  ESCAPE '\\'
    ORDER BY
      CASE WHEN name  ILIKE $2 ESCAPE '\\' THEN 0 ELSE 1 END,
      CASE WHEN email ILIKE $1 ESCAPE '\\' THEN 0 ELSE 1 END,
      id ASC
    LIMIT  $3
    OFFSET $4
  `;

  // $2 is a "starts-with" variant used only for ordering (not filtering).
  const prefixTerm = `${escapeLike(searchQuery.trim())}%`;

  const t0 = performance.now();
  const result = await query(sql, [safeTerm, prefixTerm, safeLimit, safeOffset]);
  const durationMs = performance.now() - t0;

  logQueryTiming(
    'searchUsers',
    durationMs,
    result.rowCount,
    `q="${searchQuery.trim()}" limit=${safeLimit} offset=${safeOffset}`,
  );

  const total = result.rows.length > 0
    ? parseInt(result.rows[0].total_count, 10)
    : 0;

  const users = result.rows.map(({ total_count, ...rest }) => rest);

  return {
    users,
    total,
    limit:  safeLimit,
    offset: safeOffset,
    query:  searchQuery.trim(),
  };
}

module.exports = { getUserById, getAllUsers, searchUsers };

/**
 * app.js — Express application
 *
 * Wires together the HTTP layer and the database query layer.
 * All /users routes delegate to the parameterised functions in queries.js;
 * no SQL is written here.
 */

'use strict';

require('dotenv').config();

const express = require('express');
const { getUserById, getAllUsers, searchUsers } = require('./queries');
const { closePool } = require('./db');

const app  = express();
const PORT = process.env.PORT || 3000;

app.use(express.json());

// ── Health ────────────────────────────────────────────────────────────────────

app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ── Users ─────────────────────────────────────────────────────────────────────

/**
 * GET /users
 *
 * Returns a paginated list of users, or — when `?q=` is provided — a
 * relevance-ranked search result set.
 *
 * Query parameters
 * ────────────────
 * q       {string}  Free-text search term (searches name + email, ILIKE)
 * limit   {number}  Rows per page, 1–100, default 20
 * offset  {number}  Zero-based row offset, default 0
 *
 * Responses
 * ─────────
 * 200  { users, total, limit, offset [, query] }
 * 400  { error: string }   — invalid / missing query parameter
 * 500  { error: string }   — unexpected database error
 */
app.get('/users', async (req, res) => {
  const { q, limit, offset } = req.query;

  try {
    if (q !== undefined) {
      // ── Search path ─────────────────────────────────────────────────────────
      if (typeof q !== 'string' || q.trim().length === 0) {
        return res.status(400).json({
          error: '`q` must be a non-empty string when provided',
        });
      }
      const data = await searchUsers(q, limit, offset);
      return res.json(data);
    }

    // ── List path ───────────────────────────────────────────────────────────
    const data = await getAllUsers(limit, offset);
    return res.json(data);

  } catch (err) {
    console.error('[/users] Unhandled error:', err.message);
    return res.status(500).json({ error: 'Internal server error' });
  }
});

/**
 * GET /users/:id
 *
 * Fetch a single user by numeric primary key.
 *
 * Path parameters
 * ───────────────
 * id  {integer}  User primary key (must be a positive integer)
 *
 * Responses
 * ─────────
 * 200  { id, name, email, created_at }
 * 400  { error: string }   — id is not a valid positive integer
 * 404  { error: string }   — no user with this id
 * 500  { error: string }   — unexpected database error
 */
app.get('/users/:id', async (req, res) => {
  const rawId    = req.params.id;
  const numericId = parseInt(rawId, 10);

  // Reject non-integer or non-positive ids before hitting the DB.
  if (!Number.isFinite(numericId) || numericId < 1 || String(numericId) !== rawId) {
    return res.status(400).json({
      error: '`id` must be a positive integer',
    });
  }

  try {
    const user = await getUserById(numericId);

    if (!user) {
      return res.status(404).json({ error: `User ${numericId} not found` });
    }

    return res.json(user);

  } catch (err) {
    console.error(`[/users/${numericId}] Unhandled error:`, err.message);
    return res.status(500).json({ error: 'Internal server error' });
  }
});

// ── Graceful shutdown ─────────────────────────────────────────────────────────

async function shutdown(signal) {
  console.log(`\n[app] ${signal} received — shutting down gracefully …`);
  try {
    await closePool();
  } catch (err) {
    console.error('[app] Error during shutdown:', err.message);
  }
  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ── Start ─────────────────────────────────────────────────────────────────────

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT} (${process.env.NODE_ENV ?? 'development'})`);
  });
}

module.exports = app;

/**
 * __tests__/queries.test.js
 *
 * Unit tests for queries.js.
 *
 * The PostgreSQL pool (db.js) is mocked so these tests run without a live
 * database.  Each test controls exactly what `query()` returns, letting us
 * verify the SQL strings, bound parameters, input validation, timing logs,
 * and return shapes in complete isolation.
 */

'use strict';

// ── Mock db.js before any require of queries.js ───────────────────────────────

// We need a mutable reference so individual tests can override the resolved
// value / rejection.
const mockQuery = jest.fn();

jest.mock('../db', () => ({
  query:      mockQuery,
  getClient:  jest.fn(),
  closePool:  jest.fn().mockResolvedValue(undefined),
  pool:       { on: jest.fn(), end: jest.fn() },
}));

// Also silence dotenv in tests
jest.mock('dotenv', () => ({ config: jest.fn() }));

const { getUserById, getAllUsers, searchUsers } = require('../queries');

// ── Helpers ───────────────────────────────────────────────────────────────────

/** Build a fake pg QueryResult */
function makeResult(rows) {
  const withCount = rows.map((r) => ({ ...r, total_count: String(rows.length) }));
  return { rows: withCount, rowCount: rows.length };
}

/** Build a fake pg QueryResult with an explicit total different from rows.length */
function makeResultWithTotal(rows, total) {
  const withCount = rows.map((r) => ({ ...r, total_count: String(total) }));
  return { rows: withCount, rowCount: rows.length };
}

const ALICE = { id: 1, name: 'Alice',   email: 'alice@example.com',   created_at: new Date('2024-01-01') };
const BOB   = { id: 2, name: 'Bob',     email: 'bob@example.com',     created_at: new Date('2024-01-02') };
const CAROL = { id: 3, name: 'Carol',   email: 'carol@example.com',   created_at: new Date('2024-01-03') };
const DAN   = { id: 4, name: 'Dan',     email: 'dan@example.com',     created_at: new Date('2024-01-04') };

// ── getUserById ───────────────────────────────────────────────────────────────

describe('getUserById', () => {
  beforeEach(() => mockQuery.mockReset());

  test('returns a user row when the id exists', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [ALICE], rowCount: 1 });

    const result = await getUserById(1);

    expect(result).toEqual(ALICE);
  });

  test('passes the correct parameterised SQL and binds the id', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [BOB], rowCount: 1 });

    await getUserById(2);

    expect(mockQuery).toHaveBeenCalledTimes(1);
    const [sql, params] = mockQuery.mock.calls[0];

    // Must contain a $1 placeholder — no literal id in the query string
    expect(sql).toContain('$1');
    expect(sql).not.toMatch(/WHERE id = 2/); // id never interpolated
    expect(params).toEqual([2]);
  });

  test('returns null when no row is found', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [], rowCount: 0 });

    const result = await getUserById(999);

    expect(result).toBeNull();
  });

  test('returns null and skips DB call for non-numeric id', async () => {
    const result = await getUserById('not-a-number');

    expect(result).toBeNull();
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('returns null and skips DB call for zero', async () => {
    const result = await getUserById(0);

    expect(result).toBeNull();
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('returns null and skips DB call for negative ids', async () => {
    const result = await getUserById(-5);

    expect(result).toBeNull();
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('returns null and skips DB call for a float', async () => {
    const result = await getUserById(1.5);
    // parseInt(1.5) === 1, which IS valid — query should be issued
    // (this is intentional: parseInt truncates, so 1.5 → user 1)
    expect(mockQuery).toHaveBeenCalledTimes(1);
    expect(mockQuery.mock.calls[0][1]).toEqual([1]);
    // put another way: no crash and the bound param is the truncated int
  });

  test('coerces a numeric string id', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [CAROL], rowCount: 1 });

    const result = await getUserById('3');

    expect(result).toEqual(CAROL);
    expect(mockQuery.mock.calls[0][1]).toEqual([3]);
  });

  test('propagates database errors', async () => {
    mockQuery.mockRejectedValueOnce(new Error('connection reset'));

    await expect(getUserById(1)).rejects.toThrow('connection reset');
  });

  test('emits a timing log line to console.log', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [ALICE], rowCount: 1 });
    const spy = jest.spyOn(console, 'log').mockImplementation(() => {});

    await getUserById(1);

    const call = spy.mock.calls.find(([msg]) => msg.includes('getUserById'));
    expect(call).toBeDefined();
    expect(call[0]).toMatch(/getUserById/);
    expect(call[0]).toMatch(/rows=1/);

    spy.mockRestore();
  });
});

// ── getAllUsers ───────────────────────────────────────────────────────────────

