});

// ── searchUsers ───────────────────────────────────────────────────────────────

describe('searchUsers', () => {
  beforeEach(() => mockQuery.mockReset());

  test('returns matching users with correct shape', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([ALICE]));

    const result = await searchUsers('alice');

    expect(result).toMatchObject({
      users:  [ALICE],
      total:  1,
      limit:  20,
      offset: 0,
      query:  'alice',
    });
  });

  test('strips total_count from returned user objects', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([ALICE]));

    const { users } = await searchUsers('alice');

    expect(users[0]).not.toHaveProperty('total_count');
  });

  test('wraps the search term in % wildcards as a bound parameter', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('ali');

    const [sql, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe('%ali%'); // contains-style wildcard
    expect(sql).not.toContain('ali'); // term is NEVER in the SQL string
  });

  test('search term is passed as $1, limit as $3, offset as $4', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('bob', 5, 10);

    const [sql, params] = mockQuery.mock.calls[0];
    expect(sql).toContain('$1');
    expect(sql).toContain('$3');
    expect(sql).toContain('$4');
    expect(params[2]).toBe(5);
    expect(params[3]).toBe(10);
  });

  test('escapes % in search term (prevents wildcard injection)', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('100%');

    const params = mockQuery.mock.calls[0][1];
    // The % in the user's term must be escaped so it is literal
    expect(params[0]).toBe('%100\\%%');
    expect(params[1]).toBe('100\\%%');
  });

  test('escapes _ in search term (prevents single-char wildcard injection)', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('a_b');

    const params = mockQuery.mock.calls[0][1];
    expect(params[0]).toBe('%a\\_b%');
  });

  test('escapes \\ in search term', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('C:\\\\Users');

    const params = mockQuery.mock.calls[0][1];
    // Each \ is doubled
    expect(params[0]).toContain('\\\\');
  });

  test('trims whitespace from query term', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('  alice  ');

    const params = mockQuery.mock.calls[0][1];
    expect(params[0]).toBe('%alice%');
    // also verify the returned query field is trimmed
  });

  test('throws TypeError for empty string query', async () => {
    await expect(searchUsers('')).rejects.toThrow(TypeError);
    await expect(searchUsers('')).rejects.toThrow(/non-empty/);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws TypeError for whitespace-only query', async () => {
    await expect(searchUsers('   ')).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws TypeError for non-string query', async () => {
    await expect(searchUsers(null)).rejects.toThrow(TypeError);
    await expect(searchUsers(42)).rejects.toThrow(TypeError);
    await expect(searchUsers(undefined)).rejects.toThrow(TypeError);
  });

  test('clamps limit to MAX_LIMIT', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('test', 500);

    expect(mockQuery.mock.calls[0][1][2]).toBe(100);
  });

  test('clamps negative offset to 0', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('test', 10, -1);

    expect(mockQuery.mock.calls[0][1][3]).toBe(0);
  });

  test('emits a timing log that includes the query term', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([ALICE]));
    const spy = jest.spyOn(console, 'log').mockImplementation(() => {});

    await searchUsers('alice', 5, 0);

    const call = spy.mock.calls.find(([msg]) => msg.includes('searchUsers'));
    expect(call[0]).toMatch(/q="alice"/);
    expect(call[0]).toMatch(/rows=1/);

    spy.mockRestore();
  });

  test('returns empty result set gracefully', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [], rowCount: 0 });

    const result = await searchUsers('zzznomatch');

    expect(result.total).toBe(0);
    expect(result.users).toHaveLength(0);
  });

  test('propagates database errors', async () => {
    mockQuery.mockRejectedValueOnce(new Error('db unavailable'));

    await expect(searchUsers('alice')).rejects.toThrow('db unavailable');
  });
});

// ── SQL injection edge cases (cross-cutting) ──────────────────────────────────

describe('SQL injection prevention', () => {
  beforeEach(() => mockQuery.mockReset());

  const INJECTIONS = [
    "1; DROP TABLE users; --",
    "' OR '1'='1",
    "1 UNION SELECT * FROM secrets --",
    "admin'--",
    "'; EXEC xp_cmdshell('rm -rf /'); --",
    "1 OR 1=1",
  ];

  test.each(INJECTIONS)(
    'getUserById: injection attempt %j never appears in SQL string',
    async (injection) => {
      // Even for numeric-looking injections parseInt gives a benign integer or NaN
      mockQuery.mockResolvedValue({ rows: [], rowCount: 0 });

      await getUserById(injection);

      if (mockQuery.mock.calls.length > 0) {
        const [sql] = mockQuery.mock.calls[0];
        // The raw injection string must not appear in the SQL
        expect(sql).not.toContain(injection);
      }
      // If no call was made, validation rejected it early — also safe
    },
  );

  test.each(INJECTIONS)(
    'searchUsers: injection attempt %j is bound as a parameter, never interpolated',
    async (injection) => {
      mockQuery.mockResolvedValue({ rows: [], rowCount: 0 });

      // searchUsers throws on empty string; skip those
      if (injection.trim().length === 0) return;

      await searchUsers(injection).catch(() => {}); // TypeError for invalid input is fine

      if (mockQuery.mock.calls.length > 0) {
        const [sql, params] = mockQuery.mock.calls[0];
        // Raw injection must not appear in SQL string
        expect(sql).not.toContain(injection);
        // The (escaped) term must be present in params, not in sql
        expect(params[0]).toContain(injection.trim().replace(/\\/g, '\\\\').replace(/%/g, '\\%').replace(/_/g, '\\_'));
      }
    },
  );
});

// ── Slow-query warning ────────────────────────────────────────────────────────

describe('slow query warning', () => {
  beforeEach(() => mockQuery.mockReset());

  test('logs WARN and ⚠ slow query when execution exceeds threshold', async () => {
    // Make the DB "take" 250 ms by delaying the mock resolution
    mockQuery.mockImplementationOnce(
      () => new Promise((resolve) =>
        setTimeout(() => resolve({ rows: [], rowCount: 0 }), 250),
      ),
    );

    const spy = jest.spyOn(console, 'log').mockImplementation(() => {});

    await getAllUsers();

    const call = spy.mock.calls.find(([msg]) => msg.includes('getAllUsers'));
    expect(call[0]).toMatch(/WARN/);
    expect(call[0]).toMatch(/slow query/);

    spy.mockRestore();
  }, 10_000);
});

/**
 * __tests__/app.test.js
 *
 * Integration tests for the Express routes in app.js.
 *
 * queries.js is mocked so routes are tested in isolation from the database.
 * supertest drives the HTTP layer so we exercise routing, validation, error
 * handling, and response shapes end-to-end.
 */

'use strict';

// ── Mock the query layer ──────────────────────────────────────────────────────

const mockGetUserById  = jest.fn();
const mockGetAllUsers  = jest.fn();
const mockSearchUsers  = jest.fn();

jest.mock('../queries', () => ({
  getUserById: mockGetUserById,
  getAllUsers:  mockGetAllUsers,
  searchUsers:  mockSearchUsers,
}));

jest.mock('../db', () => ({
  query:     jest.fn(),
  getClient: jest.fn(),
  closePool: jest.fn().mockResolvedValue(undefined),
  pool:      { on: jest.fn(), end: jest.fn() },
}));

jest.mock('dotenv', () => ({ config: jest.fn() }));

const request = require('supertest');
const app     = require('../app');

// ── Fixtures ──────────────────────────────────────────────────────────────────

const USER_ALICE = { id: 1, name: 'Alice', email: 'alice@example.com', created_at: '2024-01-01T00:00:00.000Z' };
const USER_BOB   = { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: '2024-01-02T00:00:00.000Z' };

const PAGE_RESULT = { users: [USER_ALICE, USER_BOB], total: 2, limit: 20, offset: 0 };

// ── /health ───────────────────────────────────────────────────────────────────

describe('GET /health', () => {
  test('returns 200 with status ok', async () => {
    const res = await request(app).get('/health');
    expect(res.status).toBe(200);
    expect(res.body.status).toBe('ok');
    expect(res.body.timestamp).toBeDefined();
  });
});

// ── GET /users (list) ─────────────────────────────────────────────────────────

describe('GET /users — list', () => {
  beforeEach(() => {
    mockGetAllUsers.mockReset();
    mockSearchUsers.mockReset();
    mockGetUserById.mockReset();
  });

  test('returns 200 with the paginated result from getAllUsers', async () => {
    mockGetAllUsers.mockResolvedValueOnce(PAGE_RESULT);

    const res = await request(app).get('/users');

    expect(res.status).toBe(200);
    expect(res.body).toEqual(PAGE_RESULT);
    expect(mockGetAllUsers).toHaveBeenCalledTimes(1);
  });

  test('forwards limit and offset query params to getAllUsers', async () => {
    mockGetAllUsers.mockResolvedValueOnce({ users: [], total: 0, limit: 5, offset: 10 });

    await request(app).get('/users?limit=5&offset=10');

    expect(mockGetAllUsers).toHaveBeenCalledWith('5', '10');
  });

  test('uses getAllUsers when q param is absent', async () => {
    mockGetAllUsers.mockResolvedValueOnce(PAGE_RESULT);

    await request(app).get('/users');

    expect(mockGetAllUsers).toHaveBeenCalledTimes(1);
    expect(mockSearchUsers).not.toHaveBeenCalled();
  });

  test('returns 500 when getAllUsers throws', async () => {
    mockGetAllUsers.mockRejectedValueOnce(new Error('db down'));

    const res = await request(app).get('/users');

    expect(res.status).toBe(500);
    expect(res.body.error).toBe('Internal server error');
  });
});

// ── GET /users?q= (search) ────────────────────────────────────────────────────

describe('GET /users — search', () => {
  beforeEach(() => {
    mockGetAllUsers.mockReset();
    mockSearchUsers.mockReset();
  });

  test('calls searchUsers when q param is provided', async () => {
    const searchResult = { users: [USER_ALICE], total: 1, limit: 20, offset: 0, query: 'alice' };
    mockSearchUsers.mockResolvedValueOnce(searchResult);

    const res = await request(app).get('/users?q=alice');

    expect(res.status).toBe(200);
    expect(res.body).toEqual(searchResult);
    expect(mockSearchUsers).toHaveBeenCalledWith('alice', undefined, undefined);
    expect(mockGetAllUsers).not.toHaveBeenCalled();
  });

  test('forwards limit and offset to searchUsers', async () => {
    mockSearchUsers.mockResolvedValueOnce({ users: [], total: 0, limit: 5, offset: 0, query: 'bob' });

    await request(app).get('/users?q=bob&limit=5&offset=0');

    expect(mockSearchUsers).toHaveBeenCalledWith('bob', '5', '0');
  });

  test('returns 400 when q is an empty string', async () => {
    const res = await request(app).get('/users?q=');

    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/non-empty/);
    expect(mockSearchUsers).not.toHaveBeenCalled();
  });

  test('returns 400 when q is whitespace only', async () => {
    const res = await request(app).get('/users?q=%20%20');

    expect(res.status).toBe(400);
    expect(mockSearchUsers).not.toHaveBeenCalled();
  });

  test('returns 500 when searchUsers throws', async () => {
    mockSearchUsers.mockRejectedValueOnce(new Error('timeout'));

    const res = await request(app).get('/users?q=alice');

    expect(res.status).toBe(500);
    expect(res.body.error).toBe('Internal server error');
  });
});

// ── GET /users/:id ────────────────────────────────────────────────────────────

describe('GET /users/:id', () => {
  beforeEach(() => mockGetUserById.mockReset());

  test('returns 200 with the user when found', async () => {
    mockGetUserById.mockResolvedValueOnce(USER_ALICE);

    const res = await request(app).get('/users/1');

    expect(res.status).toBe(200);
    expect(res.body).toEqual(USER_ALICE);
    expect(mockGetUserById).toHaveBeenCalledWith(1);
  });

  test('returns 404 when getUserById returns null', async () => {
    mockGetUserById.mockResolvedValueOnce(null);

    const res = await request(app).get('/users/999');

    expect(res.status).toBe(404);
    expect(res.body.error).toMatch(/not found/i);
  });

  test('returns 400 for a non-numeric id', async () => {
    const res = await request(app).get('/users/abc');

    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/positive integer/);
    expect(mockGetUserById).not.toHaveBeenCalled();
  });

  test('returns 400 for id = 0', async () => {
    const res = await request(app).get('/users/0');

    expect(res.status).toBe(400);
    expect(mockGetUserById).not.toHaveBeenCalled();
  });

  test('returns 400 for a negative id', async () => {
    const res = await request(app).get('/users/-1');

    expect(res.status).toBe(400);
    expect(mockGetUserById).not.toHaveBeenCalled();
  });

  test('returns 400 for a float id (e.g. 1.5)', async () => {
    const res = await request(app).get('/users/1.5');

    expect(res.status).toBe(400);
    expect(mockGetUserById).not.toHaveBeenCalled();
  });

  test('returns 400 for SQL injection attempt in id path', async () => {
    const res = await request(app).get("/users/1%3BDROP%20TABLE%20users");

    expect(res.status).toBe(400);
    expect(mockGetUserById).not.toHaveBeenCalled();
  });

  test('returns 500 when getUserById throws', async () => {
    mockGetUserById.mockRejectedValueOnce(new Error('connection lost'));

    const res = await request(app).get('/users/1');

    expect(res.status).toBe(500);
    expect(res.body.error).toBe('Internal server error');
  });

  test('does not leak error details in 500 response', async () => {
    mockGetUserById.mockRejectedValueOnce(new Error('pg: password authentication failed for user "root"'));

    const res = await request(app).get('/users/1');

    expect(res.status).toBe(500);
    // Must NOT expose the raw pg error message to the client
    expect(res.body.error).not.toContain('password');
    expect(res.body.error).not.toContain('pg:');
  });
});

// ── 404 for unknown routes ────────────────────────────────────────────────────

describe('Unknown routes', () => {
  test('returns 404 for an unregistered path', async () => {
    const res = await request(app).get('/nonexistent');
    expect(res.status).toBe(404);
  });
});

