/**
 * db.js
 *
 * Creates and exports a single pg.Pool instance shared across the entire
 * application.  All connection parameters are read exclusively from
 * environment variables so that no credentials ever appear in source code.
 *
 * Required environment variable:
 *   DATABASE_URL  – a full PostgreSQL connection string
 *                   e.g. postgres://user:pass@host:5432/dbname
 *
 * Optional tuning variables (all have safe defaults):
 *   DB_POOL_MAX          – maximum number of clients in the pool  (default 10)
 *   DB_IDLE_TIMEOUT_MS   – ms a client may sit idle before release (default 30000)
 *   DB_CONN_TIMEOUT_MS   – ms to wait for a free client             (default 5000)
 *   DB_STATEMENT_TIMEOUT – ms a single query may run                (default 10000)
 *   NODE_ENV             – when "production" SSL is enforced
 */

'use strict';

const { Pool } = require('pg');

// ── Validate that the required variable is present at start-up ──────────────
if (!process.env.DATABASE_URL) {
  throw new Error(
    '[db] DATABASE_URL environment variable is not set. ' +
      'Provide a PostgreSQL connection string before starting the server.'
  );
}

// ── Pool configuration ───────────────────────────────────────────────────────
const poolConfig = {
  connectionString: process.env.DATABASE_URL,

  // Respect optional tuning knobs, with conservative defaults.
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT_MS ?? '30000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_CONN_TIMEOUT_MS ?? '5000', 10),

  // Hard cap on how long any single statement may run.
  // pg passes this to PostgreSQL as "statement_timeout".
  statement_timeout: parseInt(process.env.DB_STATEMENT_TIMEOUT ?? '10000', 10),
};

// Enforce SSL in production (rejectUnauthorized can be relaxed per deployment).
if (process.env.NODE_ENV === 'production') {
  poolConfig.ssl = { rejectUnauthorized: true };
}

const pool = new Pool(poolConfig);

// ── Pool-level event handlers ────────────────────────────────────────────────

// Log when a brand-new physical connection is established.
pool.on('connect', (client) => {
  console.log(
    `[db] New client connected | pool size: ${pool.totalCount} ` +
      `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`
  );

  // Set the application name so the connection is identifiable in pg_stat_activity.
  client.query("SET application_name = 'express-users-api'").catch(() => {});
});

// Warn when a client is returned to the pool after an error.
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle pool client:', err.message);
});

// ── Graceful shutdown ────────────────────────────────────────────────────────
// Drain the pool cleanly when the Node process is stopped so that in-flight
// queries finish and connections are closed properly.
const shutdown = async (signal) => {
  console.log(`[db] ${signal} received – draining connection pool…`);
  try {
    await pool.end();
    console.log('[db] Pool drained. Goodbye.');
  } catch (err) {
    console.error('[db] Error while draining pool:', err.message);
  }
};

process.once('SIGINT', () => shutdown('SIGINT'));
process.once('SIGTERM', () => shutdown('SIGTERM'));

module.exports = pool;

/**
 * queries.js
 *
 * Parameterised query functions for the /users domain.
 *
 * Every public function:
 *   • uses $1 / $2 … placeholders (never string interpolation) so that the
 *     pg driver sends values as separate protocol-level parameters – the
 *     canonical defence against SQL injection.
 *   • validates and coerces its own arguments before touching the database,
 *     providing a second line of defence.
 *   • records wall-clock timing and emits structured log lines.
 *   • returns plain objects / arrays; HTTP concerns live in app.js.
 *
 * Exported functions
 * ──────────────────
 *   getUserById(id)                     → user row or null
 *   getAllUsers(limit, offset)          → { rows, total }
 *   searchUsers(query, limit, offset)   → { rows, total }
 */

'use strict';

const pool = require('./db');

// ── Internal helpers ─────────────────────────────────────────────────────────

/**
 * Thin wrapper around pool.query that:
 *   1. Adds a correlation id to each log line (monotonic counter).
 *   2. Measures and logs wall-clock execution time.
 *   3. Logs the parameterised SQL text (never the bound values, which could
 *      contain PII) so engineers can diagnose slow queries without leaking data.
 *
 * @param {string}  sql    – parameterised SQL string
 * @param {Array}   params – bound values corresponding to $1, $2, …
 * @returns {Promise<import('pg').QueryResult>}
 */
let _queryCounter = 0;

async function timedQuery(sql, params = []) {
  const queryId = ++_queryCounter;
  const start = process.hrtime.bigint();

  console.log(
    `[db:query #${queryId}] Executing | params count: ${params.length} | sql: ${sql.replace(/\s+/g, ' ').trim()}`
  );

  try {
    const result = await pool.query(sql, params);
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.log(
      `[db:query #${queryId}] OK | rows: ${result.rowCount} | duration: ${durationMs.toFixed(3)} ms`
    );

    return result;
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.error(
      `[db:query #${queryId}] ERROR | duration: ${durationMs.toFixed(3)} ms | ` +
        `code: ${err.code ?? 'unknown'} | message: ${err.message}`
    );

    // Re-throw so callers / Express error handlers can decide the HTTP response.
    throw err;
  }
}

// ── Validation helpers ───────────────────────────────────────────────────────

/**
 * Parses a value as a positive integer.
 * Throws a TypeError with a descriptive message when the value is invalid.
 *
 * @param {*}      value
 * @param {string} name   – parameter name used in the error message
 * @returns {number}
 */
function parsePositiveInt(value, name) {
  const n = parseInt(value, 10);
  if (!Number.isFinite(n) || n < 0) {
    throw new TypeError(`Invalid value for "${name}": must be a non-negative integer (got ${JSON.stringify(value)})`);
  }
  return n;
}

/**
 * Parses a value as a strictly-positive integer.
 * Throws a TypeError when the value is ≤ 0 or not a number.
 *
 * @param {*}      value
 * @param {string} name
 * @param {number} max   – upper bound (inclusive) to prevent runaway queries
 * @returns {number}
 */
function parseLimit(value, name, max = 100) {
  const n = parseInt(value, 10);
  if (!Number.isFinite(n) || n <= 0) {
    throw new TypeError(`Invalid value for "${name}": must be a positive integer (got ${JSON.stringify(value)})`);
  }
  if (n > max) {
    throw new TypeError(`Value for "${name}" exceeds the maximum allowed (${max})`);
  }
  return n;
}

/**
 * Strips any character that is not a printable ASCII character or common
 * Unicode letter/digit, then trims whitespace.
 *
 * This is an additional belt-and-braces measure: because the value is sent
 * as a query parameter (never interpolated into SQL), the database driver
 * already prevents injection.  The sanitisation here guards the application
 * layer against unexpected binary data.
 *
 * @param {*}      value
 * @param {number} maxLength
 * @returns {string}
 */
function sanitiseSearchQuery(value, maxLength = 200) {
  if (typeof value !== 'string') {
    throw new TypeError(`Search query must be a string (got ${typeof value})`);
  }

  // Remove ASCII control characters (0x00–0x1F and 0x7F).
  // Everything else – including multibyte Unicode – is kept so that the
  // search can still work with non-Latin names.
  const cleaned = value.replace(/[\x00-\x1F\x7F]/g, '').trim();

  if (cleaned.length === 0) {
    throw new TypeError('Search query must not be empty after sanitisation');
  }
  if (cleaned.length > maxLength) {
    throw new TypeError(`Search query exceeds the maximum length of ${maxLength} characters`);
  }

  return cleaned;
}

// ── Public query functions ───────────────────────────────────────────────────

/**
 * Fetches a single user by their primary-key id.
 *
 * SQL injection prevention
 * ────────────────────────
 * The id is passed as the bound parameter $1.  Even if a caller somehow
 * smuggled SQL syntax into the value it would be treated as a literal by
 * PostgreSQL and never executed as code.
 *
 * @param {number|string} id – the user's integer primary key
 * @returns {Promise<Object|null>} the user row, or null when not found
 */
async function getUserById(id) {
  // Validate before hitting the database.
  const numericId = parsePositiveInt(id, 'id');
  if (numericId === 0) {
    throw new TypeError('id must be greater than 0');
  }

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
      AND deleted_at IS NULL
  `;

  const { rows } = await timedQuery(sql, [numericId]);
  return rows[0] ?? null;
}

/**
 * Returns a paginated list of all (non-deleted) users.
 *
 * SQL injection prevention
 * ────────────────────────
 * Both limit and offset are cast to integers before use and passed as
 * bound parameters $1 / $2.  PostgreSQL's pg_catalog.int4 cast would
 * reject a non-integer at the protocol level even without our validation.
 *
 * @param {number} limit  – maximum number of rows to return (1–100, default 20)
 * @param {number} offset – number of rows to skip (default 0)
 * @returns {Promise<{ rows: Object[], total: number }>}
 */
async function getAllUsers(limit = 20, offset = 0) {
  const safeLimit = parseLimit(limit, 'limit', 100);
  const safeOffset = parsePositiveInt(offset, 'offset');

  // Fetch the page and the total count in a single round-trip.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER () AS total_count
    FROM users
    WHERE deleted_at IS NULL
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const { rows } = await timedQuery(sql, [safeLimit, safeOffset]);

  return {
    rows: rows.map(({ total_count, ...user }) => user),
    total: rows.length > 0 ? parseInt(rows[0].total_count, 10) : 0,
  };
}

/**
 * Full-text search over user names and emails.
 *
 * The search term is wrapped in % wildcards for a LIKE / ILIKE query.
 * ILIKE is PostgreSQL-specific and performs a case-insensitive match.
 *
 * SQL injection prevention
 * ────────────────────────
 * The search term is:
 *   1. Validated as a non-empty string.
 *   2. Stripped of ASCII control characters by sanitiseSearchQuery().
 *   3. Passed as the bound parameter $1 – it is NEVER interpolated into SQL.
 *
 * Wildcards inside the term (% and _) are escaped with a custom ESCAPE
 * clause so that a user cannot widen their own search by typing '%'.
 *
 * @param {string} query   – search term (matched against name and email)
 * @param {number} limit   – max rows (1–100, default 20)
 * @param {number} offset  – rows to skip (default 0)
 * @returns {Promise<{ rows: Object[], total: number }>}
 */
async function searchUsers(query, limit = 20, offset = 0) {
  const cleanQuery = sanitiseSearchQuery(query);
  const safeLimit = parseLimit(limit, 'limit', 100);
  const safeOffset = parsePositiveInt(offset, 'offset');

  // Escape LIKE metacharacters inside the user-supplied term so that they
  // are treated as literals.  The escape character is '\' (backslash).
  const escapedTerm = cleanQuery
    .replace(/\\/g, '\\\\') // must be first
    .replace(/%/g, '\\%')
    .replace(/_/g, '\\_');

  const likePattern = `%${escapedTerm}%`;

  // Window function gives us the total match count without a second query.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER () AS total_count
    FROM users
    WHERE deleted_at IS NULL
      AND (
            name  ILIKE $1 ESCAPE '\\'
         OR email ILIKE $1 ESCAPE '\\'
          )
    ORDER BY
      -- Exact-name matches rise to the top; everything else sorts by id.
      CASE WHEN LOWER(name) = LOWER($2) THEN 0 ELSE 1 END,
      id ASC
    LIMIT  $3
    OFFSET $4
  `;

  const { rows } = await timedQuery(sql, [likePattern, cleanQuery, safeLimit, safeOffset]);

  return {
    rows: rows.map(({ total_count, ...user }) => user),
    total: rows.length > 0 ? parseInt(rows[0].total_count, 10) : 0,
  };
}

// ── Exports ──────────────────────────────────────────────────────────────────

module.exports = { getUserById, getAllUsers, searchUsers };

/**
 * app.js
 *
 * Express application wired to a PostgreSQL connection pool.
 *
 * Endpoints
 * ─────────
 *   GET /health               – liveness probe
 *   GET /users                – paginated list of all users
 *   GET /users/search         – full-text search over name / email
 *   GET /users/:id            – single user by primary key
 */

'use strict';

// Load environment variables from a .env file when present.
// In production, variables should be injected by the deployment platform;
// dotenv is intentionally a no-op when variables are already set.
require('dotenv').config();

const express = require('express');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

const app = express();
app.use(express.json());

// ── Middleware ───────────────────────────────────────────────────────────────

/**
 * Request logger – records method, path, status code, and response time on
 * every request without logging query-string values (which may contain PII).
 */
app.use((req, res, next) => {
  const start = process.hrtime.bigint();

  res.on('finish', () => {
    const durationMs = (Number(process.hrtime.bigint() - start) / 1_000_000).toFixed(3);
    console.log(
      `[http] ${req.method} ${req.path} → ${res.statusCode} (${durationMs} ms)`
    );
  });

  next();
});

// ── Routes ───────────────────────────────────────────────────────────────────

/**
 * GET /health
 *
 * Liveness probe.  Also performs a lightweight DB connectivity check so that
 * load-balancer health checks catch connection-pool exhaustion early.
 */
app.get('/health', async (req, res, next) => {
  try {
    const pool = require('./db');
    await pool.query('SELECT 1');

    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      db: {
        status: 'ok',
        pool: {
          total: pool.totalCount,
          idle: pool.idleCount,
          waiting: pool.waitingCount,
        },
      },
    });
  } catch (err) {
    // Return 503 rather than 500 – the app is alive but not fully ready.
    next(Object.assign(err, { statusCode: 503 }));
  }
});

/**
 * GET /users/search?q=alice&limit=20&offset=0
 *
 * Full-text search over name and email.
 *
 * Query parameters:
 *   q       {string}  – required search term
 *   limit   {number}  – max results per page (default 20, max 100)
 *   offset  {number}  – pagination offset     (default 0)
 *
 * NOTE: This route MUST be registered before /users/:id so that the literal
 * path segment "search" is not captured as an :id parameter.
 */
app.get('/users/search', async (req, res, next) => {
  try {
    const { q, limit = 20, offset = 0 } = req.query;

    if (!q || typeof q !== 'string' || q.trim() === '') {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Query parameter "q" is required and must be a non-empty string.',
      });
    }

    const { rows, total } = await searchUsers(q, limit, offset);

    res.json({
      data: rows,
      meta: {
        total,
        limit: parseInt(limit, 10),
        offset: parseInt(offset, 10),
        returned: rows.length,
      },
    });
  } catch (err) {
    if (err instanceof TypeError) {
      return res.status(400).json({ error: 'Bad Request', message: err.message });
    }
    next(err);
  }
});

/**
 * GET /users?limit=20&offset=0
 *
 * Returns a paginated list of all users.
 *
 * Query parameters:
 *   limit   {number}  – max results per page (default 20, max 100)
 *   offset  {number}  – pagination offset     (default 0)
 */
app.get('/users', async (req, res, next) => {
  try {
    const { limit = 20, offset = 0 } = req.query;
    const { rows, total } = await getAllUsers(limit, offset);

    res.json({
      data: rows,
      meta: {
        total,
        limit: parseInt(limit, 10),
        offset: parseInt(offset, 10),
        returned: rows.length,
      },
    });
  } catch (err) {
    if (err instanceof TypeError) {
      return res.status(400).json({ error: 'Bad Request', message: err.message });
    }
    next(err);
  }
});

/**
 * GET /users/:id
 *
 * Returns a single user whose primary key matches :id.
 * Responds with 404 when no matching (non-deleted) row exists.
 */
app.get('/users/:id', async (req, res, next) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: `No user found with id ${req.params.id}.`,
      });
    }

    res.json({ data: user });
  } catch (err) {
    if (err instanceof TypeError) {
      return res.status(400).json({ error: 'Bad Request', message: err.message });
    }
    next(err);
  }
});

// ── Central error handler ────────────────────────────────────────────────────

/**
 * Catches any error passed to next().
 * Never leaks internal error details to clients in production.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  const statusCode = err.statusCode ?? 500;

  // Always log the full error server-side.
  console.error(`[error] ${req.method} ${req.path} → ${statusCode}:`, err.message);
  if (statusCode === 500) console.error(err.stack);

  const body = {
    error: statusCode === 500 ? 'Internal Server Error' : err.message,
  };

  // Expose details only outside production to avoid leaking internals.
  if (process.env.NODE_ENV !== 'production') {
    body.detail = err.message;
  }

  res.status(statusCode).json(body);
});

// ── Server bootstrap ─────────────────────────────────────────────────────────

const PORT = parseInt(process.env.PORT ?? '3000', 10);

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`[http] Server listening on port ${PORT} (${process.env.NODE_ENV ?? 'development'})`);
  });
}

module.exports = app;

/**
 * queries.test.js
 *
 * Unit tests for queries.js.
 *
 * The pg pool is mocked so these tests run without a real database.
 * Run with:  node queries.test.js
 */

'use strict';

// ── Minimal assertion helper ─────────────────────────────────────────────────
let passed = 0;
let failed = 0;

function assert(condition, label) {
  if (condition) {
    console.log(`  ✓ ${label}`);
    passed++;
  } else {
    console.error(`  ✗ ${label}`);
    failed++;
  }
}

async function assertRejects(fn, expectedType, label) {
  try {
    await fn();
    console.error(`  ✗ ${label}  (expected rejection, got resolution)`);
    failed++;
  } catch (err) {
    if (err instanceof expectedType) {
      console.log(`  ✓ ${label}`);
      passed++;
    } else {
      console.error(`  ✗ ${label}  (wrong error type: ${err.constructor.name}: ${err.message})`);
      failed++;
    }
  }
}

// ── Mock the pool so queries.js never opens a real connection ────────────────

// We intercept require('pg') before queries.js is loaded.
const Module = require('module');
const originalLoad = Module._load.bind(Module);

// Stores the next mock result queries should return.
let _mockResult = { rows: [], rowCount: 0 };
// Stores each call made to pool.query for inspection.
const queryCalls = [];

const mockPool = {
  query(sql, params) {
    queryCalls.push({ sql, params });
    return Promise.resolve({ ..._mockResult });
  },
  // Pool stats (used by /health)
  totalCount: 1,
  idleCount: 1,
  waitingCount: 0,
  on() {},
  end() { return Promise.resolve(); },
};

Module._load = function (request, parent, isMain) {
  if (request === 'pg') {
    return { Pool: class { constructor() { return mockPool; } } };
  }
  return originalLoad(request, parent, isMain);
};

// Set required env var before loading db.js / queries.js
process.env.DATABASE_URL = 'postgres://mock:mock@localhost/mock';

// Now load the module under test.
const { getUserById, getAllUsers, searchUsers } = require('./queries');

// ── Test suites ──────────────────────────────────────────────────────────────

async function testGetUserById() {
  console.log('\n▶ getUserById');
  queryCalls.length = 0;

  // ── found ──
  _mockResult = {
    rows: [{ id: 1, name: 'Alice', email: 'alice@example.com', created_at: null, updated_at: null }],
    rowCount: 1,
  };
  const user = await getUserById(1);
  assert(user.id === 1, 'returns the user row when found');
  assert(queryCalls.length === 1, 'issues exactly one query');
  assert(
    queryCalls[0].sql.includes('WHERE id = $1'),
    'SQL contains parameterised WHERE clause'
  );
  assert(
    Array.isArray(queryCalls[0].params) && queryCalls[0].params[0] === 1,
    'bound parameter is the numeric id'
  );

  // ── not found ──
  queryCalls.length = 0;
  _mockResult = { rows: [], rowCount: 0 };
  const missing = await getUserById(999);
  assert(missing === null, 'returns null when user is not found');

  // ── string id coercion ──
  queryCalls.length = 0;
  _mockResult = { rows: [{ id: 42, name: 'Bob', email: 'bob@example.com', created_at: null, updated_at: null }], rowCount: 1 };
  const byString = await getUserById('42');
  assert(byString.id === 42, 'accepts a numeric string as id');

  // ── invalid ids ──
  await assertRejects(() => getUserById('abc'),  TypeError, 'rejects non-numeric id');
  await assertRejects(() => getUserById(0),      TypeError, 'rejects id of 0');
