  // The function resolves (safely) rather than rejects.
  queryCalls.length = 0;
  _mockResult = { rows: [{ id: 1, name: 'Alice', email: 'alice@example.com', created_at: null, updated_at: null }], rowCount: 1 };
  await getUserById('1; DROP TABLE users--');
  assert(
    queryCalls[0].params[0] === 1,
    'SQL injection attempt in id: only the integer 1 reaches the DB as a bound param'
  );
  assert(
    !queryCalls[0].sql.includes('DROP'),
    'SQL injection attempt in id: DROP keyword never appears in the query string'
  );
}

async function testGetAllUsers() {
  console.log('\n▶ getAllUsers');
  queryCalls.length = 0;

  const fakeRows = [
    { id: 1, name: 'Alice', email: 'a@x.com', created_at: null, updated_at: null, total_count: '2' },
    { id: 2, name: 'Bob',   email: 'b@x.com', created_at: null, updated_at: null, total_count: '2' },
  ];
  _mockResult = { rows: fakeRows, rowCount: 2 };

  const result = await getAllUsers(10, 0);

  assert(Array.isArray(result.rows), 'returns a rows array');
  assert(result.rows.length === 2, 'returns correct number of rows');
  assert(result.total === 2, 'returns correct total from window function');
  assert(!('total_count' in result.rows[0]), 'strips total_count from row objects');

