  assert(queryCalls[0].params[1] === 0,  'offset is passed as $2');
  assert(
    queryCalls[0].sql.includes('LIMIT  $1') && queryCalls[0].sql.includes('OFFSET $2'),
    'SQL uses parameterised LIMIT / OFFSET'
