  await assertRejects(() => getAllUsers(-1),   TypeError, 'rejects negative limit');
  await assertRejects(() => getAllUsers(101),  TypeError, 'rejects limit above maximum (100)');
  await assertRejects(() => getAllUsers(10, -1), TypeError, 'rejects negative offset');
  await assertRejects(() => getAllUsers('many'), TypeError, 'rejects non-numeric limit string');
}

