  console.log('\n▶ searchUsers');
  queryCalls.length = 0;

  const fakeRows = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: null, updated_at: null, total_count: '1' },
  ];
  _mockResult = { rows: fakeRows, rowCount: 1 };

  const result = await searchUsers('alice');

  assert(Array.isArray(result.rows), 'returns a rows array');
  assert(result.total === 1, 'returns correct total');
  assert(!('total_count' in result.rows[0]), 'strips total_count from rows');

