  assert(queryCalls[0].params[1] === 'alice', 'passes clean term as $2 for exact-match ranking');
  assert(queryCalls[0].params[2] === 20,  'default limit 20 is $3');
  assert(queryCalls[0].params[3] === 0,   'default offset 0 is $4');
