  await assertRejects(() => searchUsers(''),         TypeError, 'rejects empty search query');
  await assertRejects(() => searchUsers(123),        TypeError, 'rejects non-string query');
  await assertRejects(() => searchUsers('x', 0),    TypeError, 'rejects limit of 0');
  await assertRejects(() => searchUsers('x', 101),  TypeError, 'rejects limit above maximum');
  await assertRejects(() => searchUsers('x', 10, -1), TypeError, 'rejects negative offset');
  await assertRejects(
    () => searchUsers('a'.repeat(201)),
    TypeError,
    'rejects query longer than 200 characters'
  );
