/**
 * db.js — PostgreSQL connection pool
 *
 * Reads connection configuration exclusively from environment variables so
 * no credentials are ever hard-coded.  In production, set DATABASE_URL (or
 * the individual PG* variables) before starting the process.
 *
 * Pool tuning knobs are also env-driven so they can be adjusted per
 * environment (dev / staging / prod) without code changes.
 *
 * Usage
 * -----
 *   const pool = require('./db');
 *   const { rows } = await pool.query('SELECT $1::text AS msg', ['hello']);
 */

'use strict';

const { Pool } = require('pg');

// ── Validate that a connection string is present ─────────────────────────────
if (!process.env.DATABASE_URL) {
  // Emit a clear startup error rather than a cryptic connection failure later.
  throw new Error(
    '[db] DATABASE_URL environment variable is not set. ' +
    'Export it before starting the server:\n' +
    '  export DATABASE_URL=postgres://user:password@host:5432/dbname'
  );
}

// ── Pool configuration ────────────────────────────────────────────────────────
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Never allow SSL to be disabled in production unless explicitly opted-out.
  ssl: process.env.DB_SSL === 'false'
    ? false
    : { rejectUnauthorized: process.env.DB_SSL_REJECT_UNAUTHORIZED !== 'false' },

  // Pool sizing — sensible defaults, overridable via env.
  max:              parseInt(process.env.DB_POOL_MAX      ?? '10',  10),
  min:              parseInt(process.env.DB_POOL_MIN      ?? '2',   10),
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT ?? '30000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_CONN_TIMEOUT ?? '5000', 10),

  // Immediately surface stale connections instead of silently retrying.
  allowExitOnIdle: false,
});

// ── Pool-level event hooks ─────────────────────────────────────────────────────
pool.on('connect', (client) => {
  // Tag every new physical connection for easier server-side log correlation.
  client.query("SET application_name = 'users-api'").catch(() => {});
  console.log('[db] New client connected to pool');
});

pool.on('acquire', () => {
  // Uncomment for verbose connection tracing in development:
  // console.debug('[db] Client acquired from pool');
});

pool.on('remove', () => {
  console.log('[db] Client removed from pool');
});

pool.on('error', (err) => {
  // An idle client has emitted an error — log it and keep the process alive.
  // The pool will automatically replace the broken connection.
  console.error('[db] Unexpected error on idle pool client:', err.message);
});

module.exports = pool;

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design principles
 * -----------------
 * • SQL injection prevention  — every user-supplied value is passed as a
 *   positional parameter ($1, $2 …).  Values are NEVER interpolated into the
 *   SQL string.  pg sends parameters over a separate wire channel so the
 *   database engine always treats them as data, never as SQL syntax.
 *
 * • Connection pooling — all functions receive the shared Pool instance
 *   (injected via `createQueries(pool)`) and call pool.query() which
 *   automatically checks out a client, runs the query, then returns it.
 *   Long-running transactions can instead call pool.connect() / client.release().
 *
 * • Query timing — every call is wrapped in a high-resolution timer.
 *   Slow queries (> SLOW_QUERY_THRESHOLD_MS) are logged at WARN level so
 *   they can be caught without enabling full query logging in production.
 *
 * • Input validation — lightweight validation runs before the query is sent
 *   to the database, giving callers a meaningful error rather than a DB error.
 *
 * • Pagination safety — limit is capped at MAX_LIMIT and offset is checked
 *   to be non-negative so callers cannot request unbounded result sets.
 *
 * • Search sanitisation — even though pg parameterisation prevents injection,
 *   LIKE wildcards inside the value itself are escaped so a caller cannot
 *   craft a '%_%' pattern that performs a catastrophic scan.
 *
 * Exported API
 * ------------
 *   const q = createQueries(pool);
 *   await q.getUserById(id)              → row | null
 *   await q.getAllUsers(limit, offset)   → { users, total, limit, offset }
 *   await q.searchUsers(query, limit, offset) → { users, total, query, limit, offset }
 */

'use strict';

// ── Constants ─────────────────────────────────────────────────────────────────

/** Queries that take longer than this are logged as warnings. */
const SLOW_QUERY_THRESHOLD_MS = 200;

/** Hard upper bound on page size to prevent runaway result sets. */
const MAX_LIMIT = 100;

/** Default page size when the caller omits `limit`. */
const DEFAULT_LIMIT = 20;

// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * logQueryTiming — records how long a labelled query took and warns if slow.
 *
 * @param {string}  label   - Human-readable name for log output.
 * @param {number}  startHr - Value returned by process.hrtime.bigint() before
 *                            the query was sent.
 * @param {object}  result  - pg QueryResult object (has a `rowCount` property).
 */
function logQueryTiming(label, startHr, result) {
  const elapsedNs  = process.hrtime.bigint() - startHr;
  const elapsedMs  = Number(elapsedNs) / 1_000_000;
  const rowCount   = result?.rowCount ?? 0;
  const logMessage = `[db:timing] ${label} — ${elapsedMs.toFixed(3)} ms, ${rowCount} row(s)`;

  if (elapsedMs >= SLOW_QUERY_THRESHOLD_MS) {
    console.warn(`[SLOW QUERY] ${logMessage}`);
  } else {
    console.log(logMessage);
  }
}

/**
 * escapeLikeWildcards — escapes pg LIKE special characters inside a value.
 *
 * Prevents a caller from passing '%' or '_' as part of a search term to
 * craft unintended pattern matches.  The ESCAPE clause in the SQL tells
 * Postgres which character we chose as the escape character.
 *
 * @param  {string} raw - Unescaped user-supplied search string.
 * @returns {string} Safe string ready for use as a LIKE operand value.
 */
function escapeLikeWildcards(raw) {
  return raw
    .replace(/\\/g, '\\\\') // escape the escape char first
    .replace(/%/g,  '\\%')  // literal percent
    .replace(/_/g,  '\\_'); // literal underscore
}

/**
 * validatePositiveInteger — throws a TypeError if value is not a safe,
 * non-negative integer.
 *
 * @param {*}      value     - Value to test.
 * @param {string} fieldName - Name shown in the error message.
 */
function validatePositiveInteger(value, fieldName) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0 || !Number.isFinite(n)) {
    throw new TypeError(
      `[queries] "${fieldName}" must be a non-negative integer, got: ${JSON.stringify(value)}`
    );
  }
}

/**
 * validateId — throws if id is not a valid positive integer primary key.
 *
 * @param {*} id - Value to test.
 */
function validateId(id) {
  const n = Number(id);
  if (!Number.isInteger(n) || n <= 0 || !Number.isFinite(n)) {
    throw new TypeError(
      `[queries] "id" must be a positive integer, got: ${JSON.stringify(id)}`
    );
  }
}

/**
 * validateSearchQuery — throws if the search string is empty or suspiciously
 * long (> 200 chars).  The actual injection prevention is handled by
 * parameterisation; this is a UX and DoS guard.
 *
 * @param {string} query - User-supplied search term.
 */
function validateSearchQuery(query) {
  if (typeof query !== 'string' || query.trim().length === 0) {
    throw new TypeError('[queries] "query" must be a non-empty string');
  }
  if (query.length > 200) {
    throw new TypeError('[queries] "query" must be 200 characters or fewer');
  }
}

// ── Factory ───────────────────────────────────────────────────────────────────

/**
 * createQueries — injects the pool dependency and returns query functions.
 *
 * Accepting the pool as a parameter (rather than requiring db.js directly)
 * keeps queries.js unit-testable: tests can inject a mock pool without
 * touching the real database.
 *
 * @param   {import('pg').Pool} pool - Active pg Pool instance.
 * @returns {object} Object containing getUserById, getAllUsers, searchUsers.
 */
function createQueries(pool) {

  // ── getUserById ─────────────────────────────────────────────────────────────
  /**
   * Fetches a single user by primary key.
   *
   * SQL injection prevention: `id` is passed as $1.  Postgres receives the
   * integer value through the extended query protocol, completely separate
   * from the query text — the database never parses it as SQL.
   *
   * @param   {number|string} id - User's primary key (positive integer).
   * @returns {Promise<object|null>} User row, or null if not found.
   */
  async function getUserById(id) {
    validateId(id);

    const sql = `
      SELECT
        id,
        name,
        email,
        created_at,
        updated_at
      FROM users
      WHERE id = $1
        AND deleted_at IS NULL
    `;
    // $1 is the ONLY way user data enters the query — never via interpolation.
    const params = [Number(id)];

    const start = process.hrtime.bigint();
    try {
      const result = await pool.query(sql, params);
      logQueryTiming('getUserById', start, result);
      return result.rows[0] ?? null;
    } catch (err) {
      console.error(`[db:error] getUserById(${id}):`, err.message);
      throw err;
    }
  }

  // ── getAllUsers ─────────────────────────────────────────────────────────────
  /**
   * Returns a paginated list of all active users together with the total count
   * so the caller can calculate page numbers without a separate COUNT query.
   *
   * SQL injection prevention: limit ($1) and offset ($2) are integers that
   * pass through pg's type coercion — never part of the query string.
   *
   * @param   {number} [limit=DEFAULT_LIMIT]  - Max rows to return (capped at MAX_LIMIT).
   * @param   {number} [offset=0]             - Number of rows to skip.
   * @returns {Promise<{users: object[], total: number, limit: number, offset: number}>}
   */
  async function getAllUsers(limit = DEFAULT_LIMIT, offset = 0) {
    validatePositiveInteger(limit,  'limit');
    validatePositiveInteger(offset, 'offset');

    // Clamp limit to the hard upper bound.
    const safeLimit  = Math.min(Number(limit),  MAX_LIMIT);
    const safeOffset = Number(offset);

    // A single query using a window function avoids a second round-trip to
    // fetch the total count while still returning paginated rows.
    const sql = `
      SELECT
        id,
        name,
        email,
        created_at,
        updated_at,
        COUNT(*) OVER() AS total_count
      FROM users
      WHERE deleted_at IS NULL
      ORDER BY id ASC
      LIMIT  $1
      OFFSET $2
    `;
    const params = [safeLimit, safeOffset];

    const start = process.hrtime.bigint();
    try {
      const result = await pool.query(sql, params);
      logQueryTiming('getAllUsers', start, result);

      const total = result.rows.length > 0
        ? parseInt(result.rows[0].total_count, 10)
        : 0;

      // Strip the internal total_count column from each user object.
      const users = result.rows.map(({ total_count, ...user }) => user);

      return { users, total, limit: safeLimit, offset: safeOffset };
    } catch (err) {
      console.error(`[db:error] getAllUsers(limit=${safeLimit}, offset=${safeOffset}):`, err.message);
      throw err;
    }
  }

  // ── searchUsers ─────────────────────────────────────────────────────────────
  /**
   * Full text search across name and email with pagination.
   *
   * SQL injection prevention
   * -----------------------
   * • The search term is passed as $1 — a parameterised value.
   * • LIKE wildcards within the value are escaped via escapeLikeWildcards()
   *   so '%' / '_' in user input matches literal characters, not patterns.
   * • The ESCAPE '\\' clause tells Postgres which character we use as an
   *   escape prefix, completing the LIKE-wildcard-injection defence.
   * • ILIKE is used for case-insensitive matching without LOWER() overhead.
   *
   * @param   {string} query              - Search term (≤ 200 chars).
   * @param   {number} [limit=DEFAULT_LIMIT]  - Max rows (capped at MAX_LIMIT).
   * @param   {number} [offset=0]             - Rows to skip.
   * @returns {Promise<{users: object[], total: number, query: string, limit: number, offset: number}>}
   */
  async function searchUsers(query, limit = DEFAULT_LIMIT, offset = 0) {
    validateSearchQuery(query);
    validatePositiveInteger(limit,  'limit');
    validatePositiveInteger(offset, 'offset');

    const safeLimit   = Math.min(Number(limit),  MAX_LIMIT);
    const safeOffset  = Number(offset);

    // Escape LIKE special chars, then wrap with % for a contains-match.
    const likePattern = `%${escapeLikeWildcards(query.trim())}%`;

    const sql = `
      SELECT
        id,
        name,
        email,
        created_at,
        updated_at,
        COUNT(*) OVER() AS total_count
      FROM users
      WHERE deleted_at IS NULL
        AND (
              name  ILIKE $1 ESCAPE '\\'
           OR email ILIKE $1 ESCAPE '\\'
        )
      ORDER BY
        -- Exact name matches rank above partial ones.
        CASE WHEN LOWER(name) = LOWER($2) THEN 0 ELSE 1 END,
        id ASC
      LIMIT  $3
      OFFSET $4
    `;
    // $1 = LIKE pattern (wildcards already included)
    // $2 = raw trimmed query (for the exact-match ranking expression)
    // $3 = limit
    // $4 = offset
    const params = [likePattern, query.trim(), safeLimit, safeOffset];

    const start = process.hrtime.bigint();
    try {
      const result = await pool.query(sql, params);
      logQueryTiming('searchUsers', start, result);

      const total = result.rows.length > 0
        ? parseInt(result.rows[0].total_count, 10)
        : 0;

      const users = result.rows.map(({ total_count, ...user }) => user);

      return {
        users,
        total,
        query: query.trim(),
        limit: safeLimit,
        offset: safeOffset,
      };
    } catch (err) {
      console.error(`[db:error] searchUsers("${query}", limit=${safeLimit}, offset=${safeOffset}):`, err.message);
      throw err;
    }
  }

  return { getUserById, getAllUsers, searchUsers };
}

module.exports = { createQueries, MAX_LIMIT, DEFAULT_LIMIT };

/**
 * app.js — Express application wired to the database query layer
 *
 * Endpoints
 * ---------
 *   GET /health
 *   GET /users              — paginated list  (?limit=&offset=)
 *   GET /users/search       — search          (?q=&limit=&offset=)
 *   GET /users/:id          — single user by primary key
 */

'use strict';

const express = require('express');

// ── Database pool ─────────────────────────────────────────────────────────────
// db.js reads DATABASE_URL from the environment.  If the variable is absent
// the module throws at require-time so the process never starts misconfigured.
const pool   = require('./db');

// ── Query functions ───────────────────────────────────────────────────────────
const { createQueries } = require('./queries');
const queries = createQueries(pool);

// ── App setup ─────────────────────────────────────────────────────────────────
const app = express();
app.use(express.json());

// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * parseIntParam — parses a query-string integer, returning `fallback` when the
 * param is absent, and throwing a 400-tagged Error when it is malformed.
 *
 * @param {string|undefined} raw      - Raw query-string value.
 * @param {string}           name     - Parameter name (used in error message).
 * @param {number}           fallback - Value to use when raw is undefined.
 * @returns {number}
 */
function parseIntParam(raw, name, fallback) {
  if (raw === undefined || raw === '') return fallback;
  const n = Number(raw);
  if (!Number.isInteger(n) || n < 0) {
    const err = new Error(`"${name}" must be a non-negative integer`);
    err.status = 400;
    throw err;
  }
  return n;
}

/**
 * asyncHandler — wraps an async route handler so Express receives uncaught
 * promise rejections via next(err) rather than an unhandled rejection.
 *
 * @param {Function} fn - Async (req, res, next) handler.
 * @returns {Function}
 */
function asyncHandler(fn) {
  return (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);
}

// ── Routes ────────────────────────────────────────────────────────────────────

// GET /health — liveness probe (also checks pool connectivity)
app.get('/health', asyncHandler(async (_req, res) => {
  // Quick round-trip to confirm the pool can reach the database.
  await pool.query('SELECT 1');
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
}));

// GET /users/search?q=alice&limit=20&offset=0
//   Must be registered BEFORE /users/:id so Express doesn't treat "search"
//   as an :id value.
app.get('/users/search', asyncHandler(async (req, res) => {
  const { q } = req.query;

  if (!q || String(q).trim().length === 0) {
    return res.status(400).json({
      error: 'Bad Request',
      message: '"q" query parameter is required',
    });
  }

  const limit  = parseIntParam(req.query.limit,  'limit',  20);
  const offset = parseIntParam(req.query.offset, 'offset',  0);

  const result = await queries.searchUsers(String(q), limit, offset);

  res.json(result);
}));

// GET /users?limit=20&offset=0
app.get('/users', asyncHandler(async (req, res) => {
  const limit  = parseIntParam(req.query.limit,  'limit',  20);
  const offset = parseIntParam(req.query.offset, 'offset',  0);

  const result = await queries.getAllUsers(limit, offset);

  res.json(result);
}));

// GET /users/:id
app.get('/users/:id', asyncHandler(async (req, res) => {
  const rawId = req.params.id;
  const id    = Number(rawId);

  if (!Number.isInteger(id) || id <= 0) {
    return res.status(400).json({
      error: 'Bad Request',
      message: '"id" must be a positive integer',
    });
  }

  const user = await queries.getUserById(id);

  if (!user) {
    return res.status(404).json({
      error:   'Not Found',
      message: `User with id ${id} was not found`,
    });
  }

  res.json(user);
}));

// ── Global error handler ──────────────────────────────────────────────────────
// Must have exactly four parameters so Express recognises it as an error handler.
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  // Client errors (400-range): surface the message.
  const status = err.status || 500;
  if (status < 500) {
    return res.status(status).json({ error: 'Bad Request', message: err.message });
  }

  // Server errors: log details internally, return a generic message externally
  // so implementation details are never leaked to callers.
  console.error('[app:error]', err);
  res.status(500).json({ error: 'Internal Server Error', message: 'An unexpected error occurred' });
});

// ── Server startup ────────────────────────────────────────────────────────────
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

/**
 * queries.test.js — unit tests for queries.js
 *
 * A lightweight mock pool is injected in place of a real pg.Pool so these
 * tests run without a database.  The mock records every call so assertions
 * can inspect the exact SQL and parameters that were sent.
 *
 * Run with:  node queries.test.js
 */

'use strict';

const { createQueries, MAX_LIMIT, DEFAULT_LIMIT } = require('./queries');

// ── Tiny assertion helpers ────────────────────────────────────────────────────

let passed = 0;
let failed = 0;

function assert(condition, message) {
  if (condition) {
    console.log(`  ✓  ${message}`);
    passed++;
  } else {
    console.error(`  ✗  ${message}`);
    failed++;
  }
}

function assertEqual(a, b, message) {
  const ok = JSON.stringify(a) === JSON.stringify(b);
  assert(ok, `${message} — expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`);
}

async function assertRejects(fn, expectedMessagePart, message) {
  try {
    await fn();
    console.error(`  ✗  ${message} — expected an error but none was thrown`);
    failed++;
  } catch (err) {
    if (!expectedMessagePart || err.message.includes(expectedMessagePart)) {
      console.log(`  ✓  ${message}`);
      passed++;
    } else {
      console.error(`  ✗  ${message} — error message "${err.message}" does not include "${expectedMessagePart}"`);
      failed++;
    }
  }
}

// ── Mock pool factory ─────────────────────────────────────────────────────────

/**
 * Creates a mock pg.Pool.
 *
 * @param {object[]} rows       - Rows to return from every query call.
 * @param {boolean}  [shouldThrow=false] - If true, query() rejects.
 */
function makeMockPool(rows = [], shouldThrow = false) {
  const calls = [];

  const pool = {
    calls, // expose for assertions

    async query(sql, params) {
      calls.push({ sql: sql.trim().replace(/\s+/g, ' '), params });

      if (shouldThrow) {
        throw new Error('mock db error');
      }

      // Attach total_count to every row when rows exist (mirrors the window fn).
      const enriched = rows.map(r => ({ ...r, total_count: String(rows.length) }));
      return { rows: enriched, rowCount: enriched.length };
    },
  };

  return pool;
}

// ── Test suites ───────────────────────────────────────────────────────────────

async function testGetUserById() {
  console.log('\n▶  getUserById');

  // ── happy path ──────────────────────────────────────────────────────────────
  const fakeUser = { id: 1, name: 'Alice', email: 'alice@example.com',
                     created_at: new Date(), updated_at: new Date() };
  const pool = makeMockPool([fakeUser]);
  const q    = createQueries(pool);

  const user = await q.getUserById(1);
  assert(user !== null,            'returns a user when found');
  assertEqual(user.id,    1,       'returns correct id');
  assertEqual(user.name,  'Alice', 'returns correct name');
  assertEqual(user.email, 'alice@example.com', 'returns correct email');
  assert('total_count' in user === false, 'does not expose total_count');

  // ── SQL shape ───────────────────────────────────────────────────────────────
  const { sql, params } = pool.calls[0];
  assert(sql.includes('WHERE id = $1'),    'uses $1 positional parameter for id');
  assert(sql.includes('deleted_at IS NULL'), 'filters soft-deleted rows');
  assertEqual(params, [1],                 'passes id as the sole parameter');

  // ── returns null when not found ─────────────────────────────────────────────
  const emptyPool = makeMockPool([]);
  const q2        = createQueries(emptyPool);
  const notFound  = await q2.getUserById(99);
  assertEqual(notFound, null, 'returns null when user not found');

  // ── validation ──────────────────────────────────────────────────────────────
  await assertRejects(() => q.getUserById(0),    'positive integer', 'rejects id = 0');
  await assertRejects(() => q.getUserById(-5),   'positive integer', 'rejects negative id');
  await assertRejects(() => q.getUserById('abc'),'positive integer', 'rejects non-numeric id');
  await assertRejects(() => q.getUserById(null), 'positive integer', 'rejects null id');

  // ── SQL injection attempt ────────────────────────────────────────────────────
  // A classic injection payload cannot be an integer, so it must be rejected
  // by validation before it ever reaches the pool.
  await assertRejects(
    () => q.getUserById("1 OR '1'='1'"),
    'positive integer',
    'rejects SQL injection attempt as invalid id'
  );

  // ── db error propagation ────────────────────────────────────────────────────
  const errorPool = makeMockPool([], true);
  const qErr      = createQueries(errorPool);
  await assertRejects(() => qErr.getUserById(1), 'mock db error', 'propagates db errors');
}

// ─────────────────────────────────────────────────────────────────────────────

async function testGetAllUsers() {
  console.log('\n▶  getAllUsers');

  const fakeUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), updated_at: new Date() },
    { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: new Date(), updated_at: new Date() },
  ];
  const pool = makeMockPool(fakeUsers);
  const q    = createQueries(pool);

  // ── happy path ──────────────────────────────────────────────────────────────
  const result = await q.getAllUsers(10, 0);

  assertEqual(result.users.length, 2,  'returns correct number of users');
  assertEqual(result.total,        2,  'total reflects window function count');
  assertEqual(result.limit,        10, 'echoes clamped limit');
  assertEqual(result.offset,       0,  'echoes offset');
  assert('total_count' in result.users[0] === false, 'strips total_count from user rows');

  // ── SQL shape ───────────────────────────────────────────────────────────────
  const { sql, params } = pool.calls[0];
  assert(sql.includes('LIMIT $1'),       'uses $1 for LIMIT');
  assert(sql.includes('OFFSET $2'),      'uses $2 for OFFSET');
  assert(sql.includes('COUNT(*) OVER()'), 'uses window function for total');
  assertEqual(params, [10, 0],           'passes limit and offset as parameters');

  // ── default parameters ───────────────────────────────────────────────────────
  const pool2 = makeMockPool(fakeUsers);
  const q2    = createQueries(pool2);
  const def   = await q2.getAllUsers();
  assertEqual(def.limit,  DEFAULT_LIMIT, 'uses DEFAULT_LIMIT when omitted');
  assertEqual(def.offset, 0,             'uses 0 offset when omitted');

  // ── MAX_LIMIT cap ────────────────────────────────────────────────────────────
  const pool3   = makeMockPool(fakeUsers);
  const q3      = createQueries(pool3);
  const capped  = await q3.getAllUsers(999, 0);
  assertEqual(capped.limit, MAX_LIMIT, `clamps limit to MAX_LIMIT (${MAX_LIMIT})`);
  assertEqual(pool3.calls[0].params[0], MAX_LIMIT, 'sends capped limit to database');

  // ── empty result ─────────────────────────────────────────────────────────────
  const emptyPool = makeMockPool([]);
  const qEmpty    = createQueries(emptyPool);
  const empty     = await qEmpty.getAllUsers();
  assertEqual(empty.users,  [],  'returns empty array when no rows');
  assertEqual(empty.total,  0,   'returns total=0 when no rows');

  // ── validation ──────────────────────────────────────────────────────────────
  await assertRejects(() => q.getAllUsers(-1,  0),   'non-negative', 'rejects negative limit');
  await assertRejects(() => q.getAllUsers(10, -5),   'non-negative', 'rejects negative offset');
  await assertRejects(() => q.getAllUsers('x', 0),   'non-negative', 'rejects non-integer limit');
  await assertRejects(() => q.getAllUsers(10, 'abc'),'non-negative', 'rejects non-integer offset');
}

// ─────────────────────────────────────────────────────────────────────────────

async function testSearchUsers() {
  console.log('\n▶  searchUsers');

  const fakeUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), updated_at: new Date() },
  ];
  const pool = makeMockPool(fakeUsers);
  const q    = createQueries(pool);

  // ── happy path ──────────────────────────────────────────────────────────────
  const result = await q.searchUsers('alice', 10, 0);
  assertEqual(result.users.length, 1,       'returns matching user');
  assertEqual(result.total,        1,       'returns correct total');
  assertEqual(result.query,        'alice', 'echoes trimmed search term');
  assertEqual(result.limit,        10,      'echoes limit');
  assertEqual(result.offset,       0,       'echoes offset');

  // ── SQL shape ───────────────────────────────────────────────────────────────
  const { sql, params } = pool.calls[0];
  assert(sql.includes('ILIKE $1'),         'uses ILIKE with $1 for pattern');
  assert(sql.includes("ESCAPE '\\\\'"),    'includes ESCAPE clause for LIKE wildcards');
  assert(sql.includes('LOWER($2)'),        'uses $2 for exact-match ranking');
  assert(sql.includes('LIMIT $3'),         'uses $3 for LIMIT');
  assert(sql.includes('OFFSET $4'),        'uses $4 for OFFSET');
  assertEqual(params.length, 4,            'sends exactly 4 parameters');

  // ── LIKE pattern wrapping ───────────────────────────────────────────────────
  assert(params[0].startsWith('%') && params[0].endsWith('%'),
    'wraps search term with % wildcards');
  assert(params[0].includes('alice'),      'includes search term inside pattern');

  // ── LIKE wildcard escaping (SQL injection via LIKE meta-chars) ───────────────
  const pool2 = makeMockPool([]);
  const q2    = createQueries(pool2);
  await q2.searchUsers('%_test%', 10, 0);
  const escapedPattern = pool2.calls[0].params[0];
  assert(escapedPattern.includes('\\%'),   'escapes % metacharacter in search term');
  assert(escapedPattern.includes('\\_'),   'escapes _ metacharacter in search term');

  // ── SQL injection via search term ────────────────────────────────────────────
  // The payload is passed as a parameterised value so pg treats it as pure
  // data.  We verify it flows through unmodified to the parameter (not the SQL).
  const pool3  = makeMockPool([]);
  const q3     = createQueries(pool3);
  const inject = "'; DROP TABLE users; --";
  await q3.searchUsers(inject, 10, 0);
  const injCall = pool3.calls[0];
  assert(!injCall.sql.includes('DROP'),    'injection payload never appears in SQL string');
  assert(injCall.params[0].includes('DROP'), 'payload is confined to parameter slot');

  // ── whitespace-only query rejected ──────────────────────────────────────────
  await assertRejects(() => q.searchUsers('   '), 'non-empty', 'rejects whitespace-only query');
  await assertRejects(() => q.searchUsers(''),    'non-empty', 'rejects empty query');
  await assertRejects(() => q.searchUsers(null),  'non-empty', 'rejects null query');

  // ── query length limit ───────────────────────────────────────────────────────
  const long = 'a'.repeat(201);
  await assertRejects(() => q.searchUsers(long), '200 characters', 'rejects query > 200 chars');

  // ── MAX_LIMIT cap ────────────────────────────────────────────────────────────
  const pool4  = makeMockPool([]);
  const q4     = createQueries(pool4);
  const capped = await q4.searchUsers('bob', 999, 0);
  assertEqual(capped.limit, MAX_LIMIT, `clamps limit to MAX_LIMIT (${MAX_LIMIT})`);

  // ── validation ──────────────────────────────────────────────────────────────
  await assertRejects(() => q.searchUsers('x', -1,   0), 'non-negative', 'rejects negative limit');
  await assertRejects(() => q.searchUsers('x',  10, -5), 'non-negative', 'rejects negative offset');
}

// ─────────────────────────────────────────────────────────────────────────────

async function testQueryTimingLogs() {
  console.log('\n▶  Query timing logs');

  const logs = [];
  const warns = [];
  const origLog  = console.log;
  const origWarn = console.warn;
  console.log  = (...a) => { logs.push(a.join(' '));  };
  console.warn = (...a) => { warns.push(a.join(' ')); };

  try {
    // Fast query — should produce a [db:timing] log line.
    const pool = makeMockPool([{ id: 1, name: 'Alice', email: 'a@b.com',
                                  created_at: new Date(), updated_at: new Date() }]);
    const q    = createQueries(pool);
    await q.getUserById(1);

    const timingLog = logs.find(l => l.includes('[db:timing]'));
    assert(!!timingLog,                       'emits a [db:timing] log entry');
    assert(timingLog.includes('getUserById'), 'timing log includes query name');
    assert(timingLog.includes('ms'),          'timing log includes millisecond value');
    assert(timingLog.includes('row(s)'),      'timing log includes row count');

    // Slow-query warning — mock a pool that sleeps past the threshold.
    const THRESHOLD = 200; // ms — must match SLOW_QUERY_THRESHOLD_MS in queries.js
    const slowPool = {
      async query(sql, params) {
        await new Promise(r => setTimeout(r, THRESHOLD + 10));
        return { rows: [], rowCount: 0 };
      },
    };
    const qSlow = createQueries(slowPool);
    await qSlow.getAllUsers(5, 0);

    const slowWarn = warns.find(w => w.includes('[SLOW QUERY]'));
    assert(!!slowWarn,                        'emits a [SLOW QUERY] warning for slow queries');
    assert(slowWarn.includes('getAllUsers'),   'slow query warning includes query name');
  } finally {
    console.log  = origLog;
    console.warn = origWarn;
  }
}

// ── Runner ────────────────────────────────────────────────────────────────────

(async () => {
  console.log('='.repeat(60));
  console.log(' queries.js — unit test suite');
  console.log('='.repeat(60));

  await testGetUserById();
