{
  "name": "express-db-app",
  "version": "1.0.0",
  "description": "Express app with PostgreSQL query layer",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js",
    "test": "jest --runInBand --forceExit"
  },
  "dependencies": {
    "dotenv": "^16.4.5",
    "express": "^4.19.2",
    "pg": "^8.12.0"
  },
  "devDependencies": {
    "jest": "^29.7.0",
    "supertest": "^7.0.0"
  }
}

/**
 * db.js — PostgreSQL connection pool
 *
 * A single Pool instance is created here and shared across the entire
 * application.  Importing this module multiple times is safe because
 * Node's module cache guarantees the Pool is only constructed once.
 *
 * Configuration is read exclusively from environment variables so that
 * no credentials ever appear in source code.
 */

'use strict';

require('dotenv').config();
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------
// All values fall back to pg's own defaults when the environment variable is
// absent, which means the pool still works in development with a local
// default-config Postgres instance.
// ---------------------------------------------------------------------------
const pool = new Pool({
  // pg accepts either a full connection string …
  connectionString: process.env.DATABASE_URL,

  // … or individual fields.  If DATABASE_URL is set the fields below are
  // ignored by pg, but they serve as an explicit, readable fallback.
  host:     process.env.PGHOST     || 'localhost',
  port:     parseInt(process.env.PGPORT || '5432', 10),
  database: process.env.PGDATABASE || 'postgres',
  user:     process.env.PGUSER     || 'postgres',
  password: process.env.PGPASSWORD || '',

  // --- pool sizing ---
  // Keep a minimum of 2 idle clients ready so the first requests after a
  // cold start don't have to wait for a TCP handshake.
  min: parseInt(process.env.PG_POOL_MIN || '2', 10),
  // Hard cap.  Scale this with your expected concurrency.
  max: parseInt(process.env.PG_POOL_MAX || '10', 10),

  // --- timeouts (milliseconds) ---
  // How long to wait for a free client before throwing an error.
  connectionTimeoutMillis: parseInt(process.env.PG_CONNECT_TIMEOUT_MS || '5000',  10),
  // How long a client can sit idle before being closed and removed.
  idleTimeoutMillis:       parseInt(process.env.PG_IDLE_TIMEOUT_MS    || '30000', 10),
  // Maximum lifetime of any client to prevent stale connections.
  maxUses: parseInt(process.env.PG_MAX_USES || '7500', 10),

  // Always parse DATE columns as JS strings rather than Date objects so
  // serialisation over JSON is deterministic.
  // (Applied per-query in queries.js via explicit CAST where needed.)
});

// ---------------------------------------------------------------------------
// Pool-level error handler
// ---------------------------------------------------------------------------
// Without this listener an idle client error would be an unhandled 'error'
// event and would crash the process.
pool.on('error', (err, client) => {
  console.error('[db] Unexpected idle-client error', {
    message: err.message,
    // Intentionally omit err.stack in production to avoid leaking internals.
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

pool.on('connect', () => {
  if (process.env.NODE_ENV !== 'test') {
    console.log('[db] New client connected to pool');
  }
});

pool.on('remove', () => {
  if (process.env.NODE_ENV !== 'test') {
    console.log('[db] Client removed from pool');
  }
});

module.exports = pool;

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design principles
 * -----------------
 * 1. SQL injection prevention
 *    Every dynamic value is passed as a query parameter ($1, $2, …) and
 *    never interpolated into the SQL string.  pg sends parameters to
 *    PostgreSQL in a separate protocol message, so the database driver
 *    itself enforces the boundary between code and data.
 *
 * 2. Input validation before the query reaches the database
 *    Numeric parameters are coerced and range-checked here.  String
 *    parameters are trimmed and length-capped.  This provides a second
 *    defence layer and returns clear 4xx errors instead of database errors.
 *
 * 3. Query timing logs
 *    Every query is wrapped in a thin timer that logs the SQL tag,
 *    parameter count, row count, and elapsed time in milliseconds.  The
 *    actual parameter values are never logged to avoid leaking PII.
 *
 * 4. Connection pooling
 *    All queries use pool.query() (auto-checkout / auto-release).
 *    Transactions use an explicit client from pool.connect() and always
 *    release it in a finally block.
 *
 * 5. Consistent error types
 *    Each exported function throws a plain Error with a `statusCode`
 *    property so that route handlers can map it straight to an HTTP
 *    response without knowing about the database.
 */

'use strict';

const pool = require('./db');

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Executes a parameterised query, logs timing information, and returns the
 * pg Result object.
 *
 * @param {string}   tag    - Short human-readable label used in log output.
 * @param {string}   sql    - The SQL string.  Must use $1…$N placeholders.
 * @param {Array}    params - Bound parameter values (never interpolated).
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(tag, sql, params = []) {
  const start = process.hrtime.bigint();

  try {
    const result = await pool.query(sql, params);
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.log('[query]', {
      tag,
      paramCount: params.length,
      rowCount:   result.rowCount,
      elapsedMs:  parseFloat(elapsedMs.toFixed(3)),
    });

    return result;
  } catch (err) {
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.error('[query:error]', {
      tag,
      paramCount: params.length,
      elapsedMs:  parseFloat(elapsedMs.toFixed(3)),
      // Only expose the pg error code, not the full message, to avoid leaking
      // schema details in production logs.
      pgCode: err.code,
      ...(process.env.NODE_ENV !== 'production' && { message: err.message }),
    });

    throw err;
  }
}

/**
 * Creates an Error with an attached HTTP status code.
 * Route handlers can inspect err.statusCode to choose the response status.
 */
function httpError(statusCode, message) {
  const err = new Error(message);
  err.statusCode = statusCode;
  return err;
}

// ---------------------------------------------------------------------------
// Validation helpers
// ---------------------------------------------------------------------------

/**
 * Coerces `value` to a positive integer and verifies it is within
 * [min, max].  Throws a 400 error with `fieldName` in the message if
 * validation fails.
 */
function validatePositiveInt(value, fieldName, { min = 1, max = Number.MAX_SAFE_INTEGER } = {}) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < min || n > max) {
    throw httpError(
      400,
      `"${fieldName}" must be an integer between ${min} and ${max}, received: ${value}`,
    );
  }
  return n;
}

/**
 * Trims a search string and enforces a maximum length.
 * Returns null when the input is empty so callers can decide what to do.
 */
function validateSearchQuery(value, { maxLength = 200 } = {}) {
  if (value === undefined || value === null) {
    throw httpError(400, '"query" search term is required');
  }

  const trimmed = String(value).trim();

  if (trimmed.length === 0) {
    throw httpError(400, '"query" search term must not be blank');
  }

  if (trimmed.length > maxLength) {
    throw httpError(
      400,
      `"query" search term must not exceed ${maxLength} characters`,
    );
  }

  return trimmed;
}

// ---------------------------------------------------------------------------
// Exported query functions
// ---------------------------------------------------------------------------

/**
 * getUserById(id)
 * ---------------
 * Fetches a single user row by primary key.
 *
 * @param   {number|string} id  - The user's numeric ID.
 * @returns {Promise<object|null>}  The user record, or null if not found.
 * @throws  {Error}  statusCode 400 when id is not a valid positive integer.
 */
async function getUserById(id) {
  const safeId = validatePositiveInt(id, 'id', { min: 1, max: 2_147_483_647 });

  // $1 is substituted by the pg driver on the server side — the string
  // "safeId" is never concatenated into the SQL text.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const { rows } = await timedQuery('getUserById', sql, [safeId]);

  return rows[0] ?? null;
}

/**
 * getAllUsers(limit, offset)
 * -------------------------
 * Returns a paginated slice of the users table, ordered by id for stable
 * pagination.
 *
 * @param   {number|string} limit   - Maximum rows to return (1–100).
 * @param   {number|string} offset  - Number of rows to skip (≥ 0).
 * @returns {Promise<{ users: object[], total: number }>}
 * @throws  {Error}  statusCode 400 on invalid pagination parameters.
 */
async function getAllUsers(limit = 20, offset = 0) {
  const safeLimit  = validatePositiveInt(limit,  'limit',  { min: 1, max: 100 });
  const safeOffset = validatePositiveInt(offset, 'offset', { min: 0, max: Number.MAX_SAFE_INTEGER });

  // Two queries run concurrently: the data page and the total count.
  // Both use parameterised placeholders.
  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM  users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
  `;

  const [dataResult, countResult] = await Promise.all([
    timedQuery('getAllUsers:data',  dataSql,  [safeLimit, safeOffset]),
    timedQuery('getAllUsers:count', countSql, []),
  ]);

  return {
    users:  dataResult.rows,
    total:  parseInt(countResult.rows[0].total, 10),
    limit:  safeLimit,
    offset: safeOffset,
  };
}

/**
 * searchUsers(query)
 * ------------------
 * Full-text search across name and email using PostgreSQL ILIKE.
 * The search term is wrapped in % wildcards *in application code* before
 * being passed as a parameter — it is never concatenated into the SQL text.
 *
 * @param   {string}        query   - The search string (max 200 chars).
 * @param   {number|string} limit   - Maximum rows to return (1–100).
 * @param   {number|string} offset  - Number of rows to skip (≥ 0).
 * @returns {Promise<{ users: object[], total: number }>}
 * @throws  {Error}  statusCode 400 on invalid parameters.
 */
async function searchUsers(query, limit = 20, offset = 0) {
  const safeQuery  = validateSearchQuery(query);
  const safeLimit  = validatePositiveInt(limit,  'limit',  { min: 1, max: 100 });
  const safeOffset = validatePositiveInt(offset, 'offset', { min: 0, max: Number.MAX_SAFE_INTEGER });

  // The % wildcards are constructed in JS and supplied as part of the
  // *parameter value*, not the SQL text.  The pg driver sends them to
  // Postgres over the bind-message protocol path, so the database engine
  // always treats them as data, never as SQL syntax.
  const likePattern = `%${safeQuery}%`;

  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at
    FROM  users
    WHERE name  ILIKE $1
       OR email ILIKE $1
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM  users
    WHERE name  ILIKE $1
       OR email ILIKE $1
  `;

  const [dataResult, countResult] = await Promise.all([
    timedQuery('searchUsers:data',  dataSql,  [likePattern, safeLimit, safeOffset]),
    timedQuery('searchUsers:count', countSql, [likePattern]),
  ]);

  return {
    users:  dataResult.rows,
    total:  parseInt(countResult.rows[0].total, 10),
    limit:  safeLimit,
    offset: safeOffset,
    query:  safeQuery,
  };
}

// ---------------------------------------------------------------------------
// Pool health helper (used by /health endpoint)
// ---------------------------------------------------------------------------

/**
 * Returns current pool metrics without opening a new client.
 * Useful for health-check endpoints and dashboards.
 */
function poolStats() {
  return {
    total:   pool.totalCount,
    idle:    pool.idleCount,
    waiting: pool.waitingCount,
  };
}

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  poolStats,
  // Expose for unit-testing only — not part of the public API.
  _timedQuery:          timedQuery,
  _validatePositiveInt: validatePositiveInt,
  _validateSearchQuery: validateSearchQuery,
};

/**
 * app.js — Express application
 *
 * The /users route family now delegates all database access to queries.js.
 * Route handlers are intentionally thin: they parse HTTP input, call a query
 * function, and serialise the result.  Error handling is centralised in the
 * middleware at the bottom of this file.
 */

'use strict';

require('dotenv').config();
const express = require('express');
const {
  getUserById,
  getAllUsers,
  searchUsers,
  poolStats,
} = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// GET /health
// ---------------------------------------------------------------------------
// Extended to include live pool statistics so infrastructure tooling can
// detect pool exhaustion without a separate metrics endpoint.
// ---------------------------------------------------------------------------
app.get('/health', (req, res) => {
  res.json({
    status:    'ok',
    timestamp: new Date().toISOString(),
    pool:      poolStats(),
  });
});

// ---------------------------------------------------------------------------
// GET /users
// ---------------------------------------------------------------------------
// Supports two modes determined by query-string parameters:
//
//   ?search=<term>          — full-text search across name and email
//   ?limit=<n>&offset=<n>   — paginated list (defaults: limit=20, offset=0)
//
// Both modes accept limit / offset for pagination.
// ---------------------------------------------------------------------------
app.get('/users', async (req, res, next) => {
  try {
    const { search, limit = 20, offset = 0 } = req.query;

    const result = search
      ? await searchUsers(search, limit, offset)
      : await getAllUsers(limit, offset);

    res.json(result);
  } catch (err) {
    next(err);
  }
});

// ---------------------------------------------------------------------------
// GET /users/:id
// ---------------------------------------------------------------------------
app.get('/users/:id', async (req, res, next) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      // Return a 404 rather than an empty body so clients can distinguish
      // "not found" from "empty result set".
      return res.status(404).json({
        error: 'User not found',
        id:    req.params.id,
      });
    }

    res.json(user);
  } catch (err) {
    next(err);
  }
});

// ---------------------------------------------------------------------------
// Centralised error handler
// ---------------------------------------------------------------------------
// Express calls this middleware whenever next(err) is invoked.
// It maps the optional statusCode attached by queries.js to the HTTP
// response status, keeping all HTTP-layer logic out of the query module.
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  const status = err.statusCode || 500;

  // Never expose raw database errors (which may contain schema hints) to the
  // client in production.
  const message =
    status < 500
      ? err.message                     // Validation errors are safe to show.
      : process.env.NODE_ENV === 'production'
        ? 'Internal server error'        // Hide internals in production.
        : err.message;                   // Show full message in development.

  if (status >= 500) {
    console.error('[app] Unhandled error', {
      method:  req.method,
      url:     req.originalUrl,
      status,
      message: err.message,
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
    });
  }

  res.status(status).json({ error: message });
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------
if (require.main === module) {
  const PORT = parseInt(process.env.PORT || '3000', 10);
  app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT}`);
  });
}

module.exports = app;

/**
 * queries.test.js — Unit tests for queries.js
 *
 * The pg pool is mocked entirely, so no real database is required.
 * Tests cover:
 *   - Correct SQL + parameter construction (injection-safety assertions)
 *   - Validation error paths (bad id, bad limit, blank search, etc.)
 *   - Timing log output
 *   - Pool error propagation
 */

'use strict';

// ---------------------------------------------------------------------------
// Mock the pool BEFORE requiring queries.js so the module receives the mock.
// ---------------------------------------------------------------------------
const mockQuery = jest.fn();
const mockPool  = {
  query:        mockQuery,
  totalCount:   3,
  idleCount:    2,
  waitingCount: 0,
  on:           jest.fn(),  // suppress pool event listeners
};

jest.mock('./db', () => mockPool);

const {
  getUserById,
  getAllUsers,
  searchUsers,
  poolStats,
  _validatePositiveInt,
  _validateSearchQuery,
} = require('./queries');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Builds a pg-style QueryResult. */
function pgResult(rows) {
  return { rows, rowCount: rows.length };
}

/** Extracts all console.log / console.error calls whose first arg is a string
 *  matching `tag`. */
function logsMatching(spy, tag) {
  return spy.mock.calls.filter(([first]) =>
    typeof first === 'string' && first.includes(tag),
  );
}

// ---------------------------------------------------------------------------
// Setup / teardown
// ---------------------------------------------------------------------------

let logSpy;
let errorSpy;

beforeEach(() => {
  mockQuery.mockReset();
  logSpy   = jest.spyOn(console, 'log').mockImplementation(() => {});
  errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
});

afterEach(() => {
  logSpy.restore   && logSpy.restore();
  errorSpy.restore && errorSpy.restore();
  jest.restoreAllMocks();
});

// ===========================================================================
// _validatePositiveInt
// ===========================================================================
describe('_validatePositiveInt', () => {
  test('accepts valid integer', () => {
    expect(_validatePositiveInt(5, 'id')).toBe(5);
  });

  test('accepts string integer', () => {
    expect(_validatePositiveInt('42', 'id')).toBe(42);
  });

  test('accepts boundary min', () => {
    expect(_validatePositiveInt(1, 'id', { min: 1 })).toBe(1);
  });

  test('accepts boundary max', () => {
    expect(_validatePositiveInt(100, 'limit', { min: 1, max: 100 })).toBe(100);
  });

  test('throws 400 for zero when min=1', () => {
    const err = (() => {
      try { _validatePositiveInt(0, 'id', { min: 1 }); }
      catch (e) { return e; }
    })();
    expect(err.statusCode).toBe(400);
    expect(err.message).toMatch(/"id"/);
  });

  test('throws 400 for negative value', () => {
    const err = (() => {
      try { _validatePositiveInt(-1, 'offset', { min: 0 }); }
      catch (e) { return e; }
    })();
    expect(err.statusCode).toBe(400);
  });

  test('throws 400 for float', () => {
    const err = (() => {
      try { _validatePositiveInt(1.5, 'id'); }
      catch (e) { return e; }
    })();
    expect(err.statusCode).toBe(400);
  });

  test('throws 400 for non-numeric string', () => {
    const err = (() => {
      try { _validatePositiveInt('abc', 'id'); }
      catch (e) { return e; }
    })();
    expect(err.statusCode).toBe(400);
  });

  test('throws 400 above max', () => {
    const err = (() => {
      try { _validatePositiveInt(101, 'limit', { min: 1, max: 100 }); }
      catch (e) { return e; }
    })();
    expect(err.statusCode).toBe(400);
    expect(err.message).toMatch(/"limit"/);
  });
});

// ===========================================================================
// _validateSearchQuery
// ===========================================================================
describe('_validateSearchQuery', () => {
  test('accepts normal string', () => {
    expect(_validateSearchQuery('alice')).toBe('alice');
  });

  test('trims whitespace', () => {
    expect(_validateSearchQuery('  bob  ')).toBe('bob');
  });

  test('throws 400 for undefined', () => {
    expect(() => _validateSearchQuery(undefined)).toThrow(
      expect.objectContaining({ statusCode: 400 }),
    );
  });

  test('throws 400 for blank string', () => {
    expect(() => _validateSearchQuery('   ')).toThrow(
      expect.objectContaining({ statusCode: 400 }),
    );
  });

  test('throws 400 when exceeding maxLength', () => {
    expect(() => _validateSearchQuery('a'.repeat(201))).toThrow(
      expect.objectContaining({ statusCode: 400 }),
    );
  });

  test('accepts string at exactly maxLength', () => {
    expect(_validateSearchQuery('a'.repeat(200))).toHaveLength(200);
  });
});

// ===========================================================================
// getUserById
// ===========================================================================
describe('getUserById', () => {
  const fakeUser = { id: 1, name: 'Alice', email: 'alice@example.com', created_at: null };

  test('returns the user when found', async () => {
    mockQuery.mockResolvedValueOnce(pgResult([fakeUser]));

    const result = await getUserById(1);

    expect(result).toEqual(fakeUser);
  });

  test('returns null when not found', async () => {
    mockQuery.mockResolvedValueOnce(pgResult([]));

    const result = await getUserById(999);

    expect(result).toBeNull();
  });

  // --- SQL injection safety ---
  test('passes id as a parameter, not in SQL text', async () => {
    mockQuery.mockResolvedValueOnce(pgResult([fakeUser]));

    await getUserById(1);

    const [sql, params] = mockQuery.mock.calls[0];
    // The id must appear in the params array …
    expect(params).toContain(1);
    // … and NOT be interpolated into the SQL string.
    expect(sql).not.toMatch(/WHERE id = 1/);
    expect(sql).toMatch(/\$1/);
  });

  test('SQL text contains only placeholders, no literal id value', async () => {
    mockQuery.mockResolvedValueOnce(pgResult([]));

    const maliciousId = "1 OR '1'='1'";
    // validatePositiveInt should reject this before it reaches the db
    await expect(getUserById(maliciousId)).rejects.toMatchObject({
      statusCode: 400,
    });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  // --- Validation ---
  test('rejects non-integer id with 400', async () => {
    await expect(getUserById('abc')).rejects.toMatchObject({ statusCode: 400 });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects id 0 with 400', async () => {
    await expect(getUserById(0)).rejects.toMatchObject({ statusCode: 400 });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects negative id with 400', async () => {
    await expect(getUserById(-5)).rejects.toMatchObject({ statusCode: 400 });
  });

  test('rejects id exceeding INT4 max with 400', async () => {
    await expect(getUserById(2_147_483_648)).rejects.toMatchObject({ statusCode: 400 });
  });

  // --- Timing log ---
  test('emits a timing log entry with correct shape', async () => {
    mockQuery.mockResolvedValueOnce(pgResult([fakeUser]));

    await getUserById(1);

    const logCalls = logSpy.mock.calls;
    const timingLog = logCalls.find(
      ([tag, meta]) => tag === '[query]' && meta?.tag === 'getUserById',
    );
    expect(timingLog).toBeDefined();

    const meta = timingLog[1];
    expect(meta).toMatchObject({
      tag:        'getUserById',
      paramCount: 1,
      rowCount:   1,
    });
    expect(typeof meta.elapsedMs).toBe('number');
    expect(meta.elapsedMs).toBeGreaterThanOrEqual(0);
  });

  // --- Error propagation ---
  test('propagates db errors', async () => {
    const dbError = Object.assign(new Error('connection reset'), { code: '08006' });
    mockQuery.mockRejectedValueOnce(dbError);

    await expect(getUserById(1)).rejects.toThrow('connection reset');
  });

  test('logs an error entry on db failure', async () => {
    mockQuery.mockRejectedValueOnce(new Error('timeout'));

    await expect(getUserById(1)).rejects.toThrow();

    const errCalls = errorSpy.mock.calls;
    const errLog = errCalls.find(
      ([tag, meta]) => tag === '[query:error]' && meta?.tag === 'getUserById',
    );
    expect(errLog).toBeDefined();
  });
});

// ===========================================================================
// getAllUsers
// ===========================================================================
describe('getAllUsers', () => {
  const fakeUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: null },
    { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: null },
  ];

  beforeEach(() => {
    // getAllUsers fires two concurrent queries; mock both.
    mockQuery
      .mockResolvedValueOnce(pgResult(fakeUsers))              // data
      .mockResolvedValueOnce(pgResult([{ total: '42' }]));     // count
  });

  test('returns users, total, limit, and offset', async () => {
    const result = await getAllUsers(2, 0);

    expect(result).toMatchObject({
      users:  fakeUsers,
      total:  42,
      limit:  2,
      offset: 0,
    });
  });

  test('passes limit and offset as parameters', async () => {
    await getAllUsers(10, 20);

    const calls = mockQuery.mock.calls;
    // First call is the data query: $1=limit, $2=offset
    expect(calls[0][1]).toEqual([10, 20]);
  });

  test('SQL uses $1 / $2 placeholders for LIMIT / OFFSET', async () => {
    await getAllUsers(5, 10);

    const [sql] = mockQuery.mock.calls[0];
    expect(sql).toMatch(/LIMIT\s+\$1/i);
    expect(sql).toMatch(/OFFSET\s+\$2/i);
    // No literal numbers should appear in the SQL text.
    expect(sql).not.toMatch(/LIMIT\s+5/);
    expect(sql).not.toMatch(/OFFSET\s+10/);
  });

  test('defaults to limit=20 offset=0', async () => {
    await getAllUsers();

    expect(mockQuery.mock.calls[0][1]).toEqual([20, 0]);
  });

  test('rejects limit > 100 with 400', async () => {
    await expect(getAllUsers(101, 0)).rejects.toMatchObject({ statusCode: 400 });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects limit = 0 with 400', async () => {
    await expect(getAllUsers(0, 0)).rejects.toMatchObject({ statusCode: 400 });
  });

  test('rejects string limit with 400', async () => {
    await expect(getAllUsers('many', 0)).rejects.toMatchObject({ statusCode: 400 });
  });

  test('rejects negative offset with 400', async () => {
    await expect(getAllUsers(10, -1)).rejects.toMatchObject({ statusCode: 400 });
  });

  test('emits timing logs for both sub-queries', async () => {
    await getAllUsers(2, 0);

    const dataLog = logSpy.mock.calls.find(
      ([t, m]) => t === '[query]' && m?.tag === 'getAllUsers:data',
    );
    const countLog = logSpy.mock.calls.find(
      ([t, m]) => t === '[query]' && m?.tag === 'getAllUsers:count',
    );

    expect(dataLog).toBeDefined();
    expect(countLog).toBeDefined();
  });

  test('parses total count from string to integer', async () => {
    // pg returns COUNT(*) as a string; ensure we parse it.
    const result = await getAllUsers(2, 0);
    expect(result.total).toBe(42);
    expect(typeof result.total).toBe('number');
  });
});

// ===========================================================================
// searchUsers
// ===========================================================================
describe('searchUsers', () => {
  const fakeUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: null },
  ];

  function setupSearchMocks() {
    mockQuery
      .mockResolvedValueOnce(pgResult(fakeUsers))
      .mockResolvedValueOnce(pgResult([{ total: '1' }]));
  }

  test('returns matching users', async () => {
    setupSearchMocks();

    const result = await searchUsers('alice');

    expect(result.users).toEqual(fakeUsers);
    expect(result.query).toBe('alice');
    expect(result.total).toBe(1);
  });

  // --- SQL injection prevention ---
  test('wraps search term in % wildcards as a parameter value', async () => {
    setupSearchMocks();

    await searchUsers('alice');

    const [, params] = mockQuery.mock.calls[0];
    // The LIKE pattern must be in the params array …
    expect(params[0]).toBe('%alice%');
    // … and NOT concatenated into the SQL string.
    const [sql] = mockQuery.mock.calls[0];
    expect(sql).not.toMatch(/%alice%/);
    expect(sql).toMatch(/ILIKE \$1/i);
  });

  test('does not allow SQL metacharacters to escape parameterisation', async () => {
    // A classic LIKE injection attempt: the attacker tries to terminate the
    // LIKE value and append arbitrary SQL.  Because we use $1 binding,
    // Postgres treats the entire string as a literal data value.
    const maliciousInput = "' OR 1=1 --";

    // Our length / trim validation will still pass this (it is < 200 chars),
    // so it WILL reach pool.query — but as a bound parameter, never as SQL.
    setupSearchMocks();
    await searchUsers(maliciousInput);

    const [sql, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe(`%${maliciousInput.trim()}%`);
    // The raw injection string must not appear in the SQL text.
    expect(sql).not.toContain(maliciousInput);
  });

  test('semicolons in search input are treated as literal data', async () => {
    setupSearchMocks();
    await searchUsers('alice; DROP TABLE users;');

    const [sql, params] = mockQuery.mock.calls[0];
    expect(params[0]).toContain('DROP TABLE');  // present in the *parameter*
    expect(sql).not.toContain('DROP TABLE');    // absent from the SQL text
  });

  test('trims search term before building pattern', async () => {
    setupSearchMocks();

    await searchUsers('  alice  ');

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe('%alice%');
  });

  // --- Validation ---
  test('throws 400 for blank search', async () => {
    await expect(searchUsers('   ')).rejects.toMatchObject({ statusCode: 400 });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws 400 for undefined search', async () => {
    await expect(searchUsers(undefined)).rejects.toMatchObject({ statusCode: 400 });
  });

  test('throws 400 for search term > 200 chars', async () => {
    await expect(searchUsers('x'.repeat(201))).rejects.toMatchObject({ statusCode: 400 });
  });

  test('throws 400 for invalid limit', async () => {
    await expect(searchUsers('alice', 0)).rejects.toMatchObject({ statusCode: 400 });
  });

  test('throws 400 for limit > 100', async () => {
    await expect(searchUsers('alice', 200)).rejects.toMatchObject({ statusCode: 400 });
  });

  // --- Pagination params ---
  test('passes limit and offset as $2 / $3', async () => {
    setupSearchMocks();

    await searchUsers('alice', 10, 5);

    const [, params] = mockQuery.mock.calls[0];
    expect(params[1]).toBe(10);
    expect(params[2]).toBe(5);
  });

  // --- Timing logs ---
  test('emits timing logs for both sub-queries', async () => {
    setupSearchMocks();

    await searchUsers('alice');

    const dataLog  = logSpy.mock.calls.find(([t, m]) => t === '[query]' && m?.tag === 'searchUsers:data');
    const countLog = logSpy.mock.calls.find(([t, m]) => t === '[query]' && m?.tag === 'searchUsers:count');

    expect(dataLog).toBeDefined();
    expect(countLog).toBeDefined();
  });
});

// ===========================================================================
// poolStats
// ===========================================================================
describe('poolStats', () => {
  test('returns pool metric snapshot', () => {
    const stats = poolStats();

    expect(stats).toEqual({
      total:   3,
      idle:    2,
      waiting: 0,
    });
  });
});

/**
 * app.test.js — Integration tests for app.js route handlers
 *
 * queries.js is mocked so no real database is needed.  These tests verify
 * that the HTTP layer correctly maps query-function results and errors to
 * the right status codes and response shapes.
 */

'use strict';

// Mock queries.js before requiring app.js
jest.mock('./queries', () => ({
  getUserById:  jest.fn(),
  getAllUsers:  jest.fn(),
  searchUsers:  jest.fn(),
  poolStats:    jest.fn(() => ({ total: 2, idle: 2, waiting: 0 })),
}));

const request  = require('supertest');
const app      = require('./app');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
const fakeUser  = { id: 1, name: 'Alice', email: 'alice@example.com', created_at: null };
const fakeUser2 = { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: null };

function validationError(field) {
  const err = new Error(`"${field}" is invalid`);
  err.statusCode = 400;
  return err;
}

beforeEach(() => {
  jest.clearAllMocks();
  jest.spyOn(console, 'log').mockImplementation(() => {});
  jest.spyOn(console, 'error').mockImplementation(() => {});
});

afterEach(() => jest.restoreAllMocks());

// ===========================================================================
// GET /health
// ===========================================================================
describe('GET /health', () => {
  test('returns 200 with status ok and pool stats', async () => {
    const res = await request(app).get('/health');

    expect(res.status).toBe(200);
    expect(res.body.status).toBe('ok');
    expect(res.body.timestamp).toBeDefined();
    expect(res.body.pool).toEqual({ total: 2, idle: 2, waiting: 0 });
  });
});

// ===========================================================================
// GET /users  (list / paginated)
// ===========================================================================
describe('GET /users — paginated list', () => {
  test('returns 200 with user list', async () => {
    getAllUsers.mockResolvedValueOnce({
      users: [fakeUser, fakeUser2], total: 2, limit: 20, offset: 0,
    });

    const res = await request(app).get('/users');

    expect(res.status).toBe(200);
    expect(res.body.users).toHaveLength(2);
    expect(res.body.total).toBe(2);
  });

  test('forwards limit and offset query params', async () => {
    getAllUsers.mockResolvedValueOnce({
      users: [fakeUser], total: 1, limit: 1, offset: 2,
    });

    await request(app).get('/users?limit=1&offset=2');

    expect(getAllUsers).toHaveBeenCalledWith('1', '2');
  });

  test('returns 400 when getAllUsers throws a validation error', async () => {
    getAllUsers.mockRejectedValueOnce(validationError('limit'));

    const res = await request(app).get('/users?limit=999');

    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/"limit"/);
  });

  test('returns 500 on unexpected db error', async () => {
    getAllUsers.mockRejectedValueOnce(new Error('DB exploded'));

    const res = await request(app).get('/users');

    expect(res.status).toBe(500);
  });
});

// ===========================================================================
// GET /users  (search mode)
// ===========================================================================
describe('GET /users — search', () => {
  test('delegates to searchUsers when ?search= is present', async () => {
    searchUsers.mockResolvedValueOnce({
      users: [fakeUser], total: 1, limit: 20, offset: 0, query: 'alice',
    });

    const res = await request(app).get('/users?search=alice');

    expect(res.status).toBe(200);
    expect(searchUsers).toHaveBeenCalledWith('alice', '20', '0');
    expect(getAllUsers).not.toHaveBeenCalled();
  });

  test('returns 400 when searchUsers throws a validation error', async () => {
    searchUsers.mockRejectedValueOnce(validationError('query'));

    const res = await request(app).get('/users?search=');

    expect(res.status).toBe(400);
  });

  test('returns 500 on unexpected search error', async () => {
    searchUsers.mockRejectedValueOnce(new Error('index missing'));

    const res = await request(app).get('/users?search=alice');

    expect(res.status).toBe(500);
  });
});

// ===========================================================================
// GET /users/:id
// ===========================================================================
describe('GET /users/:id', () => {
  test('returns 200 with the user when found', async () => {
    getUserById.mockResolvedValueOnce(fakeUser);

    const res = await request(app).get('/users/1');

    expect(res.status).toBe(200);
    expect(res.body).toEqual(fakeUser);
  });

  test('returns 404 when getUserById returns null', async () => {
    getUserById.mockResolvedValueOnce(null);

    const res = await request(app).get('/users/999');

    expect(res.status).toBe(404);
    expect(res.body.error).toBe('User not found');
    expect(res.body.id).toBe('999');
  });

  test('returns 400 when getUserById throws a validation error', async () => {
    getUserById.mockRejectedValueOnce(validationError('id'));

    const res = await request(app).get('/users/abc');

    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/"id"/);
  });

  test('returns 500 on unexpected error', async () => {
    getUserById.mockRejectedValueOnce(new Error('timeout'));

    const res = await request(app).get('/users/1');

    expect(res.status).toBe(500);
  });

  test('passes the raw :id string to getUserById for validation', async () => {
    getUserById.mockResolvedValueOnce(fakeUser);

    await request(app).get('/users/42');

    expect(getUserById).toHaveBeenCalledWith('42');
  });
});

