/**
 * db.js — PostgreSQL connection pool
 *
 * Reads connection config exclusively from environment variables.
 * Never hard-code credentials here; supply them via a .env file
 * (local dev) or your deployment secrets manager (production).
 *
 * Pool tuning knobs (all optional, sensible defaults are set):
 *   DB_POOL_MAX        – max simultaneous connections   (default: 10)
 *   DB_POOL_IDLE_MS    – ms before an idle client is closed (default: 10 000)
 *   DB_POOL_CONNECT_MS – ms before a new connection times out (default: 5 000)
 *   DB_STATEMENT_MS    – ms before a query is considered slow (default: 2 000)
 */

'use strict';

require('dotenv').config();
const { Pool } = require('pg');

// ── Pool configuration ────────────────────────────────────────────────────────

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Optional fine-grained overrides (DATABASE_URL covers host/port/db/user/pw)
  max:             parseInt(process.env.DB_POOL_MAX        ?? '10',  10),
  idleTimeoutMillis:  parseInt(process.env.DB_POOL_IDLE_MS    ?? '10000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_POOL_CONNECT_MS ?? '5000',  10),

  // Always use SSL in production; can be disabled for local dev via env var
  ssl: process.env.DB_SSL === 'false' ? false : { rejectUnauthorized: true },
});

// ── Pool-level event hooks ────────────────────────────────────────────────────

pool.on('connect', (client) => {
  console.log('[db] New client connected to the pool');
  // Enforce a hard statement timeout at the session level so runaway queries
  // cannot hold a connection indefinitely.
  const stmtTimeout = parseInt(process.env.DB_STATEMENT_MS ?? '2000', 10);
  client.query(`SET statement_timeout = ${stmtTimeout}`).catch((err) => {
    console.error('[db] Failed to set statement_timeout:', err.message);
  });
});

pool.on('acquire', () => {
  console.log(`[db] Client acquired — pool size: ${pool.totalCount}, idle: ${pool.idleCount}, waiting: ${pool.waitingCount}`);
});

pool.on('remove', () => {
  console.log('[db] Client removed from pool');
});

pool.on('error', (err) => {
  // An idle client encountered an unexpected error (e.g. DB restart).
  // Log it so the process doesn't crash silently.
  console.error('[db] Unexpected pool error:', err.message);
});

// ── Exported helpers ──────────────────────────────────────────────────────────

/**
 * Run a single parameterised query and return the pg QueryResult.
 *
 * @param {string}  text   – SQL string with $1/$2/… placeholders
 * @param {Array}   params – Values to bind (never string-interpolated)
 * @returns {Promise<import('pg').QueryResult>}
 */
async function query(text, params = []) {
  const start = Date.now();
  const result = await pool.query(text, params);
  const duration = Date.now() - start;

  const slowThreshold = parseInt(process.env.DB_STATEMENT_MS ?? '2000', 10);
  const level = duration >= slowThreshold ? 'SLOW' : 'OK';

  console.log(
    `[db] query ${level} | ${duration}ms | rows=${result.rowCount} | ${text.slice(0, 120).replace(/\s+/g, ' ')}`
  );

  return result;
}

/**
 * Borrow a dedicated client from the pool for multi-statement transactions.
 * Always call client.release() in a finally block.
 *
 * @returns {Promise<import('pg').PoolClient>}
 */
async function getClient() {
  const client = await pool.connect();
  return client;
}

/**
 * Gracefully drain the pool (call during process shutdown).
 */
async function closePool() {
  await pool.end();
  console.log('[db] Pool closed');
}

module.exports = { query, getClient, closePool, pool };

/**
 * queries.js — Parameterised query functions for the /users resource
 *
 * Security guarantees
 * ───────────────────
 * • Every user-supplied value is passed as a bind parameter ($1, $2, …).
 *   pg sends parameters out-of-band; the database driver NEVER interpolates
 *   them into the SQL string, making classic SQL injection impossible.
 * • LIKE wildcards (% and _) inside a freetext search term are escaped so
 *   a user cannot craft a pattern that forces a full-table scan or leaks
 *   unexpected rows.
 * • Pagination inputs are coerced to integers and clamped to safe ranges
 *   before use, guarding against type-confusion attacks.
 * • No dynamic SQL identifiers (table/column names) are ever built from
 *   user input.
 *
 * Query timing
 * ────────────
 * Each function records wall-clock duration and logs it at INFO level.
 * Slow queries (≥ DB_STATEMENT_MS, default 2 000 ms) are flagged SLOW.
 * The db.query() helper also sets a PostgreSQL statement_timeout at the
 * session level as a hard backstop.
 */

'use strict';

const { query } = require('./db');

// ── Constants ─────────────────────────────────────────────────────────────────

const MAX_LIMIT   = 100;   // Hard cap – never return more than 100 rows at once
const DEFAULT_LIMIT  = 20;
const DEFAULT_OFFSET = 0;

// ── Private helpers ───────────────────────────────────────────────────────────

/**
 * Parse and clamp a pagination integer.
 *
 * @param {*}      raw          – Raw value (string or number from req.query)
 * @param {number} defaultValue
 * @param {number} min
 * @param {number} max
 * @returns {number}
 */
function parsePaginationInt(raw, defaultValue, min, max) {
  const n = parseInt(raw, 10);
  if (!Number.isFinite(n)) return defaultValue;
  return Math.min(Math.max(n, min), max);
}

/**
 * Escape LIKE metacharacters (%, _, \) inside a user-supplied search term.
 * The escaped string is still passed as a bind parameter; this only prevents
 * the user from influencing the pattern semantics.
 *
 * @param {string} raw
 * @returns {string}
 */
function escapeLike(raw) {
  return raw.replace(/\\/g, '\\\\').replace(/%/g, '\\%').replace(/_/g, '\\_');
}

/**
 * Centralised query logger with timing.
 * (db.query already logs, but this adds function-level context.)
 *
 * @param {string} fnName  – Calling function name for log context
 * @param {Function} fn    – Async function that performs the query
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(fnName, fn) {
  const start = Date.now();
  try {
    const result = await fn();
    console.log(`[queries] ${fnName} completed in ${Date.now() - start}ms — ${result.rowCount} row(s) returned`);
    return result;
  } catch (err) {
    console.error(`[queries] ${fnName} failed after ${Date.now() - start}ms — ${err.message}`);
    throw err;
  }
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Fetch a single user by their primary-key ID.
 *
 * @param {number|string} id  – User ID (will be coerced to integer)
 * @returns {Promise<object|null>}  The user row or null if not found
 *
 * SQL-injection safety: `id` is passed as $1 — never interpolated.
 */
async function getUserById(id) {
  const safeId = parseInt(id, 10);
  if (!Number.isFinite(safeId) || safeId <= 0) {
    throw new RangeError(`getUserById: invalid id "${id}"`);
  }

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const result = await timedQuery('getUserById', () => query(sql, [safeId]));
  return result.rows[0] ?? null;
}

/**
 * Fetch a paginated list of all users.
 *
 * @param {number} [limit=20]   – Max rows to return (capped at MAX_LIMIT=100)
 * @param {number} [offset=0]   – Number of rows to skip
 * @returns {Promise<{ rows: object[], total: number }>}
 *
 * SQL-injection safety: limit and offset are cast to integers and passed
 * as $1/$2 bind parameters.
 */
async function getAllUsers(limit = DEFAULT_LIMIT, offset = DEFAULT_OFFSET) {
  const safeLimit  = parsePaginationInt(limit,  DEFAULT_LIMIT,  1, MAX_LIMIT);
  const safeOffset = parsePaginationInt(offset, DEFAULT_OFFSET, 0, Number.MAX_SAFE_INTEGER);

  // A single round-trip returns both the page and the total count via a
  // window function — avoids a separate COUNT(*) query.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER() AS total_count
    FROM users
    ORDER BY id ASC
    LIMIT $1
    OFFSET $2
  `;

  const result = await timedQuery('getAllUsers', () => query(sql, [safeLimit, safeOffset]));

  const total = result.rows.length > 0 ? parseInt(result.rows[0].total_count, 10) : 0;

  // Strip the window-function column from every returned row
  const rows = result.rows.map(({ total_count, ...rest }) => rest);

  return { rows, total, limit: safeLimit, offset: safeOffset };
}

/**
 * Full-text search across users' names and email addresses.
 *
 * Matching strategy:
 *   • Substring match on `name`  (case-insensitive via ILIKE)
 *   • Substring match on `email` (case-insensitive via ILIKE)
 *
 * @param {string} searchQuery   – Free-text search term supplied by the user
 * @param {number} [limit=20]    – Max rows (capped at MAX_LIMIT=100)
 * @param {number} [offset=0]    – Pagination offset
 * @returns {Promise<{ rows: object[], total: number }>}
 *
 * SQL-injection safety:
 *   • The term is passed as a bind parameter ($1) — never concatenated.
 *   • LIKE metacharacters (%, _) inside the term are escaped so users
 *     cannot manipulate pattern behaviour.
 */
async function searchUsers(searchQuery, limit = DEFAULT_LIMIT, offset = DEFAULT_OFFSET) {
  if (typeof searchQuery !== 'string') {
    throw new TypeError('searchUsers: searchQuery must be a string');
  }

  const trimmed = searchQuery.trim();
  if (trimmed.length === 0) {
    throw new RangeError('searchUsers: searchQuery must not be empty');
  }
  if (trimmed.length > 200) {
    throw new RangeError('searchUsers: searchQuery must be ≤ 200 characters');
  }

  const safeLimit  = parsePaginationInt(limit,  DEFAULT_LIMIT,  1, MAX_LIMIT);
  const safeOffset = parsePaginationInt(offset, DEFAULT_OFFSET, 0, Number.MAX_SAFE_INTEGER);

  // Wrap in % for substring matching AFTER escaping any user-supplied % or _
  const likePattern = `%${escapeLike(trimmed)}%`;

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY
      -- Exact matches first, then partial matches, then alphabetical
      CASE WHEN LOWER(name)  = LOWER($2) THEN 0
           WHEN LOWER(email) = LOWER($2) THEN 0
           ELSE 1
      END ASC,
      name ASC
    LIMIT $3
    OFFSET $4
  `;

  // $1 = LIKE pattern  (e.g. '%alice%')
  // $2 = raw term      (for exact-match boost — still parameterised)
  // $3 = limit
  // $4 = offset
  const result = await timedQuery('searchUsers', () =>
    query(sql, [likePattern, trimmed, safeLimit, safeOffset])
  );

  const total = result.rows.length > 0 ? parseInt(result.rows[0].total_count, 10) : 0;
  const rows  = result.rows.map(({ total_count, ...rest }) => rest);

  return { rows, total, limit: safeLimit, offset: safeOffset };
}

module.exports = { getUserById, getAllUsers, searchUsers };

/**
 * app.js — Express application
 *
 * /users endpoints now delegate to the queries.js database layer.
 * Connection pooling and query timing are handled by db.js + queries.js.
 */

'use strict';

require('dotenv').config();
const express = require('express');
const { closePool } = require('./db');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

const app = express();
app.use(express.json());

// ── Health check ──────────────────────────────────────────────────────────────

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ── GET /users — paginated list ───────────────────────────────────────────────
//
//   Query params:
//     limit  (integer, 1–100, default 20)
//     offset (integer, ≥ 0,   default 0)
//
//   Example: GET /users?limit=10&offset=20

app.get('/users', async (req, res) => {
  try {
    const { limit, offset } = req.query;
    const result = await getAllUsers(limit, offset);
    res.json(result);
  } catch (err) {
    console.error('[app] GET /users error:', err.message);
    res.status(500).json({ error: 'Failed to retrieve users' });
  }
});

// ── GET /users/search — full-text search ──────────────────────────────────────
//
//   Query params:
//     q      (string, required)      — search term
//     limit  (integer, 1–100, default 20)
//     offset (integer, ≥ 0,   default 0)
//
//   Example: GET /users/search?q=alice&limit=5
//
//   NOTE: This route must be declared BEFORE /users/:id so Express does not
//   interpret "search" as an id value.

app.get('/users/search', async (req, res) => {
  const { q, limit, offset } = req.query;

  if (!q || typeof q !== 'string' || q.trim().length === 0) {
    return res.status(400).json({ error: 'Missing or empty query parameter: q' });
  }

  try {
    const result = await searchUsers(q, limit, offset);
    res.json(result);
  } catch (err) {
    if (err instanceof TypeError || err instanceof RangeError) {
      return res.status(400).json({ error: err.message });
    }
    console.error('[app] GET /users/search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// ── GET /users/:id — single user lookup ───────────────────────────────────────
//
//   Path param:
//     id (positive integer)
//
//   Example: GET /users/42

app.get('/users/:id', async (req, res) => {
  const { id } = req.params;

  // Reject non-numeric ids before they reach the query layer
  if (!/^\d+$/.test(id)) {
    return res.status(400).json({ error: 'User id must be a positive integer' });
  }

  try {
    const user = await getUserById(id);
    if (!user) {
      return res.status(404).json({ error: `User ${id} not found` });
    }
    res.json(user);
  } catch (err) {
    if (err instanceof RangeError) {
      return res.status(400).json({ error: err.message });
    }
    console.error('[app] GET /users/:id error:', err.message);
    res.status(500).json({ error: 'Failed to retrieve user' });
  }
});

// ── Server startup / graceful shutdown ────────────────────────────────────────

const PORT = parseInt(process.env.PORT ?? '3000', 10);

const server = app.listen(PORT, () => {
  console.log(`[app] Server running on port ${PORT}`);
});

async function shutdown(signal) {
  console.log(`[app] ${signal} received — shutting down gracefully`);
  server.close(async () => {
    await closePool();
    console.log('[app] Shutdown complete');
    process.exit(0);
  });
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

module.exports = app;

/**
 * queries.test.js — Unit tests for queries.js
 *
 * All PostgreSQL I/O is mocked via Jest manual mocks so no real database
 * connection is needed.  The tests verify:
 *   1. Correct SQL shape (parameterised placeholders present, no raw values)
 *   2. Input validation / clamping
 *   3. SQL injection prevention (metacharacter escaping, integer coercion)
 *   4. Return-value shaping (total_count stripped, pagination metadata added)
 *   5. Edge cases (not-found, empty results, boundary values)
 */

'use strict';

// ── Mock db.js BEFORE requiring queries.js ────────────────────────────────────

jest.mock('./db', () => ({
  query: jest.fn(),
}));

const { query } = require('./db');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Build a mock pg QueryResult.
 *
 * @param {object[]} rows
 * @returns {import('pg').QueryResult}
 */
function mockResult(rows) {
  return {
    rows,
    rowCount: rows.length,
    command:  'SELECT',
    oid:      null,
    fields:   [],
  };
}

// ── Test data ─────────────────────────────────────────────────────────────────

const ALICE = {
  id:         1,
  name:       'Alice',
  email:      'alice@example.com',
  created_at: new Date('2024-01-01'),
  updated_at: new Date('2024-06-01'),
  total_count: '2',
};

const BOB = {
  id:         2,
  name:       'Bob',
  email:      'bob@example.com',
  created_at: new Date('2024-02-01'),
  updated_at: new Date('2024-06-01'),
  total_count: '2',
};

// ── getUserById ───────────────────────────────────────────────────────────────

describe('getUserById', () => {
  beforeEach(() => query.mockReset());

  test('returns the matched user row (without total_count)', async () => {
    query.mockResolvedValueOnce(mockResult([ALICE]));

    const user = await getUserById(1);

    expect(user).toEqual({
      id:         1,
      name:       'Alice',
      email:      'alice@example.com',
      created_at: ALICE.created_at,
      updated_at: ALICE.updated_at,
    });
  });

  test('returns null when no user is found', async () => {
    query.mockResolvedValueOnce(mockResult([]));
    const user = await getUserById(999);
    expect(user).toBeNull();
  });

  test('passes id as a bind parameter — not string-interpolated', async () => {
    query.mockResolvedValueOnce(mockResult([ALICE]));
    await getUserById(1);

    const [sql, params] = query.mock.calls[0];
    // The SQL must contain $1 placeholder
    expect(sql).toMatch(/\$1/);
    // Params array must carry the value — not the SQL string
    expect(params).toEqual([1]);
    // Raw id value must NOT appear inside the SQL text
    expect(sql).not.toContain('1');
  });

  test('coerces a string id to integer', async () => {
    query.mockResolvedValueOnce(mockResult([ALICE]));
    await getUserById('1');

    const [, params] = query.mock.calls[0];
    expect(params[0]).toBe(1);
    expect(typeof params[0]).toBe('number');
  });

  test('throws RangeError for non-numeric id', async () => {
    await expect(getUserById('abc')).rejects.toThrow(RangeError);
    expect(query).not.toHaveBeenCalled();
  });

  test('throws RangeError for zero id', async () => {
    await expect(getUserById(0)).rejects.toThrow(RangeError);
  });

  test('throws RangeError for negative id', async () => {
    await expect(getUserById(-5)).rejects.toThrow(RangeError);
  });

  test('throws RangeError for a SQL injection attempt in the id field', async () => {
    // "1 OR 1=1" would be dangerous if interpolated — must be rejected early
    await expect(getUserById('1 OR 1=1')).rejects.toThrow(RangeError);
    expect(query).not.toHaveBeenCalled();
  });
});

// ── getAllUsers ───────────────────────────────────────────────────────────────

describe('getAllUsers', () => {
  beforeEach(() => query.mockReset());

  test('returns rows, total, limit, and offset', async () => {
    query.mockResolvedValueOnce(mockResult([ALICE, BOB]));

    const result = await getAllUsers(20, 0);

    expect(result.total).toBe(2);
    expect(result.limit).toBe(20);
    expect(result.offset).toBe(0);
    expect(result.rows).toHaveLength(2);
    // total_count must be stripped from each row
    expect(result.rows[0]).not.toHaveProperty('total_count');
    expect(result.rows[1]).not.toHaveProperty('total_count');
  });

  test('passes limit and offset as bind parameters', async () => {
    query.mockResolvedValueOnce(mockResult([ALICE]));
    await getAllUsers(10, 5);

    const [sql, params] = query.mock.calls[0];
    expect(sql).toMatch(/\$1/);
    expect(sql).toMatch(/\$2/);
    expect(params).toEqual([10, 5]);
  });

  test('applies default limit (20) and offset (0) when not supplied', async () => {
    query.mockResolvedValueOnce(mockResult([]));
    await getAllUsers();

    const [, params] = query.mock.calls[0];
    expect(params[0]).toBe(20);
    expect(params[1]).toBe(0);
  });

  test('clamps limit to MAX_LIMIT (100)', async () => {
    query.mockResolvedValueOnce(mockResult([]));
    await getAllUsers(9999);

    const [, params] = query.mock.calls[0];
    expect(params[0]).toBe(100);
  });

  test('clamps limit minimum to 1', async () => {
    query.mockResolvedValueOnce(mockResult([]));
    await getAllUsers(-5);

    const [, params] = query.mock.calls[0];
    expect(params[0]).toBe(1);
  });

  test('clamps offset minimum to 0', async () => {
    query.mockResolvedValueOnce(mockResult([]));
    await getAllUsers(10, -99);

    const [, params] = query.mock.calls[0];
    expect(params[1]).toBe(0);
  });

  test('returns total=0 and empty rows for an empty table', async () => {
    query.mockResolvedValueOnce(mockResult([]));
    const result = await getAllUsers();

    expect(result.total).toBe(0);
    expect(result.rows).toEqual([]);
  });

  test('coerces string pagination values to integers', async () => {
    query.mockResolvedValueOnce(mockResult([]));
    await getAllUsers('15', '30');

    const [, params] = query.mock.calls[0];
    expect(typeof params[0]).toBe('number');
    expect(typeof params[1]).toBe('number');
    expect(params).toEqual([15, 30]);
  });
});

// ── searchUsers ───────────────────────────────────────────────────────────────

describe('searchUsers', () => {
  beforeEach(() => query.mockReset());

  test('returns matching rows with metadata', async () => {
    query.mockResolvedValueOnce(mockResult([ALICE]));

    const result = await searchUsers('alice');

    expect(result.rows).toHaveLength(1);
    expect(result.total).toBe(2);   // from total_count on the row
    expect(result.rows[0]).not.toHaveProperty('total_count');
  });

  test('uses a LIKE bind parameter — not raw string interpolation', async () => {
    query.mockResolvedValueOnce(mockResult([ALICE]));
    await searchUsers('alice');

    const [sql, params] = query.mock.calls[0];
    expect(sql).toMatch(/ILIKE \$1/i);
    // Params[0] must be the LIKE pattern, params[1] the raw term
    expect(params[0]).toBe('%alice%');
    expect(params[1]).toBe('alice');
    // Raw term must not appear bare in the SQL text
    expect(sql).not.toContain('alice');
  });

  test('escapes % in the search term (SQL injection via LIKE pattern)', async () => {
    query.mockResolvedValueOnce(mockResult([]));
    await searchUsers('50% off');

    const [, params] = query.mock.calls[0];
    // The LIKE pattern must have the % escaped
    expect(params[0]).toBe('%50\\% off%');
    // The exact-match param must be the raw (unescaped) trimmed term
    expect(params[1]).toBe('50% off');
  });

  test('escapes _ in the search term', async () => {
    query.mockResolvedValueOnce(mockResult([]));
    await searchUsers('user_name');

    const [, params] = query.mock.calls[0];
    expect(params[0]).toBe('%user\\_name%');
  });

  test('escapes backslash in the search term', async () => {
    query.mockResolvedValueOnce(mockResult([]));
    await searchUsers('C:\\path');

    const [, params] = query.mock.calls[0];
    expect(params[0]).toBe('%C:\\\\path%');
  });

  test('trims whitespace from the search term', async () => {
    query.mockResolvedValueOnce(mockResult([]));
    await searchUsers('  alice  ');

    const [, params] = query.mock.calls[0];
    expect(params[0]).toBe('%alice%');
    expect(params[1]).toBe('alice');
  });

  test('throws TypeError when searchQuery is not a string', async () => {
    await expect(searchUsers(42)).rejects.toThrow(TypeError);
    expect(query).not.toHaveBeenCalled();
  });

  test('throws RangeError for an empty search term', async () => {
    await expect(searchUsers('')).rejects.toThrow(RangeError);
    await expect(searchUsers('   ')).rejects.toThrow(RangeError);
    expect(query).not.toHaveBeenCalled();
  });

  test('throws RangeError when search term exceeds 200 characters', async () => {
    const longTerm = 'a'.repeat(201);
    await expect(searchUsers(longTerm)).rejects.toThrow(RangeError);
    expect(query).not.toHaveBeenCalled();
  });

  test('SQL injection attempt in search term is parameterised, not executed', async () => {
    query.mockResolvedValueOnce(mockResult([]));
    const injection = "' OR '1'='1";
    await searchUsers(injection);

    const [sql, params] = query.mock.calls[0];
    // The injection string must appear only in the params array
    expect(params[0]).toBe(`%' OR '1'='1%`);
    // It must not be spliced into the SQL string
    expect(sql).not.toContain("' OR '1'='1");
  });

  test('SQL injection with UNION attempt', async () => {
    query.mockResolvedValueOnce(mockResult([]));
    const injection = "x' UNION SELECT table_name,null,null,null,null FROM information_schema.tables--";
    await searchUsers(injection);

    const [sql] = query.mock.calls[0];
    expect(sql).not.toContain('UNION');
    expect(sql).not.toContain('information_schema');
  });

  test('respects limit and offset for search', async () => {
    query.mockResolvedValueOnce(mockResult([]));
    await searchUsers('bob', 5, 10);

    const [sql, params] = query.mock.calls[0];
    // limit and offset are the 3rd and 4th bind params
    expect(sql).toMatch(/LIMIT \$3/i);
    expect(sql).toMatch(/OFFSET \$4/i);
    expect(params[2]).toBe(5);
    expect(params[3]).toBe(10);
  });

  test('returns empty result set gracefully', async () => {
    query.mockResolvedValueOnce(mockResult([]));
    const result = await searchUsers('zzznomatch');

    expect(result.rows).toEqual([]);
    expect(result.total).toBe(0);
  });
});

// ── SQL shape regression guard ────────────────────────────────────────────────
//
// These tests ensure no dynamic concatenation was accidentally introduced
// by verifying that the raw user values are never found verbatim in the SQL.

describe('SQL shape regression — no dynamic interpolation', () => {
  beforeEach(() => query.mockReset());

  test('getUserById SQL never contains raw id value', async () => {
    query.mockResolvedValueOnce(mockResult([{ ...ALICE }]));
    await getUserById(42);
    const [sql] = query.mock.calls[0];
    expect(sql).not.toContain('42');
  });

  test('getAllUsers SQL never contains raw limit/offset values', async () => {
    query.mockResolvedValueOnce(mockResult([]));
    await getAllUsers(7, 14);
    const [sql] = query.mock.calls[0];
    expect(sql).not.toContain('7');
    expect(sql).not.toContain('14');
  });

  test('searchUsers SQL never contains the raw search term', async () => {
    query.mockResolvedValueOnce(mockResult([]));
    await searchUsers('uniqueterm');
    const [sql] = query.mock.calls[0];
    expect(sql).not.toContain('uniqueterm');
  });
});

