    "pg": "^8.11.3"
  },
  "devDependencies": {
    "jest": "^29.7.0",
    "nodemon": "^3.0.2"
  }
}

/**
 * db.js — PostgreSQL connection pool
 *
 * Creates a single shared pg.Pool instance for the entire process.
 * All configuration is read from environment variables so that no
 * credentials are ever hard-coded.  Call pool.end() on graceful shutdown
 * to drain the pool before the process exits.
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Validate that required environment variables are present at startup so the
// problem surfaces immediately rather than at the first query.
// ---------------------------------------------------------------------------
const REQUIRED_ENV = ['DB_HOST', 'DB_NAME', 'DB_USER', 'DB_PASSWORD'];

for (const key of REQUIRED_ENV) {
  if (!process.env[key]) {
    throw new Error(
      `[db] Missing required environment variable: ${key}. ` +
      'Copy .env.example to .env and fill in real values.'
    );
  }
}

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------
const poolConfig = {
  host:               process.env.DB_HOST,
  port:               parseInt(process.env.DB_PORT     || '5432', 10),
  database:           process.env.DB_NAME,
  user:               process.env.DB_USER,
  password:           process.env.DB_PASSWORD,

  // Number of idle clients maintained in the pool.
  min:                parseInt(process.env.DB_POOL_MIN  || '2',     10),
  // Maximum number of clients the pool will create at once.
  max:                parseInt(process.env.DB_POOL_MAX  || '10',    10),
  // How long (ms) a client is allowed to remain idle before being closed.
  idleTimeoutMillis:  parseInt(process.env.DB_IDLE_TIMEOUT_MS       || '30000', 10),
  // How long (ms) to wait when requesting a client before timing out.
  connectionTimeoutMillis: parseInt(process.env.DB_CONNECTION_TIMEOUT_MS || '2000', 10),

  // Let pg use SSL in production; set DB_SSL=false to disable explicitly.
  ssl: process.env.NODE_ENV === 'production' && process.env.DB_SSL !== 'false'
    ? { rejectUnauthorized: true }
    : false,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event listeners for observability
// ---------------------------------------------------------------------------
pool.on('connect', (client) => {
  console.log(
    `[db] New client connected — pool size: ${pool.totalCount} ` +
    `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`
  );
});

pool.on('acquire', (client) => {
  // Fires whenever a client is checked out of the pool.
  // Kept at debug level to avoid noisy production logs.
  if (process.env.NODE_ENV !== 'production') {
    console.debug(
      `[db] Client acquired — pool size: ${pool.totalCount} ` +
      `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`
    );
  }
});

pool.on('error', (err, client) => {
  // An idle client emitted an error — log and continue; pg will remove it.
  console.error('[db] Unexpected error on idle client:', err.message);
});

pool.on('remove', (client) => {
  console.log(
    `[db] Client removed from pool — pool size: ${pool.totalCount} ` +
    `(idle: ${pool.idleCount})`
  );
});

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------
module.exports = pool;

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Security model
 * ──────────────
 * • Every value supplied by the caller is passed as a positional parameter
 *   ($1, $2, …) so pg sends it to PostgreSQL as a separate protocol message.
 *   The database engine therefore never interpolates user input into the SQL
 *   text — SQL injection via value substitution is structurally impossible.
 *
 * • Column/direction identifiers used in ORDER BY clauses cannot be passed as
 *   parameters (PostgreSQL does not accept parameters there).  We defend these
 *   with strict allow-lists and throw immediately on any unrecognised value.
 *
 * • Pagination inputs (limit, offset) are coerced to integers and clamped to
 *   safe ranges before use.
 *
 * Observability
 * ─────────────
 * • Every query is wrapped in `timedQuery()` which records wall-clock duration
 *   and emits a structured log line that includes the query name, duration,
 *   and row count.  Slow queries (> SLOW_QUERY_THRESHOLD_MS) get a WARN line.
 */

'use strict';

const pool = require('./db');

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Maximum rows a single getAllUsers call may return. */
const MAX_LIMIT = 200;

/** Default page size when the caller does not supply a limit. */
const DEFAULT_LIMIT = 20;

/** Warn in the log when a query takes longer than this (milliseconds). */
const SLOW_QUERY_THRESHOLD_MS = 500;

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Execute a parameterised SQL query through the shared pool, emit a timing
 * log, and return the pg Result object.
 *
 * @param {string}  queryName  - Human-readable label used in log output.
 * @param {string}  text       - SQL string with $1/$2/… placeholders.
 * @param {Array}   params     - Positional parameter values (never interpolated into SQL).
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(queryName, text, params) {
  const start = process.hrtime.bigint();

  let result;
  try {
    result = await pool.query(text, params);
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;
    console.error(
      `[queries] ERROR query="${queryName}" duration=${durationMs.toFixed(2)}ms ` +
      `error="${err.message}"`
    );
    throw err; // re-throw so the caller / route handler can respond appropriately
  }

  const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;
  const rowCount   = result.rowCount ?? result.rows.length;
  const level      = durationMs > SLOW_QUERY_THRESHOLD_MS ? 'WARN' : 'INFO';

  console.log(
    `[queries] ${level} query="${queryName}" duration=${durationMs.toFixed(2)}ms ` +
    `rows=${rowCount}` +
    (level === 'WARN' ? ' — slow query threshold exceeded' : '')
  );

  return result;
}

/**
 * Coerce a value to a safe integer within [min, max].
 * Returns `defaultValue` when the input is absent or non-numeric.
 *
 * @param {*}      value
 * @param {number} defaultValue
 * @param {number} min
 * @param {number} max
 * @returns {number}
 */
function safeInt(value, defaultValue, min, max) {
  const n = parseInt(value, 10);
  if (!Number.isFinite(n)) return defaultValue;
  return Math.min(Math.max(n, min), max);
}

/**
 * Validate a column name against an explicit allow-list.
 * Throws a TypeError on any value not in the list — never silently falls back
 * so that a misconfigured caller fails loudly rather than producing wrong SQL.
 *
 * @param {string}   value
 * @param {string[]} allowed
 * @param {string}   fieldLabel  - Used only in the error message.
 * @returns {string}
 */
function validateAllowList(value, allowed, fieldLabel) {
  if (!allowed.includes(value)) {
    throw new TypeError(
      `Invalid ${fieldLabel} "${value}". Allowed values: ${allowed.join(', ')}`
    );
  }
  return value;
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetch a single user row by its primary-key id.
 *
 * The id is passed as a query parameter ($1); PostgreSQL handles all type
 * coercion — there is no string concatenation into the SQL text.
 *
 * @param {number|string} id - The user's primary key.
 * @returns {Promise<Object|null>} The user row, or null if not found.
 *
 * @example
 *   const user = await getUserById(42);
 */
async function getUserById(id) {
  // Coerce to integer; reject non-numeric ids before they reach the database.
  const safeId = parseInt(id, 10);
  if (!Number.isFinite(safeId) || safeId <= 0) {
    throw new TypeError(`getUserById: "id" must be a positive integer, got: ${id}`);
  }

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
  `;

  // $1 is bound to safeId — pg sends value and SQL separately over the wire.
  const result = await timedQuery('getUserById', sql, [safeId]);
  return result.rows[0] ?? null;
}

/**
 * Retrieve a page of user rows with optional column-level ordering.
 *
 * @param {number} [limit=20]   - Maximum rows to return (capped at MAX_LIMIT).
 * @param {number} [offset=0]   - Number of rows to skip (>= 0).
 * @param {string} [orderBy='id']         - Column to sort by (allow-listed).
 * @param {string} [orderDir='ASC']       - Sort direction: 'ASC' or 'DESC'.
 * @returns {Promise<{ rows: Object[], total: number }>}
 *   `rows`  – the page of user records.
 *   `total` – total number of users in the table (for pagination metadata).
 *
 * @example
 *   const { rows, total } = await getAllUsers(10, 20, 'name', 'ASC');
 */
async function getAllUsers(
  limit    = DEFAULT_LIMIT,
  offset   = 0,
  orderBy  = 'id',
  orderDir = 'ASC'
) {
  // --- Input sanitisation ------------------------------------------------

  const safeLimit  = safeInt(limit,  DEFAULT_LIMIT, 1, MAX_LIMIT);
  const safeOffset = safeInt(offset, 0,             0, Number.MAX_SAFE_INTEGER);

  // Allow-list for ORDER BY column — never interpolate arbitrary identifiers.
  const ALLOWED_ORDER_COLUMNS = ['id', 'name', 'email', 'created_at', 'updated_at'];
  const ALLOWED_ORDER_DIRS    = ['ASC', 'DESC'];

  const safeOrderBy  = validateAllowList(
    String(orderBy).toLowerCase(),
    ALLOWED_ORDER_COLUMNS,
    'orderBy column'
  );
  const safeOrderDir = validateAllowList(
    String(orderDir).toUpperCase(),
    ALLOWED_ORDER_DIRS,
    'orderDir direction'
  );

  // --- Queries -----------------------------------------------------------
  // We run both queries in parallel for efficiency: one for the page of data,
  // one for the total count needed by the caller to build pagination headers.

  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    ORDER BY ${safeOrderBy} ${safeOrderDir}
    LIMIT  $1
    OFFSET $2
  `;

  const countSql = `SELECT COUNT(*) AS total FROM users`;

  // safeOrderBy and safeOrderDir come from hard-coded allow-lists (not user
  // input), so interpolating them into the SQL text is safe.  limit and offset
  // are passed as parameters.
  const [dataResult, countResult] = await Promise.all([
    timedQuery('getAllUsers:data',  dataSql,  [safeLimit, safeOffset]),
    timedQuery('getAllUsers:count', countSql, []),
  ]);

  return {
    rows:  dataResult.rows,
    total: parseInt(countResult.rows[0].total, 10),
  };
}

/**
 * Full-text search across the name and email columns.
 *
 * The search term is wrapped in `%…%` wildcards and sent as a parameter so
 * that pg escapes it properly — a query containing `%`, `_`, or SQL keywords
 * is treated as literal text, not as SQL or a pattern meta-character.
 *
 * @param {string} query         - Search term (leading/trailing whitespace stripped).
 * @param {number} [limit=20]    - Maximum rows to return (capped at MAX_LIMIT).
 * @param {number} [offset=0]    - Number of rows to skip.
 * @returns {Promise<{ rows: Object[], total: number }>}
 *
 * @example
 *   const { rows, total } = await searchUsers('alice', 5, 0);
 */
async function searchUsers(query, limit = DEFAULT_LIMIT, offset = 0) {
  // --- Input validation --------------------------------------------------

  if (typeof query !== 'string') {
    throw new TypeError(`searchUsers: "query" must be a string, got: ${typeof query}`);
  }

  const trimmed = query.trim();

  if (trimmed.length === 0) {
    throw new TypeError('searchUsers: "query" must not be empty or whitespace-only.');
  }

  if (trimmed.length > 200) {
    throw new TypeError(
      `searchUsers: "query" exceeds maximum length of 200 characters.`
    );
  }

  const safeLimit  = safeInt(limit,  DEFAULT_LIMIT, 1, MAX_LIMIT);
  const safeOffset = safeInt(offset, 0,             0, Number.MAX_SAFE_INTEGER);

  // --- Build the LIKE pattern --------------------------------------------
  // The % wildcards are added here in application code; the entire string
  // (including %) is sent as a parameter.  PostgreSQL therefore cannot
  // interpret any part of `trimmed` as SQL.  ILIKE provides case-insensitive
  // matching without requiring an extension.
  const pattern = `%${trimmed}%`;

  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
  `;

  const [dataResult, countResult] = await Promise.all([
    timedQuery('searchUsers:data',  dataSql,  [pattern, safeLimit, safeOffset]),
    timedQuery('searchUsers:count', countSql, [pattern]),
  ]);

  return {
    rows:  dataResult.rows,
    total: parseInt(countResult.rows[0].total, 10),
  };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------
module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  // Expose pool so app.js can call pool.end() on graceful shutdown.
  pool,
};

/**
 * app.js — Express application with PostgreSQL query layer
 *
 * Endpoints
 * ─────────
 *  GET /health               — liveness probe
 *  GET /users                — paginated list  (?limit=&offset=&orderBy=&orderDir=)
 *  GET /users/search         — full-text search (?q=&limit=&offset=)
 *  GET /users/:id            — single user by primary key
 */

'use strict';

// Load .env into process.env when present (development convenience).
// In production the variables should be injected by the process manager.
try {
  require('fs').accessSync('.env');
  // Only require dotenv if the file actually exists so the production image
  // does not need the package installed.
  require('dotenv').config();
} catch (_) {
  // No .env file — rely on environment variables already in the process.
}

const express = require('express');
const { getUserById, getAllUsers, searchUsers, pool } = require('./queries');

const app  = express();
const PORT = parseInt(process.env.PORT || '3000', 10);

// ---------------------------------------------------------------------------
// Middleware
// ---------------------------------------------------------------------------

app.use(express.json());

// Minimal request logger so every incoming call is visible in the log stream.
app.use((req, _res, next) => {
  console.log(`[app] ${req.method} ${req.originalUrl}`);
  next();
});

// ---------------------------------------------------------------------------
// Helper — wraps an async route handler and forwards errors to Express.
// ---------------------------------------------------------------------------
const asyncHandler = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Simple liveness probe; also reports pool statistics.
 */
app.get('/health', (_req, res) => {
  res.json({
    status:    'ok',
    timestamp: new Date().toISOString(),
    db: {
      totalClients:   pool.totalCount,
      idleClients:    pool.idleCount,
      waitingClients: pool.waitingCount,
    },
  });
});

/**
 * GET /users/search?q=<term>[&limit=20][&offset=0]
 *
 * Must be registered BEFORE /users/:id so that the literal path segment
 * "search" is not matched as an :id parameter.
 *
 * Query parameters:
 *  q       {string}  required — search term matched against name and email
 *  limit   {number}  optional — page size  (1–200, default 20)
 *  offset  {number}  optional — rows to skip (≥ 0, default 0)
 */
app.get('/users/search', asyncHandler(async (req, res) => {
  const { q, limit, offset } = req.query;

  if (!q || typeof q !== 'string' || q.trim().length === 0) {
    return res.status(400).json({
      error: 'Missing or empty query parameter "q".',
    });
  }

  const { rows, total } = await searchUsers(q, limit, offset);

  res.json({
    data:       rows,
    pagination: buildPaginationMeta(total, limit, offset),
  });
}));

/**
 * GET /users?[limit=20][&offset=0][&orderBy=id][&orderDir=ASC]
 *
 * Query parameters:
 *  limit    {number}  optional — page size  (1–200, default 20)
 *  offset   {number}  optional — rows to skip (≥ 0, default 0)
 *  orderBy  {string}  optional — column:  id | name | email | created_at | updated_at
 *  orderDir {string}  optional — direction: ASC | DESC
 */
app.get('/users', asyncHandler(async (req, res) => {
  const { limit, offset, orderBy, orderDir } = req.query;

  const { rows, total } = await getAllUsers(limit, offset, orderBy, orderDir);

  res.json({
    data:       rows,
    pagination: buildPaginationMeta(total, limit, offset),
  });
}));

/**
 * GET /users/:id
 *
 * Path parameter:
 *  id  {number}  required — positive integer primary key
 */
app.get('/users/:id', asyncHandler(async (req, res) => {
  const user = await getUserById(req.params.id);

  if (!user) {
    return res.status(404).json({ error: `User with id ${req.params.id} not found.` });
  }

  res.json({ data: user });
}));

// ---------------------------------------------------------------------------
// Central error handler
// ---------------------------------------------------------------------------
// Must have four parameters so Express recognises it as an error handler.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, _next) => {
  // TypeError from our allow-list / input validation helpers → 400 Bad Request
  if (err instanceof TypeError) {
    return res.status(400).json({ error: err.message });
  }

  // Unexpected errors → 500
  console.error('[app] Unhandled error:', err);
  res.status(500).json({ error: 'Internal server error.' });
});

// ---------------------------------------------------------------------------
// Pagination metadata helper
// ---------------------------------------------------------------------------

/**
 * Build a consistent pagination block for list responses.
 *
 * @param {number}        total  - Total matching rows in the table.
 * @param {string|number} limit  - Raw limit value from req.query (may be undefined).
 * @param {string|number} offset - Raw offset value from req.query (may be undefined).
 * @returns {{ total: number, limit: number, offset: number, hasMore: boolean }}
 */
function buildPaginationMeta(total, limit, offset) {
  const safeLimit  = Math.min(Math.max(parseInt(limit  || '20', 10), 1), 200);
  const safeOffset = Math.max(parseInt(offset || '0', 10), 0);

  return {
    total,
    limit:   safeLimit,
    offset:  safeOffset,
    hasMore: safeOffset + safeLimit < total,
  };
}

// ---------------------------------------------------------------------------
// Start server + graceful shutdown
// ---------------------------------------------------------------------------

const server = app.listen(PORT, () => {
  console.log(`[app] Server running on port ${PORT} (${process.env.NODE_ENV || 'development'})`);
});

/**
 * Graceful shutdown — drains the pg connection pool before the process exits
 * so in-flight queries can complete and PostgreSQL does not see abrupt drops.
 */
function shutdown(signal) {
  console.log(`[app] Received ${signal}. Shutting down gracefully…`);
  server.close(async () => {
    try {
      await pool.end();
      console.log('[app] Database pool drained. Goodbye.');
    } catch (err) {
      console.error('[app] Error draining pool:', err.message);
    }
    process.exit(0);
  });
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ---------------------------------------------------------------------------
// Exports (used by tests)
// ---------------------------------------------------------------------------
module.exports = app;

/**
 * queries.test.js — Unit tests for the queries module
 *
 * The PostgreSQL pool is mocked so that no real database connection is needed.
 * Each test group covers one exported function.  SQL injection attempts are
 * included as explicit test cases.
 */

'use strict';

// ---------------------------------------------------------------------------
// Mock the entire db module BEFORE requiring queries.js so that queries.js
// picks up the mock pool when it calls require('./db').
// ---------------------------------------------------------------------------

// A small in-memory "database" the mock can draw from.
const DB_ROWS = [
  { id: 1, name: 'Alice',   email: 'alice@example.com',   created_at: new Date('2024-01-01'), updated_at: new Date('2024-01-01') },
  { id: 2, name: 'Bob',     email: 'bob@example.com',     created_at: new Date('2024-02-01'), updated_at: new Date('2024-02-01') },
  { id: 3, name: 'Charlie', email: 'charlie@example.com', created_at: new Date('2024-03-01'), updated_at: new Date('2024-03-01') },
];

// Build a predictable mock pool that mirrors what pg.Pool.query() returns.
let mockQueryImpl = jest.fn();

jest.mock('./db', () => {
  const mock = {
    query:          (...args) => mockQueryImpl(...args),
    totalCount:     2,
    idleCount:      2,
    waitingCount:   0,
    end:            jest.fn().mockResolvedValue(undefined),
    on:             jest.fn(),
  };
  return mock;
});

const { getUserById, getAllUsers, searchUsers } = require('./queries');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Produce a pg-style result object. */
function pgResult(rows) {
  return { rows, rowCount: rows.length };
}

/**
 * Install a mock that replies with the supplied rows for ALL calls to
 * pool.query() in a given test.  When a test requires different responses for
 * sequential queries, pass an array of pg-result objects.
 */
function mockPool(...results) {
  let callIndex = 0;
  mockQueryImpl.mockImplementation(() => {
    const r = results[callIndex] ?? results[results.length - 1];
    callIndex++;
    return Promise.resolve(r);
  });
}

// ---------------------------------------------------------------------------
// getUserById
// ---------------------------------------------------------------------------
describe('getUserById', () => {
  beforeEach(() => jest.clearAllMocks());

  test('returns the matching user for a valid id', async () => {
    const row = DB_ROWS[0];
    mockPool(pgResult([row]));

    const result = await getUserById(1);

    expect(result).toEqual(row);
    // Verify the query was parameterised — id is in the params array, not SQL.
    const [sql, params] = mockQueryImpl.mock.calls[0];
    expect(sql).not.toContain('1');   // id must NOT be interpolated into SQL text
    expect(params).toEqual([1]);
  });

  test('returns null when no user is found', async () => {
    mockPool(pgResult([]));
    const result = await getUserById(999);
    expect(result).toBeNull();
  });

  test('coerces a numeric string id', async () => {
    mockPool(pgResult([DB_ROWS[1]]));
    const result = await getUserById('2');
    expect(result).toEqual(DB_ROWS[1]);
    const [, params] = mockQueryImpl.mock.calls[0];
    expect(params).toEqual([2]);
  });

  test('throws TypeError for a non-numeric id', async () => {
    await expect(getUserById('abc')).rejects.toThrow(TypeError);
    expect(mockQueryImpl).not.toHaveBeenCalled();
  });

  test('throws TypeError for id = 0', async () => {
    await expect(getUserById(0)).rejects.toThrow(TypeError);
    expect(mockQueryImpl).not.toHaveBeenCalled();
  });

  test('throws TypeError for a negative id', async () => {
    await expect(getUserById(-5)).rejects.toThrow(TypeError);
    expect(mockQueryImpl).not.toHaveBeenCalled();
  });

  // SQL injection: the value must end up in params, never spliced into SQL.
  test('SQL injection in id is rejected before reaching the database', async () => {
    await expect(getUserById("1 OR 1=1")).rejects.toThrow(TypeError);
    expect(mockQueryImpl).not.toHaveBeenCalled();
  });

  test('re-throws database errors', async () => {
    mockQueryImpl.mockRejectedValueOnce(new Error('connection refused'));
    await expect(getUserById(1)).rejects.toThrow('connection refused');
  });
});

// ---------------------------------------------------------------------------
// getAllUsers
// ---------------------------------------------------------------------------
describe('getAllUsers', () => {
  beforeEach(() => jest.clearAllMocks());

  test('returns rows and total with defaults', async () => {
    mockPool(
      pgResult(DB_ROWS),                       // first call  → data
      pgResult([{ total: '3' }])               // second call → count
    );

    const { rows, total } = await getAllUsers();

    expect(rows).toEqual(DB_ROWS);
    expect(total).toBe(3);
    // Two queries should have been issued (data + count).
    expect(mockQueryImpl).toHaveBeenCalledTimes(2);
  });

  test('passes limit and offset as parameters', async () => {
    mockPool(
      pgResult([DB_ROWS[0]]),
      pgResult([{ total: '1' }])
    );

    await getAllUsers(1, 0);

    // Find the data query (the one with LIMIT/OFFSET parameters).
    const dataSqlCall = mockQueryImpl.mock.calls.find(([, params]) => params.length === 2);
    expect(dataSqlCall[1]).toEqual([1, 0]);
  });

  test('caps limit at MAX_LIMIT (200)', async () => {
    mockPool(pgResult([]), pgResult([{ total: '0' }]));

    await getAllUsers(9999);

    const dataSqlCall = mockQueryImpl.mock.calls.find(([, params]) => params.length === 2);
    expect(dataSqlCall[1][0]).toBe(200);
  });

  test('accepts valid orderBy columns', async () => {
    const validColumns = ['id', 'name', 'email', 'created_at', 'updated_at'];
    for (const col of validColumns) {
      jest.clearAllMocks();
      mockPool(pgResult([]), pgResult([{ total: '0' }]));
      await expect(getAllUsers(10, 0, col, 'ASC')).resolves.toBeDefined();
    }
  });

  test('throws TypeError for invalid orderBy column (allow-list enforced)', async () => {
    await expect(getAllUsers(10, 0, 'password', 'ASC')).rejects.toThrow(TypeError);
