 *
 * @example
 *   const { rows, total } = await searchUsers('alice', 5, 0);
 */
async function searchUsers(query, limit = DEFAULT_LIMIT, offset = 0) {
  // --- Input validation --------------------------------------------------

  if (typeof query !== 'string') {
    throw new TypeError(`searchUsers: "query" must be a string, got: ${typeof query}`);
  }

  const trimmed = query.trim();

  if (trimmed.length === 0) {
    throw new TypeError('searchUsers: "query" must not be empty or whitespace-only.');
  }

  if (trimmed.length > 200) {
    throw new TypeError(
      `searchUsers: "query" exceeds maximum length of 200 characters.`
    );
  }

  const safeLimit  = safeInt(limit,  DEFAULT_LIMIT, 1, MAX_LIMIT);
  const safeOffset = safeInt(offset, 0,             0, Number.MAX_SAFE_INTEGER);

  // --- Build the LIKE pattern --------------------------------------------
  // The % wildcards are added here in application code; the entire string
  // (including %) is sent as a parameter.  PostgreSQL therefore cannot
  // interpret any part of `trimmed` as SQL.  ILIKE provides case-insensitive
  // matching without requiring an extension.
  const pattern = `%${trimmed}%`;

  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
  `;

  const [dataResult, countResult] = await Promise.all([
    timedQuery('searchUsers:data',  dataSql,  [pattern, safeLimit, safeOffset]),
    timedQuery('searchUsers:count', countSql, [pattern]),
