/**
 * app.js — Express application with PostgreSQL query layer
 *
 * Endpoints
 * ─────────
 *  GET /health               — liveness probe
 *  GET /users                — paginated list  (?limit=&offset=&orderBy=&orderDir=)
 *  GET /users/search         — full-text search (?q=&limit=&offset=)
 *  GET /users/:id            — single user by primary key
 */

'use strict';

// Load .env into process.env when present (development convenience).
// In production the variables should be injected by the process manager.
try {
  require('fs').accessSync('.env');
  // Only require dotenv if the file actually exists so the production image
  // does not need the package installed.
  require('dotenv').config();
} catch (_) {
  // No .env file — rely on environment variables already in the process.
}

const express = require('express');
const { getUserById, getAllUsers, searchUsers, pool } = require('./queries');

const app  = express();
const PORT = parseInt(process.env.PORT || '3000', 10);

// ---------------------------------------------------------------------------
// Middleware
// ---------------------------------------------------------------------------

app.use(express.json());

// Minimal request logger so every incoming call is visible in the log stream.
app.use((req, _res, next) => {
  console.log(`[app] ${req.method} ${req.originalUrl}`);
  next();
});

// ---------------------------------------------------------------------------
// Helper — wraps an async route handler and forwards errors to Express.
// ---------------------------------------------------------------------------
const asyncHandler = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Simple liveness probe; also reports pool statistics.
 */
app.get('/health', (_req, res) => {
  res.json({
    status:    'ok',
    timestamp: new Date().toISOString(),
    db: {
      totalClients:   pool.totalCount,
      idleClients:    pool.idleCount,
      waitingClients: pool.waitingCount,
    },
  });
});

/**
 * GET /users/search?q=<term>[&limit=20][&offset=0]
 *
 * Must be registered BEFORE /users/:id so that the literal path segment
 * "search" is not matched as an :id parameter.
 *
 * Query parameters:
 *  q       {string}  required — search term matched against name and email
 *  limit   {number}  optional — page size  (1–200, default 20)
 *  offset  {number}  optional — rows to skip (≥ 0, default 0)
 */
app.get('/users/search', asyncHandler(async (req, res) => {
  const { q, limit, offset } = req.query;

  if (!q || typeof q !== 'string' || q.trim().length === 0) {
    return res.status(400).json({
      error: 'Missing or empty query parameter "q".',
    });
  }

  const { rows, total } = await searchUsers(q, limit, offset);

  res.json({
    data:       rows,
    pagination: buildPaginationMeta(total, limit, offset),
  });
}));

/**
 * GET /users?[limit=20][&offset=0][&orderBy=id][&orderDir=ASC]
 *
 * Query parameters:
 *  limit    {number}  optional — page size  (1–200, default 20)
 *  offset   {number}  optional — rows to skip (≥ 0, default 0)
 *  orderBy  {string}  optional — column:  id | name | email | created_at | updated_at
 *  orderDir {string}  optional — direction: ASC | DESC
 */
app.get('/users', asyncHandler(async (req, res) => {
  const { limit, offset, orderBy, orderDir } = req.query;

  const { rows, total } = await getAllUsers(limit, offset, orderBy, orderDir);

  res.json({
    data:       rows,
    pagination: buildPaginationMeta(total, limit, offset),
  });
}));

/**
 * GET /users/:id
 *
 * Path parameter:
 *  id  {number}  required — positive integer primary key
 */
app.get('/users/:id', asyncHandler(async (req, res) => {
  const user = await getUserById(req.params.id);

  if (!user) {
    return res.status(404).json({ error: `User with id ${req.params.id} not found.` });
  }

  res.json({ data: user });
}));

// ---------------------------------------------------------------------------
// Central error handler
// ---------------------------------------------------------------------------
// Must have four parameters so Express recognises it as an error handler.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, _next) => {
  // TypeError from our allow-list / input validation helpers → 400 Bad Request
  if (err instanceof TypeError) {
    return res.status(400).json({ error: err.message });
  }

  // Unexpected errors → 500
  console.error('[app] Unhandled error:', err);
  res.status(500).json({ error: 'Internal server error.' });
});

// ---------------------------------------------------------------------------
// Pagination metadata helper
// ---------------------------------------------------------------------------

/**
 * Build a consistent pagination block for list responses.
 *
 * @param {number}        total  - Total matching rows in the table.
 * @param {string|number} limit  - Raw limit value from req.query (may be undefined).
 * @param {string|number} offset - Raw offset value from req.query (may be undefined).
 * @returns {{ total: number, limit: number, offset: number, hasMore: boolean }}
 */
function buildPaginationMeta(total, limit, offset) {
  const safeLimit  = Math.min(Math.max(parseInt(limit  || '20', 10), 1), 200);
  const safeOffset = Math.max(parseInt(offset || '0', 10), 0);

  return {
    total,
    limit:   safeLimit,
    offset:  safeOffset,
    hasMore: safeOffset + safeLimit < total,
  };
}

// ---------------------------------------------------------------------------
// Start server + graceful shutdown
// ---------------------------------------------------------------------------

const server = app.listen(PORT, () => {
  console.log(`[app] Server running on port ${PORT} (${process.env.NODE_ENV || 'development'})`);
});

/**
 * Graceful shutdown — drains the pg connection pool before the process exits
 * so in-flight queries can complete and PostgreSQL does not see abrupt drops.
 */
function shutdown(signal) {
  console.log(`[app] Received ${signal}. Shutting down gracefully…`);
  server.close(async () => {
    try {
      await pool.end();
      console.log('[app] Database pool drained. Goodbye.');
    } catch (err) {
      console.error('[app] Error draining pool:', err.message);
    }
    process.exit(0);
  });
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ---------------------------------------------------------------------------
// Exports (used by tests)
// ---------------------------------------------------------------------------
module.exports = app;

/**
 * queries.test.js — Unit tests for the queries module
 *
 * The PostgreSQL pool is mocked so that no real database connection is needed.
 * Each test group covers one exported function.  SQL injection attempts are
 * included as explicit test cases.
