/**
 * db.js — PostgreSQL connection pool
 *
 * Reads connection config exclusively from environment variables (loaded by
 * dotenv in the entry-point).  Never hard-code credentials here.
 *
 * Pool tuning is also driven by env vars so each deployment environment
 * (dev / staging / production) can size the pool independently without
 * touching source code.
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Build pool config from environment variables
// ---------------------------------------------------------------------------

const poolConfig = {
  // Connection target — prefer a full connection string when available.
  // Individual fields are used as a fallback for environments that inject
  // each value separately (e.g. some container orchestrators).
  connectionString: process.env.DATABASE_URL || undefined,

  // Fallback individual fields (ignored when connectionString is set)
  host:     process.env.DB_HOST     || 'localhost',
  port:     parseInt(process.env.DB_PORT || '5432', 10),
  database: process.env.DB_NAME     || 'app',
  user:     process.env.DB_USER     || 'postgres',
  password: process.env.DB_PASSWORD || undefined,

  // ---------------------------------------------------------------------------
  // Pool sizing
  // ---------------------------------------------------------------------------

  // Maximum simultaneous clients kept open.
  // A sensible default for a moderate-traffic API is 10; tune up under load.
  max: parseInt(process.env.DB_POOL_MAX || '10', 10),

  // Minimum idle clients kept ready to serve requests immediately.
  min: parseInt(process.env.DB_POOL_MIN || '2', 10),

  // How long (ms) a client may sit idle before it is closed and removed.
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT_MS || '30000', 10),

  // How long (ms) to wait for a free client before throwing "pool exhausted".
  connectionTimeoutMillis: parseInt(process.env.DB_CONNECT_TIMEOUT_MS || '5000', 10),

  // Maximum lifetime of a single connection (ms).
  // Cycling connections prevents stale states and helps with load-balancer
  // connection pinning in cloud environments.
  maxUses: parseInt(process.env.DB_MAX_USES || '7500', 10),

  // ---------------------------------------------------------------------------
  // TLS — enforce encrypted connections in non-development environments
  // ---------------------------------------------------------------------------
  ssl: process.env.DB_SSL === 'false'
    ? false
    : process.env.NODE_ENV !== 'development'
      ? { rejectUnauthorized: process.env.DB_SSL_REJECT_UNAUTHORIZED !== 'false' }
      : false,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event listeners
// ---------------------------------------------------------------------------

pool.on('connect', (client) => {
  // Tag every connection with the application name so you can identify it
  // in pg_stat_activity without an extra query.
  client.query("SET application_name = 'node-api'").catch(() => {
    // Non-fatal — the pool still works; just log the anomaly.
    console.warn('[db] Could not set application_name on new connection');
  });
  console.debug('[db] New client connected to pool');
});

pool.on('acquire', () => {
  console.debug(`[db] Client acquired — pool size: ${pool.totalCount}, idle: ${pool.idleCount}, waiting: ${pool.waitingCount}`);
});

pool.on('remove', () => {
  console.debug('[db] Client removed from pool');
});

pool.on('error', (err, client) => {
  // An idle client threw an unexpected error (e.g. server closed the
  // connection, network blip).  Log it so ops is alerted; the pool will
  // automatically replace the broken client.
  console.error('[db] Unexpected error on idle client', err.message);
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------

/**
 * Drain the pool cleanly when the process receives a shutdown signal.
 * Call this from your main entry-point signal handlers.
 */
async function closePool() {
  console.info('[db] Draining connection pool…');
  await pool.end();
  console.info('[db] Pool drained. All connections closed.');
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { pool, closePool };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design principles
 * -----------------
 * 1. SQL injection prevention
 *    Every piece of caller-supplied data is passed as a *parameter* ($1, $2 …)
 *    and never interpolated into the SQL string.  The pg driver sends values
 *    out-of-band via the PostgreSQL extended query protocol, so the server
 *    treats them strictly as data — never as SQL.  `LIKE` patterns receive
 *    the same treatment, with metacharacters escaped before binding.
 *
 * 2. Input validation
 *    Each function validates and sanitises its arguments before touching the
 *    pool, returning a well-typed error immediately on bad input rather than
 *    letting the database surface a cryptic error.
 *
 * 3. Query timing
 *    Every query is wrapped by `timedQuery()`, which logs the SQL label,
 *    execution time in milliseconds, and whether the query succeeded or
 *    failed.  Times are measured with `process.hrtime.bigint()` for
 *    sub-millisecond accuracy.
 *
 * 4. Connection pooling
 *    All queries use the shared pool from db.js.  For operations that need
 *    multiple queries inside one transaction, a dedicated client is checked
 *    out and always released in a `finally` block to prevent pool leaks.
 */

'use strict';

const { pool } = require('./db');

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Escape special LIKE metacharacters in a string so that user-supplied search
 * terms are treated as literals, not patterns.
 *
 * PostgreSQL LIKE metacharacters: % _ \
 *
 * @param {string} raw  The raw search string from the caller.
 * @returns {string}    The escaped string, safe to use inside a LIKE pattern.
 */
function escapeLike(raw) {
  // Escape backslash first (it is the escape character itself), then % and _.
  return raw
    .replace(/\\/g, '\\\\')
    .replace(/%/g, '\\%')
    .replace(/_/g, '\\_');
}

/**
 * Execute a parameterised query against the pool and emit structured timing
 * logs.
 *
 * @param {string}   label   Human-readable name used in log output.
 * @param {string}   sql     The SQL statement with $1/$2/… placeholders.
 * @param {Array}    params  Bound parameter values (never interpolated).
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(label, sql, params = []) {
  const start = process.hrtime.bigint();           // nanosecond resolution
  let rowCount = 0;
  let status = 'ok';

  try {
    const result = await pool.query(sql, params);
    rowCount = result.rowCount ?? result.rows.length;
    return result;
  } catch (err) {
    status = 'error';
    throw err;                                      // re-throw for caller
  } finally {
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    // Structured log — easy to ingest into any log aggregator.
    console.info(
      JSON.stringify({
        level:    'query',
        label,
        status,
        durationMs: parseFloat(elapsedMs.toFixed(3)),
        rowCount,
        paramCount: params.length,
        timestamp: new Date().toISOString(),
      })
    );
  }
}

/**
 * Validate that a value is a safe positive integer.
 *
 * @param {*}      value   The raw value to check.
 * @param {string} name    Parameter name used in error messages.
 * @param {number} max     Upper bound (inclusive).
 * @returns {number}       The validated integer.
 * @throws {RangeError}    When validation fails.
 */
function requirePositiveInt(value, name, max = Number.MAX_SAFE_INTEGER) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 1 || n > max) {
    throw new RangeError(
      `"${name}" must be a positive integer between 1 and ${max}; got: ${JSON.stringify(value)}`
    );
  }
  return n;
}

/**
 * Validate a non-negative integer (0 is acceptable for offset / limit).
 *
 * @param {*}      value
 * @param {string} name
 * @param {number} max
 * @returns {number}
 */
function requireNonNegativeInt(value, name, max = Number.MAX_SAFE_INTEGER) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0 || n > max) {
    throw new RangeError(
      `"${name}" must be a non-negative integer up to ${max}; got: ${JSON.stringify(value)}`
    );
  }
  return n;
}

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Hard ceiling on rows a single list query may return. */
const MAX_LIMIT = 200;

/** Maximum characters accepted in a search query string. */
const MAX_SEARCH_LENGTH = 200;

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetch a single user by primary-key ID.
 *
 * SQL injection prevention
 * ------------------------
 * The `id` value is passed as bound parameter `$1`.  PostgreSQL receives it
 * over the extended query protocol as a typed integer, making it impossible
 * for the value to alter the statement's parse tree.
 *
 * @param {number|string} id  The user's integer primary key.
 * @returns {Promise<Object|null>}  The user row, or `null` if not found.
 * @throws {RangeError}   On invalid `id`.
 * @throws {Error}        On database errors.
 *
 * @example
 *   const user = await getUserById(42);
 *   if (!user) return res.status(404).json({ error: 'User not found' });
 */
async function getUserById(id) {
  // Validate: id must be a positive integer (auto-increment PKs start at 1).
  const safeId = requirePositiveInt(id, 'id', Number.MAX_SAFE_INTEGER);

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const result = await timedQuery('getUserById', sql, [safeId]);
  return result.rows[0] ?? null;
}

/**
 * Retrieve a paginated list of all users, ordered by creation time (newest
 * first).
 *
 * SQL injection prevention
 * ------------------------
 * Both `limit` and `offset` are validated as non-negative integers and passed
 * as bound parameters `$1` / `$2`.  PostgreSQL's planner accepts integer
 * parameters for LIMIT/OFFSET in the extended protocol, so no interpolation
 * ever occurs.
 *
 * @param {number} [limit=20]   Maximum rows to return (1–200).
 * @param {number} [offset=0]   Number of rows to skip (≥ 0).
 * @returns {Promise<{ users: Object[], total: number, limit: number, offset: number }>}
 * @throws {RangeError}  On out-of-range `limit` or `offset`.
 * @throws {Error}       On database errors.
 *
 * @example
 *   const page = await getAllUsers(20, 40);
 *   // page.users — rows 41–60
 *   // page.total — total user count (for building pagination UI)
 */
async function getAllUsers(limit = 20, offset = 0) {
  const safeLimit  = requireNonNegativeInt(limit,  'limit',  MAX_LIMIT);
  const safeOffset = requireNonNegativeInt(offset, 'offset');

  // A zero limit makes no sense for a listing endpoint; enforce a floor.
  if (safeLimit === 0) {
    throw new RangeError('"limit" must be at least 1');
  }

  // Run the data query and the COUNT in parallel to minimise latency.
  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    ORDER BY created_at DESC, id DESC
    LIMIT  $1
    OFFSET $2
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
  `;

  const [dataResult, countResult] = await Promise.all([
    timedQuery('getAllUsers:data',  dataSql,  [safeLimit, safeOffset]),
    timedQuery('getAllUsers:count', countSql, []),
  ]);

  return {
    users:  dataResult.rows,
    total:  parseInt(countResult.rows[0].total, 10),
    limit:  safeLimit,
    offset: safeOffset,
  };
}

/**
 * Full-text search over user names and emails.
 *
 * SQL injection prevention
 * ------------------------
 * The search term is processed in two layers:
 *   1. The raw string is trimmed and length-capped before use.
 *   2. `escapeLike()` escapes LIKE metacharacters (%, _, \) so the term is
 *      treated as a literal substring.
 *   3. The escaped term is passed as bound parameter `$1` — never
 *      concatenated into the SQL string — so PostgreSQL always parses it
 *      as a value, not SQL.
 *
 * Search is case-insensitive via `ILIKE`.
 * Pagination mirrors `getAllUsers` and uses the same bounds enforcement.
 *
 * @param {string} query          The search term (1–200 characters).
 * @param {number} [limit=20]     Maximum rows to return (1–200).
 * @param {number} [offset=0]     Rows to skip (≥ 0).
 * @returns {Promise<{ users: Object[], total: number, query: string, limit: number, offset: number }>}
 * @throws {TypeError}   When `query` is not a non-empty string.
 * @throws {RangeError}  On out-of-range `limit` or `offset`.
 * @throws {Error}       On database errors.
 *
 * @example
 *   const results = await searchUsers('alice', 10, 0);
 */
async function searchUsers(query, limit = 20, offset = 0) {
  // ---- Input validation ---------------------------------------------------

  if (typeof query !== 'string') {
    throw new TypeError(`"query" must be a string; got ${typeof query}`);
  }

  const trimmed = query.trim();

  if (trimmed.length === 0) {
    throw new TypeError('"query" must not be an empty string');
  }

  if (trimmed.length > MAX_SEARCH_LENGTH) {
    throw new RangeError(
      `"query" must be ${MAX_SEARCH_LENGTH} characters or fewer; got ${trimmed.length}`
    );
  }

  const safeLimit  = requireNonNegativeInt(limit,  'limit',  MAX_LIMIT);
  const safeOffset = requireNonNegativeInt(offset, 'offset');

  if (safeLimit === 0) {
    throw new RangeError('"limit" must be at least 1');
  }

  // ---- Build safe LIKE pattern -------------------------------------------
  // escapeLike turns user input into a safe literal; wrapping with % makes it
  // a "contains" search.  This string is still bound as a parameter below —
  // it is never concatenated into SQL.
  const likePattern = `%${escapeLike(trimmed)}%`;

  // ---- Queries -----------------------------------------------------------

  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY
      -- Exact matches rank first, then partial matches.
      CASE
        WHEN LOWER(name)  = LOWER($2) THEN 0
        WHEN LOWER(email) = LOWER($2) THEN 0
        ELSE 1
      END,
      created_at DESC,
      id DESC
    LIMIT  $3
    OFFSET $4
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
  `;

  // $1 = likePattern, $2 = trimmed (for exact-match ranking), $3 = limit, $4 = offset
  const [dataResult, countResult] = await Promise.all([
    timedQuery('searchUsers:data',  dataSql,  [likePattern, trimmed, safeLimit, safeOffset]),
    timedQuery('searchUsers:count', countSql, [likePattern]),
  ]);

  return {
    users:  dataResult.rows,
    total:  parseInt(countResult.rows[0].total, 10),
    query:  trimmed,
    limit:  safeLimit,
    offset: safeOffset,
  };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,

  // Export for unit testing only — not part of the public API surface.
  _internal: { escapeLike, timedQuery },
};

/**
 * app.js — Express application with a real PostgreSQL query layer
 *
 * /users endpoints
 * ----------------
 *   GET /users              — paginated list    (getAllUsers)
 *   GET /users/search       — search by name/email (searchUsers)
 *   GET /users/:id          — single user by PK (getUserById)
 *
 * All database interaction goes through queries.js, which uses parameterised
 * queries and connection pooling.  This file owns only HTTP concerns:
 * parsing query-string parameters, mapping query errors to HTTP status codes,
 * and serialising responses.
 */

'use strict';

// Load environment variables from .env before any other module reads
// process.env.  In production this is typically handled by the platform, but
// dotenv is a safe no-op when the vars are already present.
require('dotenv').config();

const express = require('express');
const { closePool } = require('./db');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

const app = express();

app.use(express.json());

// ---------------------------------------------------------------------------
// Request-level timing middleware
// ---------------------------------------------------------------------------

/**
 * Attaches a high-resolution start time to every incoming request and emits a
 * structured access log after the response is finished.  This is separate from
 * the per-query timing logs in queries.js so you can correlate HTTP latency
 * with DB latency.
 */
app.use((req, res, next) => {
  const requestStart = process.hrtime.bigint();

  res.on('finish', () => {
    const durationMs = Number(process.hrtime.bigint() - requestStart) / 1_000_000;
    console.info(
      JSON.stringify({
        level:      'access',
        method:     req.method,
        path:       req.path,
        status:     res.statusCode,
        durationMs: parseFloat(durationMs.toFixed(3)),
        timestamp:  new Date().toISOString(),
      })
    );
  });

  next();
});

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Map a validation / query error to an appropriate HTTP response.
 *
 * @param {Error} err
 * @param {import('express').Response} res
 */
function handleQueryError(err, res) {
  if (err instanceof TypeError || err instanceof RangeError) {
    // Validation errors are always the caller's fault → 400 Bad Request.
    return res.status(400).json({ error: err.message });
  }

  // Anything else is an unexpected server-side fault → 500.
  console.error('[app] Unhandled query error:', err.message, err.stack);
  return res.status(500).json({ error: 'Internal server error' });
}

/**
 * Parse an optional integer query-string parameter.
 *
 * @param {string|undefined} raw      Raw query-string value.
 * @param {number}           fallback Default when the param is absent.
 * @returns {number}
 */
function parseIntParam(raw, fallback) {
  if (raw === undefined || raw === '') return fallback;
  const n = Number(raw);
  // Let queries.js do deep validation; just return the number so we don't
  // duplicate range logic here.
  return Number.isFinite(n) ? n : fallback;
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// -- Health ------------------------------------------------------------------

app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// -- Users -------------------------------------------------------------------

/**
 * GET /users/search?q=<term>[&limit=20&offset=0]
 *
 * Must be registered *before* /users/:id so Express does not interpret the
 * literal string "search" as an :id value.
 *
 * Query parameters:
 *   q       {string}  Required. Search term (matched case-insensitively
 *                     against name and email).
 *   limit   {number}  Optional. Max rows to return (default 20, max 200).
 *   offset  {number}  Optional. Rows to skip for pagination (default 0).
 *
 * Response 200:
 *   {
 *     "users":  [ { id, name, email, created_at, updated_at }, … ],
 *     "total":  <integer>,   // total matching rows (for pagination UI)
 *     "query":  "<term>",
 *     "limit":  <integer>,
 *     "offset": <integer>
 *   }
 *
 * Response 400: Missing / invalid parameters.
 * Response 500: Database or internal error.
 */
app.get('/users/search', async (req, res) => {
  const { q } = req.query;

  if (!q || (typeof q === 'string' && q.trim() === '')) {
    return res.status(400).json({
      error: 'Missing required query parameter: q',
    });
  }

  const limit  = parseIntParam(req.query.limit,  20);
  const offset = parseIntParam(req.query.offset,  0);

  try {
    const result = await searchUsers(q, limit, offset);
    return res.json(result);
  } catch (err) {
    return handleQueryError(err, res);
  }
});

/**
 * GET /users?[limit=20&offset=0]
 *
 * Returns a paginated list of all users ordered by newest first.
 *
 * Query parameters:
 *   limit   {number}  Optional. Max rows to return (default 20, max 200).
 *   offset  {number}  Optional. Rows to skip for pagination (default 0).
 *
 * Response 200:
 *   {
 *     "users":  [ { id, name, email, created_at, updated_at }, … ],
 *     "total":  <integer>,
 *     "limit":  <integer>,
 *     "offset": <integer>
 *   }
 *
 * Response 400: Invalid parameters.
 * Response 500: Database or internal error.
 */
app.get('/users', async (req, res) => {
  const limit  = parseIntParam(req.query.limit,  20);
  const offset = parseIntParam(req.query.offset,  0);

  try {
    const result = await getAllUsers(limit, offset);
    return res.json(result);
  } catch (err) {
    return handleQueryError(err, res);
  }
});

/**
 * GET /users/:id
 *
 * Returns a single user by primary-key ID.
 *
 * Path parameters:
 *   id  {integer}  Positive integer user ID.
 *
 * Response 200:
 *   { id, name, email, created_at, updated_at }
 *
 * Response 400: Non-integer or out-of-range :id.
 * Response 404: No user with that ID.
 * Response 500: Database or internal error.
 */
app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({ error: `User with id ${req.params.id} not found` });
    }

    return res.json(user);
  } catch (err) {
    return handleQueryError(err, res);
  }
});

// ---------------------------------------------------------------------------
// Graceful shutdown
// ---------------------------------------------------------------------------

/**
 * On SIGTERM / SIGINT:
 *  1. Stop accepting new connections.
 *  2. Drain the PostgreSQL pool so in-flight queries can finish.
 *  3. Exit cleanly.
 *
 * This is especially important in containerised environments where the
 * orchestrator sends SIGTERM before forcibly killing the process.
 */
async function shutdown(signal) {
  console.info(`[app] Received ${signal} — shutting down gracefully…`);
  server.close(async () => {
    try {
      await closePool();
      console.info('[app] Shutdown complete.');
      process.exit(0);
    } catch (err) {
      console.error('[app] Error during shutdown:', err.message);
      process.exit(1);
    }
  });
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------

const PORT = parseInt(process.env.PORT || '3000', 10);
const server = app.listen(PORT, () => {
  console.info(`[app] Server running on port ${PORT} (${process.env.NODE_ENV || 'development'})`);
});

module.exports = app;

/**
 * queries.test.js — Unit tests for queries.js
 *
 * Strategy
 * --------
 * The PostgreSQL pool (db.js → pg.Pool) is mocked so tests run without a
 * real database.  Every test exercises:
 *   • Input validation / sanitisation
 *   • Correct SQL parameterisation (no user input in the SQL string)
 *   • Query timing log output
 *   • Return-value shape
 *
 * Run with:
 *   npx jest   (or: node --test queries.test.js  if you prefer node:test)
 */

'use strict';

// ---------------------------------------------------------------------------
// Mock the pool BEFORE requiring queries.js
// ---------------------------------------------------------------------------

// We intercept require('pg') so no real connections are ever attempted.
const mockQuery = jest.fn();

jest.mock('./db', () => ({
  pool: { query: mockQuery },
  closePool: jest.fn(),
}));

// Capture console.info calls so we can assert on timing logs.
const logSpy = jest.spyOn(console, 'info').mockImplementation(() => {});
// Silence any error/warn noise from the module under test.
jest.spyOn(console, 'error').mockImplementation(() => {});
jest.spyOn(console, 'debug').mockImplementation(() => {});
jest.spyOn(console, 'warn').mockImplementation(() => {});

const { getUserById, getAllUsers, searchUsers, _internal } = require('./queries');
const { escapeLike } = _internal;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/** Collect the structured JSON objects written to console.info. */
function capturedLogs() {
  return logSpy.mock.calls
    .map(([msg]) => { try { return JSON.parse(msg); } catch { return null; } })
    .filter(Boolean);
}

beforeEach(() => {
  mockQuery.mockReset();
  logSpy.mockClear();
});

// ===========================================================================
// escapeLike
// ===========================================================================

describe('escapeLike()', () => {
  test('leaves ordinary strings unchanged', () => {
    expect(escapeLike('alice')).toBe('alice');
    expect(escapeLike('Bob Smith')).toBe('Bob Smith');
  });

  test('escapes % so it cannot act as a LIKE wildcard', () => {
    expect(escapeLike('100%')).toBe('100\\%');
  });

  test('escapes _ so it cannot act as a single-char wildcard', () => {
    expect(escapeLike('user_name')).toBe('user\\_name');
  });

  test('escapes backslash (the LIKE escape character itself)', () => {
    expect(escapeLike('C:\\path')).toBe('C:\\\\path');
  });

  test('escapes all metacharacters together', () => {
    expect(escapeLike('100% off_sale\\deal')).toBe('100\\% off\\_sale\\\\deal');
  });

  test('returns empty string unchanged', () => {
    expect(escapeLike('')).toBe('');
  });
});

