describe('getUserById()', () => {
  const fakeUser = {
    id: 1, name: 'Alice', email: 'alice@example.com',
    created_at: new Date(), updated_at: new Date(),
  };

  test('returns the user row when found', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [fakeUser], rowCount: 1 });

    const result = await getUserById(1);

    expect(result).toEqual(fakeUser);
  });

  test('returns null when no row is found', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [], rowCount: 0 });

    const result = await getUserById(999);

    expect(result).toBeNull();
  });

  test('passes id as a bound parameter, never interpolated into SQL', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [fakeUser], rowCount: 1 });

    await getUserById(42);

    const [sql, params] = mockQuery.mock.calls[0];
    expect(params).toEqual([42]);
    // The SQL string must NOT contain the literal value 42.
    expect(sql).not.toContain('42');
    // Must use the $1 placeholder.
    expect(sql).toContain('$1');
  });

  test('emits a structured timing log', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [fakeUser], rowCount: 1 });

    await getUserById(1);

    const logs = capturedLogs();
    const queryLog = logs.find(l => l.label === 'getUserById');
    expect(queryLog).toBeDefined();
    expect(queryLog.level).toBe('query');
    expect(typeof queryLog.durationMs).toBe('number');
    expect(queryLog.status).toBe('ok');
    expect(queryLog.paramCount).toBe(1);
  });

  test('logs status "error" and re-throws on DB failure', async () => {
    mockQuery.mockRejectedValueOnce(new Error('connection refused'));

    await expect(getUserById(1)).rejects.toThrow('connection refused');

    const logs = capturedLogs();
    const queryLog = logs.find(l => l.label === 'getUserById');
    expect(queryLog.status).toBe('error');
  });

  // ---- Input validation ----

  test('throws RangeError for id = 0', async () => {
    await expect(getUserById(0)).rejects.toBeInstanceOf(RangeError);
  });

  test('throws RangeError for negative id', async () => {
    await expect(getUserById(-5)).rejects.toBeInstanceOf(RangeError);
  });

  test('throws RangeError for non-integer id', async () => {
    await expect(getUserById('abc')).rejects.toBeInstanceOf(RangeError);
    await expect(getUserById(1.5)).rejects.toBeInstanceOf(RangeError);
  });

  test('throws RangeError for NaN', async () => {
    await expect(getUserById(NaN)).rejects.toBeInstanceOf(RangeError);
  });

  test('accepts a numeric string id', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [fakeUser], rowCount: 1 });
    const result = await getUserById('7');
    expect(result).toEqual(fakeUser);
    const [, params] = mockQuery.mock.calls[0];
    expect(params).toEqual([7]);
  });

  test('does not call pool.query on invalid input', async () => {
    await expect(getUserById(-1)).rejects.toBeInstanceOf(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });
});

