// getAllUsers
// ===========================================================================

describe('getAllUsers()', () => {
  const fakeRows = [
    { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: new Date(), updated_at: new Date() },
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), updated_at: new Date() },
  ];

  function mockBothQueries(rows = fakeRows, total = 2) {
    // First call = data query, second call = count query (run in parallel via Promise.all).
    mockQuery
      .mockResolvedValueOnce({ rows, rowCount: rows.length })
      .mockResolvedValueOnce({ rows: [{ total: String(total) }], rowCount: 1 });
  }

  test('returns users array, total, limit and offset', async () => {
    mockBothQueries();
    const result = await getAllUsers(20, 0);

    expect(result.users).toEqual(fakeRows);
    expect(result.total).toBe(2);
    expect(result.limit).toBe(20);
    expect(result.offset).toBe(0);
  });

  test('passes limit and offset as bound parameters', async () => {
    mockBothQueries();
    await getAllUsers(10, 30);

    // The data query receives both limit and offset.
    const dataCalls = mockQuery.mock.calls.filter(([_sql, params]) =>
      params && params.length === 2
    );
    expect(dataCalls.length).toBeGreaterThan(0);
    const [, params] = dataCalls[0];
    expect(params).toEqual([10, 30]);
    // Verify values are not embedded in the SQL string.
    const [sql] = dataCalls[0];
    expect(sql).toContain('$1');
    expect(sql).toContain('$2');
    expect(sql).not.toMatch(/\bLIMIT\s+10\b/);
    expect(sql).not.toMatch(/\bOFFSET\s+30\b/);
  });

  test('emits timing logs for both queries', async () => {
    mockBothQueries();
    await getAllUsers();

    const logs = capturedLogs();
    expect(logs.some(l => l.label === 'getAllUsers:data')).toBe(true);
    expect(logs.some(l => l.label === 'getAllUsers:count')).toBe(true);
  });

  test('uses default limit=20, offset=0 when called with no args', async () => {
    mockBothQueries();
    const result = await getAllUsers();
    expect(result.limit).toBe(20);
    expect(result.offset).toBe(0);
  });

  test('total is returned as a number, not a string', async () => {
    mockBothQueries([], 0);
    const result = await getAllUsers();
    expect(typeof result.total).toBe('number');
  });

  // ---- Input validation ----

  test('throws RangeError when limit exceeds 200', async () => {
    await expect(getAllUsers(201, 0)).rejects.toBeInstanceOf(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws RangeError when limit is 0', async () => {
    await expect(getAllUsers(0, 0)).rejects.toBeInstanceOf(RangeError);
  });

  test('throws RangeError for negative offset', async () => {
    await expect(getAllUsers(10, -1)).rejects.toBeInstanceOf(RangeError);
  });

  test('throws RangeError for non-integer limit', async () => {
    await expect(getAllUsers('lots', 0)).rejects.toBeInstanceOf(RangeError);
  });

  test('accepts string representations of valid integers', async () => {
    mockBothQueries();
    const result = await getAllUsers('5', '10');
    expect(result.limit).toBe(5);
    expect(result.offset).toBe(10);
  });
});

// ===========================================================================
// searchUsers
// ===========================================================================

describe('searchUsers()', () => {
  const fakeRows = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), updated_at: new Date() },
  ];

  function mockBothSearchQueries(rows = fakeRows, total = 1) {
    mockQuery
      .mockResolvedValueOnce({ rows, rowCount: rows.length })
      .mockResolvedValueOnce({ rows: [{ total: String(total) }], rowCount: 1 });
  }

  test('returns matched users, total, query, limit and offset', async () => {
    mockBothSearchQueries();
    const result = await searchUsers('alice');

    expect(result.users).toEqual(fakeRows);
    expect(result.total).toBe(1);
    expect(result.query).toBe('alice');
    expect(result.limit).toBe(20);
    expect(result.offset).toBe(0);
  });

  test('wraps the search term in % for ILIKE and passes it as a bound parameter', async () => {
    mockBothSearchQueries();
    await searchUsers('alice');

    // The data query is the one with 4 params ($1=pattern, $2=term, $3=limit, $4=offset).
    const dataCall = mockQuery.mock.calls.find(([_sql, params]) => params && params.length === 4);
    expect(dataCall).toBeDefined();
    const [sql, params] = dataCall;

    // $1 must be the wrapped LIKE pattern.
    expect(params[0]).toBe('%alice%');
    // $2 must be the bare term (for exact-match ranking).
    expect(params[1]).toBe('alice');
    // The raw term must NOT appear in the SQL string.
    expect(sql).not.toContain('alice');
    // Placeholders must be present.
    expect(sql).toContain('$1');
    expect(sql).toContain('$2');
    expect(sql).toContain('$3');
    expect(sql).toContain('$4');
  });

  test('escapes LIKE metacharacters in the search pattern', async () => {
    mockBothSearchQueries();
    await searchUsers('100%');

    const dataCall = mockQuery.mock.calls.find(([, params]) => params && params.length === 4);
    const [, params] = dataCall;
    // The % in "100%" must be escaped to \% inside the LIKE pattern.
    expect(params[0]).toBe('%100\\%%');
  });

  test('escapes underscore metacharacter', async () => {
    mockBothSearchQueries();
    await searchUsers('user_name');

    const dataCall = mockQuery.mock.calls.find(([, params]) => params && params.length === 4);
    const [, params] = dataCall;
    expect(params[0]).toBe('%user\\_name%');
  });

  test('trims whitespace from the query string', async () => {
    mockBothSearchQueries();
    const result = await searchUsers('  alice  ');
    expect(result.query).toBe('alice');

    const dataCall = mockQuery.mock.calls.find(([, params]) => params && params.length === 4);
    expect(dataCall[1][1]).toBe('alice');
  });

  test('emits timing logs for both queries', async () => {
    mockBothSearchQueries();
    await searchUsers('bob');

    const logs = capturedLogs();
    expect(logs.some(l => l.label === 'searchUsers:data')).toBe(true);
    expect(logs.some(l => l.label === 'searchUsers:count')).toBe(true);
  });

  // ---- Input validation ----

  test('throws TypeError for empty string', async () => {
    await expect(searchUsers('')).rejects.toBeInstanceOf(TypeError);
    await expect(searchUsers('   ')).rejects.toBeInstanceOf(TypeError);
  });

  test('throws TypeError for non-string query', async () => {
    await expect(searchUsers(42)).rejects.toBeInstanceOf(TypeError);
    await expect(searchUsers(null)).rejects.toBeInstanceOf(TypeError);
    await expect(searchUsers(undefined)).rejects.toBeInstanceOf(TypeError);
  });

  test('throws RangeError for query exceeding 200 characters', async () => {
    const longQuery = 'a'.repeat(201);
    await expect(searchUsers(longQuery)).rejects.toBeInstanceOf(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('accepts query of exactly 200 characters', async () => {
    mockBothSearchQueries();
    const maxQuery = 'a'.repeat(200);
    await expect(searchUsers(maxQuery)).resolves.toBeDefined();
  });

  test('throws RangeError when limit exceeds 200', async () => {
    await expect(searchUsers('alice', 201)).rejects.toBeInstanceOf(RangeError);
  });

  test('throws RangeError for negative offset', async () => {
    await expect(searchUsers('alice', 20, -1)).rejects.toBeInstanceOf(RangeError);
  });

  test('does not call pool.query on invalid input', async () => {
    await expect(searchUsers('')).rejects.toBeInstanceOf(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  // ---- SQL injection attempts ----

  test('a classic SQL injection string is fully parameterised', async () => {
    mockBothSearchQueries([], 0);
    const injection = "' OR '1'='1";
    await searchUsers(injection);

    const dataCall = mockQuery.mock.calls.find(([, params]) => params && params.length === 4);
    const [sql, params] = dataCall;

    // The injection string must appear ONLY in the params array, never in the SQL.
    expect(params[1]).toBe(injection.trim());
    expect(sql).not.toContain("'");
    expect(sql).not.toContain('OR');
  });

  test('a UNION-based injection is not interpolated into SQL', async () => {
    mockBothSearchQueries([], 0);
    const injection = 'x UNION SELECT * FROM secrets--';
    await searchUsers(injection);

    const dataCall = mockQuery.mock.calls.find(([, params]) => params && params.length === 4);
    const [sql] = dataCall;
    expect(sql).not.toContain('UNION');
    expect(sql).not.toContain('secrets');
  });
});

