/**
 * db.js — PostgreSQL connection pool
 *
 * Reads connection config exclusively from environment variables (loaded by
 * dotenv in the entry-point).  Never hard-code credentials here.
 *
 * Pool tuning is also driven by env vars so each deployment environment
 * (dev / staging / production) can size the pool independently without
 * touching source code.
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Build pool config from environment variables
// ---------------------------------------------------------------------------

const poolConfig = {
  // Connection target — prefer a full connection string when available.
  // Individual fields are used as a fallback for environments that inject
  // each value separately (e.g. some container orchestrators).
  connectionString: process.env.DATABASE_URL || undefined,

  // Fallback individual fields (ignored when connectionString is set)
  host:     process.env.DB_HOST     || 'localhost',
  port:     parseInt(process.env.DB_PORT || '5432', 10),
  database: process.env.DB_NAME     || 'app',
  user:     process.env.DB_USER     || 'postgres',
  password: process.env.DB_PASSWORD || undefined,

  // ---------------------------------------------------------------------------
  // Pool sizing
  // ---------------------------------------------------------------------------

  // Maximum simultaneous clients kept open.
  // A sensible default for a moderate-traffic API is 10; tune up under load.
  max: parseInt(process.env.DB_POOL_MAX || '10', 10),

  // Minimum idle clients kept ready to serve requests immediately.
  min: parseInt(process.env.DB_POOL_MIN || '2', 10),

  // How long (ms) a client may sit idle before it is closed and removed.
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT_MS || '30000', 10),

  // How long (ms) to wait for a free client before throwing "pool exhausted".
  connectionTimeoutMillis: parseInt(process.env.DB_CONNECT_TIMEOUT_MS || '5000', 10),

  // Maximum lifetime of a single connection (ms).
  // Cycling connections prevents stale states and helps with load-balancer
  // connection pinning in cloud environments.
  maxUses: parseInt(process.env.DB_MAX_USES || '7500', 10),

  // ---------------------------------------------------------------------------
  // TLS — enforce encrypted connections in non-development environments
  // ---------------------------------------------------------------------------
  ssl: process.env.DB_SSL === 'false'
    ? false
    : process.env.NODE_ENV !== 'development'
      ? { rejectUnauthorized: process.env.DB_SSL_REJECT_UNAUTHORIZED !== 'false' }
      : false,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event listeners
// ---------------------------------------------------------------------------

pool.on('connect', (client) => {
  // Tag every connection with the application name so you can identify it
  // in pg_stat_activity without an extra query.
  client.query("SET application_name = 'node-api'").catch(() => {
    // Non-fatal — the pool still works; just log the anomaly.
    console.warn('[db] Could not set application_name on new connection');
  });
  console.debug('[db] New client connected to pool');
});

pool.on('acquire', () => {
  console.debug(`[db] Client acquired — pool size: ${pool.totalCount}, idle: ${pool.idleCount}, waiting: ${pool.waitingCount}`);
});

pool.on('remove', () => {
  console.debug('[db] Client removed from pool');
});

pool.on('error', (err, client) => {
  // An idle client threw an unexpected error (e.g. server closed the
  // connection, network blip).  Log it so ops is alerted; the pool will
  // automatically replace the broken client.
  console.error('[db] Unexpected error on idle client', err.message);
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------

/**
 * Drain the pool cleanly when the process receives a shutdown signal.
 * Call this from your main entry-point signal handlers.
 */
async function closePool() {
  console.info('[db] Draining connection pool…');
  await pool.end();
  console.info('[db] Pool drained. All connections closed.');
}

