/** Hard ceiling on rows a single list query may return. */
const MAX_LIMIT = 200;

/** Maximum characters accepted in a search query string. */
const MAX_SEARCH_LENGTH = 200;

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetch a single user by primary-key ID.
 *
 * SQL injection prevention
 * ------------------------
 * The `id` value is passed as bound parameter `$1`.  PostgreSQL receives it
 * over the extended query protocol as a typed integer, making it impossible
 * for the value to alter the statement's parse tree.
 *
 * @param {number|string} id  The user's integer primary key.
 * @returns {Promise<Object|null>}  The user row, or `null` if not found.
 * @throws {RangeError}   On invalid `id`.
 * @throws {Error}        On database errors.
 *
 * @example
 *   const user = await getUserById(42);
 *   if (!user) return res.status(404).json({ error: 'User not found' });
 */
async function getUserById(id) {
  // Validate: id must be a positive integer (auto-increment PKs start at 1).
  const safeId = requirePositiveInt(id, 'id', Number.MAX_SAFE_INTEGER);

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const result = await timedQuery('getUserById', sql, [safeId]);
  return result.rows[0] ?? null;
}

/**
 * Retrieve a paginated list of all users, ordered by creation time (newest
 * first).
 *
 * SQL injection prevention
 * ------------------------
 * Both `limit` and `offset` are validated as non-negative integers and passed
 * as bound parameters `$1` / `$2`.  PostgreSQL's planner accepts integer
 * parameters for LIMIT/OFFSET in the extended protocol, so no interpolation
 * ever occurs.
 *
 * @param {number} [limit=20]   Maximum rows to return (1–200).
 * @param {number} [offset=0]   Number of rows to skip (≥ 0).
 * @returns {Promise<{ users: Object[], total: number, limit: number, offset: number }>}
 * @throws {RangeError}  On out-of-range `limit` or `offset`.
 * @throws {Error}       On database errors.
 *
 * @example
 *   const page = await getAllUsers(20, 40);
 *   // page.users — rows 41–60
 *   // page.total — total user count (for building pagination UI)
 */
async function getAllUsers(limit = 20, offset = 0) {
  const safeLimit  = requireNonNegativeInt(limit,  'limit',  MAX_LIMIT);
  const safeOffset = requireNonNegativeInt(offset, 'offset');

  // A zero limit makes no sense for a listing endpoint; enforce a floor.
  if (safeLimit === 0) {
    throw new RangeError('"limit" must be at least 1');
  }

  // Run the data query and the COUNT in parallel to minimise latency.
  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    ORDER BY created_at DESC, id DESC
    LIMIT  $1
    OFFSET $2
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
  `;

  const [dataResult, countResult] = await Promise.all([
    timedQuery('getAllUsers:data',  dataSql,  [safeLimit, safeOffset]),
    timedQuery('getAllUsers:count', countSql, []),
  ]);

  return {
    users:  dataResult.rows,
    total:  parseInt(countResult.rows[0].total, 10),
    limit:  safeLimit,
    offset: safeOffset,
  };
}

