/**
 * GET /users/search?q=<term>[&limit=20&offset=0]
 *
 * Must be registered *before* /users/:id so Express does not interpret the
 * literal string "search" as an :id value.
 *
 * Query parameters:
 *   q       {string}  Required. Search term (matched case-insensitively
 *                     against name and email).
 *   limit   {number}  Optional. Max rows to return (default 20, max 200).
 *   offset  {number}  Optional. Rows to skip for pagination (default 0).
 *
 * Response 200:
 *   {
 *     "users":  [ { id, name, email, created_at, updated_at }, … ],
 *     "total":  <integer>,   // total matching rows (for pagination UI)
 *     "query":  "<term>",
 *     "limit":  <integer>,
 *     "offset": <integer>
 *   }
 *
 * Response 400: Missing / invalid parameters.
 * Response 500: Database or internal error.
 */
app.get('/users/search', async (req, res) => {
  const { q } = req.query;

  if (!q || (typeof q === 'string' && q.trim() === '')) {
    return res.status(400).json({
      error: 'Missing required query parameter: q',
    });
  }

  const limit  = parseIntParam(req.query.limit,  20);
  const offset = parseIntParam(req.query.offset,  0);

  try {
    const result = await searchUsers(q, limit, offset);
    return res.json(result);
  } catch (err) {
    return handleQueryError(err, res);
  }
});

/**
 * GET /users?[limit=20&offset=0]
 *
 * Returns a paginated list of all users ordered by newest first.
 *
 * Query parameters:
 *   limit   {number}  Optional. Max rows to return (default 20, max 200).
 *   offset  {number}  Optional. Rows to skip for pagination (default 0).
 *
 * Response 200:
 *   {
 *     "users":  [ { id, name, email, created_at, updated_at }, … ],
 *     "total":  <integer>,
 *     "limit":  <integer>,
 *     "offset": <integer>
 *   }
 *
 * Response 400: Invalid parameters.
 * Response 500: Database or internal error.
 */
app.get('/users', async (req, res) => {
  const limit  = parseIntParam(req.query.limit,  20);
  const offset = parseIntParam(req.query.offset,  0);

  try {
    const result = await getAllUsers(limit, offset);
    return res.json(result);
  } catch (err) {
    return handleQueryError(err, res);
  }
});

/**
 * GET /users/:id
 *
 * Returns a single user by primary-key ID.
 *
 * Path parameters:
 *   id  {integer}  Positive integer user ID.
 *
 * Response 200:
 *   { id, name, email, created_at, updated_at }
 *
 * Response 400: Non-integer or out-of-range :id.
 * Response 404: No user with that ID.
 * Response 500: Database or internal error.
 */
app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({ error: `User with id ${req.params.id} not found` });
    }

    return res.json(user);
  } catch (err) {
    return handleQueryError(err, res);
  }
});

// ---------------------------------------------------------------------------
// Graceful shutdown
// ---------------------------------------------------------------------------

/**
 * On SIGTERM / SIGINT:
 *  1. Stop accepting new connections.
 *  2. Drain the PostgreSQL pool so in-flight queries can finish.
 *  3. Exit cleanly.
 *
 * This is especially important in containerised environments where the
 * orchestrator sends SIGTERM before forcibly killing the process.
 */
async function shutdown(signal) {
  console.info(`[app] Received ${signal} — shutting down gracefully…`);
  server.close(async () => {
    try {
      await closePool();
      console.info('[app] Shutdown complete.');
      process.exit(0);
    } catch (err) {
      console.error('[app] Error during shutdown:', err.message);
      process.exit(1);
    }
  });
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

