/**
 * logger.js
 *
 * Centralised Winston logger used by every module in the project.
 * Produces structured JSON in production and human-readable coloured
 * output in development so that query-timing lines are easy to spot.
 */

'use strict';

const { createLogger, format, transports } = require('winston');

const { combine, timestamp, errors, json, colorize, printf } = format;

// ── pretty format used only in development ──────────────────────────────────
const devFormat = combine(
  colorize({ all: true }),
  timestamp({ format: 'HH:mm:ss.SSS' }),
  errors({ stack: true }),
  printf(({ level, message, timestamp, stack, ...meta }) => {
    const metaStr = Object.keys(meta).length ? ' ' + JSON.stringify(meta) : '';
    return `${timestamp} [${level}] ${stack || message}${metaStr}`;
  }),
);

// ── structured JSON format used in production / test ────────────────────────
const prodFormat = combine(
  timestamp(),
  errors({ stack: true }),
  json(),
);

const logger = createLogger({
  // honour LOG_LEVEL env var; fall back based on NODE_ENV
  level: process.env.LOG_LEVEL || (process.env.NODE_ENV === 'production' ? 'info' : 'debug'),
  format: process.env.NODE_ENV === 'development' ? devFormat : prodFormat,
  transports: [new transports.Console()],
  // Don't crash the process on unhandled logger errors
  exitOnError: false,
});

module.exports = logger;

/**
 * db.js
 *
 * Manages a single shared pg.Pool instance for the entire process.
 *
 * Design decisions
 * ─────────────────
 * • One pool per process — creating a pool per request is a common
 *   anti-pattern that exhausts file descriptors quickly.
 * • All pool parameters are read from environment variables so that
 *   the same binary can be tuned for different deployment sizes without
 *   a code change.
 * • Pool events are wired to the shared logger so connection errors and
 *   slow acquisitions are visible in structured logs.
 * • `getPool()` is exported instead of the pool itself so tests can
 *   call `closePool()` for a clean teardown without touching internals.
 */

'use strict';

require('dotenv').config();

const { Pool } = require('pg');
const logger   = require('./logger');

// ── helpers ──────────────────────────────────────────────────────────────────

/**
 * Parse a positive integer from an environment variable, falling back to
 * `defaultValue` when the variable is absent or not a valid integer.
 *
 * @param {string} name          - Environment variable name
 * @param {number} defaultValue  - Fallback
 * @returns {number}
 */
function envInt(name, defaultValue) {
  const raw = process.env[name];
  const parsed = parseInt(raw, 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : defaultValue;
}

// ── pool singleton ────────────────────────────────────────────────────────────

/** @type {import('pg').Pool | null} */
let _pool = null;

/**
 * Build and return the singleton Pool.
 * Safe to call multiple times — only one Pool is ever created.
 *
 * @returns {import('pg').Pool}
 */
function getPool() {
  if (_pool) return _pool;

  const connectionString = process.env.DATABASE_URL;

  if (!connectionString) {
    throw new Error(
      'DATABASE_URL environment variable is not set. ' +
      'Copy .env.example to .env and fill in your connection details.',
    );
  }

  _pool = new Pool({
    connectionString,

    // Maximum number of clients in the pool.
    // Rule of thumb: (2 × CPU cores) + effective_spindle_count
    max: envInt('DB_POOL_MAX', 10),

    // How long (ms) a client may sit idle in the pool before being
    // closed and removed.
    idleTimeoutMillis: envInt('DB_POOL_IDLE_TIMEOUT_MS', 30_000),

    // How long (ms) to wait for a connection from the pool before
    // throwing an error.
    connectionTimeoutMillis: envInt('DB_POOL_CONNECTION_TIMEOUT_MS', 2_000),

    // Enforce SSL in production; allow self-signed certs in dev.
    ssl: process.env.NODE_ENV === 'production'
      ? { rejectUnauthorized: true }
      : false,
  });

  // ── pool event listeners ───────────────────────────────────────────────────

  _pool.on('connect', (client) => {
    logger.debug('pg pool: new client connected', {
      totalCount: _pool.totalCount,
      idleCount:  _pool.idleCount,
      waitingCount: _pool.waitingCount,
    });
    // Harden every fresh connection: abort any statement that runs
    // longer than 30 s so runaway queries cannot hold the pool hostage.
    client.query("SET statement_timeout = '30s'").catch((err) => {
      logger.warn('pg pool: failed to set statement_timeout', { err: err.message });
    });
  });

  _pool.on('acquire', () => {
    logger.debug('pg pool: client acquired', {
      totalCount:   _pool.totalCount,
      idleCount:    _pool.idleCount,
      waitingCount: _pool.waitingCount,
    });
  });

  _pool.on('remove', () => {
    logger.debug('pg pool: client removed', {
      totalCount:   _pool.totalCount,
      idleCount:    _pool.idleCount,
      waitingCount: _pool.waitingCount,
    });
  });

  // Surface connection errors that occur outside a query (e.g. the DB
  // goes away while a client is idle).  Without this handler Node would
  // crash with an unhandled 'error' event.
  _pool.on('error', (err) => {
    logger.error('pg pool: unexpected error on idle client', {
      message: err.message,
      code:    err.code,
    });
  });

  logger.info('pg pool: initialised', {
    max:                    _pool.options.max,
    idleTimeoutMillis:      _pool.options.idleTimeoutMillis,
    connectionTimeoutMillis: _pool.options.connectionTimeoutMillis,
  });

  return _pool;
}

/**
 * Gracefully drain the pool.
 * Call this during SIGTERM / SIGINT handling so in-flight queries
 * finish before the process exits.
 *
 * @returns {Promise<void>}
 */
async function closePool() {
  if (!_pool) return;
  logger.info('pg pool: closing all connections …');
  await _pool.end();
  _pool = null;
  logger.info('pg pool: all connections closed');
}

module.exports = { getPool, closePool };

/**
 * queries.js
 *
 * Parameterised query functions for the /users domain.
 *
 * Security model
 * ──────────────
 * Every externally-supplied value is passed as a bind parameter ($1, $2 …)
 * so PostgreSQL treats it as data, never as SQL.  No string interpolation
 * or template literals are used with user input anywhere in this file.
 *
 * To search by partial name / email (searchUsers) we use the pg_trgm
 * ILIKE operator with the search term as a bind parameter — the wildcard
 * characters are added in application code to a sanitised copy of the
 * string, not by the user.
 *
 * Additional hardening
 * ─────────────────────
 * • `limit` / `offset` are coerced to integers and clamped to safe
 *   ranges before use.
 * • `id` is validated as a positive integer before the query is issued.
 * • The `query` string for searchUsers is trimmed and length-capped.
 * • `statement_timeout` is set on every new pool connection (see db.js)
 *   so runaway full-text scans cannot stall the server.
 *
 * Query timing
 * ─────────────
 * Every public function wraps `pool.query()` in a `queryWithTiming()`
 * helper that records wall-clock duration and logs it at DEBUG level as
 * structured JSON, giving you a searchable audit trail:
 *
 *   { queryName, durationMs, rowCount, params (sanitised) }
 *
 * Sensitive parameter values (passwords, tokens) should be added to the
 * SENSITIVE_PARAM_INDEXES set of each call when this module is extended.
 */

'use strict';

const { getPool } = require('./db');
const logger      = require('./logger');

// ── constants ─────────────────────────────────────────────────────────────────

/** Hard ceiling for the number of rows a single list call may return. */
const MAX_LIMIT = parseInt(process.env.MAX_PAGE_LIMIT, 10) || 100;

/** Default page size when the caller supplies no limit. */
const DEFAULT_LIMIT = parseInt(process.env.DEFAULT_PAGE_LIMIT, 10) || 20;

// ── internal helpers ──────────────────────────────────────────────────────────

/**
 * Execute `pool.query(text, params)`, measure wall-clock duration, and
 * emit a structured timing log entry.
 *
 * @param {object} options
 * @param {string}   options.queryName           - Human-readable label for logs
 * @param {string}   options.text                - Parameterised SQL statement
 * @param {unknown[]} options.params             - Bind parameters
 * @param {number[]} [options.redactedIndexes]   - 0-based param indexes whose
 *                                                 values should be hidden in logs
 *                                                 (e.g. password fields)
 * @returns {Promise<import('pg').QueryResult>}
 */
async function queryWithTiming({ queryName, text, params = [], redactedIndexes = [] }) {
  const pool  = getPool();
  const start = process.hrtime.bigint();

  let result;
  try {
    result = await pool.query(text, params);
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1e6;
    logger.error('db query error', {
      queryName,
      durationMs: parseFloat(durationMs.toFixed(3)),
      error:      err.message,
      code:       err.code,
    });
    throw err;
  }

  const durationMs = Number(process.hrtime.bigint() - start) / 1e6;

  // Build a safe copy of params for logging — redact sensitive positions.
  const safeParams = params.map((v, i) =>
    redactedIndexes.includes(i) ? '[REDACTED]' : v,
  );

  logger.debug('db query timing', {
    queryName,
    durationMs:  parseFloat(durationMs.toFixed(3)),
    rowCount:    result.rowCount,
    params:      safeParams,
  });

  return result;
}

/**
 * Coerce `value` to an integer, throwing a descriptive TypeError when it
 * is not a finite, non-negative integer.
 *
 * @param {unknown} value
 * @param {string}  fieldName - Used in the error message
 * @returns {number}
 */
function requirePositiveInt(value, fieldName) {
  const n = Number(value);
  if (!Number.isInteger(n) || n <= 0) {
    throw new TypeError(`${fieldName} must be a positive integer, got: ${JSON.stringify(value)}`);
  }
  return n;
}

/**
 * Clamp a number between `min` and `max` (inclusive), defaulting to
 * `fallback` when the input is not a finite number.
 *
 * @param {unknown} value
 * @param {number}  min
 * @param {number}  max
 * @param {number}  fallback
 * @returns {number}
 */
function clampInt(value, min, max, fallback) {
  const n = parseInt(value, 10);
  if (!Number.isFinite(n)) return fallback;
  return Math.min(Math.max(n, min), max);
}

/**
 * Sanitise a free-text search string.
 *
 * • Trims whitespace.
 * • Caps length to prevent absurdly long ILIKE patterns.
 * • Does NOT escape SQL wildcards ('%', '_') because we are using bind
 *   parameters — PostgreSQL does that for us.
 *
 * @param {unknown} raw
 * @param {number}  [maxLength=200]
 * @returns {string}
 */
function sanitiseSearchQuery(raw, maxLength = 200) {
  if (typeof raw !== 'string') {
    throw new TypeError(`search query must be a string, got: ${typeof raw}`);
  }
  const trimmed = raw.trim();
  if (trimmed.length === 0) {
    throw new TypeError('search query must not be empty');
  }
  return trimmed.slice(0, maxLength);
}

// ── public query functions ────────────────────────────────────────────────────

/**
 * Fetch a single user by their primary-key id.
 *
 * @param {number|string} id - The user's integer id
 * @returns {Promise<object|null>} The user row, or `null` if not found
 *
 * @example
 *   const user = await getUserById(42);
 *   // { id: 42, name: 'Alice', email: 'alice@example.com',
 *   //   created_at: Date, updated_at: Date }
 */
async function getUserById(id) {
  // Validate before touching the database — cheap and gives callers a
  // clear error message instead of a cryptic Postgres type error.
  const safeId = requirePositiveInt(id, 'id');

  // $1 is the only externally-supplied value; PostgreSQL casts it to the
  // column type (integer) before evaluating the WHERE clause.
  const text = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const result = await queryWithTiming({
    queryName: 'getUserById',
    text,
    params: [safeId],
  });

  return result.rows[0] ?? null;
}

/**
 * Return a paginated list of all users, ordered by id ascending.
 *
 * @param {number} [limit=DEFAULT_LIMIT]  - Rows per page (clamped to MAX_LIMIT)
 * @param {number} [offset=0]             - Number of rows to skip
 * @returns {Promise<{ users: object[], total: number, limit: number, offset: number }>}
 *
 * @example
 *   const page = await getAllUsers(10, 20);
 *   // { users: [...], total: 42, limit: 10, offset: 20 }
 */
async function getAllUsers(limit = DEFAULT_LIMIT, offset = 0) {
  const safeLimit  = clampInt(limit,  1, MAX_LIMIT, DEFAULT_LIMIT);
  const safeOffset = clampInt(offset, 0, Number.MAX_SAFE_INTEGER, 0);

  // We run two queries in parallel:
  //   1. The paginated data slice
  //   2. The total row count (so the client can build pagination UI)
  // Both use the pool concurrently — no transaction needed because we
  // only read and count consistency across two SELECT statements is fine.

  const dataText = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const countText = `
    SELECT COUNT(*) AS total
    FROM users
  `;

  const [dataResult, countResult] = await Promise.all([
    queryWithTiming({
      queryName: 'getAllUsers:data',
      text:      dataText,
      params:    [safeLimit, safeOffset],
    }),
    queryWithTiming({
      queryName: 'getAllUsers:count',
      text:      countText,
      params:    [],
    }),
  ]);

  return {
    users:  dataResult.rows,
    total:  parseInt(countResult.rows[0].total, 10),
    limit:  safeLimit,
    offset: safeOffset,
  };
