  const safeLimit  = clampInt(limit,  1, MAX_LIMIT, DEFAULT_LIMIT);
  const safeOffset = clampInt(offset, 0, Number.MAX_SAFE_INTEGER, 0);

  // The wildcard characters are appended in application code to a value
  // that is then passed as a bind parameter.  PostgreSQL's parameterised
