    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY
      -- Exact matches first, then prefix matches, then substring matches
      CASE
        WHEN name  ILIKE $2 THEN 0
        WHEN email ILIKE $2 THEN 0
        WHEN name  ILIKE $3 THEN 1
        WHEN email ILIKE $3 THEN 1
        ELSE 2
      END ASC,
      id ASC
    LIMIT  $4
    OFFSET $5
