/**
 * app.js
 *
 * Express application wired to the PostgreSQL query layer.
 *
 * /users endpoints
 * ─────────────────
 *   GET /users               - Paginated list  (getAllUsers)
 *   GET /users/search        - Free-text search (searchUsers)
 *   GET /users/:id           - Single user      (getUserById)
