});

// ── /users/search ── must be declared BEFORE /users/:id so Express does
//                     not try to parse "search" as an integer id.
/**
 * GET /users/search?q=alice&limit=10&offset=0
 *
 * Query parameters:
 *   q       {string}  required — search term
 *   limit   {number}  optional — rows per page
 *   offset  {number}  optional — rows to skip
 *
 * Response 200:
 *   { users: [...], total, limit, offset, query }
 */
app.get('/users/search', asyncRoute(async (req, res) => {
