  if (!q || typeof q !== 'string' || q.trim().length === 0) {
    return sendError(res, 400, 'Missing or empty query parameter: q');
  }

  const result = await searchUsers(q, limit, offset);
  res.json(result);
}));

// ── GET /users ───────────────────────────────────────────────────────────────
/**
 * GET /users?limit=20&offset=0
 *
 * Query parameters:
 *   limit   {number}  optional — rows per page  (default 20, max 100)
 *   offset  {number}  optional — rows to skip   (default 0)
 *
 * Response 200:
 *   { users: [...], total, limit, offset }
 */
app.get('/users', asyncRoute(async (req, res) => {
  const { limit, offset } = req.query;
  const result = await getAllUsers(limit, offset);
  res.json(result);
}));

// ── GET /users/:id ────────────────────────────────────────────────────────────
/**
 * GET /users/:id
 *
 * Path parameter:
 *   id  {number}  required — positive integer
 *
 * Response 200:  { id, name, email, created_at, updated_at }
 * Response 404:  { error: { status: 404, message: '…' } }
 */
app.get('/users/:id', asyncRoute(async (req, res) => {
  const rawId = req.params.id;

