  // letting the query layer throw a TypeError.
  if (!/^\d+$/.test(rawId)) {
    return sendError(res, 400, 'User id must be a positive integer', { received: rawId });
  }

  const user = await getUserById(rawId);

  if (!user) {
    return sendError(res, 404, `User with id ${rawId} not found`);
  }

  res.json(user);
