  // PostgreSQL errors have a `code` property (e.g. '42P01' = table missing).
  if (err.code) {
    logger.error('database error', {
      message: err.message,
      code:    err.code,
      path:    req.path,
    });
    return sendError(res, 503, 'Database error — please try again later');
  }

  // Catch-all
  logger.error('unhandled error', { message: err.message, stack: err.stack });
  sendError(res, 500, 'Internal server error');
});

// ── graceful shutdown ─────────────────────────────────────────────────────────

async function shutdown(signal) {
  logger.info(`${signal} received — shutting down gracefully`);
  // Give in-flight requests up to 10 s to complete.
  const server = app._server;
  if (server) {
    await new Promise((resolve) => server.close(resolve));
  }
  await closePool();
  logger.info('Shutdown complete');
  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ── start ─────────────────────────────────────────────────────────────────────

// Only listen when this file is run directly (not when imported by tests).
if (require.main === module) {
  const server = app.listen(PORT, () => {
    logger.info(`Server running on port ${PORT}`);
  });
  // Stash the server reference so the shutdown handler can close it.
  app._server = server;
}

module.exports = app;

