describe('getUserById', () => {
  const fakeUser = { id: 1, name: 'Alice', email: 'alice@example.com' };

  test('returns the user row when found', async () => {
    getPoolInstance().query.mockResolvedValueOnce({ rows: [fakeUser], rowCount: 1 });

    const user = await getUserById(1);
    expect(user).toEqual(fakeUser);
  });

  test('returns null when not found', async () => {
    getPoolInstance().query.mockResolvedValueOnce({ rows: [], rowCount: 0 });

    const user = await getUserById(999);
    expect(user).toBeNull();
  });

  test('passes id as a bind parameter, not interpolated', async () => {
    getPoolInstance().query.mockResolvedValueOnce({ rows: [fakeUser], rowCount: 1 });

    await getUserById(1);

    const [sql, params] = getPoolInstance().query.mock.calls[0];
    expect(params).toEqual([1]);
    // The SQL must NOT contain the id value directly.
    expect(sql).not.toMatch(/WHERE id = 1/);
    // It must use a placeholder.
    expect(sql).toMatch(/WHERE id = \$1/);
  });

  test('accepts a numeric string id', async () => {
    getPoolInstance().query.mockResolvedValueOnce({ rows: [fakeUser], rowCount: 1 });
    const user = await getUserById('1');
    expect(user).toEqual(fakeUser);
  });

  test('rejects non-integer id', async () => {
    await expect(getUserById('abc')).rejects.toThrow(TypeError);
  });

  test('rejects id = 0', async () => {
    await expect(getUserById(0)).rejects.toThrow(TypeError);
  });

  test('rejects negative id', async () => {
    await expect(getUserById(-5)).rejects.toThrow(TypeError);
  });

  // SQL injection prevention
  test.each([
    ["1 OR 1=1"],
    ["1; DROP TABLE users; --"],
    ["' OR '1'='1"],
    ["1 UNION SELECT * FROM secrets"],
  ])('rejects SQL-injection payload %s', async (payload) => {
    await expect(getUserById(payload)).rejects.toThrow(TypeError);
  });

  test('emits a debug timing log on success', async () => {
    getPoolInstance().query.mockResolvedValueOnce({ rows: [fakeUser], rowCount: 1 });
    await getUserById(1);

    expect(logger.debug).toHaveBeenCalledWith(
      'db query timing',
      expect.objectContaining({
        queryName:  'getUserById',
        durationMs: expect.any(Number),
        rowCount:   1,
      }),
    );
  });

  test('emits an error log and rethrows on DB failure', async () => {
    const dbErr = Object.assign(new Error('connection refused'), { code: 'ECONNREFUSED' });
    getPoolInstance().query.mockRejectedValueOnce(dbErr);

    await expect(getUserById(1)).rejects.toThrow('connection refused');
    expect(logger.error).toHaveBeenCalledWith(
      'db query error',
      expect.objectContaining({ queryName: 'getUserById' }),
    );
  });
});

