describe('getAllUsers', () => {
  const fakeUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  // getAllUsers issues TWO parallel queries; mock both.
  function mockBothQueries(users = fakeUsers, total = 2) {
    const pool = getPoolInstance();
    pool.query
      .mockResolvedValueOnce({ rows: users,                    rowCount: users.length })
      .mockResolvedValueOnce({ rows: [{ total: String(total) }], rowCount: 1 });
  }

  test('returns users array and total', async () => {
    mockBothQueries();
    const result = await getAllUsers();
    expect(result.users).toEqual(fakeUsers);
    expect(result.total).toBe(2);
  });

  test('applies default limit and offset', async () => {
    mockBothQueries();
    const result = await getAllUsers();
    expect(result.limit).toBe(DEFAULT_LIMIT);
    expect(result.offset).toBe(0);
  });

  test('respects provided limit and offset', async () => {
    mockBothQueries();
    const result = await getAllUsers(5, 10);
    expect(result.limit).toBe(5);
    expect(result.offset).toBe(10);
  });

  test('clamps limit to MAX_LIMIT', async () => {
    mockBothQueries();
    const result = await getAllUsers(9999);
    expect(result.limit).toBe(MAX_LIMIT);
  });

  test('clamps limit minimum to 1', async () => {
    mockBothQueries();
    const result = await getAllUsers(0);
    expect(result.limit).toBe(1);
  });

  test('clamps negative offset to 0', async () => {
    mockBothQueries();
    const result = await getAllUsers(10, -5);
    expect(result.offset).toBe(0);
  });

  test('passes limit and offset as bind parameters', async () => {
    mockBothQueries();
    await getAllUsers(10, 20);

    // First call is the data query — params should be [limit, offset].
    const [sql, params] = getPoolInstance().query.mock.calls[0];
    expect(params).toEqual([10, 20]);
    expect(sql).toMatch(/LIMIT\s+\$1/);
    expect(sql).toMatch(/OFFSET\s+\$2/);
  });

  test('emits timing logs for both sub-queries', async () => {
    mockBothQueries();
    await getAllUsers();

    const timingCalls = logger.debug.mock.calls.filter(
      ([msg]) => msg === 'db query timing',
    );
    expect(timingCalls).toHaveLength(2);
    const names = timingCalls.map(([, meta]) => meta.queryName);
    expect(names).toContain('getAllUsers:data');
    expect(names).toContain('getAllUsers:count');
  });
});

