// searchUsers
// ─────────────────────────────────────────────────────────────────────────────

describe('searchUsers', () => {
  const fakeUsers = [{ id: 1, name: 'Alice', email: 'alice@example.com' }];

  function mockBothQueries(users = fakeUsers, total = 1) {
    const pool = getPoolInstance();
    pool.query
      .mockResolvedValueOnce({ rows: users,                    rowCount: users.length })
      .mockResolvedValueOnce({ rows: [{ total: String(total) }], rowCount: 1 });
  }

  test('returns matching users and total', async () => {
    mockBothQueries();
    const result = await searchUsers('ali');
    expect(result.users).toEqual(fakeUsers);
    expect(result.total).toBe(1);
  });

  test('echoes back the sanitised query string', async () => {
    mockBothQueries();
    const result = await searchUsers('  alice  ');
    expect(result.query).toBe('alice');
  });

  test('wraps search term in % wildcards as a bind parameter', async () => {
    mockBothQueries();
    await searchUsers('alice');

    const [sql, params] = getPoolInstance().query.mock.calls[0];
    // The wildcard pattern must be a bind param, not inline SQL.
    expect(params[0]).toBe('%alice%');
    expect(sql).not.toMatch(/%alice%/);
    expect(sql).toMatch(/ILIKE \$1/);
  });

  test('uses separate bind params for exact and prefix boost', async () => {
    mockBothQueries();
    await searchUsers('alice');

    const [, params] = getPoolInstance().query.mock.calls[0];
    expect(params[0]).toBe('%alice%');   // ILIKE filter
    expect(params[1]).toBe('alice');     // exact boost
    expect(params[2]).toBe('alice%');    // prefix boost
  });

  test('throws on empty query', async () => {
    await expect(searchUsers('')).rejects.toThrow(TypeError);
  });

  test('throws on whitespace-only query', async () => {
    await expect(searchUsers('   ')).rejects.toThrow(TypeError);
  });

  test('throws on non-string query', async () => {
    await expect(searchUsers(42)).rejects.toThrow(TypeError);
  });

  // SQL injection prevention — the key property being tested is that the
  // payload is *always* passed as a bind parameter, never interpolated.
  test.each([
    ["' OR '1'='1"],
    ["alice'; DROP TABLE users; --"],
    ["% OR 1=1 --"],
    ["alice' UNION SELECT password FROM users --"],
    ["\\"],
    ["\0"],
  ])('passes SQL-injection payload safely as bind param: %s', async (payload) => {
    mockBothQueries([], 0);
    // Should NOT throw — the payload is just treated as a search string.
    const result = await searchUsers(payload);
    const [, params] = getPoolInstance().query.mock.calls[0];
    // The raw payload must appear only inside the pattern bind param.
    expect(params[0]).toContain(payload.trim());
    expect(result.users).toEqual([]);
  });

  test('emits timing logs for both sub-queries', async () => {
    mockBothQueries();
    await searchUsers('alice');

    const timingCalls = logger.debug.mock.calls.filter(
      ([msg]) => msg === 'db query timing',
    );
    expect(timingCalls).toHaveLength(2);
    const names = timingCalls.map(([, meta]) => meta.queryName);
    expect(names).toContain('searchUsers:data');
    expect(names).toContain('searchUsers:count');
  });

  test('respects limit and offset', async () => {
    mockBothQueries();
    const result = await searchUsers('alice', 5, 10);
    expect(result.limit).toBe(5);
    expect(result.offset).toBe(10);
  });

  test('clamps oversized limit', async () => {
    mockBothQueries();
    const result = await searchUsers('alice', 9999);
    expect(result.limit).toBe(MAX_LIMIT);
  });
});

