  test('response error shape is consistent', async () => {
    getUserById.mockResolvedValueOnce(null);

    const res = await request(app).get('/users/999');
    expect(res.body).toMatchObject({
      error: {
        status:  404,
        message: expect.any(String),
      },
    });
  });
});

