/**
 * db.js — PostgreSQL connection pool
 *
 * Reads connection config exclusively from environment variables.
 * Never hard-codes credentials.
 *
 * Required env vars (set in .env for local dev, never committed to VCS):
 *   DATABASE_URL  – full postgres connection string, OR use the five
 *                   individual vars below.
 *   PGHOST        – database host
 *   PGPORT        – database port (default 5432)
 *   PGDATABASE    – database name
 *   PGUSER        – database user
 *   PGPASSWORD    – database password
 *
 * Optional tuning vars:
 *   DB_POOL_MAX            – maximum pool size          (default 10)
 *   DB_POOL_IDLE_TIMEOUT   – idle client timeout ms     (default 30000)
 *   DB_CONN_TIMEOUT        – connection timeout ms      (default 5000)
 *   DB_STATEMENT_TIMEOUT   – per-query timeout ms       (default 10000)
 *   NODE_ENV               – when 'test', SSL is skipped
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool construction
// ---------------------------------------------------------------------------

const isTest = process.env.NODE_ENV === 'test';

const poolConfig = {
  // If DATABASE_URL is set it takes precedence; otherwise pg reads the
  // individual PG* env vars automatically.
  ...(process.env.DATABASE_URL ? { connectionString: process.env.DATABASE_URL } : {}),

  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT ?? '30000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_CONN_TIMEOUT ?? '5000', 10),

  // Enforce a server-side statement timeout so a runaway query cannot tie up
  // a pool slot indefinitely.
  options: `--statement_timeout=${process.env.DB_STATEMENT_TIMEOUT ?? '10000'}`,

  // Require SSL in non-test environments; accept self-signed certs only if
  // DB_SSL_REJECT_UNAUTHORIZED=false is explicitly set (staging, etc.).
  ...(isTest
    ? {}
    : {
        ssl: {
          rejectUnauthorized: process.env.DB_SSL_REJECT_UNAUTHORIZED !== 'false',
        },
      }),
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event listeners
// ---------------------------------------------------------------------------

pool.on('connect', (client) => {
  // Tag every new physical connection for easier server-side identification.
  client.query("SET application_name = 'express-app'").catch(() => {});
});

pool.on('error', (err) => {
  // Log unexpected errors on idle clients; never crash the process.
  console.error('[db] Unexpected pool client error:', err.message);
});

// ---------------------------------------------------------------------------
// Graceful shutdown
// ---------------------------------------------------------------------------

const shutdown = async () => {
  try {
    await pool.end();
    console.log('[db] Pool closed cleanly.');
  } catch (err) {
    console.error('[db] Error closing pool:', err.message);
  }
};

process.once('SIGINT', shutdown);
process.once('SIGTERM', shutdown);

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = pool;

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design principles
 * ─────────────────
 * 1. SQL injection prevention
 *    Every dynamic value is passed as a positional parameter ($1, $2, …).
 *    The pg driver sends them to PostgreSQL as wire-protocol bind parameters,
 *    so the database treats them as data, never as SQL syntax.  No string
 *    concatenation or template literals are used to build query text.
 *
 * 2. Input validation before the query reaches the DB
 *    Each exported function validates and sanitises its arguments first and
 *    throws a typed QueryValidationError that the route handler can map to a
 *    400 response — without an unnecessary round-trip to the database.
 *
 * 3. Connection pooling
 *    All functions use the shared Pool exported from db.js.  pool.query()
 *    automatically checks out a client, runs the query, and returns it —
 *    no manual client management is needed for single-statement operations.
 *
 * 4. Query timing
 *    Every query is wrapped with a high-resolution timer.  Duration is
 *    emitted as a structured log line so it can be ingested by any log
 *    aggregator without additional parsing.
 *
 * 5. Least-privilege column selection
 *    Queries select explicit columns rather than SELECT *.  Password hashes
 *    and other sensitive columns are never returned to callers.
 */

'use strict';

const pool = require('./db');

// ---------------------------------------------------------------------------
// Constants & configuration
// ---------------------------------------------------------------------------

/** Maximum number of rows a single getAllUsers call may return. */
const MAX_LIMIT = parseInt(process.env.QUERY_MAX_LIMIT ?? '100', 10);

/** Default page size when the caller omits `limit`. */
const DEFAULT_LIMIT = parseInt(process.env.QUERY_DEFAULT_LIMIT ?? '20', 10);

/** Minimum search term length for searchUsers (prevents full-table scans). */
const MIN_SEARCH_LENGTH = 2;

/** Maximum search term length (prevents oversized inputs). */
const MAX_SEARCH_LENGTH = 100;

// Columns returned to callers — never includes password_hash or secrets.
const USER_COLUMNS = 'id, name, email, created_at, updated_at';

// ---------------------------------------------------------------------------
// Typed error class
// ---------------------------------------------------------------------------

/**
 * Thrown when caller-supplied parameters fail validation.
 * The route handler maps this to a 400 Bad Request response.
 */
class QueryValidationError extends Error {
  /**
   * @param {string} message   Human-readable explanation.
   * @param {string} field     The parameter that failed validation.
   */
  constructor(message, field) {
    super(message);
    this.name = 'QueryValidationError';
    this.field = field;
    // Preserve stack trace in V8
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, QueryValidationError);
    }
  }
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Wraps pool.query() with structured timing logs.
 *
 * @param {string}   label       Short human-readable name shown in logs.
 * @param {string}   text        Parameterised SQL string.
 * @param {Array}    params      Positional parameter values.
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(label, text, params) {
  const start = process.hrtime.bigint();

  try {
    const result = await pool.query(text, params);
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.log(
      JSON.stringify({
        level: 'info',
        type: 'db_query',
        query: label,
        rows: result.rowCount,
        duration_ms: parseFloat(durationMs.toFixed(3)),
        timestamp: new Date().toISOString(),
      })
    );

    return result;
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.error(
      JSON.stringify({
        level: 'error',
        type: 'db_query_error',
        query: label,
        duration_ms: parseFloat(durationMs.toFixed(3)),
        // Log the error code & message but NOT the parameter values,
        // which could contain PII or secret data.
        error_code: err.code,
        error_message: err.message,
        timestamp: new Date().toISOString(),
      })
    );

    throw err;
  }
}

/**
 * Validates that a value is a safe positive integer.
 *
 * @param {*}      value   Raw value from caller.
 * @param {string} field   Field name used in error messages.
 * @param {number} min     Inclusive minimum.
 * @param {number} max     Inclusive maximum.
 * @returns {number}       Validated integer.
 * @throws {QueryValidationError}
 */
function validatePositiveInt(value, field, min, max) {
  const n = Number(value);

  if (!Number.isInteger(n)) {
    throw new QueryValidationError(
      `"${field}" must be an integer, received: ${JSON.stringify(value)}`,
      field
    );
  }
  if (n < min || n > max) {
    throw new QueryValidationError(
      `"${field}" must be between ${min} and ${max}, received: ${n}`,
      field
    );
  }

  return n;
}

/**
 * Validates and sanitises a free-text search term.
 *
 * @param {*} value   Raw value from caller.
 * @returns {string}  Trimmed, validated string.
 * @throws {QueryValidationError}
 */
function validateSearchQuery(value) {
  if (typeof value !== 'string') {
    throw new QueryValidationError(
      `"query" must be a string, received: ${typeof value}`,
      'query'
    );
  }

  const trimmed = value.trim();

  if (trimmed.length < MIN_SEARCH_LENGTH) {
    throw new QueryValidationError(
      `"query" must be at least ${MIN_SEARCH_LENGTH} characters after trimming`,
      'query'
    );
  }
  if (trimmed.length > MAX_SEARCH_LENGTH) {
    throw new QueryValidationError(
      `"query" must be at most ${MAX_SEARCH_LENGTH} characters`,
      'query'
    );
  }

  return trimmed;
}

// ---------------------------------------------------------------------------
// Exported query functions
// ---------------------------------------------------------------------------

/**
 * Fetch a single user by their primary key.
 *
 * SQL injection prevention
 * ────────────────────────
 * `id` is passed as the $1 bind parameter.  PostgreSQL casts it to the
 * column's integer type before evaluation — the user can never inject SQL
 * through this parameter.
 *
 * @param {number|string} id   The user's numeric ID.
 * @returns {Promise<Object|null>}   The user row, or null if not found.
 * @throws {QueryValidationError}    If `id` is not a valid positive integer.
 */
async function getUserById(id) {
  const safeId = validatePositiveInt(id, 'id', 1, Number.MAX_SAFE_INTEGER);

  const sql = `
    SELECT ${USER_COLUMNS}
    FROM   users
    WHERE  id = $1
    LIMIT  1
  `;

  const { rows } = await timedQuery('getUserById', sql, [safeId]);
  return rows[0] ?? null;
}

/**
 * Return a paginated list of all users.
 *
 * SQL injection prevention
 * ────────────────────────
 * Both `limit` and `offset` are passed as $1/$2 bind parameters.
 * PostgreSQL treats them as integer literals, never as SQL fragments.
 *
 * @param {number} [limit=DEFAULT_LIMIT]   Max rows to return (1–MAX_LIMIT).
 * @param {number} [offset=0]             Number of rows to skip (≥ 0).
 * @returns {Promise<{users: Object[], total: number, limit: number, offset: number}>}
 * @throws {QueryValidationError}   If limit or offset are out of range.
 */
async function getAllUsers(limit = DEFAULT_LIMIT, offset = 0) {
  const safeLimit  = validatePositiveInt(limit,  'limit',  1, MAX_LIMIT);
  const safeOffset = validatePositiveInt(offset, 'offset', 0, Number.MAX_SAFE_INTEGER);

  // Two parameterised statements: one for the page, one for the total count.
  // COUNT(*) uses the same WHERE clause (none here) so the total stays in
  // sync when filters are later added.
  const dataSql = `
    SELECT   ${USER_COLUMNS}
    FROM     users
    ORDER BY id ASC
    LIMIT    $1
    OFFSET   $2
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM   users
  `;

  // Run both queries concurrently — they are independent reads.
  const [dataResult, countResult] = await Promise.all([
    timedQuery('getAllUsers:data',  dataSql,  [safeLimit, safeOffset]),
    timedQuery('getAllUsers:count', countSql, []),
  ]);

  return {
    users:  dataResult.rows,
    total:  parseInt(countResult.rows[0].total, 10),
    limit:  safeLimit,
    offset: safeOffset,
  };
}

/**
 * Full-text search across user names and emails.
 *
 * SQL injection prevention
 * ────────────────────────
 * The search term is passed as the $1 bind parameter wrapped in `%…%` for
 * ILIKE.  The wrapping happens in JavaScript before binding, so the final
 * value is still a single parameter — never concatenated into the SQL text.
 * PostgreSQL's ILIKE operator treats `%` and `_` inside the pattern as
 * wildcards, so we additionally escape those characters in the user's input
 * to prevent wildcard abuse (e.g. a lone `%` matching every row).
 *
 * @param {string} query              The search term (2–100 chars after trim).
 * @param {number} [limit=DEFAULT_LIMIT]
 * @param {number} [offset=0]
 * @returns {Promise<{users: Object[], total: number, limit: number, offset: number, query: string}>}
 * @throws {QueryValidationError}   If any argument fails validation.
 */
async function searchUsers(query, limit = DEFAULT_LIMIT, offset = 0) {
  const safeQuery  = validateSearchQuery(query);
  const safeLimit  = validatePositiveInt(limit,  'limit',  1, MAX_LIMIT);
  const safeOffset = validatePositiveInt(offset, 'offset', 0, Number.MAX_SAFE_INTEGER);

  // Escape ILIKE special characters in the caller's term so that `%`, `_`,
  // and `\` are treated as literals rather than pattern metacharacters.
  // The ESCAPE clause tells PostgreSQL that `\` is our escape character.
  const escapedTerm = safeQuery
    .replace(/\\/g, '\\\\')   // backslash first (order matters)
    .replace(/%/g,  '\\%')
    .replace(/_/g,  '\\_');

  const pattern = `%${escapedTerm}%`;

  const dataSql = `
    SELECT   ${USER_COLUMNS}
    FROM     users
    WHERE    name  ILIKE $1 ESCAPE '\\'
          OR email ILIKE $1 ESCAPE '\\'
    ORDER BY id ASC
    LIMIT    $2
    OFFSET   $3
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM   users
    WHERE  name  ILIKE $1 ESCAPE '\\'
        OR email ILIKE $1 ESCAPE '\\'
  `;

  const [dataResult, countResult] = await Promise.all([
    timedQuery('searchUsers:data',  dataSql,  [pattern, safeLimit, safeOffset]),
    timedQuery('searchUsers:count', countSql, [pattern]),
  ]);

  return {
    users:  dataResult.rows,
    total:  parseInt(countResult.rows[0].total, 10),
    limit:  safeLimit,
    offset: safeOffset,
    query:  safeQuery,   // echo back the sanitised term, not the raw input
  };
}

// ---------------------------------------------------------------------------
// Module exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryValidationError,  // exported so route handlers can do instanceof checks
};

/**
 * app.js — Express application with database-backed /users endpoint
 *
 * Route overview
 * ──────────────
 *   GET /health          — liveness probe
 *   GET /users           — paginated list  (?limit=20&offset=0)
 *   GET /users/search    — search by name/email (?q=alice&limit=20&offset=0)
 *   GET /users/:id       — single user by ID
 */

'use strict';

// Load .env only in local development; production injects vars via the host.
if (process.env.NODE_ENV !== 'production') {
  require('dotenv').config();
}

const express = require('express');
const { getUserById, getAllUsers, searchUsers, QueryValidationError } = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Request-level timing middleware
// ---------------------------------------------------------------------------

app.use((req, res, next) => {
  const start = process.hrtime.bigint();

  res.on('finish', () => {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;
    console.log(
      JSON.stringify({
        level: 'info',
        type: 'http_request',
        method: req.method,
        path: req.path,
        status: res.statusCode,
        duration_ms: parseFloat(durationMs.toFixed(3)),
        timestamp: new Date().toISOString(),
      })
    );
  });

  next();
});

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Centralised error handler for route callbacks.
 * Maps QueryValidationError → 400, everything else → 500.
 *
 * @param {Error}    err
 * @param {import('express').Response} res
 */
function handleError(err, res) {
  if (err instanceof QueryValidationError) {
    return res.status(400).json({
      error: 'Bad Request',
      message: err.message,
      field: err.field,
    });
  }

  // Log server-side errors without leaking internals to the client.
  console.error(
    JSON.stringify({
      level: 'error',
      type: 'unhandled_route_error',
      error_message: err.message,
      stack: err.stack,
      timestamp: new Date().toISOString(),
    })
  );

  return res.status(500).json({ error: 'Internal Server Error' });
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/** Liveness probe — does NOT hit the database. */
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users/search?q=<term>[&limit=20][&offset=0]
 *
 * Must be registered BEFORE /users/:id so that the literal path segment
 * "search" is not captured as an :id parameter.
 */
app.get('/users/search', async (req, res) => {
  const { q, limit, offset } = req.query;

  if (!q) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Missing required query parameter: q',
      field: 'q',
    });
  }

  try {
    const result = await searchUsers(
      q,
      limit  !== undefined ? Number(limit)  : undefined,
      offset !== undefined ? Number(offset) : undefined
    );
    return res.json(result);
  } catch (err) {
    return handleError(err, res);
  }
});

/**
 * GET /users[?limit=20][&offset=0]
 *
 * Returns a paginated list of all users together with the total row count
 * so clients can calculate page numbers without a separate request.
 */
app.get('/users', async (req, res) => {
  const { limit, offset } = req.query;

  try {
    const result = await getAllUsers(
      limit  !== undefined ? Number(limit)  : undefined,
      offset !== undefined ? Number(offset) : undefined
    );
    return res.json(result);
  } catch (err) {
    return handleError(err, res);
  }
});

/**
 * GET /users/:id
 *
 * Path parameter :id is validated inside getUserById before it ever reaches
 * the database.  A non-numeric value triggers a 400 rather than a DB error.
 */
app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: `No user found with id ${req.params.id}`,
      });
    }

    return res.json(user);
  } catch (err) {
    return handleError(err, res);
  }
});

// ---------------------------------------------------------------------------
// Server bootstrap
// ---------------------------------------------------------------------------

const PORT = parseInt(process.env.PORT ?? '3000', 10);

// Only start listening when this file is executed directly, not when it is
// require()'d by tests.
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(
      JSON.stringify({
        level: 'info',
        type: 'server_start',
        port: PORT,
        node_env: process.env.NODE_ENV ?? 'development',
        timestamp: new Date().toISOString(),
      })
    );
  });
}

module.exports = app;

/**
 * queries.test.js — Unit tests for queries.js
 *
 * Runs without a real database by mocking the `pg` Pool.
 * Run with: node queries.test.js
 */

'use strict';

// ---------------------------------------------------------------------------
// Minimal test harness (no external test-runner dependency)
// ---------------------------------------------------------------------------

let passed = 0;
let failed = 0;

async function test(description, fn) {
  try {
    await fn();
    console.log(`  ✓  ${description}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${description}`);
    console.error(`     ${err.message}`);
    failed++;
  }
}

function assert(condition, msg) {
  if (!condition) throw new Error(msg ?? 'Assertion failed');
}

function assertEqual(a, b, msg) {
  if (a !== b)
    throw new Error(msg ?? `Expected ${JSON.stringify(a)} === ${JSON.stringify(b)}`);
}

function assertRejects(promise, errorName) {
  return promise.then(
    () => { throw new Error(`Expected rejection but promise resolved`); },
    (err) => {
      if (errorName && err.name !== errorName)
        throw new Error(`Expected ${errorName} but got ${err.name}: ${err.message}`);
    }
  );
}

// ---------------------------------------------------------------------------
// Mock pg pool
// ---------------------------------------------------------------------------

// Track every call made to pool.query for assertion purposes.
const queryCalls = [];

// Default stub rows returned by pool.query — overridden per test.
let mockRows       = [];
let mockRowCount   = 0;
let mockCountRow   = { total: '0' };
let shouldThrow    = null;

// Replace the real `pg` module with a lightweight mock.
const Module = require('module');
const originalLoad = Module._load;

Module._load = function (request, parent, isMain) {
  if (request === 'pg') {
    return {
      Pool: class MockPool {
        constructor() {}
        query(text, params) {
          queryCalls.push({ text: text.replace(/\s+/g, ' ').trim(), params });

          if (shouldThrow) {
            return Promise.reject(shouldThrow);
          }

          // COUNT query returns the count row; data query returns mock rows.
          const isCount = /SELECT COUNT/i.test(text);
          return Promise.resolve({
            rows:      isCount ? [mockCountRow] : mockRows,
            rowCount:  isCount ? 1 : mockRowCount,
          });
        }
        on() {}
        end() { return Promise.resolve(); }
      },
    };
  }
  return originalLoad.apply(this, arguments);
};

// Invalidate the require cache so queries.js picks up our mock pool.
delete require.cache[require.resolve('./db')];
delete require.cache[require.resolve('./queries')];

const { getUserById, getAllUsers, searchUsers, QueryValidationError } = require('./queries');

// ---------------------------------------------------------------------------
// Helper: reset state between tests
// ---------------------------------------------------------------------------

function reset(opts = {}) {
  queryCalls.length = 0;
  mockRows        = opts.rows      ?? [];
  mockRowCount    = opts.rowCount  ?? (opts.rows?.length ?? 0);
  mockCountRow    = { total: String(opts.total ?? 0) };
  shouldThrow     = opts.throws    ?? null;
}

// ---------------------------------------------------------------------------
// getUserById
// ---------------------------------------------------------------------------

console.log('\ngetUserById');

await test('returns the matching user row', async () => {
  reset({ rows: [{ id: 1, name: 'Alice', email: 'alice@example.com' }] });
  const user = await getUserById(1);
  assertEqual(user.id, 1);
  assertEqual(user.name, 'Alice');
});

await test('returns null when no row is found', async () => {
  reset({ rows: [] });
  const user = await getUserById(99);
  assertEqual(user, null);
});

await test('passes id as a bind parameter, not inline SQL', async () => {
  reset({ rows: [] });
  await getUserById(42);
  const { params } = queryCalls[0];
