/**
 * queries.test.js — Unit tests for queries.js
 *
 * Runs without a real database by mocking the `pg` Pool.
 * Run with: node queries.test.js
 */

'use strict';

// ---------------------------------------------------------------------------
// Minimal test harness (no external test-runner dependency)
// ---------------------------------------------------------------------------

let passed = 0;
let failed = 0;

async function test(description, fn) {
  try {
    await fn();
    console.log(`  ✓  ${description}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${description}`);
    console.error(`     ${err.message}`);
    failed++;
  }
}

function assert(condition, msg) {
  if (!condition) throw new Error(msg ?? 'Assertion failed');
}

function assertEqual(a, b, msg) {
  if (a !== b)
    throw new Error(msg ?? `Expected ${JSON.stringify(a)} === ${JSON.stringify(b)}`);
}

function assertRejects(promise, errorName) {
  return promise.then(
    () => { throw new Error(`Expected rejection but promise resolved`); },
    (err) => {
      if (errorName && err.name !== errorName)
        throw new Error(`Expected ${errorName} but got ${err.name}: ${err.message}`);
    }
  );
}

// ---------------------------------------------------------------------------
// Mock pg pool
// ---------------------------------------------------------------------------

// Track every call made to pool.query for assertion purposes.
const queryCalls = [];

// Default stub rows returned by pool.query — overridden per test.
let mockRows       = [];
let mockRowCount   = 0;
let mockCountRow   = { total: '0' };
let shouldThrow    = null;

// Replace the real `pg` module with a lightweight mock.
const Module = require('module');
const originalLoad = Module._load;

Module._load = function (request, parent, isMain) {
  if (request === 'pg') {
    return {
      Pool: class MockPool {
        constructor() {}
        query(text, params) {
          queryCalls.push({ text: text.replace(/\s+/g, ' ').trim(), params });

          if (shouldThrow) {
            return Promise.reject(shouldThrow);
          }

          // COUNT query returns the count row; data query returns mock rows.
          const isCount = /SELECT COUNT/i.test(text);
          return Promise.resolve({
            rows:      isCount ? [mockCountRow] : mockRows,
            rowCount:  isCount ? 1 : mockRowCount,
          });
        }
        on() {}
        end() { return Promise.resolve(); }
      },
    };
  }
  return originalLoad.apply(this, arguments);
};

// Invalidate the require cache so queries.js picks up our mock pool.
delete require.cache[require.resolve('./db')];
delete require.cache[require.resolve('./queries')];

