/**
 * db.js — PostgreSQL connection pool
 *
 * Centralises pool creation so every module imports the same
 * singleton instance. Configuration is read exclusively from
 * environment variables — never hard-coded credentials.
 *
 * Required environment variables (set in .env for local dev):
 *   DB_HOST      – hostname of the PostgreSQL server
 *   DB_PORT      – port (default 5432)
 *   DB_NAME      – database name
 *   DB_USER      – database user
 *   DB_PASSWORD  – database password
 *   DB_POOL_MIN  – minimum pool size (default 2)
 *   DB_POOL_MAX  – maximum pool size (default 10)
 *   DB_IDLE_MS   – ms before an idle client is released (default 10 000)
 *   DB_CONN_MS   – connection timeout in ms (default 5 000)
 *   NODE_ENV     – when "test" the pool is created but never used for real queries
 */

'use strict';

require('dotenv').config();
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration — all values sourced from the environment
// ---------------------------------------------------------------------------
const poolConfig = {
  host:               process.env.DB_HOST     || 'localhost',
  port:               parseInt(process.env.DB_PORT  || '5432', 10),
  database:           process.env.DB_NAME     || 'app',
  user:               process.env.DB_USER,           // no default — must be set
  password:           process.env.DB_PASSWORD,        // no default — must be set
  min:                parseInt(process.env.DB_POOL_MIN  || '2',     10),
  max:                parseInt(process.env.DB_POOL_MAX  || '10',    10),
  idleTimeoutMillis:  parseInt(process.env.DB_IDLE_MS   || '10000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_CONN_MS || '5000', 10),

  // Enforce SSL in production; allow override for local dev
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true }
    : (process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false),
};

// ---------------------------------------------------------------------------
// Create the shared pool singleton
// ---------------------------------------------------------------------------
const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event listeners
// ---------------------------------------------------------------------------

/** Log when a new physical connection is established. */
pool.on('connect', (client) => {
  console.log(
    `[db] New client connected — pool size: ${pool.totalCount} ` +
    `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`
  );
});

/** Log idle client removal. */
pool.on('remove', () => {
  console.log(
    `[db] Client removed from pool — pool size: ${pool.totalCount} ` +
    `(idle: ${pool.idleCount})`
  );
});

/**
 * Catch background errors emitted by idle clients (e.g. server-side
 * connection resets). Without this listener Node would throw an
 * unhandled 'error' event and crash the process.
 */
pool.on('error', (err) => {
  console.error('[db] Unexpected error on idle client:', err.message);
  // Do NOT process.exit() here — let the pool recover by creating
  // a replacement connection automatically.
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------

/**
 * Drain the pool cleanly during process shutdown.
 * Call this from your SIGTERM / SIGINT handlers.
 */
async function closePool() {
  console.log('[db] Draining connection pool…');
  await pool.end();
  console.log('[db] Pool closed.');
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------
module.exports = { pool, closePool };

/**
 * queries.js — Parameterised query functions for the /users resource
 *
 * Design principles applied here:
 *
 *  1. SQL injection prevention
 *     Every value that originates from user input is passed as a parameter
 *     ($1, $2 …) so it is transmitted to PostgreSQL separately from the SQL
 *     text. pg never interpolates user values into the query string.
 *
 *  2. Additional input validation
 *     Parameters are validated and coerced before they reach the driver.
 *     Invalid values throw a typed ValidationError so callers can return
 *     HTTP 400 instead of leaking a database error.
 *
 *  3. Connection pooling
 *     All queries use pool.query() which automatically checks out a client,
 *     runs the query, and returns the client to the pool — no manual release
 *     needed for simple queries.
 *
 *  4. Query timing logs
 *     A thin executeQuery() wrapper measures wall-clock duration for every
 *     query and writes a structured log line so slow queries are visible in
 *     application logs.
 *
 *  5. No secrets in logs
 *     Log lines include the query tag and timing but never parameter values,
 *     preventing accidental exposure of PII or credentials.
 */

'use strict';

const { pool } = require('./db');

// ---------------------------------------------------------------------------
// Typed error class — lets app.js distinguish validation failures
// ---------------------------------------------------------------------------

class ValidationError extends Error {
  /**
   * @param {string} message  Human-readable description
   * @param {string} field    Name of the offending parameter
   */
  constructor(message, field) {
    super(message);
    this.name  = 'ValidationError';
    this.field = field;
  }
}

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Maximum rows a single getAllUsers call may return. */
const MAX_LIMIT = 100;

/** Minimum allowed limit value. */
const MIN_LIMIT = 1;

/** Maximum length of the search query string. */
const MAX_SEARCH_LENGTH = 200;

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * executeQuery — runs a parameterised query through the shared pool,
 * measures its duration, and emits a structured timing log.
 *
 * @param {string}   tag    Short label used in logs (never user-supplied).
 * @param {string}   text   Parameterised SQL string.
 * @param {Array}    params Bound parameter values — never interpolated.
 * @returns {Promise<import('pg').QueryResult>}
 */
async function executeQuery(tag, text, params = []) {
  const start = process.hrtime.bigint();           // nanosecond precision

  try {
    const result = await pool.query({ text, values: params });

    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.log(
      `[query] tag=${tag} rows=${result.rowCount} ` +
      `duration=${durationMs.toFixed(3)}ms`
    );

    return result;
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    // Log the error but strip parameter values to avoid leaking PII.
    console.error(
      `[query] tag=${tag} status=error ` +
      `duration=${durationMs.toFixed(3)}ms ` +
      `message=${err.message}`
    );

    throw err;   // re-throw so callers can handle / map to HTTP responses
  }
}

/**
 * parsePositiveInt — coerces a value to a positive integer or throws
 * a ValidationError.
 *
 * @param {*}      raw    The raw value (string from query-string, number, etc.)
 * @param {string} field  Parameter name for the error message.
 * @param {number} min    Minimum acceptable value (inclusive).
 * @param {number} max    Maximum acceptable value (inclusive).
 * @returns {number}
 */
function parsePositiveInt(raw, field, min, max) {
  const n = Number(raw);

  if (!Number.isInteger(n)) {
    throw new ValidationError(
      `'${field}' must be an integer, received: ${JSON.stringify(raw)}`,
      field
    );
  }

  if (n < min || n > max) {
    throw new ValidationError(
      `'${field}' must be between ${min} and ${max}, received: ${n}`,
      field
    );
  }

  return n;
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * getUserById — fetch a single user row by primary key.
 *
 * SQL injection prevention: `id` is bound as $1; the driver sends it in a
 * separate binary wire frame, so it is physically impossible for it to alter
 * the query text.
 *
 * @param {number|string} id  The user's primary key.
 * @returns {Promise<Object|null>}  The user object, or null if not found.
 *
 * @example
 *   const user = await getUserById(42);
 *   if (!user) return res.status(404).json({ error: 'Not found' });
 */
async function getUserById(id) {
  // Validate: must be a positive integer that fits in a 32-bit signed column.
  const safeId = parsePositiveInt(id, 'id', 1, 2_147_483_647);

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const result = await executeQuery('getUserById', sql, [safeId]);
  return result.rows[0] ?? null;
}

/**
 * getAllUsers — fetch a paginated list of users.
 *
 * SQL injection prevention: `limit` and `offset` are both bound parameters.
 * Even though they are integers, passing them as parameters (rather than
 * string-interpolating them) means they are validated by the pg type system
 * and can never smuggle extra SQL tokens.
 *
 * @param {number|string} limit   Maximum rows to return (1–100, default 20).
 * @param {number|string} offset  Row offset for pagination (≥ 0, default 0).
 * @returns {Promise<{ users: Object[], total: number, limit: number, offset: number }>}
 *
 * @example
 *   const page = await getAllUsers(20, 40);
 *   // page.total lets the client calculate how many pages exist
 */
async function getAllUsers(limit = 20, offset = 0) {
  const safeLimit  = parsePositiveInt(limit,  'limit',  MIN_LIMIT, MAX_LIMIT);
  const safeOffset = parsePositiveInt(offset, 'offset', 0, Number.MAX_SAFE_INTEGER);

  // A single round-trip returns both the page of rows and the total count via
  // a window function, avoiding a second COUNT(*) query.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER() AS total_count
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const result = await executeQuery('getAllUsers', sql, [safeLimit, safeOffset]);

  const total = result.rows.length > 0
    ? parseInt(result.rows[0].total_count, 10)
    : 0;

  // Strip the internal total_count column from every returned row.
  const users = result.rows.map(({ total_count, ...user }) => user);

  return { users, total, limit: safeLimit, offset: safeOffset };
}

/**
 * searchUsers — full-text search across name and email columns.
 *
 * SQL injection prevention:
 *  • The search term is passed as $1 — it is NEVER concatenated into the
 *    SQL string.
 *  • ILIKE is used for case-insensitive matching; the wildcards (%) are
 *    appended inside the parameter value itself, not in the SQL text.
 *  • The search term is also sanitised: any literal % or _ characters
 *    (which are ILIKE metacharacters) are escaped with a backslash before
 *    being passed as the parameter, so users cannot craft wildcard patterns
 *    that blow up query performance.
 *  • limit and offset follow the same rules as getAllUsers.
 *
 * @param {string}        query   The search string (max 200 characters).
 * @param {number|string} limit   Maximum rows to return (1–100, default 20).
 * @param {number|string} offset  Row offset for pagination (≥ 0, default 0).
 * @returns {Promise<{ users: Object[], total: number, limit: number, offset: number, query: string }>}
 *
 * @example
 *   const results = await searchUsers('alice', 10, 0);
 */
async function searchUsers(query, limit = 20, offset = 0) {
  // ---- Validate query string -----------------------------------------------
  if (typeof query !== 'string') {
    throw new ValidationError(
      `'query' must be a string, received: ${typeof query}`,
      'query'
    );
  }

  const trimmed = query.trim();

  if (trimmed.length === 0) {
    throw new ValidationError("'query' must not be empty after trimming.", 'query');
  }

  if (trimmed.length > MAX_SEARCH_LENGTH) {
    throw new ValidationError(
      `'query' exceeds maximum length of ${MAX_SEARCH_LENGTH} characters.`,
      'query'
    );
  }

  // ---- Validate pagination --------------------------------------------------
  const safeLimit  = parsePositiveInt(limit,  'limit',  MIN_LIMIT, MAX_LIMIT);
  const safeOffset = parsePositiveInt(offset, 'offset', 0, Number.MAX_SAFE_INTEGER);

  // ---- Escape ILIKE metacharacters -----------------------------------------
  // This prevents the caller from injecting % and _ wildcards that would match
  // everything (or cause catastrophic backtracking in some DB engines).
  // The escape character used is '\'; we tell PostgreSQL via ESCAPE '\\'.
  const escapedQuery = trimmed
    .replace(/\\/g, '\\\\')   // must be first: escape the escape char itself
    .replace(/%/g,  '\\%')    // literal percent
    .replace(/_/g,  '\\_');   // literal underscore

  // Wrap in % for substring matching — only after escaping metacharacters.
  const searchParam = `%${escapedQuery}%`;

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE
      name  ILIKE $1 ESCAPE '\\'
      OR email ILIKE $1 ESCAPE '\\'
    ORDER BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const result = await executeQuery('searchUsers', sql, [searchParam, safeLimit, safeOffset]);

  const total = result.rows.length > 0
    ? parseInt(result.rows[0].total_count, 10)
    : 0;

  const users = result.rows.map(({ total_count, ...user }) => user);

  return { users, total, limit: safeLimit, offset: safeOffset, query: trimmed };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------
module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  ValidationError,   // exported so app.js can do `instanceof ValidationError`
};

'use strict';

require('dotenv').config();
const express = require('express');
const { closePool } = require('./db');
const { getUserById, getAllUsers, searchUsers, ValidationError } = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Request timing middleware
// ---------------------------------------------------------------------------

/**
 * Attaches a high-resolution start timestamp to every request and emits
 * a structured access-log line when the response finishes.
 */
app.use((req, res, next) => {
  req._startAt = process.hrtime.bigint();

  res.on('finish', () => {
    const durationMs = Number(process.hrtime.bigint() - req._startAt) / 1_000_000;
    console.log(
      `[http] ${req.method} ${req.originalUrl} ` +
      `status=${res.statusCode} duration=${durationMs.toFixed(3)}ms`
    );
  });

  next();
});

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Wraps a route handler so any thrown error is forwarded to Express's
 * error-handling middleware instead of crashing the process.
 *
 * @param {Function} fn  Async route handler.
 */
const asyncHandler = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/** GET /health — liveness probe */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------------------------------------------------------------------------
// GET /users
//
// Returns a paginated list of users, or performs a search when ?search= is
// supplied.
//
// Query-string parameters:
//   limit   {integer, 1–100}  Rows per page          (default: 20)
//   offset  {integer, ≥ 0}    Pagination offset       (default: 0)
//   search  {string, ≤ 200}   Substring to search for (optional)
//
// Examples:
//   GET /users
//   GET /users?limit=10&offset=20
//   GET /users?search=alice&limit=5
// ---------------------------------------------------------------------------
app.get(
  '/users',
  asyncHandler(async (req, res) => {
    const { limit = 20, offset = 0, search } = req.query;

    let payload;

    if (search !== undefined) {
      // searchUsers validates limit, offset, and search internally.
      payload = await searchUsers(search, limit, offset);
    } else {
      payload = await getAllUsers(limit, offset);
    }

    res.json({
      data:   payload.users,
      meta: {
        total:  payload.total,
        limit:  payload.limit,
        offset: payload.offset,
        ...(payload.query !== undefined && { query: payload.query }),
      },
    });
  })
);

// ---------------------------------------------------------------------------
// GET /users/:id
//
// Returns a single user by primary key.
//
// Path parameters:
//   id  {positive integer}  The user's primary key.
//
// Responses:
//   200  { data: { id, name, email, created_at, updated_at } }
//   400  { error: 'Validation error', details: '…', field: '…' }
//   404  { error: 'User not found', id: <n> }
// ---------------------------------------------------------------------------
app.get(
  '/users/:id',
  asyncHandler(async (req, res) => {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({
        error: 'User not found',
        id:    req.params.id,
      });
    }

    res.json({ data: user });
  })
);

// ---------------------------------------------------------------------------
// Error-handling middleware
// ---------------------------------------------------------------------------

/**
 * Central error handler.
 *
 * Converts ValidationError → 400, everything else → 500.
 * Database error messages are intentionally withheld from the client in
 * production to prevent information leakage.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  if (err instanceof ValidationError) {
    return res.status(400).json({
      error:   'Validation error',
      details: err.message,
      field:   err.field,
    });
  }

  // Log the full error server-side but never expose it to the client.
  console.error(`[error] ${req.method} ${req.originalUrl}:`, err.message);

  const isProd = process.env.NODE_ENV === 'production';
  res.status(500).json({
    error:   'Internal server error',
    ...(isProd ? {} : { details: err.message }),
  });
});

// ---------------------------------------------------------------------------
// Server startup & graceful shutdown
// ---------------------------------------------------------------------------
const PORT = parseInt(process.env.PORT || '3000', 10);

const server = app.listen(PORT, () => {
  console.log(`[app] Server running on port ${PORT} (NODE_ENV=${process.env.NODE_ENV || 'development'})`);
});

/**
 * Graceful shutdown: stop accepting new connections, wait for in-flight
 * requests to finish, then drain the DB pool.
 */
function shutdown(signal) {
  console.log(`[app] ${signal} received — shutting down gracefully…`);

  server.close(async () => {
    console.log('[app] HTTP server closed.');
    await closePool();
    process.exit(0);
  });

  // Force exit after 10 s if something is still hanging.
  setTimeout(() => {
    console.error('[app] Forced shutdown after timeout.');
    process.exit(1);
  }, 10_000).unref();
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

module.exports = app;

