require('dotenv').config();
const express = require('express');
const { closePool } = require('./db');
const { getUserById, getAllUsers, searchUsers, ValidationError } = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Request timing middleware
// ---------------------------------------------------------------------------

/**
 * Attaches a high-resolution start timestamp to every request and emits
 * a structured access-log line when the response finishes.
 */
app.use((req, res, next) => {
  req._startAt = process.hrtime.bigint();

  res.on('finish', () => {
    const durationMs = Number(process.hrtime.bigint() - req._startAt) / 1_000_000;
    console.log(
      `[http] ${req.method} ${req.originalUrl} ` +
      `status=${res.statusCode} duration=${durationMs.toFixed(3)}ms`
    );
  });

  next();
});

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Wraps a route handler so any thrown error is forwarded to Express's
 * error-handling middleware instead of crashing the process.
 *
 * @param {Function} fn  Async route handler.
 */
const asyncHandler = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/** GET /health — liveness probe */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------------------------------------------------------------------------
// GET /users
//
// Returns a paginated list of users, or performs a search when ?search= is
// supplied.
//
// Query-string parameters:
//   limit   {integer, 1–100}  Rows per page          (default: 20)
//   offset  {integer, ≥ 0}    Pagination offset       (default: 0)
//   search  {string, ≤ 200}   Substring to search for (optional)
//
// Examples:
//   GET /users
//   GET /users?limit=10&offset=20
//   GET /users?search=alice&limit=5
// ---------------------------------------------------------------------------
app.get(
  '/users',
  asyncHandler(async (req, res) => {
    const { limit = 20, offset = 0, search } = req.query;

    let payload;

    if (search !== undefined) {
      // searchUsers validates limit, offset, and search internally.
      payload = await searchUsers(search, limit, offset);
    } else {
      payload = await getAllUsers(limit, offset);
    }

    res.json({
      data:   payload.users,
      meta: {
        total:  payload.total,
        limit:  payload.limit,
        offset: payload.offset,
        ...(payload.query !== undefined && { query: payload.query }),
      },
    });
  })
);

