 * Graceful shutdown: stop accepting new connections, wait for in-flight
 * requests to finish, then drain the DB pool.
 */
function shutdown(signal) {
  console.log(`[app] ${signal} received — shutting down gracefully…`);

  server.close(async () => {
    console.log('[app] HTTP server closed.');
    await closePool();
