/**
 * queries.js
 * ----------
 * Parameterised query layer for the /users endpoint.
 *
 * Design decisions
 * ----------------
 * - All queries use numbered placeholders ($1, $2 …) — the pg driver sends
 *   values out-of-band so the database engine never interpolates user input
 *   into the SQL string.  This is the primary SQL-injection defence.
 * - A single pg.Pool is created once and exported so every request reuses an
 *   existing connection rather than opening a new one.
 * - Every query is wrapped in a timing helper that emits structured logs; the
 *   log lines are easy to pipe into any log aggregator.
 * - Input validation is performed before the query reaches the driver as a
 *   second line of defence.
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// 1. Connection pool
// ---------------------------------------------------------------------------

/**
 * A single pool instance shared across the entire process lifetime.
 * Configuration is read entirely from environment variables so no credentials
 * ever appear in source code.
 *
 * Recognised env vars (all optional — pg falls back to its own defaults):
 *   DATABASE_URL          – full connection string, takes precedence
 *   PGHOST / PGUSER / PGPASSWORD / PGDATABASE / PGPORT – individual fields
 *   DB_POOL_MAX           – maximum concurrent connections  (default: 10)
 *   DB_IDLE_TIMEOUT_MS    – ms before idle connection is closed (default: 30000)
 *   DB_CONN_TIMEOUT_MS    – ms to wait for a connection from the pool (default: 5000)
 */
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,   // undefined → pg uses PG* vars
  max:              parseInt(process.env.DB_POOL_MAX          ?? '10',  10),
  idleTimeoutMillis:parseInt(process.env.DB_IDLE_TIMEOUT_MS   ?? '30000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_CONN_TIMEOUT_MS ?? '5000', 10),
});

// Emit a warning if the pool itself encounters an idle-client error so the
// problem surfaces in logs even when no request is in flight.
pool.on('error', (err) => {
  console.error('[db] Unexpected pool error:', err.message);
});

// ---------------------------------------------------------------------------
// 2. Query timing / logging helper
// ---------------------------------------------------------------------------

/**
 * Executes a parameterised query, logs timing information, and returns the
 * pg Result object.
 *
 * @param {string}   sql    - The SQL string with $1…$n placeholders
 * @param {Array}    params - Positional parameter values (never interpolated)
 * @param {string}   [label] - Human-readable label for the log line
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery(sql, params, label = 'query') {
  const start = process.hrtime.bigint();

  try {
    const result = await pool.query(sql, params);
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.log(
      JSON.stringify({
        level:    'info',
        event:    'db_query',
        label,
        rows:     result.rowCount,
        duration: `${elapsedMs.toFixed(3)}ms`,
        ts:       new Date().toISOString(),
      })
    );

    return result;
  } catch (err) {
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.error(
      JSON.stringify({
        level:    'error',
        event:    'db_query_error',
        label,
        message:  err.message,
        duration: `${elapsedMs.toFixed(3)}ms`,
        ts:       new Date().toISOString(),
      })
    );

    throw err; // re-throw so the caller can translate it into an HTTP error
  }
}

// ---------------------------------------------------------------------------
// 3. Input validation helpers
// ---------------------------------------------------------------------------

/**
 * Asserts that a value is a safe positive integer.
 * Throws a TypeError (HTTP 400) if the assertion fails.
 *
 * @param {unknown} value
 * @param {string}  name  - Field name used in the error message
 * @returns {number}
 */
function requirePositiveInt(value, name) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 1) {
    const err = new TypeError(`"${name}" must be a positive integer, got: ${JSON.stringify(value)}`);
    err.statusCode = 400;
    throw err;
  }
  return n;
}

/**
 * Asserts that a value is a non-negative integer (0 is valid for OFFSET).
 *
 * @param {unknown} value
 * @param {string}  name
 * @returns {number}
 */
function requireNonNegativeInt(value, name) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0) {
    const err = new TypeError(`"${name}" must be a non-negative integer, got: ${JSON.stringify(value)}`);
    err.statusCode = 400;
    throw err;
  }
  return n;
}

/**
 * Sanitises a free-text search term.
 * - Strips leading/trailing whitespace.
 * - Enforces a maximum length to prevent abuse.
 * - Rejects empty strings.
 *
 * Note: the value is still passed as a query *parameter* ($1) so the database
 * driver never interpolates it.  The sanitisation here is an extra guard that
 * prevents excessively long strings from reaching the DB layer at all.
 *
 * @param {unknown} value
 * @returns {string}
 */
function requireSearchTerm(value) {
  if (typeof value !== 'string') {
    const err = new TypeError('"query" must be a string');
    err.statusCode = 400;
    throw err;
  }
  const term = value.trim();
  if (term.length === 0) {
    const err = new TypeError('"query" must not be empty');
    err.statusCode = 400;
    throw err;
  }
  if (term.length > 200) {
    const err = new TypeError('"query" must be 200 characters or fewer');
    err.statusCode = 400;
    throw err;
  }
  return term;
}

// ---------------------------------------------------------------------------
// 4. Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetch a single user by their primary key.
 *
 * SQL injection prevention:
 *   `id` is validated as a positive integer before the call and is passed as
 *   the $1 parameter — it is never concatenated into the SQL string.
 *
 * @param {number|string} id - The user's primary-key value
 * @returns {Promise<object|null>} The user row, or null if not found
 *
 * @example
 *   const user = await getUserById(42);
 */
async function getUserById(id) {
  const safeId = requirePositiveInt(id, 'id');

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at AS "createdAt"
    FROM users
    WHERE id = $1
  `;

  const { rows } = await timedQuery(sql, [safeId], 'getUserById');
  return rows[0] ?? null;
}

/**
 * Return a page of users using keyset-safe LIMIT / OFFSET pagination.
 *
 * SQL injection prevention:
 *   Both `limit` and `offset` are validated as integers and passed as
 *   positional parameters — the SQL string is entirely static.
 *
 * @param {number} limit  - Maximum number of rows to return (1–100)
 * @param {number} offset - Number of rows to skip (≥ 0)
 * @returns {Promise<object[]>} Array of user rows (may be empty)
 *
 * @example
 *   const page1 = await getAllUsers(20, 0);
 *   const page2 = await getAllUsers(20, 20);
 */
async function getAllUsers(limit, offset) {
  const safeLimit  = requirePositiveInt(limit, 'limit');
  const safeOffset = requireNonNegativeInt(offset, 'offset');

  if (safeLimit > 100) {
    const err = new TypeError('"limit" must not exceed 100');
    err.statusCode = 400;
    throw err;
  }

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at AS "createdAt"
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const { rows } = await timedQuery(sql, [safeLimit, safeOffset], 'getAllUsers');
  return rows;
}

/**
 * Full-text search across user name and email using a case-insensitive
 * ILIKE pattern.  The wildcard characters are added *inside* the parameterised
 * value, not in the SQL string, so the driver still treats the entire pattern
 * as a plain string literal.
 *
 * SQL injection prevention:
 *   - `term` is validated and length-capped before use.
 *   - ILIKE metacharacters (%, _) inside the user's input are escaped so a
 *     user cannot craft a wildcard that degrades into a full-table scan or
 *     leaks unexpected rows.
 *   - The escaped term is passed as $1 — never concatenated.
 *
 * @param {string} query - Free-text search term
 * @returns {Promise<object[]>} Matching user rows (may be empty)
 *
 * @example
 *   const results = await searchUsers('ali');
 */
async function searchUsers(query) {
  const term = requireSearchTerm(query);

  // Escape ILIKE metacharacters so user input cannot be used to craft
  // arbitrary patterns.  The result is wrapped in % wildcards afterwards.
  const escaped  = term.replace(/[\\%_]/g, '\\$&');
  const pattern  = `%${escaped}%`;

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at AS "createdAt"
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY id ASC
    LIMIT 100
  `;

  const { rows } = await timedQuery(sql, [pattern], 'searchUsers');
  return rows;
}

// ---------------------------------------------------------------------------
// 5. Exports
// ---------------------------------------------------------------------------

module.exports = {
  pool,          // exported so app.js can call pool.end() on graceful shutdown
  getUserById,
  getAllUsers,
  searchUsers,
};

/**
 * app.js
 * ------
 * Express application wired up to the query layer in queries.js.
 *
 * /users endpoints
 * ----------------
 *   GET /users                    – paginated list  (?limit=20&offset=0)
 *   GET /users/search?query=alice – full-text search
 *   GET /users/:id                – single user by id
 */

'use strict';

const express = require('express');
const {
  pool,
  getUserById,
  getAllUsers,
  searchUsers,
} = require('./queries');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Utility: translate query-layer errors into appropriate HTTP responses
// ---------------------------------------------------------------------------

/**
 * Wraps an async route handler so unhandled rejections are forwarded to
 * Express's next(err) error pipeline automatically.
 *
 * @param {Function} fn - async (req, res, next) => void
 * @returns {Function}
 */
const asyncHandler = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

/**
 * Translates a caught error into a structured JSON response.
 * - TypeError thrown by the validation helpers carries statusCode 400.
 * - Everything else becomes a 500 with the message hidden from the client.
 *
 * @param {Error}    err
 * @param {object}   res - Express response
 */
function sendError(err, res) {
  const status = err.statusCode ?? 500;
  const message =
    status < 500
      ? err.message                       // safe to surface validation errors
      : 'An internal server error occurred'; // never leak db details to clients
  res.status(status).json({ error: message });
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Health-check (unchanged)
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ------------------------------------------------------------------
// GET /users/search?query=<term>
// Must be registered BEFORE /users/:id so Express matches it first.
// ------------------------------------------------------------------
app.get(
  '/users/search',
  asyncHandler(async (req, res) => {
    const { query } = req.query;

    if (!query) {
      return res
        .status(400)
        .json({ error: 'Missing required query parameter: "query"' });
    }

    const users = await searchUsers(query);
    res.json({ data: users, count: users.length });
  })
);

// ------------------------------------------------------------------
// GET /users/:id
// ------------------------------------------------------------------
app.get(
  '/users/:id',
  asyncHandler(async (req, res) => {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({ error: `User ${req.params.id} not found` });
    }

    res.json({ data: user });
  })
);

// ------------------------------------------------------------------
// GET /users?limit=20&offset=0
// ------------------------------------------------------------------
app.get(
  '/users',
  asyncHandler(async (req, res) => {
    // Apply safe defaults so the endpoint works with no query string.
    const limit  = req.query.limit  ?? '20';
    const offset = req.query.offset ?? '0';

    const users = await getAllUsers(limit, offset);
    res.json({
      data:   users,
      count:  users.length,
      limit:  Number(limit),
      offset: Number(offset),
    });
  })
);

// ---------------------------------------------------------------------------
// Global error handler (catches anything forwarded via next(err))
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  // Unexpected errors are logged server-side with full detail …
  console.error(
    JSON.stringify({
      level:   'error',
      event:   'unhandled_route_error',
      message: err.message,
      stack:   err.stack,
      ts:      new Date().toISOString(),
    })
  );
  // … but only a safe message is returned to the client.
  sendError(err, res);
});

// ---------------------------------------------------------------------------
// Server startup / graceful shutdown
// ---------------------------------------------------------------------------

const PORT = parseInt(process.env.PORT ?? '3000', 10);

const server = app.listen(PORT, () => {
  console.log(
    JSON.stringify({
      level: 'info',
      event: 'server_start',
      port:  PORT,
      ts:    new Date().toISOString(),
    })
  );
});

/**
 * Graceful shutdown: stop accepting new connections, wait for in-flight
 * requests to finish, then drain the connection pool cleanly.
 */
async function shutdown(signal) {
  console.log(
    JSON.stringify({ level: 'info', event: 'shutdown', signal, ts: new Date().toISOString() })
  );

  await new Promise((resolve, reject) =>
    server.close((err) => (err ? reject(err) : resolve()))
