// getAllUsers
// ===========================================================================
describe('getAllUsers', () => {
  const fakeUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: '2024-01-01' },
    { id: 2, name: 'Bob',   email: 'bob@example.com',   createdAt: '2024-01-02' },
  ];

  test('calls pool.query with parameterised LIMIT and OFFSET', async () => {
    mockQuery.mockResolvedValue(pgResult(fakeUsers));

    await getAllUsers(20, 0);

    const [sql, params] = mockQuery.mock.calls[0];

    expect(sql).toContain('$1');
    expect(sql).toContain('$2');
    expect(sql).toContain('LIMIT');
    expect(sql).toContain('OFFSET');
    // Values must NOT appear as literals in the SQL string
    expect(sql).not.toMatch(/\bLIMIT\s+20\b/);
    expect(sql).not.toMatch(/\bOFFSET\s+0\b/);
    expect(params).toEqual([20, 0]);
  });

  test('returns array of user rows', async () => {
    mockQuery.mockResolvedValue(pgResult(fakeUsers));
    const result = await getAllUsers(20, 0);
    expect(result).toEqual(fakeUsers);
  });

  test('returns empty array when no rows match', async () => {
    mockQuery.mockResolvedValue(pgResult([]));
    const result = await getAllUsers(10, 1000);
    expect(result).toEqual([]);
  });

  test('accepts string numbers for limit and offset', async () => {
    mockQuery.mockResolvedValue(pgResult(fakeUsers));
    await getAllUsers('10', '5');
    expect(mockQuery.mock.calls[0][1]).toEqual([10, 5]);
  });

