describe('searchUsers', () => {
  const fakeUsers = [
    { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: '2024-01-01' },
  ];

  test('calls pool.query with a parameterised ILIKE pattern', async () => {
    mockQuery.mockResolvedValue(pgResult(fakeUsers));

    await searchUsers('alice');

    const [sql, params] = mockQuery.mock.calls[0];

    expect(sql).toContain('$1');
    expect(sql).toContain('ILIKE');
    // 'alice' must NOT be interpolated into the SQL string
    expect(sql).not.toContain('alice');
    // Pattern is wrapped in % wildcards and passed as the parameter
    expect(params).toEqual(['%alice%']);
  });

  test('returns matching user rows', async () => {
    mockQuery.mockResolvedValue(pgResult(fakeUsers));
    const result = await searchUsers('alice');
    expect(result).toEqual(fakeUsers);
  });

  test('returns empty array when no users match', async () => {
    mockQuery.mockResolvedValue(pgResult([]));
    const result = await searchUsers('zzz');
    expect(result).toEqual([]);
  });

  test('escapes ILIKE metacharacters in user input', async () => {
    mockQuery.mockResolvedValue(pgResult([]));

    await searchUsers('50% off');
    expect(mockQuery.mock.calls[0][1]).toEqual(['%50\\% off%']);

    mockQuery.mockClear();
    await searchUsers('a_b');
    expect(mockQuery.mock.calls[0][1]).toEqual(['%a\\_b%']);
  });

  test('prevents sql injection attempt from reaching the db', async () => {
    mockQuery.mockResolvedValue(pgResult([]));

    // Classic injection string — must remain a literal parameter value, not SQL
    const injection = "' OR '1'='1";
    await searchUsers(injection);

    const [sql, params] = mockQuery.mock.calls[0];
    expect(sql).not.toContain(injection);
    expect(params[0]).toBe(`%${injection}%`);
  });

  test('trims surrounding whitespace from the search term', async () => {
    mockQuery.mockResolvedValue(pgResult(fakeUsers));
    await searchUsers('  alice  ');
    expect(mockQuery.mock.calls[0][1]).toEqual(['%alice%']);
  });

  test.each([
    ['empty string',      ''],
    ['whitespace only',   '   '],
    ['non-string number', 123],
    ['null',              null],
    ['undefined',         undefined],
  ])('rejects invalid query: %s', async (_label, badQuery) => {
    await expect(searchUsers(badQuery)).rejects.toMatchObject({ statusCode: 400 });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects queries longer than 200 characters', async () => {
    const longQuery = 'a'.repeat(201);
    await expect(searchUsers(longQuery)).rejects.toMatchObject({ statusCode: 400 });
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('accepts a query of exactly 200 characters', async () => {
    mockQuery.mockResolvedValue(pgResult([]));
    const edgeQuery = 'a'.repeat(200);
    await expect(searchUsers(edgeQuery)).resolves.toEqual([]);
  });

  test('emits a timing log on success', async () => {
    mockQuery.mockResolvedValue(pgResult(fakeUsers));
    await searchUsers('alice');

    const logArg = JSON.parse(console.log.mock.calls[0][0]);
    expect(logArg).toMatchObject({ label: 'searchUsers', event: 'db_query' });
  });

  test('emits an error log and re-throws on db failure', async () => {
    mockQuery.mockRejectedValue(new Error('syntax error'));

    await expect(searchUsers('alice')).rejects.toThrow('syntax error');
    const logArg = JSON.parse(console.error.mock.calls[0][0]);
    expect(logArg.event).toBe('db_query_error');
  });
});

