/**
 * db.js — PostgreSQL connection pool
 *
 * A single Pool instance is created once and reused across the entire
 * application lifetime. Importing this module anywhere always returns
 * the same pool, so no extra connections are opened.
 *
 * Configuration is read exclusively from environment variables so that
 * credentials are never hard-coded in source files.
 *
 * Environment variables (set these in .env or in your deployment env):
 *   DATABASE_URL   – full connection URI  (takes precedence when present)
 *   PGHOST         – hostname
 *   PGPORT         – port          (default 5432)
 *   PGUSER         – username
 *   PGPASSWORD     – password
 *   PGDATABASE     – database name
 *   DB_POOL_MAX    – max pool size  (default 10)
 *   DB_POOL_MIN    – min pool size  (default 2)
 *   DB_IDLE_MS     – idle timeout ms (default 10 000)
 *   DB_CONN_MS     – connection timeout ms (default 5 000)
 *   DB_STATEMENT_MS– statement timeout ms (default 30 000)
 */

'use strict';

require('dotenv').config();

const { Pool } = require('pg');

// ─── Pool configuration ────────────────────────────────────────────────────

const poolConfig = {
  // When DATABASE_URL is present pg uses it directly; all PGXXX vars are
  // ignored in that case, so we only set them as a fallback.
  ...(process.env.DATABASE_URL
    ? { connectionString: process.env.DATABASE_URL }
    : {
        host:     process.env.PGHOST     ?? 'localhost',
        port:     Number(process.env.PGPORT ?? 5432),
        user:     process.env.PGUSER,
        password: process.env.PGPASSWORD,
        database: process.env.PGDATABASE,
      }),

  // Pool sizing
  max:              Number(process.env.DB_POOL_MAX  ?? 10),
  min:              Number(process.env.DB_POOL_MIN  ?? 2),

  // How long (ms) a client may sit idle before being closed
  idleTimeoutMillis:    Number(process.env.DB_IDLE_MS        ?? 10_000),

  // How long (ms) to wait for a client from the pool before throwing
  connectionTimeoutMillis: Number(process.env.DB_CONN_MS     ?? 5_000),

  // Hard upper bound on any single statement — last-resort runaway guard
  statement_timeout:    Number(process.env.DB_STATEMENT_MS   ?? 30_000),

  // Automatically apply TLS when the server advertises it
  ssl: process.env.PGSSLMODE === 'disable'
    ? false
    : { rejectUnauthorized: process.env.PGSSLMODE !== 'no-verify' },
};

const pool = new Pool(poolConfig);

// ─── Pool-level event hooks ────────────────────────────────────────────────

pool.on('connect', (client) => {
  console.info(`[db] new client connected — pool size ${pool.totalCount}`);

  // Set a per-session application name for pg_stat_activity visibility
  client.query("SET application_name = 'express-api'").catch(() => {});
});

pool.on('acquire', () => {
  console.debug(
    `[db] client acquired — idle ${pool.idleCount}  waiting ${pool.waitingCount}`
  );
});

pool.on('remove', () => {
  console.info(`[db] client removed — pool size now ${pool.totalCount}`);
});

pool.on('error', (err) => {
  // An idle client in the pool has thrown an unexpected error.
  // This does not crash the process but we must log it loudly.
  console.error('[db] unexpected pool error:', err.message);
});

// ─── Graceful shutdown ─────────────────────────────────────────────────────

async function closePool() {
  console.info('[db] draining connection pool…');
  await pool.end();
  console.info('[db] pool closed');
}

// ─── Exports ───────────────────────────────────────────────────────────────

module.exports = { pool, closePool };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Security model
 * ──────────────
 * Every value supplied by a caller is passed as a query *parameter* ($1, $2 …)
 * and never interpolated into the SQL string.  PostgreSQL's wire protocol
 * keeps the query text and the parameter values in separate protocol messages,
 * so the database server itself separates code from data — SQL injection is
 * structurally impossible regardless of what the parameter values contain.
 *
 * For `searchUsers` the LIKE pattern characters (% and _) are escaped in
 * application code before the value is handed to the driver so that a caller
 * cannot accidentally (or maliciously) broaden the match.
 *
 * Observability
 * ─────────────
 * Every function measures wall-clock time with `performance.now()` and emits
 * a structured timing log so slow queries are immediately visible in the
 * application log stream.
 */

'use strict';

const { performance } = require('perf_hooks');
const { pool }        = require('./db');

// ─── Constants ─────────────────────────────────────────────────────────────

// Hard limits prevent runaway queries even if the caller passes huge values.
const MAX_LIMIT  = 100;
const MIN_LIMIT  = 1;
const MIN_OFFSET = 0;

// Minimum search-term length guards against full-table scans on tiny strings.
const MIN_SEARCH_LENGTH = 2;
const MAX_SEARCH_LENGTH = 100;

// ─── Internal helpers ──────────────────────────────────────────────────────

/**
 * logQueryTiming — emit a structured timing entry.
 *
 * @param {string} fnName     - the public function name
 * @param {string} sql        - the SQL string (no parameter values)
 * @param {unknown[]} params  - bound parameter values
 * @param {number} startMs    - value from performance.now() before the query
 * @param {'ok'|'error'} status
 */
function logQueryTiming(fnName, sql, params, startMs, status) {
  const durationMs = (performance.now() - startMs).toFixed(3);

  // Intentionally log the SQL template and param *count*, not the param
  // *values*, to keep PII and sensitive data out of the log stream.
  console.info(
    JSON.stringify({
      ts:        new Date().toISOString(),
      layer:     'queries',
      fn:        fnName,
      status,
      durationMs: Number(durationMs),
      paramCount: params.length,
      sql:        sql.replace(/\s+/g, ' ').trim(),
    })
  );
}

/**
 * runQuery — thin wrapper that adds timing and uniform error handling around
 * `pool.query`.  All query functions call this instead of pool.query directly.
 *
 * @param {string}    fnName  - caller name, used in logs
 * @param {string}    sql     - parameterised SQL string
 * @param {unknown[]} params  - parameter values, matched positionally to $N
 * @returns {Promise<import('pg').QueryResult>}
 */
async function runQuery(fnName, sql, params) {
  const start = performance.now();
  try {
    const result = await pool.query(sql, params);
    logQueryTiming(fnName, sql, params, start, 'ok');
    return result;
  } catch (err) {
    logQueryTiming(fnName, sql, params, start, 'error');
    // Re-throw so the route handler can decide how to respond.
    throw err;
  }
}

/**
 * sanitiseLikePattern — escape LIKE metacharacters so that a caller-supplied
 * search term cannot widen or manipulate pattern matching.
 *
 * PostgreSQL LIKE special characters:
 *   %  – matches any sequence of characters
 *   _  – matches any single character
 *   \  – default escape character
 *
 * We escape the backslash first (to avoid double-escaping), then % and _.
 *
 * @param {string} raw
 * @returns {string}
 */
function sanitiseLikePattern(raw) {
  return raw
    .replace(/\\/g, '\\\\')
    .replace(/%/g, '\\%')
    .replace(/_/g, '\\_');
}

/**
 * validatePositiveInteger — throw a descriptive TypeError when a value is not
 * a safe, non-negative integer.  Used for `id`, `limit`, and `offset`.
 *
 * @param {unknown} value
 * @param {string}  name   - field name, used in the error message
 * @returns {number}
 */
function validatePositiveInteger(value, name) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0 || !Number.isFinite(n)) {
    throw new TypeError(
      `Invalid value for "${name}": expected a non-negative integer, got ${JSON.stringify(value)}`
    );
  }
  return n;
}

// ─── Public query functions ────────────────────────────────────────────────

/**
 * getUserById — fetch a single user row by primary key.
 *
 * @param {number|string} id  - the user's numeric primary key
 * @returns {Promise<object|null>}  the user object or null when not found
 *
 * @example
 *   const user = await getUserById(42);
 */
async function getUserById(id) {
  // Validate before touching the database.
  const safeId = validatePositiveInteger(id, 'id');

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const { rows } = await runQuery('getUserById', sql, [safeId]);
  return rows[0] ?? null;
}

/**
 * getAllUsers — return a paginated slice of the users table.
 *
 * Both `limit` and `offset` are clamped/validated server-side so callers
 * cannot request unlimited rows or supply negative offsets.
 *
 * @param {number} [limit=20]   - maximum rows to return (capped at MAX_LIMIT)
 * @param {number} [offset=0]   - number of rows to skip
 * @returns {Promise<{ users: object[], total: number, limit: number, offset: number }>}
 *
 * @example
 *   const page = await getAllUsers(10, 20);
 */
async function getAllUsers(limit = 20, offset = 0) {
  // Validate and clamp both pagination parameters.
  const safeOffset = Math.max(MIN_OFFSET, validatePositiveInteger(offset, 'offset'));
  const safeLimit  = Math.min(
    MAX_LIMIT,
    Math.max(MIN_LIMIT, validatePositiveInteger(limit, 'limit'))
  );

  // Fetch the data page and the total count in one round-trip using a window
  // function.  This avoids a second COUNT(*) query while keeping the SQL
  // readable.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER() AS total_count
    FROM users
    ORDER BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const { rows } = await runQuery('getAllUsers', sql, [safeLimit, safeOffset]);

  // Separate the pagination metadata from the row data.
  const total = rows.length > 0 ? Number(rows[0].total_count) : 0;
  const users = rows.map(({ total_count: _drop, ...rest }) => rest);

  return { users, total, limit: safeLimit, offset: safeOffset };
}

/**
 * searchUsers — case-insensitive prefix/substring search across name and email.
 *
 * LIKE metacharacters in `query` are escaped before binding so a search for
 * "50% off" cannot become a wildcard pattern.
 *
 * The `ESCAPE '\'` clause tells PostgreSQL which character we used for escaping
 * so it interprets our literal \% and \_ correctly.
 *
 * @param {string} query          - the search term (2–100 characters)
 * @param {number} [limit=20]     - maximum rows to return (capped at MAX_LIMIT)
 * @param {number} [offset=0]     - number of rows to skip
 * @returns {Promise<{ users: object[], total: number, limit: number, offset: number, query: string }>}
 *
 * @example
 *   const results = await searchUsers('ali', 5, 0);
 */
async function searchUsers(query, limit = 20, offset = 0) {
  // ── Input validation ──────────────────────────────────────────────────────

  if (typeof query !== 'string') {
    throw new TypeError(`Invalid search query: expected a string, got ${typeof query}`);
  }

  const trimmed = query.trim();

  if (trimmed.length < MIN_SEARCH_LENGTH) {
    throw new RangeError(
      `Search query must be at least ${MIN_SEARCH_LENGTH} characters long`
    );
  }
  if (trimmed.length > MAX_SEARCH_LENGTH) {
    throw new RangeError(
      `Search query must be at most ${MAX_SEARCH_LENGTH} characters long`
    );
  }

  const safeOffset = Math.max(MIN_OFFSET, validatePositiveInteger(offset, 'offset'));
  const safeLimit  = Math.min(
    MAX_LIMIT,
    Math.max(MIN_LIMIT, validatePositiveInteger(limit, 'limit'))
  );

  // ── SQL injection prevention ──────────────────────────────────────────────
  //
  // Two-layer defence:
  //   1. The search term is a *bound parameter* ($1) — never interpolated into
  //      the SQL string.  The db driver sends it in a separate protocol buffer.
  //   2. LIKE metacharacters inside the term are escaped so the user cannot
  //      abuse % or _ to widen the match.
  //
  // The ILIKE operator provides case-insensitive matching without requiring a
  // LOWER() call on the column, making it index-friendly (with a
  // `pg_trgm` GIN/GIST index or a standard `lower(column)` index).

  const escapedTerm   = sanitiseLikePattern(trimmed);
  const likePattern   = `%${escapedTerm}%`;   // substring match

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER() AS total_count
    FROM users
    WHERE
      name  ILIKE $1 ESCAPE '\\'
      OR
      email ILIKE $1 ESCAPE '\\'
    ORDER BY
      -- Exact matches first, then prefix matches, then substring matches.
      CASE
        WHEN name  ILIKE $2 ESCAPE '\\' THEN 0
        WHEN email ILIKE $2 ESCAPE '\\' THEN 1
        ELSE 2
      END ASC,
      id ASC
    LIMIT  $3
    OFFSET $4
  `;

  // $2 is a prefix pattern used only for relevance ordering (not filtering).
  const prefixPattern = `${escapedTerm}%`;

  const { rows } = await runQuery('searchUsers', sql, [
    likePattern,
    prefixPattern,
    safeLimit,
    safeOffset,
  ]);

  const total = rows.length > 0 ? Number(rows[0].total_count) : 0;
  const users = rows.map(({ total_count: _drop, ...rest }) => rest);

  return { users, total, limit: safeLimit, offset: safeOffset, query: trimmed };
}

// ─── Exports ───────────────────────────────────────────────────────────────

module.exports = { getUserById, getAllUsers, searchUsers };

/**
 * app.js — Express application with PostgreSQL-backed /users endpoint
 *
 * Route map
 * ─────────
 *   GET /health            – liveness probe
 *   GET /users             – paginated list  (?limit=&offset=)
 *   GET /users/search      – search          (?q=&limit=&offset=)
 *   GET /users/:id         – single user by primary key
 */

'use strict';

require('dotenv').config();

const express = require('express');
const { closePool }  = require('./db');
const { getUserById, getAllUsers, searchUsers } = require('./queries');

const app  = express();
const PORT = Number(process.env.PORT ?? 3000);

// ─── Middleware ────────────────────────────────────────────────────────────

app.use(express.json());

// Basic request logger (method + path + response time)
app.use((req, _res, next) => {
  const start = Date.now();
  _res.on('finish', () => {
    console.info(
      `[http] ${req.method} ${req.originalUrl} → ${_res.statusCode} (${Date.now() - start}ms)`
    );
  });
  next();
});

// ─── Helpers ───────────────────────────────────────────────────────────────

/**
 * parseIntParam — safely coerce a query-string value to an integer.
 * Returns `defaultValue` when the string is absent or not a valid integer.
 *
 * @param {string|undefined} raw
 * @param {number} defaultValue
 * @returns {number}
 */
function parseIntParam(raw, defaultValue) {
  if (raw === undefined || raw === '') return defaultValue;
  const n = Number(raw);
  return Number.isInteger(n) ? n : defaultValue;
}

/**
 * handleQueryError — map known error types to appropriate HTTP responses.
 *
 * @param {unknown} err
 * @param {import('express').Response} res
 */
function handleQueryError(err, res) {
  if (err instanceof TypeError || err instanceof RangeError) {
    // Validation errors from queries.js are always the caller's fault.
    return res.status(400).json({ error: err.message });
  }

  const pgCode = err?.code;

  // PostgreSQL error codes reference:
  // https://www.postgresql.org/docs/current/errcodes-appendix.html
  if (pgCode === '57014') {
    // query_canceled — statement_timeout fired
    return res.status(504).json({ error: 'Query timed out' });
  }
  if (pgCode === '53300') {
    // too_many_connections
    return res.status(503).json({ error: 'Service temporarily unavailable' });
  }
  if (pgCode?.startsWith('08')) {
    // Connection exception class
    return res.status(503).json({ error: 'Database connection error' });
  }

  console.error('[app] unhandled query error:', err);
  return res.status(500).json({ error: 'Internal server error' });
}

// ─── Routes ────────────────────────────────────────────────────────────────

// GET /health — simple liveness probe (no DB call; just confirms the process
// is alive and the event loop is not blocked)
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// GET /users/search?q=alice&limit=10&offset=0
//
// IMPORTANT: this route must be registered *before* /users/:id so that the
// literal segment "search" is not consumed as an :id parameter value.
app.get('/users/search', async (req, res) => {
  const { q }  = req.query;
  const limit  = parseIntParam(req.query.limit,  20);
  const offset = parseIntParam(req.query.offset,  0);

  if (!q || typeof q !== 'string' || q.trim() === '') {
    return res
      .status(400)
      .json({ error: 'Missing required query parameter: q' });
  }

  try {
    const result = await searchUsers(q, limit, offset);
    return res.json(result);
  } catch (err) {
    return handleQueryError(err, res);
  }
});

// GET /users?limit=20&offset=0
app.get('/users', async (req, res) => {
  const limit  = parseIntParam(req.query.limit,  20);
  const offset = parseIntParam(req.query.offset,  0);

  try {
    const result = await getAllUsers(limit, offset);
    return res.json(result);
  } catch (err) {
    return handleQueryError(err, res);
  }
});

// GET /users/:id
app.get('/users/:id', async (req, res) => {
  const { id } = req.params;

  // Reject obviously non-numeric IDs before hitting the DB layer.
  if (!/^\d+$/.test(id)) {
    return res.status(400).json({ error: 'User id must be a positive integer' });
  }

  try {
    const user = await getUserById(id);
    if (!user) {
      return res.status(404).json({ error: `User ${id} not found` });
    }
    return res.json(user);
  } catch (err) {
    return handleQueryError(err, res);
  }
});

// ─── 404 catch-all ────────────────────────────────────────────────────────

app.use((_req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// ─── Server lifecycle ──────────────────────────────────────────────────────

const server = app.listen(PORT, () => {
  console.info(`[app] server listening on port ${PORT}`);
});

// Graceful shutdown: stop accepting new connections, drain active ones, then
// close the database pool so the process exits cleanly.
async function shutdown(signal) {
  console.info(`[app] received ${signal} — shutting down gracefully`);

  server.close(async () => {
    try {
      await closePool();
      console.info('[app] shutdown complete');
      process.exit(0);
    } catch (err) {
      console.error('[app] error during shutdown:', err);
      process.exit(1);
    }
  });
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

module.exports = app;

/**
 * queries.test.js — unit tests for the queries module
 *
 * The PostgreSQL pool is mocked so these tests run without a live database.
 * They verify:
 *   • correct SQL is generated for each function
 *   • parameters are always bound positionally (never interpolated)
 *   • input validation rejects bad values before touching the DB
 *   • pagination clamping is enforced
 *   • LIKE metacharacters are escaped in searchUsers
 *   • timing logs are emitted for every call
 *   • error propagation reaches the caller unchanged
 */

'use strict';

// ─── Mock the pool before any module under test loads it ──────────────────

// We intercept `require('./db')` and replace `pool.query` with a Jest mock
// so no real database connection is ever attempted.
const mockQuery = jest.fn();

jest.mock('./db', () => ({
  pool:      { query: mockQuery },
  closePool: jest.fn(),
}));

const { getUserById, getAllUsers, searchUsers } = require('./queries');

// ─── Helpers ───────────────────────────────────────────────────────────────

/** Build a fake pg QueryResult with an optional total_count column. */
function fakeResult(rows, withCount = true) {
  const enriched = withCount
    ? rows.map((r) => ({ ...r, total_count: String(rows.length) }))
    : rows;
  return { rows: enriched, rowCount: rows.length };
}

// ─── Setup / teardown ─────────────────────────────────────────────────────

beforeEach(() => {
  mockQuery.mockReset();
  jest.spyOn(console, 'info').mockImplementation(() => {});
  jest.spyOn(console, 'error').mockImplementation(() => {});
});

afterEach(() => {
  jest.restoreAllMocks();
});

