describe('getUserById', () => {
  test('executes a parameterised SELECT with the given id', async () => {
    const row = { id: 1, name: 'Alice', email: 'alice@example.com',
                  created_at: null, updated_at: null };
    mockQuery.mockResolvedValueOnce(fakeResult([row], false));

    const result = await getUserById(1);

    expect(mockQuery).toHaveBeenCalledTimes(1);
    const [sql, params] = mockQuery.mock.calls[0];

    // The id must be a bound parameter, never embedded in the SQL string.
    expect(params).toEqual([1]);
    expect(sql).toMatch(/WHERE\s+id\s*=\s*\$1/i);
    expect(result).toEqual(row);
  });

  test('accepts a numeric string id', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([], false));
    const result = await getUserById('7');
    const [, params] = mockQuery.mock.calls[0];
    expect(params).toEqual([7]);
    expect(result).toBeNull();
  });

  test('returns null when no row is found', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([], false));
    const result = await getUserById(999);
    expect(result).toBeNull();
  });

  test('emits a timing log on success', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([], false));
    await getUserById(1);
    const logged = JSON.parse(console.info.mock.calls[0][0]);
    expect(logged).toMatchObject({
      fn:     'getUserById',
      status: 'ok',
      layer:  'queries',
    });
    expect(typeof logged.durationMs).toBe('number');
  });

  test('emits an error timing log and re-throws on DB failure', async () => {
    const dbErr = new Error('connection refused');
    mockQuery.mockRejectedValueOnce(dbErr);

    await expect(getUserById(1)).rejects.toThrow('connection refused');

    const logged = JSON.parse(console.info.mock.calls[0][0]);
    expect(logged.status).toBe('error');
  });

  // Validation
  test.each([
    ['negative integer', -1],
    ['float',           1.5],
    ['NaN string',      'abc'],
    ['null',            null],
    ['undefined',       undefined],
    ['object',          {}],
  ])('rejects invalid id: %s', async (_label, badId) => {
    await expect(getUserById(badId)).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });
});

