describe('searchUsers', () => {
  const rows = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: null, updated_at: null },
  ];

  test('passes the LIKE pattern as a bound parameter', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult(rows));
    await searchUsers('ali');

    const [sql, params] = mockQuery.mock.calls[0];

    // The pattern must appear as $1 in params, never inside the SQL string.
    expect(params[0]).toBe('%ali%');
    expect(sql).toMatch(/ILIKE\s+\$1/i);
    // The raw search term must NOT be interpolated into the SQL text.
    expect(sql).not.toContain('ali');
  });

  test('includes a prefix pattern as $2 for relevance ordering', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult(rows));
    await searchUsers('ali');

    const [, params] = mockQuery.mock.calls[0];
    expect(params[1]).toBe('ali%');
  });

  test('passes limit as $3 and offset as $4', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult(rows));
    await searchUsers('ali', 5, 10);

    const [, params] = mockQuery.mock.calls[0];
    expect(params[2]).toBe(5);
    expect(params[3]).toBe(10);
  });

  test('escapes LIKE metacharacter % in the search term', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));
    await searchUsers('50% off');

    const [, params] = mockQuery.mock.calls[0];
    // % should be escaped to \% inside the surrounding % wildcards
    expect(params[0]).toBe('%50\\% off%');
    expect(params[1]).toBe('50\\% off%');
  });

  test('escapes LIKE metacharacter _ in the search term', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));
    await searchUsers('a_b_c');

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe('%a\\_b\\_c%');
  });

  test('escapes backslash in the search term', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));
    await searchUsers('C:\\path');

    const [, params] = mockQuery.mock.calls[0];
    expect(params[0]).toContain('C:\\\\');
  });

  test('returns trimmed query in the response envelope', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult(rows));
    const result = await searchUsers('  ali  ');
    expect(result.query).toBe('ali');
  });

  test('strips total_count from returned rows', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult(rows));
    const { users } = await searchUsers('ali');
    users.forEach((u) => expect(u).not.toHaveProperty('total_count'));
  });

  test('emits a timing log', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));
    await searchUsers('te');
    const logged = JSON.parse(console.info.mock.calls[0][0]);
    expect(logged.fn).toBe('searchUsers');
  });

  // Validation — input length
  test('rejects a query shorter than MIN_SEARCH_LENGTH', async () => {
    await expect(searchUsers('a')).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects a query longer than MAX_SEARCH_LENGTH', async () => {
    await expect(searchUsers('x'.repeat(101))).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects a non-string query', async () => {
    await expect(searchUsers(42)).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects a whitespace-only query (collapses to empty after trim)', async () => {
    await expect(searchUsers('   ')).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  // Pagination clamping (same rules as getAllUsers)
  test('clamps limit to 100', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));
    await searchUsers('al', 500, 0);
    const [, params] = mockQuery.mock.calls[0];
    expect(params[2]).toBe(100);
  });

  test('clamps negative offset to 0', async () => {
    mockQuery.mockResolvedValueOnce(fakeResult([]));
    await searchUsers('al', 10, -99);
    const [, params] = mockQuery.mock.calls[0];
    expect(params[3]).toBe(0);
  });
});

/**
 * run_tests.js — self-contained test runner (no external dependencies)
 *
 * Uses only Node built-ins (assert, perf_hooks) so it runs in any environment
 * without npm install.  Mirrors every assertion in queries.test.js.
 */

'use strict';

const assert = require('assert/strict');

// ─── Minimal test harness ──────────────────────────────────────────────────

let passed = 0;
let failed = 0;
const failures = [];

async function test(label, fn) {
  try {
    await fn();
    console.log(`  ✓  ${label}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${label}`);
    console.error(`     ${err.message}`);
    failed++;
    failures.push({ label, err });
  }
}

function describe(suite, fn) {
  console.log(`\n${suite}`);
  return fn();
}

// ─── Mock the pool ─────────────────────────────────────────────────────────
//
// We inject a controllable mock before loading queries.js by patching the
// module cache directly.

const Module  = require('module');
const path    = require('path');
const dbPath  = path.resolve('./db.js');

let mockQueryImpl = null;   // set per-test

// Intercept require('./db') so queries.js gets our mock instead.
const originalLoad = Module._load;
Module._load = function (request, parent, isMain) {
  if (path.resolve(path.dirname(parent?.filename ?? '.'), request) === dbPath ||
      request === './db') {
    return {
      pool:      { query: (...args) => mockQueryImpl(...args) },
      closePool: () => Promise.resolve(),
    };
  }
  return originalLoad.apply(this, arguments);
};

// Also stub dotenv so it doesn't try to read a file.
Module._load = (function (orig) {
  return function (request, parent, isMain) {
    if (request === 'dotenv') return { config: () => {} };
    return orig.apply(this, arguments);
  };
})(Module._load);

// Now load queries (it will use our mock pool).
const { getUserById, getAllUsers, searchUsers } = require('./queries');

// ─── Helpers ───────────────────────────────────────────────────────────────

let consoleLogs = [];
const realInfo  = console.info;
console.info = (...args) => { consoleLogs.push(args[0]); };

function fakeResult(rows, withCount = true) {
  const enriched = withCount
    ? rows.map((r) => ({ ...r, total_count: String(rows.length) }))
    : rows;
  return { rows: enriched, rowCount: rows.length };
}

function setMock(result) {
  mockQueryImpl = jest_once(result);
}

// Simple "resolve once" helper (no jest needed).
function jest_once(result) {
  let calls = 0;
  return (...args) => {
    calls++;
    if (result instanceof Error) return Promise.reject(result);
    // Store the last call arguments so tests can inspect them.
    jest_once._lastCall = args;
    return Promise.resolve(result);
  };
}
// Track the SQL and params from the most recent pool.query call.
function getLastCall() { return jest_once._lastCall; }

function resetMock(impl) {
  consoleLogs = [];
  mockQueryImpl = impl || null;
}

