    assert.equal(params[2], 5);
    assert.equal(params[3], 10);
  });

  await test('escapes LIKE metacharacter % in the search term', async () => {
    resetMock(); setMock(fakeResult([]));
    await searchUsers('50% off');
    const [, params] = getLastCall();
    assert.equal(params[0], '%50\\% off%');
    assert.equal(params[1], '50\\% off%');
  });

  await test('escapes LIKE metacharacter _ in the search term', async () => {
    resetMock(); setMock(fakeResult([]));
    await searchUsers('a_b_c');
    const [, params] = getLastCall();
    assert.equal(params[0], '%a\\_b\\_c%');
  });

  await test('escapes backslash in the search term', async () => {
    resetMock(); setMock(fakeResult([]));
    await searchUsers('C:\\path');
    const [, params] = getLastCall();
    assert.ok(params[0].includes('C:\\\\'));
  });

  await test('returns trimmed query in the response envelope', async () => {
    resetMock(); setMock(fakeResult(rows));
    const result = await searchUsers('  ali  ');
    assert.equal(result.query, 'ali');
  });

  await test('strips total_count from returned rows', async () => {
    resetMock(); setMock(fakeResult(rows));
    const { users } = await searchUsers('ali');
    users.forEach((u) => assert.equal('total_count' in u, false));
  });

  await test('emits a timing log', async () => {
    resetMock(); setMock(fakeResult([]));
    await searchUsers('te');
    const logged = JSON.parse(consoleLogs[0]);
    assert.equal(logged.fn, 'searchUsers');
  });

  await test('rejects a query shorter than MIN_SEARCH_LENGTH', async () => {
    resetMock();
