    await assert.rejects(() => searchUsers('a'), RangeError);
    assert.equal(called, false);
  });

  await test('rejects a query longer than MAX_SEARCH_LENGTH', async () => {
    resetMock();
    let called = false;
    mockQueryImpl = () => { called = true; return Promise.resolve({ rows: [] }); };
    await assert.rejects(() => searchUsers('x'.repeat(101)), RangeError);
    assert.equal(called, false);
  });

  await test('rejects a non-string query', async () => {
    resetMock();
    await assert.rejects(() => searchUsers(42), TypeError);
  });

  await test('rejects a whitespace-only query', async () => {
    resetMock();
    await assert.rejects(() => searchUsers('   '), RangeError);
  });

  await test('clamps limit to 100', async () => {
    resetMock(); setMock(fakeResult([]));
    await searchUsers('al', 500, 0);
    const [, params] = getLastCall();
    assert.equal(params[2], 100);
  });

  await test('clamps negative offset to 0', async () => {
    resetMock(); setMock(fakeResult([]));
    await searchUsers('al', 10, -99);
    const [, params] = getLastCall();
    assert.equal(params[3], 0);
  });
