/**
 * db.js — PostgreSQL connection pool
 *
 * Exports a single shared `pg.Pool` instance (connection pooling).
 * All query modules should import this file rather than creating
 * their own connections, so the pool is shared across the process.
 *
 * Configuration is read exclusively from environment variables —
 * never hard-code credentials here.
 *
 * Required env vars (set in .env for local dev, injected by your
 * secrets manager in production):
 *
 *   DATABASE_URL   – full postgres connection string, OR use the
 *                    individual vars below:
 *   PGHOST         – database hostname
 *   PGPORT         – database port          (default: 5432)
 *   PGDATABASE     – database name
 *   PGUSER         – database username
 *   PGPASSWORD     – database password
 *   DB_POOL_MAX    – max pool connections   (default: 10)
 *   DB_POOL_IDLE   – idle timeout ms        (default: 10000)
 *   DB_POOL_CONN   – connection timeout ms  (default: 5000)
 *   DB_STATEMENT_TIMEOUT – per-query hard timeout ms (default: 30000)
 *   DB_SSL         – 'true' to require TLS  (default: false)
 */

'use strict';

const { Pool } = require('pg');

// ─── Pool Configuration ───────────────────────────────────────────────────────

const poolConfig = {
  // If DATABASE_URL is set it takes precedence; otherwise pg reads the
  // individual PG* env vars automatically.
  connectionString: process.env.DATABASE_URL || undefined,

  max: parseInt(process.env.DB_POOL_MAX  ?? '10',    10),
  idleTimeoutMillis:    parseInt(process.env.DB_POOL_IDLE ?? '10000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_POOL_CONN ?? '5000',  10),

  // Hard cap on how long any single statement may run.
  // Prevents runaway queries from holding a pool connection indefinitely.
  statement_timeout: parseInt(process.env.DB_STATEMENT_TIMEOUT ?? '30000', 10),

  // Require TLS when DB_SSL=true (always set this in production).
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: true } : false,
};

const pool = new Pool(poolConfig);

// ─── Pool-level error handler ─────────────────────────────────────────────────
// Without this, an idle-client error (e.g. server closes the socket) would
// throw an unhandled exception and crash the process.
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client', {
    message: err.message,
    code:    err.code,
  });
  // Do NOT log err.stack in production — it can contain connection details.
});

pool.on('connect', () => {
  // Fires each time a brand-new physical connection is opened.
  console.log('[db] New client connected to pool');
});

pool.on('remove', () => {
  console.log('[db] Client removed from pool');
});

// ─── Graceful shutdown ────────────────────────────────────────────────────────
// Drain the pool cleanly when the process exits so in-flight queries finish
// and connections are closed before the OS reclaims the socket.
const shutdown = async (signal) => {
  console.log(`[db] ${signal} received — draining connection pool…`);
  try {
    await pool.end();
    console.log('[db] Pool drained. Exiting.');
  } catch (err) {
    console.error('[db] Error draining pool:', err.message);
  }
  process.exit(0);
};

process.once('SIGINT',  () => shutdown('SIGINT'));
process.once('SIGTERM', () => shutdown('SIGTERM'));

module.exports = pool;

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design principles
 * ─────────────────
 * 1. SQL injection prevention
 *    Every value that originates from user input is passed as a
 *    parameterised placeholder ($1, $2 …) — never interpolated into
 *    the query string.  pg's wire protocol sends parameters in a
 *    separate bind message, so the database never parses them as SQL.
 *
 * 2. Input validation & sanitisation
 *    Parameters are validated and coerced before they reach pg so that
 *    invalid values are rejected with a clear application-level error
 *    rather than a cryptic database error.
 *
 * 3. Connection pooling
 *    All functions call pool.query(), which borrows a connection from
 *    the shared pool in db.js and returns it immediately after the
 *    query completes — no manual connect/release needed for simple
 *    queries.  A single checkout + explicit release is used only where
 *    we want timing guarantees across multiple statements.
 *
 * 4. Query timing
 *    Every public function measures and logs wall-clock execution time
 *    (start → first row received) so slow queries are visible in logs
 *    without needing an external APM tool.
 *
 * 5. Explicit column lists
 *    No SELECT * — columns are listed explicitly so that adding a
 *    sensitive column to the table never accidentally leaks it through
 *    the API.
 */

'use strict';

const pool = require('./db');

// ─── Constants ────────────────────────────────────────────────────────────────

const MAX_LIMIT  = 100;   // hard cap — callers can't page more than this
const MIN_LIMIT  = 1;
const MAX_OFFSET = 1_000_000;

/** Columns returned to callers — never SELECT * */
const USER_COLUMNS = 'id, name, email, created_at';

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Wraps pool.query with a high-resolution timer and structured log line.
 *
 * @param {string}   label   – human-readable name shown in the log
 * @param {string}   text    – parameterised SQL string
 * @param {Array}    values  – bound parameter values
 * @returns {Promise<pg.QueryResult>}
 */
async function timedQuery(label, text, values) {
  const startHr = process.hrtime.bigint();

  let result;
  try {
    result = await pool.query({ text, values });
  } catch (err) {
    const durationMs = nanosToMs(process.hrtime.bigint() - startHr);
    // Log only safe metadata — never log `values` as they may contain PII.
    console.error('[queries] Query error', {
      label,
      durationMs,
      errorCode: err.code,       // pg error code, e.g. '23505'
      errorMessage: err.message,
    });
    throw err;   // re-throw so the caller / route handler decides the response
  }

  const durationMs = nanosToMs(process.hrtime.bigint() - startHr);
  console.log('[queries] Query OK', {
    label,
    durationMs,
    rowCount: result.rowCount,
  });

  return result;
}

/** Convert BigInt nanoseconds → rounded milliseconds (number). */
function nanosToMs(ns) {
  return Number(ns / 1_000_000n);
}

/**
 * Validate and coerce an integer parameter.
 *
 * @param {*}      raw    – raw value from req.params / req.query
 * @param {string} name   – field name (used in error messages only)
 * @param {number} min
 * @param {number} max
 * @returns {number}
 * @throws {ValidationError}
 */
function requireInt(raw, name, min, max) {
  const n = Number(raw);
  if (!Number.isInteger(n) || n < min || n > max) {
    throw new ValidationError(
      `"${name}" must be an integer between ${min} and ${max} (got ${JSON.stringify(raw)})`
    );
  }
  return n;
}

/**
 * Validate and normalise a free-text search string.
 *
 * Rules
 * ─────
 * - Must be a non-empty string after trimming whitespace.
 * - Length is capped so an attacker cannot send a multi-megabyte string
 *   and force the database to evaluate a huge LIKE pattern.
 * - The value is NOT escaped here: pg's parameterised queries handle
 *   that.  We only strip leading/trailing whitespace for UX.
 *
 * @param {*}      raw   – raw value from req.query
 * @param {string} name  – field name (for error messages)
 * @returns {string}
 * @throws {ValidationError}
 */
function requireSearchString(raw, name) {
  if (typeof raw !== 'string') {
    throw new ValidationError(`"${name}" must be a string`);
  }
  const trimmed = raw.trim();
  if (trimmed.length === 0) {
    throw new ValidationError(`"${name}" must not be empty`);
  }
  if (trimmed.length > 200) {
    throw new ValidationError(`"${name}" must not exceed 200 characters`);
  }
  return trimmed;
}

/** Application-level validation error (maps to HTTP 400). */
class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
  }
}

// ─── Public query functions ───────────────────────────────────────────────────

/**
 * Fetch a single user by primary key.
 *
 * SQL injection prevention
 * ─────────────────────────
 * `id` is passed as $1 — the pg client sends it as a typed parameter in
 * the Bind message.  The database parses the query template once and
 * substitutes the value at execution time; there is no string
 * concatenation involved.
 *
 * @param {number|string} id – user primary key (coerced to integer)
 * @returns {Promise<Object|null>} user row or null if not found
 * @throws {ValidationError} if id is not a valid positive integer
 */
async function getUserById(id) {
  const safeId = requireInt(id, 'id', 1, Number.MAX_SAFE_INTEGER);

  const { rows } = await timedQuery(
    'getUserById',
    `SELECT ${USER_COLUMNS}
       FROM users
      WHERE id = $1
      LIMIT 1`,
    [safeId],
  );

  return rows[0] ?? null;
}

/**
 * Fetch a page of users ordered by id.
 *
 * SQL injection prevention
 * ─────────────────────────
 * `limit` and `offset` are both passed as $1 / $2 parameters.
 * LIMIT / OFFSET accept numeric parameters in PostgreSQL's extended
 * query protocol, so there is no need to inline them.
 *
 * @param {number|string} limit  – max rows to return (1–100, default 20)
 * @param {number|string} offset – rows to skip       (0–1_000_000, default 0)
 * @returns {Promise<{ users: Object[], total: number }>}
 * @throws {ValidationError} if limit / offset are out of range
 */
async function getAllUsers(limit = 20, offset = 0) {
  const safeLimit  = requireInt(limit,  'limit',  MIN_LIMIT,  MAX_LIMIT);
  const safeOffset = requireInt(offset, 'offset', 0,          MAX_OFFSET);

  // Run the data query and the count query in a single round-trip using
  // a CTE so we only acquire one pool connection.
  const { rows } = await timedQuery(
    'getAllUsers',
    `WITH page AS (
       SELECT ${USER_COLUMNS}
         FROM users
        ORDER BY id
        LIMIT  $1
        OFFSET $2
     ),
     total AS (
       SELECT COUNT(*) AS total_count FROM users
     )
     SELECT p.*, t.total_count
       FROM page p, total t`,
    [safeLimit, safeOffset],
  );

  const total = rows.length > 0 ? parseInt(rows[0].total_count, 10) : 0;
  // Strip the injected total_count column from each user object.
  const users = rows.map(({ total_count, ...user }) => user);   // eslint-disable-line no-unused-vars

  return { users, total };
}

/**
 * Full-text search across user name and email.
 *
 * SQL injection prevention
 * ─────────────────────────
 * The search term is passed as $1 — pg wraps it in quotes at the
 * protocol level.  The `%…%` wildcards are added by the application
 * inside the parameter value (not the SQL string), which is safe:
 * the database treats the entire $1 value as a literal pattern, not
 * as SQL.  A user who sends the string "'; DROP TABLE users; --" will
 * simply get zero results — the pattern is never interpreted as SQL.
 *
 * @param {string}        query  – search term (max 200 chars)
 * @param {number|string} limit  – max rows to return (1–100, default 20)
 * @param {number|string} offset – rows to skip       (0–1_000_000, default 0)
 * @returns {Promise<{ users: Object[], total: number }>}
 * @throws {ValidationError} if query / limit / offset fail validation
 */
async function searchUsers(query, limit = 20, offset = 0) {
  const safeQuery  = requireSearchString(query, 'query');
  const safeLimit  = requireInt(limit,  'limit',  MIN_LIMIT,  MAX_LIMIT);
  const safeOffset = requireInt(offset, 'offset', 0,          MAX_OFFSET);

  // Wrap the sanitised term in SQL LIKE wildcards.
  // This is safe because the wildcards become part of the parameter
  // value — they are never in the SQL template itself.
  const likePattern = `%${safeQuery}%`;

  const { rows } = await timedQuery(
    'searchUsers',
    `WITH matches AS (
       SELECT ${USER_COLUMNS}
         FROM users
        WHERE name  ILIKE $1
           OR email ILIKE $1
        ORDER BY id
        LIMIT  $2
        OFFSET $3
     ),
     total AS (
       SELECT COUNT(*) AS total_count
         FROM users
        WHERE name  ILIKE $1
           OR email ILIKE $1
     )
     SELECT m.*, t.total_count
       FROM matches m, total t`,
    [likePattern, safeLimit, safeOffset],
  );

  const total = rows.length > 0 ? parseInt(rows[0].total_count, 10) : 0;
  const users = rows.map(({ total_count, ...user }) => user);   // eslint-disable-line no-unused-vars

  return { users, total };
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  ValidationError,   // exported so route handlers can instanceof-check it
  // Exposed for unit testing only — do not call in production code.
  _internal: { timedQuery, requireInt, requireSearchString, nanosToMs },
};

/**
 * app.js — Express application
 *
 * /health          – liveness probe (no DB)
 * /users           – paginated user list
 * /users/search    – full-text search across name + email
 * /users/:id       – single user by primary key
 *
 * All database access goes through queries.js.
 * Route handlers only parse/validate HTTP concerns (headers, status
 * codes) — business-level validation is owned by queries.js.
 */

'use strict';

// Load environment variables from .env (if present) before anything
// else runs.  In production, variables are injected by the runtime and
// this call is a no-op.
require('dotenv').config();

const express = require('express');
const {
  getUserById,
  getAllUsers,
  searchUsers,
  ValidationError,
} = require('./queries');

const app = express();
app.use(express.json());

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Wrap an async route handler so that any rejected promise is forwarded
 * to Express's error handler via next(err) instead of causing an
 * UnhandledPromiseRejection.
 */
const asyncHandler = (fn) => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

// ─── Routes ───────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Liveness probe — no database call, always fast.
 */
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users/search?query=alice&limit=20&offset=0
 *
 * Must be declared BEFORE /users/:id so Express doesn't treat
 * the literal string "search" as an :id value.
 *
 * Query params:
 *   query  {string}  – required, search term (matched against name & email)
 *   limit  {number}  – optional, 1–100, default 20
 *   offset {number}  – optional, 0–1 000 000, default 0
 */
app.get('/users/search', asyncHandler(async (req, res) => {
  const { query, limit = 20, offset = 0 } = req.query;

  if (!query) {
    return res.status(400).json({
      error: 'Missing required query parameter: query',
    });
  }

  const result = await searchUsers(query, limit, offset);

  return res.json({
    data:   result.users,
    total:  result.total,
    limit:  Number(limit),
    offset: Number(offset),
  });
}));

/**
 * GET /users?limit=20&offset=0
 *
 * Query params:
 *   limit  {number} – optional, 1–100, default 20
 *   offset {number} – optional, 0–1 000 000, default 0
 */
app.get('/users', asyncHandler(async (req, res) => {
  const { limit = 20, offset = 0 } = req.query;
  const result = await getAllUsers(limit, offset);

  return res.json({
    data:   result.users,
    total:  result.total,
    limit:  Number(limit),
    offset: Number(offset),
  });
}));

/**
 * GET /users/:id
 *
 * Path params:
 *   id {integer} – positive integer primary key
 */
app.get('/users/:id', asyncHandler(async (req, res) => {
  const user = await getUserById(req.params.id);

  if (!user) {
    return res.status(404).json({ error: `User ${req.params.id} not found` });
  }

  return res.json({ data: user });
}));

// ─── Centralised error handler ────────────────────────────────────────────────
// Must be declared last and have exactly four parameters so Express
// recognises it as an error handler.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, _next) => {
  // Validation errors → 400 Bad Request
  if (err instanceof ValidationError) {
    return res.status(400).json({ error: err.message });
  }

  // Database / unexpected errors → 500
  // Log the full error server-side but return only a generic message
  // to the client so internal details are not leaked.
  console.error('[app] Unhandled error', {
    method:  req.method,
    path:    req.path,
    message: err.message,
    code:    err.code,
  });

  return res.status(500).json({ error: 'Internal server error' });
});

// ─── Server startup ───────────────────────────────────────────────────────────

const PORT = parseInt(process.env.PORT ?? '3000', 10);

if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT}`);
  });
}

module.exports = app;

/**
 * queries.test.js — Unit + integration-style tests for queries.js
 *
 * The pg pool is mocked so no real database is required.
 * Tests cover:
 *   - Happy paths for all three query functions
 *   - Input validation (ValidationError) for every parameter
 *   - SQL injection attempts are rejected at the validation layer
 *   - Query timing log is emitted on success and on error
 *   - Parameterised queries: the SQL template never contains raw input
 */

'use strict';

// ─── Mock the pool (db.js) before requiring queries.js ───────────────────────

// We intercept require('pg') so that `new Pool()` returns our mock.
// This avoids needing a real PostgreSQL server.

let mockQueryFn;  // tests assign a function here to control pg responses

jest.mock('./db', () => {
  // Return a fake pool whose .query() delegates to `mockQueryFn`.
  // The real db.js creates a pg.Pool; here we return a plain object.
  return {
    query: (...args) => mockQueryFn(...args),
  };
});

const {
  getUserById,
  getAllUsers,
  searchUsers,
  ValidationError,
  _internal: { requireInt, requireSearchString, nanosToMs },
} = require('./queries');

// ─── Fixtures ─────────────────────────────────────────────────────────────────

const ALICE = { id: 1, name: 'Alice', email: 'alice@example.com', created_at: '2024-01-01' };
const BOB   = { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: '2024-01-02' };

// Simulate what pg returns for getAllUsers / searchUsers
// (the CTE adds a total_count column that queries.js strips off).
const withCount = (rows, total_count) =>
  rows.map((r) => ({ ...r, total_count: String(total_count) }));

// ─── Helper ───────────────────────────────────────────────────────────────────

/** Make pool.query() resolve with the given rows. */
function resolveWith(rows, rowCount = rows.length) {
  mockQueryFn = jest.fn().mockResolvedValue({ rows, rowCount });
}

/** Make pool.query() reject with an error. */
function rejectWith(err) {
  mockQueryFn = jest.fn().mockRejectedValue(err);
}

// Suppress console output during tests (uncomment to debug).
beforeAll(() => {
  jest.spyOn(console, 'log').mockImplementation(() => {});
  jest.spyOn(console, 'error').mockImplementation(() => {});
});
afterAll(() => {
  console.log.mockRestore();
  console.error.mockRestore();
});

beforeEach(() => {
  mockQueryFn = undefined;
});

// ─── nanosToMs ────────────────────────────────────────────────────────────────

describe('nanosToMs', () => {
  test('converts BigInt nanoseconds to numeric milliseconds', () => {
    expect(nanosToMs(1_000_000n)).toBe(1);
    expect(nanosToMs(500_000n)).toBe(0);   // floor
    expect(nanosToMs(1_500_000n)).toBe(1); // floor
    expect(nanosToMs(0n)).toBe(0);
  });
});

// ─── requireInt ───────────────────────────────────────────────────────────────

describe('requireInt', () => {
  test('accepts valid integers', () => {
    expect(requireInt(1,   'id', 1, 100)).toBe(1);
    expect(requireInt(100, 'id', 1, 100)).toBe(100);
    expect(requireInt('42','id', 1, 100)).toBe(42);
  });

  test('rejects float strings', () => {
    expect(() => requireInt('1.5', 'id', 1, 100)).toThrow(ValidationError);
  });

  test('rejects non-numeric strings', () => {
    expect(() => requireInt('abc', 'id', 1, 100)).toThrow(ValidationError);
  });

  test('rejects SQL injection strings', () => {
    expect(() => requireInt("1; DROP TABLE users", 'id', 1, 100)).toThrow(ValidationError);
    expect(() => requireInt("1 OR 1=1",            'id', 1, 100)).toThrow(ValidationError);
    expect(() => requireInt("' OR '1'='1",         'id', 1, 100)).toThrow(ValidationError);
  });

  test('rejects values below min', () => {
    expect(() => requireInt(0, 'id', 1, 100)).toThrow(ValidationError);
  });

  test('rejects values above max', () => {
    expect(() => requireInt(101, 'id', 1, 100)).toThrow(ValidationError);
  });

  test('includes field name in error message', () => {
    expect(() => requireInt(-1, 'myField', 1, 100))
      .toThrow(/"myField"/);
  });
});

// ─── requireSearchString ─────────────────────────────────────────────────────

describe('requireSearchString', () => {
  test('accepts normal search terms', () => {
    expect(requireSearchString('alice', 'query')).toBe('alice');
    expect(requireSearchString('  bob  ', 'query')).toBe('bob');   // trims
  });

  test('rejects empty strings', () => {
    expect(() => requireSearchString('',    'query')).toThrow(ValidationError);
    expect(() => requireSearchString('   ', 'query')).toThrow(ValidationError);
  });

  test('rejects strings longer than 200 characters', () => {
    expect(() => requireSearchString('a'.repeat(201), 'query')).toThrow(ValidationError);
  });

  test('accepts strings of exactly 200 characters', () => {
    expect(() => requireSearchString('a'.repeat(200), 'query')).not.toThrow();
  });

  test('rejects non-strings', () => {
    expect(() => requireSearchString(42,   'query')).toThrow(ValidationError);
    expect(() => requireSearchString(null, 'query')).toThrow(ValidationError);
    expect(() => requireSearchString([],   'query')).toThrow(ValidationError);
  });

  test('does NOT reject SQL strings — pg parameterisation handles them safely', () => {
    // These strings are dangerous only if interpolated into SQL.
    // Since we pass them as bound parameters, returning them from
    // validation is correct — pg will treat them as literal values.
    expect(() => requireSearchString("'; DROP TABLE users; --", 'query')).not.toThrow();
    expect(() => requireSearchString("1 OR 1=1",                'query')).not.toThrow();
    expect(() => requireSearchString("admin'--",                 'query')).not.toThrow();
  });
});

// ─── getUserById ──────────────────────────────────────────────────────────────

describe('getUserById', () => {
  test('returns user when found', async () => {
    resolveWith([ALICE]);
    const user = await getUserById(1);
    expect(user).toEqual(ALICE);
  });

  test('returns null when not found', async () => {
    resolveWith([]);
    const user = await getUserById(999);
    expect(user).toBeNull();
  });

  test('uses a parameterised query — id is in values array, not SQL string', async () => {
    resolveWith([ALICE]);
    await getUserById(1);

    const callArg = mockQueryFn.mock.calls[0][0]; // { text, values }
    expect(callArg.text).toContain('$1');
    expect(callArg.text).not.toContain('1');  // raw id not in SQL template
    expect(callArg.values).toEqual([1]);
  });

  test('accepts string "1" (coerces to integer)', async () => {
    resolveWith([ALICE]);
    const user = await getUserById('1');
    expect(user).toEqual(ALICE);
  });

  test('throws ValidationError for id = 0', async () => {
    await expect(getUserById(0)).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for negative id', async () => {
    await expect(getUserById(-5)).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for float id', async () => {
    await expect(getUserById(1.5)).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for non-numeric id', async () => {
    await expect(getUserById('abc')).rejects.toThrow(ValidationError);
  });

  test('SQL injection in id → ValidationError, query never executed', async () => {
    mockQueryFn = jest.fn();
    await expect(getUserById("1; DROP TABLE users; --")).rejects.toThrow(ValidationError);
    expect(mockQueryFn).not.toHaveBeenCalled();
  });

  test('logs timing on success', async () => {
    resolveWith([ALICE]);
    await getUserById(1);
    expect(console.log).toHaveBeenCalledWith(
      '[queries] Query OK',
      expect.objectContaining({ label: 'getUserById', durationMs: expect.any(Number) })
    );
  });

  test('logs error and re-throws on db failure', async () => {
    const dbErr = Object.assign(new Error('connection refused'), { code: '08006' });
    rejectWith(dbErr);
    await expect(getUserById(1)).rejects.toThrow('connection refused');
    expect(console.error).toHaveBeenCalledWith(
      '[queries] Query error',
      expect.objectContaining({ label: 'getUserById' })
    );
  });
});

// ─── getAllUsers ───────────────────────────────────────────────────────────────

describe('getAllUsers', () => {
  test('returns users and total', async () => {
    resolveWith(withCount([ALICE, BOB], 2));
    const result = await getAllUsers(20, 0);
    expect(result.users).toEqual([ALICE, BOB]);
    expect(result.total).toBe(2);
  });

  test('strips total_count from user objects', async () => {
    resolveWith(withCount([ALICE], 50));
    const { users } = await getAllUsers(1, 0);
    expect(users[0]).not.toHaveProperty('total_count');
  });

  test('total is 0 when result set is empty', async () => {
    resolveWith([]);
    const result = await getAllUsers(20, 0);
    expect(result.users).toEqual([]);
    expect(result.total).toBe(0);
  });

  test('uses parameterised query for limit and offset', async () => {
    resolveWith(withCount([ALICE], 1));
    await getAllUsers(10, 5);

    const callArg = mockQueryFn.mock.calls[0][0];
    expect(callArg.text).toContain('$1');
    expect(callArg.text).toContain('$2');
    expect(callArg.values).toEqual([10, 5]);
  });

  test('default limit=20 offset=0 are used when omitted', async () => {
    resolveWith(withCount([], 0));
    await getAllUsers();

    const callArg = mockQueryFn.mock.calls[0][0];
    expect(callArg.values).toEqual([20, 0]);
  });

  test('accepts string numbers from query-string', async () => {
    resolveWith(withCount([ALICE], 1));
    await expect(getAllUsers('10', '0')).resolves.toBeDefined();
  });

  test('throws ValidationError for limit > 100', async () => {
    await expect(getAllUsers(101, 0)).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for limit < 1', async () => {
    await expect(getAllUsers(0, 0)).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for negative offset', async () => {
    await expect(getAllUsers(10, -1)).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for offset > 1_000_000', async () => {
    await expect(getAllUsers(10, 1_000_001)).rejects.toThrow(ValidationError);
  });

  test('SQL injection in limit → ValidationError, query never executed', async () => {
    mockQueryFn = jest.fn();
    await expect(getAllUsers("10; DROP TABLE users", 0)).rejects.toThrow(ValidationError);
    expect(mockQueryFn).not.toHaveBeenCalled();
  });

  test('logs timing on success', async () => {
    resolveWith(withCount([ALICE], 1));
    await getAllUsers();
    expect(console.log).toHaveBeenCalledWith(
      '[queries] Query OK',
      expect.objectContaining({ label: 'getAllUsers' })
    );
  });
});

// ─── searchUsers ──────────────────────────────────────────────────────────────

describe('searchUsers', () => {
  test('returns matching users and total', async () => {
    resolveWith(withCount([ALICE], 1));
    const result = await searchUsers('alice');
    expect(result.users).toEqual([ALICE]);
    expect(result.total).toBe(1);
  });

  test('passes LIKE-wrapped pattern as $1 parameter', async () => {
    resolveWith(withCount([ALICE], 1));
    await searchUsers('alice', 20, 0);

    const callArg = mockQueryFn.mock.calls[0][0];
    // The SQL template uses a placeholder, not the raw value.
    expect(callArg.text).toContain('$1');
    expect(callArg.text).not.toContain('alice');
    // The value array contains the wrapped pattern.
    expect(callArg.values[0]).toBe('%alice%');
    expect(callArg.values[1]).toBe(20);
    expect(callArg.values[2]).toBe(0);
  });

  test('trims whitespace from search query', async () => {
    resolveWith(withCount([], 0));
    await searchUsers('  bob  ');

    const callArg = mockQueryFn.mock.calls[0][0];
    expect(callArg.values[0]).toBe('%bob%');  // trimmed
  });

  test('strips total_count from user objects', async () => {
    resolveWith(withCount([ALICE], 10));
    const { users } = await searchUsers('alice');
    expect(users[0]).not.toHaveProperty('total_count');
  });

  test('total is 0 when no matches', async () => {
    resolveWith([]);
    const result = await searchUsers('zzz');
    expect(result.total).toBe(0);
  });

  test('throws ValidationError for empty query string', async () => {
    await expect(searchUsers('')).rejects.toThrow(ValidationError);
    await expect(searchUsers('   ')).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for query > 200 chars', async () => {
    await expect(searchUsers('a'.repeat(201))).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for non-string query', async () => {
    await expect(searchUsers(null)).rejects.toThrow(ValidationError);
    await expect(searchUsers(undefined)).rejects.toThrow(ValidationError);
  });

  test('SQL injection in query string → value is parameterised, not executed', async () => {
    // The dangerous string should reach pg as a plain bound value, so
    // mockQueryFn IS called — but with the injection attempt as a safe $1.
    resolveWith([]);
    const injectionAttempt = "'; DROP TABLE users; --";
    await searchUsers(injectionAttempt);

    const callArg = mockQueryFn.mock.calls[0][0];
    // The raw injection string must NOT appear anywhere in the SQL template.
    expect(callArg.text).not.toContain(injectionAttempt);
    // It must appear only in the values array (harmless as a bound param).
    expect(callArg.values[0]).toBe(`%${injectionAttempt.trim()}%`);
  });

  test('SQL injection via UNION in query → parameterised, not executed as SQL', async () => {
    resolveWith([]);
    const unionInjection = "x' UNION SELECT id,name,email,created_at FROM admins--";
    await searchUsers(unionInjection);

    const callArg = mockQueryFn.mock.calls[0][0];
    expect(callArg.text).not.toContain('UNION SELECT');
    expect(callArg.values[0]).toContain('UNION SELECT');  // present only as data
  });

  test('throws ValidationError for limit > 100', async () => {
    await expect(searchUsers('alice', 101)).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for negative offset', async () => {
    await expect(searchUsers('alice', 20, -1)).rejects.toThrow(ValidationError);
  });

  test('logs timing on success', async () => {
    resolveWith(withCount([], 0));
    await searchUsers('test');
    expect(console.log).toHaveBeenCalledWith(
      '[queries] Query OK',
      expect.objectContaining({ label: 'searchUsers' })
    );
  });

  test('logs error and re-throws on db failure', async () => {
    const dbErr = Object.assign(new Error('timeout'), { code: '57014' });
    rejectWith(dbErr);
    await expect(searchUsers('alice')).rejects.toThrow('timeout');
    expect(console.error).toHaveBeenCalledWith(
      '[queries] Query error',
      expect.objectContaining({ label: 'searchUsers', errorCode: '57014' })
    );
  });
});

