/**
 * db/pool.js
 *
 * Creates and exports a single shared pg connection pool for the entire
 * application lifetime.  Every query in queries.js borrows a connection from
 * this pool rather than opening a new TCP socket per request.
 *
 * Configuration is read exclusively from environment variables so that no
 * credentials ever appear in source code.
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------
// All values come from environment variables.  Sensible defaults are provided
// for non-sensitive settings so the app starts cleanly in development without
// a full .env file, but DATABASE_URL (or the individual PG* vars) must be set.
// ---------------------------------------------------------------------------
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Maximum number of clients the pool will hold open simultaneously.
  // Tune this to (db max_connections / number_of_app_instances) – 5.
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

  // Milliseconds a client is allowed to sit idle before being closed.
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT_MS ?? '30000', 10),

  // Milliseconds to wait for a connection before throwing a timeout error.
  connectionTimeoutMillis: parseInt(
    process.env.DB_CONNECT_TIMEOUT_MS ?? '5000',
    10
  ),

  // Keep TLS on in production; allow it to be disabled in local dev via env.
  ssl:
    process.env.DB_SSL === 'false'
      ? false
      : { rejectUnauthorized: process.env.DB_SSL_REJECT_UNAUTHORIZED !== 'false' },
});

// ---------------------------------------------------------------------------
// Pool-level event hooks
// ---------------------------------------------------------------------------

pool.on('connect', (client) => {
  // Tag every new physical connection so it appears in pg logs.
  client
    .query("SET application_name = 'express-app'")
    .catch((err) =>
      console.error('[pool] Failed to set application_name:', err.message)
    );
  console.info('[pool] New client connected to the database.');
});

pool.on('acquire', () => {
  console.debug('[pool] Client acquired from pool.');
});

pool.on('remove', () => {
  console.info('[pool] Client removed from pool.');
});

pool.on('error', (err) => {
  // Idle-client errors must be caught here or they crash the process.
  console.error('[pool] Unexpected error on idle database client:', err.message);
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------
// Call this during SIGTERM / SIGINT handling so all in-flight queries finish
// and the pool drains cleanly before the process exits.

async function closePool() {
  console.info('[pool] Draining connection pool…');
  await pool.end();
  console.info('[pool] Pool closed.');
}

module.exports = { pool, closePool };

/**
 * db/queries.js
 *
 * Parameterised query functions for the /users endpoint.
 *
 * Security guarantees
 * -------------------
 * • Every dynamic value is passed as a query parameter ($1, $2, …), never
 *   interpolated into the SQL string.  This is the primary defence against
 *   SQL injection: the database driver sends the SQL text and the parameter
 *   values separately; they are never concatenated.
 * • Input values are validated and sanitised *before* they reach the driver as
 *   a second line of defence (defence-in-depth).
 * • Dangerous characters that have no legitimate use in a full-text search
 *   query are stripped, and tsquery operators are normalised so a crafted
 *   search string cannot alter query semantics even if parameterisation were
 *   somehow bypassed.
 * • LIMIT and OFFSET are coerced to integers and clamped to safe ranges so a
 *   caller cannot request an unbounded result set.
 *
 * Performance
 * -----------
 * • All functions use the shared connection pool from db/pool.js.
 * • Every query is wrapped in a timing harness that logs SQL, parameters
 *   (with PII fields redacted), and execution duration in milliseconds.
 * • Prepared-statement names are given where appropriate so pg can cache the
 *   query plan on the server side.
 */

'use strict';

const { pool } = require('./pool');

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const MAX_LIMIT = 100;   // Hard upper bound — callers cannot exceed this.
const DEFAULT_LIMIT = 20;
const DEFAULT_OFFSET = 0;

// Fields that must not appear verbatim in query logs.
const PII_FIELDS = new Set(['email', 'password', 'phone']);

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * redactParams
 *
 * Returns a shallow copy of the params array with PII-adjacent positional
 * values replaced by '[REDACTED]'.  Because positional params carry no field
 * name we use a conservative heuristic: redact any string that looks like an
 * e-mail address.
 *
 * @param {unknown[]} params
 * @returns {unknown[]}
 */
function redactParams(params) {
  return params.map((p) => {
    if (typeof p === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p)) {
      return '[REDACTED]';
    }
    return p;
  });
}

/**
 * timedQuery
 *
 * Executes a parameterised query through the shared pool, emits structured
 * timing logs, and surfaces the pg QueryResult to the caller.
 *
 * @param {object}    options
 * @param {string}    options.label    - Human-readable label for log lines.
 * @param {string}    options.sql      - The SQL query text with $n placeholders.
 * @param {unknown[]} options.params   - Positional parameter values.
 * @param {string}   [options.name]    - Optional prepared-statement name.
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery({ label, sql, params, name }) {
  const start = process.hrtime.bigint();

  console.info(
    `[query] ${label} | params: ${JSON.stringify(redactParams(params))}`
  );
  console.debug(`[query] SQL: ${sql.replace(/\s+/g, ' ').trim()}`);

  try {
    const queryConfig = name
      ? { name, text: sql, values: params }
      : { text: sql, values: params };

    const result = await pool.query(queryConfig);

    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;
    console.info(
      `[query] ${label} | rows: ${result.rowCount} | duration: ${durationMs.toFixed(3)} ms`
    );

    return result;
  } catch (err) {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;
    console.error(
      `[query] ${label} | ERROR after ${durationMs.toFixed(3)} ms | ${err.message}`
    );
    throw err;
  }
}

/**
 * validatePositiveInteger
 *
 * Coerces a value to a safe integer, throwing a descriptive RangeError if it
 * falls outside the supplied bounds.
 *
 * @param {unknown} value
 * @param {string}  name       - Parameter name for error messages.
 * @param {number}  min
 * @param {number}  max
 * @param {number}  fallback   - Value to use when `value` is null/undefined.
 * @returns {number}
 */
function validatePositiveInteger(value, name, min, max, fallback) {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const n = Math.trunc(Number(value));
  if (!Number.isFinite(n)) {
    throw new RangeError(`${name} must be a finite number, got: ${value}`);
  }
  if (n < min || n > max) {
    throw new RangeError(
      `${name} must be between ${min} and ${max}, got: ${n}`
    );
  }
  return n;
}

/**
 * sanitiseSearchQuery
 *
 * Prepares a raw caller-supplied string for use as a PostgreSQL tsquery.
 *
 * Why this matters even with parameterisation
 * -------------------------------------------
 * The value is passed as a parameter ($1), so it cannot alter the SQL
 * *structure*.  However, to_tsquery() itself interprets operator characters
 * such as & | ! : * inside the string.  A value like "admin'--" would be
 * harmless SQL-wise (it is just a string literal to the DB driver), but
 * "password & 1=1" would be interpreted by to_tsquery as a compound
 * expression.  We therefore use plainto_tsquery() in the SQL (which treats
 * the whole input as plain words) and additionally strip characters that have
 * no legitimate place in a simple keyword search, giving defence-in-depth.
 *
 * @param {string} raw
 * @returns {string}
 */
function sanitiseSearchQuery(raw) {
  if (typeof raw !== 'string') {
    throw new TypeError('Search query must be a string.');
  }

  // Reject empty or whitespace-only strings up-front.
  const trimmed = raw.trim();
  if (trimmed.length === 0) {
    throw new RangeError('Search query must not be empty.');
  }

  // Hard length cap — prevents excessively long strings from degrading DB
  // performance even if they are syntactically valid.
  if (trimmed.length > 200) {
    throw new RangeError('Search query must not exceed 200 characters.');
  }

  // Strip characters that are only meaningful as SQL/tsquery operators.
  // Allows Unicode letters, digits, spaces, hyphens, and apostrophes (common
  // in names such as "O'Brien" or "Smith-Jones").
  const sanitised = trimmed.replace(/[^'\-\p{L}\p{N}\s]/gu, ' ').trim();

  if (sanitised.length === 0) {
    throw new RangeError(
      'Search query contained no usable characters after sanitisation.'
    );
  }

  return sanitised;
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * getUserById
 *
 * Fetches a single user row by primary key.
 *
 * SQL injection prevention
 * ------------------------
 * The `id` value is coerced to an integer by `validatePositiveInteger`; a
 * non-numeric string will throw before it ever reaches the database.  It is
 * then passed as parameter $1 — the DB driver sends the integer value in the
 * binary protocol, completely separate from the SQL text.
 *
 * @param {number|string} id - The user's primary key.
 * @returns {Promise<object|null>} The user row or null if not found.
 */
async function getUserById(id) {
  const safeId = validatePositiveInteger(id, 'id', 1, Number.MAX_SAFE_INTEGER, null);
  if (safeId === null) {
    throw new TypeError('id is required.');
  }

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
      AND deleted_at IS NULL
    LIMIT 1;
  `;

  const result = await timedQuery({
    label: 'getUserById',
    sql,
    params: [safeId],
    name: 'get_user_by_id', // Prepared-statement name — plan is cached by pg.
  });

  return result.rows[0] ?? null;
}

/**
 * getAllUsers
 *
 * Returns a paginated slice of the users table ordered by creation date
 * (newest first).
 *
 * SQL injection prevention
 * ------------------------
 * Both `limit` and `offset` are coerced to integers and clamped to a safe
 * range before being passed as $1 and $2.  There are no dynamic identifiers
 * (table/column names) in the query, so there is no opportunity for injection
 * via those vectors.
 *
 * @param {number} [limit=20]  - Rows per page (max 100).
 * @param {number} [offset=0]  - Zero-based row offset.
 * @returns {Promise<{ users: object[], total: number }>}
 */
async function getAllUsers(limit = DEFAULT_LIMIT, offset = DEFAULT_OFFSET) {
  const safeLimit = validatePositiveInteger(limit, 'limit', 1, MAX_LIMIT, DEFAULT_LIMIT);
  const safeOffset = validatePositiveInteger(offset, 'offset', 0, 1_000_000, DEFAULT_OFFSET);

  // Fetch the page and the total count in a single round-trip using a window
  // function so the caller can build pagination metadata without a second query.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER () AS total_count
    FROM users
    WHERE deleted_at IS NULL
    ORDER BY created_at DESC, id DESC
    LIMIT $1
    OFFSET $2;
  `;

  const result = await timedQuery({
    label: 'getAllUsers',
    sql,
    params: [safeLimit, safeOffset],
    name: 'get_all_users',
  });

  // Separate the injected total_count column from the actual user fields.
  const users = result.rows.map(({ total_count, ...user }) => user);
  const total = result.rows.length > 0 ? parseInt(result.rows[0].total_count, 10) : 0;

  return { users, total };
}

/**
 * searchUsers
 *
 * Full-text search across the `name` and `email` columns using PostgreSQL's
 * built-in text-search engine.  Results are ranked by relevance.
 *
 * SQL injection prevention
 * ------------------------
 * 1. `sanitiseSearchQuery` validates and strips operator characters from the
 *    raw input string (defence-in-depth).
 * 2. The sanitised string is passed as parameter $1 to `plainto_tsquery()`.
 *    plainto_tsquery treats its input as a sequence of plain words, so even
 *    if a stray operator character somehow survived sanitisation it would be
 *    treated as a word, not an operator.
 * 3. LIMIT/OFFSET follow the same integer-coercion path as getAllUsers.
 *
 * Index requirement
 * -----------------
 * For this query to be fast at scale, create a GIN index:
 *   CREATE INDEX users_fts_idx ON users
 *   USING GIN (to_tsvector('english', coalesce(name,'') || ' ' || coalesce(email,'')));
 *
 * @param {string} query          - Plain-text search terms.
 * @param {number} [limit=20]     - Rows per page (max 100).
 * @param {number} [offset=0]     - Zero-based row offset.
 * @returns {Promise<{ users: object[], total: number }>}
 */
async function searchUsers(query, limit = DEFAULT_LIMIT, offset = DEFAULT_OFFSET) {
  const safeQuery = sanitiseSearchQuery(query);
  const safeLimit = validatePositiveInteger(limit, 'limit', 1, MAX_LIMIT, DEFAULT_LIMIT);
  const safeOffset = validatePositiveInteger(offset, 'offset', 0, 1_000_000, DEFAULT_OFFSET);

  // plainto_tsquery converts a plain string into a tsquery; it never
  // interprets operator characters so it is safe for untrusted input.
  // ts_rank_cd scores results by coverage density for better relevance.
  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at,
      COUNT(*) OVER ()                                             AS total_count,
      ts_rank_cd(
        to_tsvector('english', coalesce(name, '') || ' ' || coalesce(email, '')),
        plainto_tsquery('english', $1)
      )                                                            AS rank
    FROM users
    WHERE
      deleted_at IS NULL
      AND to_tsvector('english', coalesce(name, '') || ' ' || coalesce(email, ''))
          @@ plainto_tsquery('english', $1)
    ORDER BY rank DESC, created_at DESC
    LIMIT $2
    OFFSET $3;
  `;

  const result = await timedQuery({
    label: 'searchUsers',
    sql,
    params: [safeQuery, safeLimit, safeOffset],
    // Note: no prepared-statement name here because plainto_tsquery with a
    // variable argument produces different plans depending on the input, so
    // plan caching is less beneficial.
  });

  const users = result.rows.map(({ total_count, rank, ...user }) => user);
  const total = result.rows.length > 0 ? parseInt(result.rows[0].total_count, 10) : 0;

  return { users, total };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
};

/**
 * middleware/queryErrorHandler.js
 *
 * Translates known query-layer errors (validation, not-found, DB timeouts)
 * into appropriate HTTP responses so that app.js route handlers stay clean.
 *
 * Attach this *after* all routes:
 *   app.use(queryErrorHandler);
 */

'use strict';

/**
 * @param {Error}                   err
 * @param {import('express').Request}  req
 * @param {import('express').Response} res
 * @param {import('express').NextFunction} next
 */
function queryErrorHandler(err, req, res, next) {
  // Must keep the four-argument signature so Express recognises this as an
  // error-handling middleware even if `next` is not called.
  if (res.headersSent) {
    return next(err);
  }

  console.error(`[error] ${req.method} ${req.path} — ${err.message}`);

  if (err instanceof TypeError || err instanceof RangeError) {
    return res.status(400).json({
      error: 'Bad Request',
      message: err.message,
    });
  }

  // pg connection timeout
  if (err.code === 'ECONNREFUSED' || err.message?.includes('timeout')) {
    return res.status(503).json({
      error: 'Service Unavailable',
      message: 'Database is temporarily unreachable. Please retry shortly.',
    });
  }

  // Catch-all — never leak internal details to the client.
  return res.status(500).json({
    error: 'Internal Server Error',
    message: 'An unexpected error occurred.',
  });
}

module.exports = { queryErrorHandler };

/**
 * app.js
 *
 * Express application with a full database query layer.
 *
 * Endpoints
 * ---------
 *   GET /health              — Liveness probe (no DB call).
 *   GET /users               — Paginated list of all users.
 *   GET /users/search        — Full-text search across name + email.
 *   GET /users/:id           — Single user by primary key.
 *
 * All database access goes through db/queries.js which uses:
 *   • A shared pg connection pool  (db/pool.js)
 *   • Fully parameterised queries  (SQL injection prevention)
 *   • Per-query timing logs
 *   • Input validation before values reach the DB driver
 */

'use strict';

const express = require('express');
const { getUserById, getAllUsers, searchUsers } = require('./db/queries');
const { queryErrorHandler } = require('./middleware/queryErrorHandler');
const { closePool } = require('./db/pool');

const app = express();

app.use(express.json());

// ---------------------------------------------------------------------------
// Request-level timing middleware
// ---------------------------------------------------------------------------
// Logs method, path, status, and total request duration for every call.
// ---------------------------------------------------------------------------
app.use((req, res, next) => {
  const start = process.hrtime.bigint();

  res.on('finish', () => {
    const durationMs = Number(process.hrtime.bigint() - start) / 1_000_000;
    console.info(
      `[http] ${req.method} ${req.path} → ${res.statusCode} (${durationMs.toFixed(3)} ms)`
    );
  });

  next();
});

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 *
 * Simple liveness probe.  Does not hit the database so it stays responsive
 * even when the DB is down.
 */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users/search?q=<terms>[&limit=<n>&offset=<n>]
 *
 * Full-text search across name and email.
 *
 * Query parameters
 * ----------------
 *   q       {string}  Required. Plain-text search terms (max 200 chars).
 *   limit   {number}  Optional. Rows per page, 1–100 (default 20).
 *   offset  {number}  Optional. Zero-based row offset (default 0).
 *
 * This route MUST be registered before /users/:id so that the literal
 * segment "search" is not mistaken for a numeric id.
 */
app.get('/users/search', async (req, res, next) => {
  try {
    const { q, limit, offset } = req.query;

    // `q` is required — surface a clear 400 rather than a cryptic DB error.
    if (!q || String(q).trim() === '') {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Query parameter "q" is required and must not be empty.',
      });
    }

    const { users, total } = await searchUsers(q, limit, offset);

    return res.json({
      data: users,
      meta: {
        total,
        limit: Number(limit ?? 20),
        offset: Number(offset ?? 0),
        query: q,
      },
    });
  } catch (err) {
    return next(err);
  }
});

/**
 * GET /users?limit=<n>&offset=<n>
 *
 * Returns a paginated list of all non-deleted users, newest first.
 *
 * Query parameters
 * ----------------
 *   limit   {number}  Optional. Rows per page, 1–100 (default 20).
 *   offset  {number}  Optional. Zero-based row offset (default 0).
 */
app.get('/users', async (req, res, next) => {
  try {
    const { limit, offset } = req.query;
    const { users, total } = await getAllUsers(limit, offset);

    return res.json({
      data: users,
      meta: {
        total,
        limit: Number(limit ?? 20),
        offset: Number(offset ?? 0),
      },
    });
  } catch (err) {
    return next(err);
  }
});

/**
 * GET /users/:id
 *
 * Returns a single user by integer primary key.
 *
 * Path parameters
 * ---------------
 *   id  {number}  Required. Must be a positive integer.
 */
app.get('/users/:id', async (req, res, next) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: `No user found with id ${req.params.id}.`,
      });
    }

    return res.json({ data: user });
  } catch (err) {
    return next(err);
  }
});

// ---------------------------------------------------------------------------
// Error handling
// ---------------------------------------------------------------------------
// Must be registered after all routes so Express routes errors here last.
// ---------------------------------------------------------------------------
app.use(queryErrorHandler);

// ---------------------------------------------------------------------------
// Server startup & graceful shutdown
// ---------------------------------------------------------------------------

const PORT = parseInt(process.env.PORT ?? '3000', 10);

const server = app.listen(PORT, () => {
  console.info(`[server] Running on port ${PORT}`);
});

/**
 * Graceful shutdown
 *
 * On SIGTERM (sent by container orchestrators like Kubernetes) or SIGINT
 * (Ctrl-C in development):
 *   1. Stop accepting new connections.
 *   2. Wait for in-flight requests to finish (up to 10 s).
 *   3. Drain the connection pool.
 *   4. Exit cleanly.
 */
async function shutdown(signal) {
  console.info(`[server] ${signal} received — shutting down gracefully…`);

  server.close(async () => {
    try {
      await closePool();
      console.info('[server] Shutdown complete.');
      process.exit(0);
    } catch (err) {
      console.error('[server] Error during shutdown:', err.message);
      process.exit(1);
    }
  });

  // Force-exit if graceful shutdown exceeds 10 seconds.
  setTimeout(() => {
    console.error('[server] Graceful shutdown timed out — forcing exit.');
    process.exit(1);
  }, 10_000).unref();
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = app;

/**
 * tests/queries.test.js
 *
 * Unit tests for db/queries.js.
 *
 * The pg pool is mocked so no live database connection is needed.  Each test
 * verifies that:
 *   - The correct SQL is generated.
 *   - Parameters are passed in the right positions.
 *   - Input validation fires before the pool is touched.
 *   - SQL injection payloads are neutralised.
 */

'use strict';

// ---------------------------------------------------------------------------
// Mock the pool BEFORE requiring queries.js so the module picks up the mock.
// ---------------------------------------------------------------------------
const mockQuery = jest.fn();

jest.mock('../db/pool', () => ({
  pool: {
    query: mockQuery,
    on: jest.fn(),
  },
  closePool: jest.fn(),
}));

const { getUserById, getAllUsers, searchUsers } = require('../db/queries');

// ---------------------------------------------------------------------------
// Helper — builds a fake pg QueryResult
// ---------------------------------------------------------------------------
function makeResult(rows) {
  return { rows, rowCount: rows.length, command: 'SELECT' };
}

// ---------------------------------------------------------------------------
// Shared setup
// ---------------------------------------------------------------------------
beforeEach(() => {
  jest.clearAllMocks();
  // Suppress console noise during tests.
  jest.spyOn(console, 'info').mockImplementation(() => {});
  jest.spyOn(console, 'debug').mockImplementation(() => {});
  jest.spyOn(console, 'error').mockImplementation(() => {});
});

afterEach(() => {
  jest.restoreAllMocks();
});

// ===========================================================================
// getUserById
// ===========================================================================
describe('getUserById', () => {
  const fakeUser = {
    id: 1,
    name: 'Alice',
    email: 'alice@example.com',
    created_at: new Date(),
    updated_at: new Date(),
  };

  test('returns a user object when the row exists', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([fakeUser]));

    const user = await getUserById(1);

    expect(user).toEqual(fakeUser);
  });

  test('returns null when no row is found', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    const user = await getUserById(999);

    expect(user).toBeNull();
  });

  test('passes id as a positional parameter — never interpolated', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([fakeUser]));

    await getUserById(42);

    const callArg = mockQuery.mock.calls[0][0];
    // The SQL text must contain the placeholder, not the literal value.
    expect(callArg.text).toContain('$1');
    expect(callArg.text).not.toContain('42');
    // The value is passed separately.
    expect(callArg.values).toEqual([42]);
  });

  test('uses a prepared-statement name for plan caching', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await getUserById(1);

    const callArg = mockQuery.mock.calls[0][0];
    expect(callArg.name).toBe('get_user_by_id');
  });

  test('throws TypeError when id is missing', async () => {
    await expect(getUserById(null)).rejects.toThrow(TypeError);
    await expect(getUserById(undefined)).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws RangeError when id is zero', async () => {
    await expect(getUserById(0)).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws RangeError when id is negative', async () => {
    await expect(getUserById(-5)).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  // SQL injection attempts --------------------------------------------------

  test('rejects SQL injection string "1 OR 1=1"', async () => {
    // Non-numeric string → coerced to NaN → RangeError before the pool.
    await expect(getUserById('1 OR 1=1')).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects UNION-based payload', async () => {
    await expect(
      getUserById("1 UNION SELECT table_name FROM information_schema.tables--")
    ).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects "1; DROP TABLE users;--"', async () => {
    await expect(getUserById('1; DROP TABLE users;--')).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('accepts a valid numeric string "7"', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));
    await expect(getUserById('7')).resolves.toBeNull();
    expect(mockQuery.mock.calls[0][0].values).toEqual([7]);
  });
});

// ===========================================================================
// getAllUsers
// ===========================================================================
describe('getAllUsers', () => {
  const fakeRows = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), updated_at: new Date(), total_count: '2' },
    { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: new Date(), updated_at: new Date(), total_count: '2' },
  ];

  test('returns users array and total count', async () => {
    mockQuery.mockResolvedValueOnce(makeResult(fakeRows));

    const { users, total } = await getAllUsers();

    expect(users).toHaveLength(2);
    expect(total).toBe(2);
    // total_count must be stripped from user objects.
    expect(users[0]).not.toHaveProperty('total_count');
  });

  test('applies default limit=20 and offset=0', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await getAllUsers();

    const { values } = mockQuery.mock.calls[0][0];
    expect(values).toEqual([20, 0]);
  });

  test('forwards supplied limit and offset', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await getAllUsers(5, 10);

    const { values } = mockQuery.mock.calls[0][0];
    expect(values).toEqual([5, 10]);
  });

  test('uses $1 and $2 placeholders for limit and offset', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await getAllUsers(10, 0);

    const { text } = mockQuery.mock.calls[0][0];
    expect(text).toContain('$1');
    expect(text).toContain('$2');
    expect(text).not.toContain('10');
  });

  test('clamps limit to MAX_LIMIT (100)', async () => {
    await expect(getAllUsers(101, 0)).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects negative limit', async () => {
    await expect(getAllUsers(-1, 0)).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects negative offset', async () => {
    await expect(getAllUsers(10, -1)).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('returns empty result when table is empty', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    const { users, total } = await getAllUsers();

    expect(users).toEqual([]);
    expect(total).toBe(0);
  });

  // SQL injection attempts --------------------------------------------------

  test('rejects SQL injection in limit "10; DROP TABLE users--"', async () => {
    await expect(getAllUsers('10; DROP TABLE users--', 0)).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('rejects SQL injection in offset "0 OR 1=1"', async () => {
    await expect(getAllUsers(10, '0 OR 1=1')).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });
});

// ===========================================================================
// searchUsers
// ===========================================================================
describe('searchUsers', () => {
  const fakeRows = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: new Date(), updated_at: new Date(), total_count: '1', rank: 0.9 },
  ];

  test('returns matching users and total', async () => {
    mockQuery.mockResolvedValueOnce(makeResult(fakeRows));

    const { users, total } = await searchUsers('Alice');

    expect(users).toHaveLength(1);
    expect(total).toBe(1);
    // rank and total_count must be stripped.
    expect(users[0]).not.toHaveProperty('rank');
    expect(users[0]).not.toHaveProperty('total_count');
  });

  test('uses plainto_tsquery in the SQL (not to_tsquery)', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('alice');

    const { text } = mockQuery.mock.calls[0][0];
    expect(text).toContain('plainto_tsquery');
    expect(text).not.toContain('to_tsquery(');
  });

  test('passes search term, limit, and offset as positional params', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('bob', 5, 10);

    const { values } = mockQuery.mock.calls[0][0];
    expect(values[0]).toBe('bob');
    expect(values[1]).toBe(5);
    expect(values[2]).toBe(10);
  });

  test('throws RangeError for empty search query', async () => {
    await expect(searchUsers('')).rejects.toThrow(RangeError);
    await expect(searchUsers('   ')).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws TypeError when query is not a string', async () => {
    await expect(searchUsers(null)).rejects.toThrow(TypeError);
    await expect(searchUsers(42)).rejects.toThrow(TypeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws RangeError when query exceeds 200 characters', async () => {
    await expect(searchUsers('a'.repeat(201))).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  // SQL injection attempts --------------------------------------------------

  test('strips SQL comment operator "--" from search query', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers("alice'--");

    // The value actually sent to the DB must not contain "--".
    const { values } = mockQuery.mock.calls[0][0];
    expect(values[0]).not.toContain('--');
  });

  test('strips semicolons from search query', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('alice; DROP TABLE users');

    const { values } = mockQuery.mock.calls[0][0];
    expect(values[0]).not.toContain(';');
  });

  test('strips tsquery operator "&" from search query', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('password & 1=1');

    const { values } = mockQuery.mock.calls[0][0];
    expect(values[0]).not.toContain('&');
    expect(values[0]).not.toContain('=');
  });

  test('strips tsquery operator "|" from search query', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('alice | DROP TABLE users');

    const { values } = mockQuery.mock.calls[0][0];
    expect(values[0]).not.toContain('|');
  });

  test('strips tsquery negation operator "!" from search query', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('!admin');

    const { values } = mockQuery.mock.calls[0][0];
    expect(values[0]).not.toContain('!');
  });

  test('preserves legitimate hyphenated name "Smith-Jones"', async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers('Smith-Jones');

    const { values } = mockQuery.mock.calls[0][0];
    expect(values[0]).toBe('Smith-Jones');
  });

  test("preserves legitimate apostrophe name \"O'Brien\"", async () => {
    mockQuery.mockResolvedValueOnce(makeResult([]));

    await searchUsers("O'Brien");

    const { values } = mockQuery.mock.calls[0][0];
    expect(values[0]).toBe("O'Brien");
  });

  test('throws RangeError when only illegal characters are supplied', async () => {
    await expect(searchUsers('!&|;--')).rejects.toThrow(RangeError);
    expect(mockQuery).not.toHaveBeenCalled();
  });
});

