{
  "name": "express-db-app",
  "version": "1.0.0",
  "description": "Express app with PostgreSQL query layer and connection pooling",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js",
    "test": "jest --runInBand --forceExit"
  },
  "dependencies": {
    "dotenv": "^16.4.5",
    "express": "^4.19.2",
    "pg": "^8.12.0"
  },
  "devDependencies": {
    "jest": "^29.7.0",
    "supertest": "^7.0.0"
  }
}

/**
 * db.js — PostgreSQL connection pool
 *
 * A single Pool instance is created once and shared across the entire
 * application.  Callers import { pool } and call pool.query() directly,
 * or use the higher-level helpers in queries.js.
 *
 * Configuration is read exclusively from environment variables so that
 * no credentials ever appear in source code.  See .env.example for the
 * full list of supported variables.
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------

/**
 * Build a pg Pool configuration object from environment variables.
 * Every sensitive value (host, user, password, database name) is read
 * from the environment; sensible defaults are provided for non-sensitive
 * pool-tuning parameters only.
 *
 * @returns {import('pg').PoolConfig}
 */
function buildPoolConfig() {
  // When DATABASE_URL is present pg will parse it automatically.
  // Individual variable overrides are still respected by pg when present
  // alongside a connection string, but we keep things simple: use one
  // or the other.
  if (process.env.DATABASE_URL) {
    return {
      connectionString: process.env.DATABASE_URL,
      // Enforce TLS in production; allow override for local dev.
      ssl:
        process.env.DB_SSL === 'false'
          ? false
          : process.env.NODE_ENV === 'production'
          ? { rejectUnauthorized: true }
          : false,
      // Pool tuning — all optional with safe defaults.
      max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),
      idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT_MS ?? '30000', 10),
      connectionTimeoutMillis: parseInt(process.env.DB_CONN_TIMEOUT_MS ?? '5000', 10),
    };
  }

  // Individual connection parameters.
  return {
    host: process.env.DB_HOST ?? 'localhost',
    port: parseInt(process.env.DB_PORT ?? '5432', 10),
    database: process.env.DB_NAME,
    user: process.env.DB_USER,
    password: process.env.DB_PASSWORD,
    ssl:
      process.env.DB_SSL === 'false'
        ? false
        : process.env.NODE_ENV === 'production'
        ? { rejectUnauthorized: true }
        : false,
    max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),
    idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT_MS ?? '30000', 10),
    connectionTimeoutMillis: parseInt(process.env.DB_CONN_TIMEOUT_MS ?? '5000', 10),
  };
}

// ---------------------------------------------------------------------------
// Create and export the pool
// ---------------------------------------------------------------------------

const pool = new Pool(buildPoolConfig());

// Surface pool-level errors so they don't go unhandled (pg recommendation).
pool.on('error', (err) => {
  console.error('[db] Unexpected pool error:', err.message);
});

// Convenience wrapper: run a single parameterised query and return the
// pg QueryResult.  Callers should prefer the functions in queries.js.
async function query(text, params) {
  return pool.query(text, params);
}

// Graceful shutdown helper — call this in your SIGTERM / SIGINT handlers.
async function closePool() {
  await pool.end();
}

module.exports = { pool, query, closePool };

/**
 * queries.js — parameterised query functions for the /users endpoint
 *
 * Design principles
 * -----------------
 * 1. SQL injection prevention
 *    Every value that originates from outside this module is passed as a
 *    *parameter* ($1, $2, …) — never interpolated into the SQL string.
 *    pg sends parameters to PostgreSQL over the wire protocol as separate
 *    typed values, so the database engine itself treats them as data, never
 *    as SQL syntax.  String concatenation into SQL text is intentionally
 *    avoided throughout this file.
 *
 * 2. Input validation
 *    Parameters are validated and coerced before the query is sent.
 *    Invalid values throw a typed ValidationError so callers can return an
 *    appropriate HTTP 400 response without leaking stack traces.
 *
 * 3. Query timing
 *    Every query is wrapped in a timer.  Timing data is written to stdout as
 *    structured JSON so it can be ingested by any log aggregator.  The query
 *    *text* is logged (it is static) but *parameter values* are never logged
 *    to avoid leaking personal data.
 *
 * 4. Connection pooling
 *    All queries share the single Pool exported by db.js.  Individual clients
 *    are borrowed from the pool only when executing a transaction; for simple
 *    queries pool.query() is used, which handles checkout/release internally.
 */

'use strict';

const { pool } = require('./db');

// ---------------------------------------------------------------------------
// Custom error types
// ---------------------------------------------------------------------------

/**
 * Thrown when a caller passes an argument that fails validation.
 * The HTTP layer should convert this to a 400 response.
 */
class ValidationError extends Error {
  /** @param {string} message  Human-readable description of the violation. */
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
  }
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

/**
 * Emit a structured timing log entry to stdout.
 *
 * Parameter *values* are intentionally excluded from the log to avoid
 * inadvertently recording personal data.  The number of parameters is
 * recorded instead so queries can be correlated in debugging sessions.
 *
 * @param {object} opts
 * @param {string}  opts.queryName   - Logical name of the query (e.g. 'getUserById')
 * @param {string}  opts.sql         - The SQL text that was executed
 * @param {number}  opts.paramCount  - How many bound parameters were sent
 * @param {number}  opts.durationMs  - Wall-clock time in milliseconds
 * @param {number}  opts.rowCount    - Number of rows returned / affected
 * @param {boolean} opts.success     - Whether the query completed without error
 * @param {string}  [opts.error]     - Error message when success === false
 */
function logQueryTiming({
  queryName,
  sql,
  paramCount,
  durationMs,
  rowCount,
  success,
  error,
}) {
  const entry = {
    timestamp: new Date().toISOString(),
    level: success ? 'info' : 'error',
    event: 'db_query',
    queryName,
    sql,
    paramCount,
    durationMs,
    rowCount,
    success,
    ...(error ? { error } : {}),
  };
  // Use process.stdout.write to keep the log on a single line.
  process.stdout.write(JSON.stringify(entry) + '\n');
}

/**
 * Execute a parameterised query against the shared pool, measure its
 * wall-clock duration, emit a timing log, and return the pg QueryResult.
 *
 * @param {object} opts
 * @param {string}   opts.queryName - Logical name used in timing logs
 * @param {string}   opts.sql       - Parameterised SQL text ($1, $2, …)
 * @param {Array}    opts.params    - Bound parameter values (never interpolated)
 * @returns {Promise<import('pg').QueryResult>}
 */
async function timedQuery({ queryName, sql, params }) {
  const start = process.hrtime.bigint();
  let result;
  let success = true;
  let errorMessage;

  try {
    result = await pool.query(sql, params);
  } catch (err) {
    success = false;
    errorMessage = err.message;
    throw err;
  } finally {
    const end = process.hrtime.bigint();
    // Convert nanoseconds → milliseconds with two decimal places.
    const durationMs = Number(end - start) / 1_000_000;

    logQueryTiming({
      queryName,
      sql,
      paramCount: params.length,
      durationMs: parseFloat(durationMs.toFixed(2)),
      rowCount: result?.rowCount ?? 0,
      success,
      ...(errorMessage ? { error: errorMessage } : {}),
    });
  }

  return result;
}

// ---------------------------------------------------------------------------
// Validation helpers
// ---------------------------------------------------------------------------

/**
 * Parse and validate a user ID.
 * Accepts a string (from req.params) or a number.
 *
 * @param {string|number} raw
 * @returns {number} A safe positive integer.
 * @throws {ValidationError}
 */
function validateId(raw) {
  const n = Number(raw);
  if (!Number.isInteger(n) || n < 1) {
    throw new ValidationError(
      `Invalid id: expected a positive integer, got "${raw}"`
    );
  }
  return n;
}

/**
 * Parse and validate pagination parameters.
 *
 * @param {string|number} rawLimit
 * @param {string|number} rawOffset
 * @returns {{ limit: number, offset: number }}
 * @throws {ValidationError}
 */
function validatePagination(rawLimit, rawOffset) {
  const limit = Number(rawLimit ?? 20);
  const offset = Number(rawOffset ?? 0);

  if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
    throw new ValidationError(
      'limit must be an integer between 1 and 100'
    );
  }
  if (!Number.isInteger(offset) || offset < 0) {
    throw new ValidationError('offset must be a non-negative integer');
  }

  return { limit, offset };
}

/**
 * Validate a free-text search query string.
 *
 * @param {string} raw
 * @returns {string} Trimmed, non-empty string of acceptable length.
 * @throws {ValidationError}
 */
function validateSearchQuery(raw) {
  if (typeof raw !== 'string') {
    throw new ValidationError('query must be a string');
  }
  const trimmed = raw.trim();
  if (trimmed.length === 0) {
    throw new ValidationError('query must not be empty');
  }
  if (trimmed.length > 200) {
    throw new ValidationError('query must be 200 characters or fewer');
  }
  return trimmed;
}

// ---------------------------------------------------------------------------
// Public query functions
// ---------------------------------------------------------------------------

/**
 * Fetch a single user by their primary-key id.
 *
 * The id is passed as a bound parameter ($1) — it is never interpolated
 * into the SQL string, preventing SQL injection unconditionally.
 *
 * @param {string|number} id  - The user's numeric primary key.
 * @returns {Promise<object|null>}  The user row, or null if not found.
 * @throws {ValidationError}        If id is not a valid positive integer.
 */
async function getUserById(id) {
  const safeId = validateId(id);

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE id = $1
    LIMIT 1
  `;

  const result = await timedQuery({
    queryName: 'getUserById',
    sql,
    params: [safeId],
  });

  return result.rows[0] ?? null;
}

/**
 * Fetch a paginated list of all users, ordered by id ascending.
 *
 * LIMIT and OFFSET are passed as bound parameters ($1 and $2).
 * PostgreSQL accepts integer parameters for LIMIT/OFFSET in the same
 * way it accepts them for WHERE clauses, so no interpolation is needed.
 *
 * @param {string|number} [limit=20]   - Maximum rows to return (1–100).
 * @param {string|number} [offset=0]   - Number of rows to skip.
 * @returns {Promise<{ users: object[], total: number, limit: number, offset: number }>}
 * @throws {ValidationError}  If limit or offset are out of range.
 */
async function getAllUsers(limit = 20, offset = 0) {
  const { limit: safeLimit, offset: safeOffset } = validatePagination(
    limit,
    offset
  );

  // Run the data query and the count query concurrently for efficiency.
  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    ORDER BY id ASC
    LIMIT $1 OFFSET $2
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
  `;

  const [dataResult, countResult] = await Promise.all([
    timedQuery({
      queryName: 'getAllUsers',
      sql: dataSql,
      params: [safeLimit, safeOffset],
    }),
    timedQuery({
      queryName: 'getAllUsers_count',
      sql: countSql,
      params: [],
    }),
  ]);

  return {
    users: dataResult.rows,
    total: parseInt(countResult.rows[0].total, 10),
    limit: safeLimit,
    offset: safeOffset,
  };
}

/**
 * Search users by name or email using a case-insensitive partial match.
 *
 * The search term is passed as a single parameterised value ($1).  The
 * ILIKE pattern is constructed *inside* the database (via the `$1`
 * placeholder) — the percent wildcards are part of the value, not the
 * SQL text, so PostgreSQL's parser never interprets user input as SQL.
 *
 * The `query` argument is validated for type, emptiness, and maximum
 * length before the query is sent.
 *
 * @param {string}        searchQuery  - Free-text search term.
 * @param {string|number} [limit=20]   - Maximum rows to return (1–100).
 * @param {string|number} [offset=0]   - Number of rows to skip.
 * @returns {Promise<{ users: object[], total: number, limit: number, offset: number, query: string }>}
 * @throws {ValidationError}  If searchQuery is empty/too long, or pagination is invalid.
 */
async function searchUsers(searchQuery, limit = 20, offset = 0) {
  const safeQuery = validateSearchQuery(searchQuery);
  const { limit: safeLimit, offset: safeOffset } = validatePagination(
    limit,
    offset
  );

  // The wildcard pattern is built as a plain JS string and sent to
  // PostgreSQL as a bound parameter value — never concatenated into SQL.
  const pattern = `%${safeQuery}%`;

  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
    ORDER BY id ASC
    LIMIT $2 OFFSET $3
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM users
    WHERE
      name  ILIKE $1
      OR email ILIKE $1
  `;

  const [dataResult, countResult] = await Promise.all([
    timedQuery({
      queryName: 'searchUsers',
      sql: dataSql,
      params: [pattern, safeLimit, safeOffset],
    }),
    timedQuery({
      queryName: 'searchUsers_count',
      sql: countSql,
      params: [pattern],
    }),
  ]);

  return {
    users: dataResult.rows,
    total: parseInt(countResult.rows[0].total, 10),
    limit: safeLimit,
    offset: safeOffset,
    query: safeQuery,
  };
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  ValidationError, // exported so HTTP layer can instanceof-check it
};

/**
 * app.js — Express application with a PostgreSQL-backed /users endpoint
 *
 * Route overview
 * --------------
 *  GET /health            — liveness probe
 *  GET /users             — paginated list of all users
 *  GET /users/search      — search users by name or email (must come before /:id)
 *  GET /users/:id         — single user by numeric id
 */

'use strict';

// Load environment variables from .env (if present) before any other module
// reads process.env.  In production, variables should be injected by the
// runtime environment instead.
require('dotenv').config();

const express = require('express');
const { getUserById, getAllUsers, searchUsers, ValidationError } = require('./queries');
const { closePool } = require('./db');

const app = express();
app.use(express.json());

// ---------------------------------------------------------------------------
// Helper: uniform error response
// ---------------------------------------------------------------------------

/**
 * Send a JSON error response.  Stack traces are never exposed to callers.
 *
 * @param {import('express').Response} res
 * @param {number} status  HTTP status code
 * @param {string} message Human-readable error message
 */
function sendError(res, status, message) {
  res.status(status).json({ error: message });
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

/**
 * GET /health
 * Simple liveness probe — does not touch the database.
 */
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users/search?query=<term>[&limit=<n>&offset=<n>]
 *
 * Search users whose name or email contains the given term
 * (case-insensitive).
 *
 * Query parameters:
 *   query   {string}  Required. Search term (max 200 chars).
 *   limit   {number}  Optional. Rows per page, 1–100, default 20.
 *   offset  {number}  Optional. Rows to skip, default 0.
 *
 * This route is intentionally declared *before* GET /users/:id so that
 * Express resolves /users/search as a literal path, not as id="search".
 */
app.get('/users/search', async (req, res) => {
  const { query, limit, offset } = req.query;

  if (!query) {
    return sendError(res, 400, 'Missing required query parameter: query');
  }

  try {
    const result = await searchUsers(query, limit, offset);
    res.json(result);
  } catch (err) {
    if (err instanceof ValidationError) {
      return sendError(res, 400, err.message);
    }
    console.error('[GET /users/search] Unexpected error:', err.message);
    sendError(res, 500, 'Internal server error');
  }
});

/**
 * GET /users?[limit=<n>&offset=<n>]
 *
 * Return a paginated list of all users ordered by id ascending.
 *
 * Query parameters:
 *   limit   {number}  Optional. Rows per page, 1–100, default 20.
 *   offset  {number}  Optional. Rows to skip, default 0.
 *
 * Response shape:
 *   { users: [...], total: <count>, limit: <n>, offset: <n> }
 */
app.get('/users', async (req, res) => {
  const { limit, offset } = req.query;

  try {
    const result = await getAllUsers(limit, offset);
    res.json(result);
  } catch (err) {
    if (err instanceof ValidationError) {
      return sendError(res, 400, err.message);
    }
    console.error('[GET /users] Unexpected error:', err.message);
    sendError(res, 500, 'Internal server error');
  }
});

/**
 * GET /users/:id
 *
 * Fetch a single user by numeric primary key.
 *
 * URL parameters:
 *   id  {number}  Required. Must be a positive integer.
 *
 * Responds with 404 when no user with the given id exists.
 */
app.get('/users/:id', async (req, res) => {
  const { id } = req.params;

  try {
    const user = await getUserById(id);

    if (!user) {
      return sendError(res, 404, `User with id ${id} not found`);
    }

    res.json(user);
  } catch (err) {
    if (err instanceof ValidationError) {
      return sendError(res, 400, err.message);
    }
    console.error('[GET /users/:id] Unexpected error:', err.message);
    sendError(res, 500, 'Internal server error');
  }
});

// ---------------------------------------------------------------------------
// Graceful shutdown
// ---------------------------------------------------------------------------

async function shutdown(signal) {
  console.log(`[app] ${signal} received — closing DB pool and exiting`);
  await closePool();
  process.exit(0);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

// ---------------------------------------------------------------------------
// Server startup
// ---------------------------------------------------------------------------

if (require.main === module) {
  const PORT = parseInt(process.env.PORT ?? '3000', 10);
  app.listen(PORT, () => {
    console.log(`[app] Server running on port ${PORT}`);
  });
}

module.exports = app;

/**
 * queries.test.js — unit tests for queries.js
 *
 * The PostgreSQL pool is mocked at the module level so tests run without
 * a real database.  Each test group covers:
 *   - Happy-path behaviour (correct SQL, correct parameters, correct shape)
 *   - Input validation (ValidationError thrown for bad inputs)
 *   - Not-found handling
 *   - Query timing log emission
 *   - SQL injection prevention (user input never appears in SQL text)
 */

'use strict';

// ---------------------------------------------------------------------------
// Mock db.js before queries.js is required
// ---------------------------------------------------------------------------

const mockQuery = jest.fn();

jest.mock('./db', () => ({
  pool: { query: mockQuery },
  closePool: jest.fn(),
}));

// Capture all stdout writes so we can assert on timing log entries.
let stdoutLines = [];
const originalWrite = process.stdout.write.bind(process.stdout);

beforeEach(() => {
  stdoutLines = [];
  jest
    .spyOn(process.stdout, 'write')
    .mockImplementation((chunk) => {
      stdoutLines.push(String(chunk));
      return true;
    });
  mockQuery.mockReset();
});

afterEach(() => {
  jest.restoreAllMocks();
});

// Require the module under test *after* mocks are in place.
const {
  getUserById,
  getAllUsers,
  searchUsers,
  ValidationError,
} = require('./queries');

// ---------------------------------------------------------------------------
// Helper
// ---------------------------------------------------------------------------

/** Parse and return all structured log entries emitted during a test. */
function capturedLogs() {
  return stdoutLines
    .map((line) => {
      try {
        return JSON.parse(line.trim());
      } catch {
        return null;
      }
    })
    .filter(Boolean);
}

// ---------------------------------------------------------------------------
// getUserById
// ---------------------------------------------------------------------------

describe('getUserById', () => {
  const mockUser = {
    id: 1,
    name: 'Alice',
    email: 'alice@example.com',
    created_at: '2024-01-01T00:00:00.000Z',
    updated_at: '2024-01-01T00:00:00.000Z',
  };

  test('returns a user row when found', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [mockUser], rowCount: 1 });

    const result = await getUserById(1);

    expect(result).toEqual(mockUser);
  });

  test('returns null when no row matches', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [], rowCount: 0 });

    const result = await getUserById(99);

    expect(result).toBeNull();
  });

  test('passes id as a bound parameter, not in the SQL text', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [mockUser], rowCount: 1 });

    await getUserById(42);

    const [sql, params] = mockQuery.mock.calls[0];
    // The literal number must appear in params[], not embedded in the SQL string.
    expect(params).toEqual([42]);
    expect(sql).not.toMatch(/42/);
    expect(sql).toMatch(/\$1/);
  });

  test('SQL injection string does not appear in SQL text', async () => {
    // Even if validateId would reject this, confirm the raw string is never
    // interpolated.  We test the validation path separately below.
    mockQuery.mockResolvedValueOnce({ rows: [], rowCount: 0 });

    // Use a numeric value that is also potentially confusing; real injection
    // strings fail validation, so we just verify the param binding mechanism.
    await getUserById('7');

    const [sql, params] = mockQuery.mock.calls[0];
    expect(params[0]).toBe(7);
    expect(sql).not.toContain('7');
  });

  test('emits a timing log entry with correct shape', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [mockUser], rowCount: 1 });

    await getUserById(1);

    const logs = capturedLogs();
    expect(logs).toHaveLength(1);
    const log = logs[0];

    expect(log).toMatchObject({
      event: 'db_query',
      queryName: 'getUserById',
      paramCount: 1,
      rowCount: 1,
      success: true,
    });
    expect(typeof log.durationMs).toBe('number');
    expect(log.durationMs).toBeGreaterThanOrEqual(0);
    expect(log.timestamp).toMatch(/^\d{4}-\d{2}-\d{2}T/);
  });

  test('timing log marks success=false and includes error on DB failure', async () => {
    mockQuery.mockRejectedValueOnce(new Error('connection refused'));

    await expect(getUserById(1)).rejects.toThrow('connection refused');

    const logs = capturedLogs();
    expect(logs[0]).toMatchObject({
      success: false,
      error: 'connection refused',
    });
  });

  test('timing log does not include parameter values', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [mockUser], rowCount: 1 });

    await getUserById(1);

    const raw = stdoutLines.join('');
    // The value "1" alone is too common to assert, but we can confirm the
    // log entry does NOT have a "params" key.
    const log = capturedLogs()[0];
    expect(log).not.toHaveProperty('params');
  });

  // Validation -----------------------------------------------------------

  test('throws ValidationError for id = 0', async () => {
    await expect(getUserById(0)).rejects.toThrow(ValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws ValidationError for negative id', async () => {
    await expect(getUserById(-5)).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for non-numeric string id', async () => {
    await expect(getUserById('abc')).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for SQL injection attempt in id', async () => {
    await expect(getUserById("1 OR 1=1")).rejects.toThrow(ValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws ValidationError for floating-point id', async () => {
    await expect(getUserById(1.5)).rejects.toThrow(ValidationError);
  });

  test('accepts numeric string id', async () => {
    mockQuery.mockResolvedValueOnce({ rows: [mockUser], rowCount: 1 });

    const result = await getUserById('3');
    expect(result).toEqual(mockUser);
    expect(mockQuery.mock.calls[0][1]).toEqual([3]);
  });
});

