  // Validation -----------------------------------------------------------

  test('throws ValidationError for limit > 100', async () => {
    await expect(getAllUsers(101, 0)).rejects.toThrow(ValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws ValidationError for limit = 0', async () => {
    await expect(getAllUsers(0, 0)).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for negative offset', async () => {
    await expect(getAllUsers(10, -1)).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for non-numeric limit', async () => {
    await expect(getAllUsers('abc', 0)).rejects.toThrow(ValidationError);
  });

  test('accepts limit and offset as numeric strings', async () => {
    setupAllUsersQueries();

    const result = await getAllUsers('5', '10');
    expect(result.limit).toBe(5);
    expect(result.offset).toBe(10);
  });
});

// ---------------------------------------------------------------------------
// searchUsers
// ---------------------------------------------------------------------------

describe('searchUsers', () => {
  const mockResults = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: null, updated_at: null },
  ];

  function setupSearchQueries(results = mockResults, total = 1) {
    mockQuery
      .mockResolvedValueOnce({ rows: results, rowCount: results.length })
      .mockResolvedValueOnce({ rows: [{ total: String(total) }], rowCount: 1 });
  }

  test('returns paginated result with query echoed back', async () => {
    setupSearchQueries();

    const result = await searchUsers('Alice');

    expect(result).toMatchObject({
      users: mockResults,
      total: 1,
      limit: 20,
      offset: 0,
      query: 'Alice',
    });
  });

  test('passes ILIKE pattern as a bound parameter', async () => {
    setupSearchQueries();

    await searchUsers('alice');

    // The data query takes [pattern, limit, offset] → 3 params.
    const dataCall = mockQuery.mock.calls.find((c) => c[1].length === 3);
    expect(dataCall[1][0]).toBe('%alice%');
    // The raw term must NOT appear in the SQL text.
    expect(dataCall[0]).not.toMatch(/alice/i);
    expect(dataCall[0]).toMatch(/ILIKE \$1/i);
  });

  test('count query reuses the same bound ILIKE parameter', async () => {
    setupSearchQueries();

    await searchUsers('bob');

    const countCall = mockQuery.mock.calls.find((c) => c[1].length === 1);
    expect(countCall[1][0]).toBe('%bob%');
  });

  test('trims whitespace from the search term', async () => {
    setupSearchQueries();

    await searchUsers('  Alice  ');

    const dataCall = mockQuery.mock.calls.find((c) => c[1].length === 3);
    // Trimmed, then wrapped in wildcards.
    expect(dataCall[1][0]).toBe('%Alice%');
  });

  test('SQL injection attempt in search term is passed as data, not SQL', async () => {
    setupSearchQueries([]);

    const injection = "' OR '1'='1";
    await searchUsers(injection);

    const dataCall = mockQuery.mock.calls.find((c) => c[1].length === 3);
    // The injected string must appear only as a parameter value.
    expect(dataCall[1][0]).toBe(`%${injection}%`);
    // And must not affect the SQL text.
    expect(dataCall[0]).not.toContain(injection);
  });

  test('emits two timing log entries', async () => {
    setupSearchQueries();

    await searchUsers('Alice');

    const logs = capturedLogs();
    expect(logs).toHaveLength(2);
    const names = logs.map((l) => l.queryName);
    expect(names).toContain('searchUsers');
    expect(names).toContain('searchUsers_count');
  });

  test('timing log includes paramCount=3 for data query', async () => {
    setupSearchQueries();

    await searchUsers('Alice');

    const logs = capturedLogs();
    const dataLog = logs.find((l) => l.queryName === 'searchUsers');
    expect(dataLog.paramCount).toBe(3);
  });

  // Validation -----------------------------------------------------------

  test('throws ValidationError for empty query string', async () => {
    await expect(searchUsers('')).rejects.toThrow(ValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws ValidationError for whitespace-only query string', async () => {
    await expect(searchUsers('   ')).rejects.toThrow(ValidationError);
    expect(mockQuery).not.toHaveBeenCalled();
  });

  test('throws ValidationError for query longer than 200 chars', async () => {
    await expect(searchUsers('x'.repeat(201))).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for non-string query', async () => {
    await expect(searchUsers(12345)).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for limit out of range', async () => {
    await expect(searchUsers('Alice', 200)).rejects.toThrow(ValidationError);
  });

  test('throws ValidationError for negative offset', async () => {
    await expect(searchUsers('Alice', 10, -5)).rejects.toThrow(ValidationError);
  });

  test('respects custom limit and offset', async () => {
    setupSearchQueries();

    const result = await searchUsers('test', 5, 15);
    expect(result.limit).toBe(5);
    expect(result.offset).toBe(15);

    const dataCall = mockQuery.mock.calls.find((c) => c[1].length === 3);
    expect(dataCall[1]).toEqual(['%test%', 5, 15]);
  });
});

// ---------------------------------------------------------------------------
// ValidationError class
// ---------------------------------------------------------------------------

describe('ValidationError', () => {
  test('is an instance of Error', () => {
    const err = new ValidationError('bad input');
    expect(err).toBeInstanceOf(Error);
  });

  test('has name "ValidationError"', () => {
    const err = new ValidationError('bad input');
    expect(err.name).toBe('ValidationError');
  });

  test('message is preserved', () => {
    const err = new ValidationError('id must be positive');
    expect(err.message).toBe('id must be positive');
  });
});

