/**
 * db.js — PostgreSQL connection pool
 *
 * Exports a single shared `pg.Pool` instance that is reused across every
 * module that requires this file.  Connection configuration is read
 * exclusively from environment variables so that no credentials ever appear
 * in source code.
 *
 * Environment variables (set these in .env / your deployment secrets):
 *   DATABASE_URL          — full connection string (takes priority)
 *   PGHOST / PGPORT / PGDATABASE / PGUSER / PGPASSWORD — individual fields
 *   DB_POOL_MAX           — maximum pool size            (default: 10)
 *   DB_POOL_IDLE_TIMEOUT  — ms before idle client closes (default: 30 000)
 *   DB_CONNECT_TIMEOUT    — ms before a connection attempt times out (default: 5 000)
 *   NODE_ENV              — set to 'production' to suppress verbose pool logs
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------

const poolConfig = {
  // If DATABASE_URL is set it takes precedence over the individual PG* vars.
  // pg automatically reads PGHOST, PGPORT, PGDATABASE, PGUSER, PGPASSWORD
  // from the environment when connectionString is undefined, so both styles
  // work without any extra code here.
  connectionString: process.env.DATABASE_URL || undefined,

  // Maximum number of clients kept alive in the pool.
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

  // How long (ms) a client is allowed to sit idle before being closed.
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT ?? '30000', 10),

  // How long (ms) to wait for a new connection before throwing.
  connectionTimeoutMillis: parseInt(process.env.DB_CONNECT_TIMEOUT ?? '5000', 10),

  // SSL: require SSL in production unless explicitly disabled.
  ssl:
    process.env.DB_SSL === 'false'
      ? false
      : process.env.NODE_ENV === 'production'
        ? { rejectUnauthorized: true }
        : false,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event listeners
// ---------------------------------------------------------------------------

const isDev = process.env.NODE_ENV !== 'production';

pool.on('connect', (client) => {
  if (isDev) {
    console.log(
      `[db] New client connected — pool size: ${pool.totalCount} ` +
        `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`,
    );
  }
});

pool.on('acquire', () => {
  if (isDev) {
    console.log(
      `[db] Client acquired — pool size: ${pool.totalCount} ` +
        `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`,
    );
  }
});

pool.on('remove', () => {
  if (isDev) {
    console.log(
      `[db] Client removed — pool size: ${pool.totalCount} ` +
        `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`,
    );
  }
});

// A pool error means a background client threw — log it so the process does
// not crash silently.
pool.on('error', (err) => {
  console.error('[db] Unexpected pool error:', err.message);
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------

/**
 * Drain the pool and release all connections.
 * Call this during SIGTERM / SIGINT handling.
 *
 * @returns {Promise<void>}
 */
async function closePool() {
  console.log('[db] Draining connection pool…');
  await pool.end();
  console.log('[db] Pool drained.');
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { pool, closePool };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design goals
 * ────────────
 * • SQL injection prevention — every piece of user-supplied data is passed as
 *   a parameterised value ($1, $2, …) and never interpolated into the SQL
 *   string.  Input validation adds a second line of defence.
 * • Connection pooling — all functions use the shared Pool from db.js, so
 *   clients are borrowed and returned automatically.
 * • Query timing — every query is wrapped in a timer that logs the SQL
 *   label, parameters (safe, no PII in production), and elapsed time.
 * • Structured errors — database errors are wrapped in a QueryError class
 *   that carries an HTTP-appropriate statusCode, letting route handlers stay
 *   clean.
 */

'use strict';

const { pool } = require('./db');

// ─── Constants ──────────────────────────────────────────────────────────────

const MAX_LIMIT = 100;          // hard ceiling to prevent runaway queries
const DEFAULT_LIMIT = 20;
const DEFAULT_OFFSET = 0;
const MAX_SEARCH_LENGTH = 200;  // prevents absurdly long LIKE patterns

const isDev = process.env.NODE_ENV !== 'production';

// ─── Custom error class ─────────────────────────────────────────────────────

/**
 * Wraps a database error with an HTTP status code so that route handlers can
 * respond appropriately without knowing about Postgres internals.
 */
class QueryError extends Error {
  /**
   * @param {string}  message    Human-readable description.
   * @param {number}  statusCode HTTP status code to return to the client.
   * @param {Error}  [cause]     Original error from pg.
   */
  constructor(message, statusCode = 500, cause = null) {
    super(message);
    this.name = 'QueryError';
    this.statusCode = statusCode;
    if (cause) this.cause = cause;
  }
}

// ─── Input validators ────────────────────────────────────────────────────────

/**
 * Validates and coerces a user ID.
 *
 * Accepts a string or number; rejects values that are not positive integers.
 * Using a strict allowlist (digits only) before the parseInt call means a
 * payload like "1; DROP TABLE users--" is rejected outright before it ever
 * reaches the query builder.
 *
 * @param  {string|number} id
 * @returns {number}
 * @throws {QueryError} 400 if invalid
 */
function validateId(id) {
  // Allow only strings that look like positive integers, or actual numbers.
  if (typeof id === 'number') {
    if (!Number.isInteger(id) || id <= 0) {
      throw new QueryError('ID must be a positive integer.', 400);
    }
    return id;
  }

  if (typeof id !== 'string' || !/^\d+$/.test(id.trim())) {
    throw new QueryError('ID must be a positive integer.', 400);
  }

  const parsed = parseInt(id.trim(), 10);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    throw new QueryError('ID must be a positive integer.', 400);
  }
  return parsed;
}

/**
 * Validates and coerces pagination parameters.
 *
 * @param  {string|number} rawLimit
 * @param  {string|number} rawOffset
 * @returns {{ limit: number, offset: number }}
 * @throws {QueryError} 400 if invalid
 */
function validatePagination(rawLimit, rawOffset) {
  const limit  = rawLimit  !== undefined ? parseInt(String(rawLimit),  10) : DEFAULT_LIMIT;
  const offset = rawOffset !== undefined ? parseInt(String(rawOffset), 10) : DEFAULT_OFFSET;

  if (!Number.isInteger(limit)  || limit  < 1)        throw new QueryError('limit must be a positive integer.',               400);
  if (!Number.isInteger(offset) || offset < 0)        throw new QueryError('offset must be a non-negative integer.',          400);
  if (limit > MAX_LIMIT)                              throw new QueryError(`limit must not exceed ${MAX_LIMIT}.`,             400);

  return { limit, offset };
}

/**
 * Validates a search query string.
 *
 * The search term is always passed as a parameterised value — this function
 * only performs allowlist-style length and character checking as a secondary
 * control, and sanitises LIKE wildcards so that a term like "100%" does not
 * accidentally match all rows.
 *
 * @param  {string} query  Raw search term from the request.
 * @returns {string}       Validated, LIKE-escaped search term.
 * @throws {QueryError}    400 if invalid.
 */
function validateAndEscapeSearch(query) {
  if (typeof query !== 'string') {
    throw new QueryError('Search query must be a string.', 400);
  }

  const trimmed = query.trim();

  if (trimmed.length === 0) {
    throw new QueryError('Search query must not be empty.', 400);
  }

  if (trimmed.length > MAX_SEARCH_LENGTH) {
    throw new QueryError(`Search query must not exceed ${MAX_SEARCH_LENGTH} characters.`, 400);
  }

  // Escape LIKE special characters (%, _, \) so the term is treated as a
  // literal substring.  The backslash escape character used here ('\\') is
  // passed as the ESCAPE clause in the SQL, keeping everything parameterised.
  const escaped = trimmed
    .replace(/\\/g, '\\\\')  // must come first
    .replace(/%/g,  '\\%')
    .replace(/_/g,  '\\_');

  return escaped;
}

// ─── Query timing helper ─────────────────────────────────────────────────────

/**
 * Executes a parameterised query against the shared pool, measures its wall-
 * clock duration, and emits a structured timing log.
 *
 * Parameters are NEVER interpolated into the SQL string; they are always
 * forwarded to pg as the second argument to `pool.query()`, so the driver
 * handles escaping and type binding at the protocol level.
 *
 * @param {string}   label    Short human label used in log output.
 * @param {string}   sql      Parameterised SQL string ($1, $2, …).
 * @param {Array}    params   Bound parameter values (never concatenated).
 * @returns {Promise<import('pg').QueryResult>}
 * @throws {QueryError}
 */
async function timedQuery(label, sql, params = []) {
  const start = process.hrtime.bigint();

  try {
    // pool.query() borrows a client, runs the query, and returns it to the
    // pool automatically — no manual client.release() needed.
    const result = await pool.query(sql, params);

    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    // In production, omit the param values to avoid leaking sensitive data
    // into logs.  In development, include them for debugging convenience.
    const logParams = isDev ? params : `[${params.length} param(s) redacted]`;

    console.log(
      `[query] ${label} | rows: ${result.rowCount} | ` +
        `time: ${elapsedMs.toFixed(2)} ms | params: ${JSON.stringify(logParams)}`,
    );

    return result;
  } catch (err) {
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.error(
      `[query] ${label} FAILED | time: ${elapsedMs.toFixed(2)} ms | ` +
        `pg code: ${err.code ?? 'n/a'} | message: ${err.message}`,
    );

    // Map well-known pg error codes to meaningful HTTP responses.
    // Full list: https://www.postgresql.org/docs/current/errcodes-appendix.html
    switch (err.code) {
      case '23505': throw new QueryError('A record with that value already exists.', 409, err);
      case '23503': throw new QueryError('Referenced record does not exist.',        404, err);
      case '42P01': throw new QueryError('Database table not found.',                500, err);
      case '28P01': // invalid_password
      case '28000': throw new QueryError('Database authentication failed.',          503, err);
      case '3D000': throw new QueryError('Database does not exist.',                 503, err);
      case '53300': throw new QueryError('Too many database connections.',           503, err);
      default:      throw new QueryError('An unexpected database error occurred.',   500, err);
    }
  }
}

// ─── Public query functions ──────────────────────────────────────────────────

/**
 * Retrieves a single user by their primary-key ID.
 *
 * SQL injection prevention:
 *   `id` is validated as a positive integer by `validateId()`, then passed
 *   as the parameterised value $1.  The SQL string never contains the raw
 *   user-supplied value.
 *
 * @param   {string|number} id  The user's ID.
 * @returns {Promise<Object|null>}  The user row, or null if not found.
 * @throws  {QueryError}
 *
 * @example
 *   const user = await getUserById(42);
 *   if (!user) return res.status(404).json({ error: 'Not found' });
 */
async function getUserById(id) {
  // Validate and coerce — throws QueryError(400) on bad input.
  const safeId = validateId(id);

  const sql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM   users
    WHERE  id = $1
    LIMIT  1
  `;

  const result = await timedQuery('getUserById', sql, [safeId]);

  return result.rows[0] ?? null;
}

/**
 * Returns a paginated list of all users, ordered by ID ascending.
 *
 * SQL injection prevention:
 *   `limit` and `offset` are validated as non-negative integers and then
 *   passed as parameterised values ($1, $2).  PostgreSQL does not allow
 *   LIMIT/OFFSET to be parameterised in all drivers, but pg does support it
 *   natively so no string interpolation is needed.
 *
 * @param   {string|number} [limit=20]   Max rows to return (1–100).
 * @param   {string|number} [offset=0]   Number of rows to skip.
 * @returns {Promise<{ users: Object[], total: number, limit: number, offset: number }>}
 * @throws  {QueryError}
 *
 * @example
 *   const page = await getAllUsers(10, 20);
 *   res.json(page); // { users: [...], total: 83, limit: 10, offset: 20 }
 */
async function getAllUsers(limit, offset) {
  // Validate — throws QueryError(400) on bad input.
  const { limit: safeLimit, offset: safeOffset } = validatePagination(limit, offset);

  // Run the data query and the count query concurrently to keep latency low.
  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM   users
    ORDER  BY id ASC
    LIMIT  $1
    OFFSET $2
  `;

  const countSql = `SELECT COUNT(*) AS total FROM users`;

  const [dataResult, countResult] = await Promise.all([
    timedQuery('getAllUsers:data',  dataSql,  [safeLimit, safeOffset]),
    timedQuery('getAllUsers:count', countSql, []),
  ]);

  return {
    users:  dataResult.rows,
    total:  parseInt(countResult.rows[0].total, 10),
    limit:  safeLimit,
    offset: safeOffset,
  };
}

/**
 * Full-text search over users' name and email columns.
 *
 * SQL injection prevention (three independent layers):
 *   1. `validateAndEscapeSearch()` rejects empty/overlong strings and escapes
 *      LIKE special characters (\, %, _) so the term is treated as a literal
 *      substring.
 *   2. The escaped term is wrapped in `%…%` in JavaScript, then passed as
 *      the parameterised value $1 — it is never concatenated into the SQL.
 *   3. `LIKE` with a parameterised value and an explicit ESCAPE clause
 *      ensures the database treats the pattern literally.
 *   Pagination inputs are validated by `validatePagination()` as above.
 *
 * @param   {string}        query          Search term.
 * @param   {string|number} [limit=20]     Max rows to return (1–100).
 * @param   {string|number} [offset=0]     Rows to skip.
 * @returns {Promise<{ users: Object[], total: number, query: string, limit: number, offset: number }>}
 * @throws  {QueryError}
 *
 * @example
 *   const results = await searchUsers('alice', 10, 0);
 *   res.json(results);
 */
async function searchUsers(query, limit, offset) {
  // Validate inputs — each throws QueryError(400) on bad data.
  const safeSearch = validateAndEscapeSearch(query);
  const { limit: safeLimit, offset: safeOffset } = validatePagination(limit, offset);

  // Wrap in wildcards for a "contains" LIKE search.
  // This string is still fully parameterised below — no SQL interpolation.
  const likePattern = `%${safeSearch}%`;

  // Case-insensitive search using ILIKE (Postgres extension).
  // $1 is bound for both WHERE clauses; pg sends the value once and the
  // server references it twice — no duplication on the wire.
  const dataSql = `
    SELECT
      id,
      name,
      email,
      created_at,
      updated_at
    FROM   users
    WHERE  name  ILIKE $1 ESCAPE '\\'
       OR  email ILIKE $1 ESCAPE '\\'
    ORDER  BY id ASC
    LIMIT  $2
    OFFSET $3
  `;

  const countSql = `
    SELECT COUNT(*) AS total
    FROM   users
    WHERE  name  ILIKE $1 ESCAPE '\\'
       OR  email ILIKE $1 ESCAPE '\\'
  `;

  const [dataResult, countResult] = await Promise.all([
    timedQuery('searchUsers:data',  dataSql,  [likePattern, safeLimit, safeOffset]),
    timedQuery('searchUsers:count', countSql, [likePattern]),
  ]);

  return {
    users:  dataResult.rows,
    total:  parseInt(countResult.rows[0].total, 10),
    query:  query.trim(),   // return the original (unescaped) term for UX
    limit:  safeLimit,
    offset: safeOffset,
  };
}

// ─── Exports ─────────────────────────────────────────────────────────────────

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
  QueryError,   // exported so route error handlers can do `instanceof QueryError`
};

/**
 * app.js — Express application
 *
 * Wires the /users endpoint to the parameterised query layer in queries.js
 * and the connection pool in db.js.
 *
 * Route overview
 * ──────────────
 *  GET /health                   — liveness probe
 *  GET /users                    — paginated list  (limit, offset)
 *  GET /users/search             — search by name/email (q, limit, offset)
 *  GET /users/:id                — fetch one user by ID
 */

'use strict';

// Load environment variables from .env (if present) before anything else.
// This must come before db.js / queries.js are required so that the pool is
// initialised with the correct DATABASE_URL.
require('dotenv').config();

const express = require('express');
const { closePool } = require('./db');
const { getUserById, getAllUsers, searchUsers, QueryError } = require('./queries');

const app = express();
app.use(express.json());

// ─── Request logging middleware ───────────────────────────────────────────────

app.use((req, _res, next) => {
  console.log(`[http] ${req.method} ${req.path}`);
  next();
});

// ─── Routes ──────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Liveness probe — also reports basic pool stats so infrastructure dashboards
 * can detect connection exhaustion without querying the database.
 */
app.get('/health', (_req, res) => {
  const { pool } = require('./db');
  res.json({
    status:    'ok',
    timestamp: new Date().toISOString(),
    pool: {
      total:   pool.totalCount,
      idle:    pool.idleCount,
      waiting: pool.waitingCount,
    },
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// IMPORTANT: /users/search must be declared BEFORE /users/:id so that Express
// does not try to coerce the literal string "search" into an :id parameter.
// ─────────────────────────────────────────────────────────────────────────────

/**
 * GET /users/search?q=<term>[&limit=20&offset=0]
 *
 * Searches users by name or email using a case-insensitive substring match.
 * The search term and pagination values are validated and passed to
 * searchUsers() as parameterised query arguments — never interpolated.
 *
 * Query parameters:
 *   q      {string}  Required. The search term (1–200 characters).
 *   limit  {number}  Optional. Rows per page, 1–100 (default 20).
 *   offset {number}  Optional. Rows to skip (default 0).
 *
 * Responses:
 *   200 { users, total, query, limit, offset }
 *   400 { error }  — missing/invalid parameters
 *   500 { error }  — database error
 */
app.get('/users/search', async (req, res, next) => {
  const { q, limit, offset } = req.query;

  if (!q) {
    return res.status(400).json({ error: 'Query parameter "q" is required.' });
  }

  try {
    const data = await searchUsers(q, limit, offset);
    return res.json(data);
  } catch (err) {
    return next(err);
  }
});

/**
 * GET /users?[limit=20&offset=0]
 *
 * Returns a paginated list of all users ordered by ID.
 *
 * Query parameters:
 *   limit  {number}  Optional. Rows per page, 1–100 (default 20).
 *   offset {number}  Optional. Rows to skip (default 0).
 *
 * Responses:
 *   200 { users, total, limit, offset }
 *   400 { error }  — invalid pagination values
 *   500 { error }  — database error
 */
app.get('/users', async (req, res, next) => {
  const { limit, offset } = req.query;

  try {
    const data = await getAllUsers(limit, offset);
    return res.json(data);
  } catch (err) {
    return next(err);
  }
});

/**
 * GET /users/:id
 *
 * Returns a single user identified by their integer primary key.
 *
 * Path parameters:
 *   id  {integer}  Required. Must be a positive integer.
 *
 * Responses:
 *   200 { id, name, email, created_at, updated_at }
 *   400 { error }  — id is not a positive integer
 *   404 { error }  — no user with that id
 *   500 { error }  — database error
 */
app.get('/users/:id', async (req, res, next) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({ error: `User with id ${req.params.id} not found.` });
    }

    return res.json(user);
  } catch (err) {
    return next(err);
  }
});

// ─── Centralised error handler ────────────────────────────────────────────────

/**
 * All errors flow here via next(err).  QueryError instances carry an HTTP
 * statusCode; everything else defaults to 500.
 *
 * In production the raw error message is never sent to the client — a generic
 * message is returned instead to avoid leaking internals.
 */
// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  const isDev = process.env.NODE_ENV !== 'production';

  if (err instanceof QueryError) {
    // Validation errors (4xx): safe to surface the message.
    if (err.statusCode < 500) {
      return res.status(err.statusCode).json({ error: err.message });
    }

    // Server-side errors (5xx): log in full, return generic message.
    console.error('[error]', err.message, err.cause ?? '');
    return res.status(err.statusCode).json({
      error: isDev ? err.message : 'An internal server error occurred.',
    });
  }

  // Unexpected non-QueryError (e.g. a bug in a route handler).
  console.error('[error] Unhandled error:', err);
  return res.status(500).json({
    error: isDev ? err.message : 'An internal server error occurred.',
  });
});

// ─── Server startup & graceful shutdown ──────────────────────────────────────

const PORT = parseInt(process.env.PORT ?? '3000', 10);

const server = app.listen(PORT, () => {
  console.log(`[app] Server running on port ${PORT} (${process.env.NODE_ENV ?? 'development'})`);
});

/**
 * Graceful shutdown: stop accepting new connections, wait for in-flight
 * requests to finish, then drain the DB pool.
 */
function shutdown(signal) {
  console.log(`[app] ${signal} received — shutting down gracefully…`);

  server.close(async () => {
    console.log('[app] HTTP server closed.');
    await closePool();
    process.exit(0);
  });

  // Force-exit if shutdown takes longer than 10 s.
  setTimeout(() => {
    console.error('[app] Forced shutdown after timeout.');
    process.exit(1);
  }, 10_000);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

module.exports = app;

/**
 * queries.test.js — Unit tests for the query layer
 *
 * Run with:  node --test queries.test.js   (Node 18+, no extra deps)
 *    or:     npx jest queries.test.js
 *
 * Strategy
 * ────────
 * The pg Pool is mocked so these tests run without a real database.
 * We verify:
 *   • Input validation catches every class of bad input before any SQL is sent.
 *   • Parameterised queries are built correctly (right SQL, right param array).
 *   • LIKE special characters are escaped in the search term.
 *   • Pagination defaults and limits are applied.
 *   • QueryError is thrown (and not raw pg errors) on pool failures.
 */

'use strict';

const assert = require('node:assert/strict');
const { describe, it, before, afterEach } = require('node:test');

// ─── Mock the pool BEFORE requiring queries.js ───────────────────────────────

// Keep a reference to the mock so individual tests can configure it.
let mockQueryFn;

// Intercept the `pg` module so no real connections are opened.
const Module = require('node:module');
const originalLoad = Module._load.bind(Module);

Module._load = function (request, parent, isMain) {
  if (request === './db' || request === '../db') {
    return {
      pool: {
        query:        (...args) => mockQueryFn(...args),
        totalCount:   0,
        idleCount:    0,
        waitingCount: 0,
        on:           () => {},
        end:          async () => {},
      },
      closePool: async () => {},
    };
  }
  return originalLoad(request, parent, isMain);
};

// Now safe to load queries.js with the mock in place.
const { getUserById, getAllUsers, searchUsers, QueryError } = require('./queries');

// ─── Helpers ─────────────────────────────────────────────────────────────────

/** Returns a mock pg result with the given rows. */
function mockResult(rows) {
  return { rows, rowCount: rows.length };
}

// ─── Test suites ──────────────────────────────────────────────────────────────

describe('getUserById', () => {
  it('calls pool.query with the correct SQL and parameterised id', async () => {
    let capturedSql, capturedParams;

    mockQueryFn = (sql, params) => {
      capturedSql    = sql;
      capturedParams = params;
      return Promise.resolve(mockResult([{ id: 1, name: 'Alice', email: 'alice@example.com' }]));
    };

    const user = await getUserById('1');

    assert.equal(user.id, 1);
    assert.equal(user.name, 'Alice');

    // The SQL must use a placeholder, never the raw value.
    assert.match(capturedSql, /\$1/);
    assert.ok(!capturedSql.includes('1'), 'Raw id must not appear in SQL string');

    // The value must be the coerced integer, not the raw string.
    assert.deepEqual(capturedParams, [1]);
  });

  it('returns null when no row is found', async () => {
    mockQueryFn = () => Promise.resolve(mockResult([]));
    const user = await getUserById(99);
    assert.equal(user, null);
  });

  it('throws QueryError(400) for a non-numeric id string', async () => {
    await assert.rejects(
      () => getUserById('abc'),
      (err) => {
        assert.ok(err instanceof QueryError);
        assert.equal(err.statusCode, 400);
        return true;
      },
    );
  });

  it('throws QueryError(400) for a SQL-injection-style string', async () => {
    await assert.rejects(
      () => getUserById("1; DROP TABLE users--"),
      (err) => err instanceof QueryError && err.statusCode === 400,
    );
  });

  it('throws QueryError(400) for a negative id', async () => {
    await assert.rejects(
      () => getUserById(-5),
      (err) => err instanceof QueryError && err.statusCode === 400,
    );
  });

  it('throws QueryError(400) for a float id', async () => {
    await assert.rejects(
      () => getUserById(3.14),
      (err) => err instanceof QueryError && err.statusCode === 400,
    );
  });

  it('throws QueryError(400) for id = 0', async () => {
    await assert.rejects(
      () => getUserById(0),
      (err) => err instanceof QueryError && err.statusCode === 400,
    );
  });

  it('wraps pool errors in a QueryError', async () => {
    const pgError   = Object.assign(new Error('connection refused'), { code: '53300' });
    mockQueryFn = () => Promise.reject(pgError);

    await assert.rejects(
      () => getUserById(1),
      (err) => {
        assert.ok(err instanceof QueryError);
        assert.equal(err.statusCode, 503);  // 53300 → too many connections
        return true;
      },
    );
  });
});

// ─────────────────────────────────────────────────────────────────────────────

describe('getAllUsers', () => {
  before(() => {
    // Default mock: data query + count query
    mockQueryFn = (sql, params) => {
      if (sql.trim().startsWith('SELECT COUNT')) {
        return Promise.resolve(mockResult([{ total: '5' }]));
      }
      return Promise.resolve(mockResult([
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
      ]));
    };
  });

  it('applies default limit and offset when none are supplied', async () => {
    const calls = [];
    mockQueryFn = (sql, params) => {
      calls.push({ sql, params });
      if (sql.trim().startsWith('SELECT COUNT')) return Promise.resolve(mockResult([{ total: '2' }]));
      return Promise.resolve(mockResult([{ id: 1 }]));
    };

    const result = await getAllUsers(undefined, undefined);

    assert.equal(result.limit, 20);
    assert.equal(result.offset, 0);

    const dataCall = calls.find(c => !c.sql.trim().startsWith('SELECT COUNT'));
    assert.deepEqual(dataCall.params, [20, 0]);
  });

  it('passes limit and offset as parameters, not in the SQL string', async () => {
    let capturedParams;
    mockQueryFn = (sql, params) => {
      if (!sql.trim().startsWith('SELECT COUNT')) capturedParams = params;
      return sql.trim().startsWith('SELECT COUNT')
        ? Promise.resolve(mockResult([{ total: '50' }]))
        : Promise.resolve(mockResult([]));
    };

    await getAllUsers(10, 30);

    assert.deepEqual(capturedParams, [10, 30]);
  });

  it('includes total, limit, and offset in the response', async () => {
    mockQueryFn = (sql) =>
      sql.trim().startsWith('SELECT COUNT')
        ? Promise.resolve(mockResult([{ total: '42' }]))
        : Promise.resolve(mockResult([{ id: 1 }]));

    const result = await getAllUsers(5, 10);
    assert.equal(result.total, 42);
    assert.equal(result.limit, 5);
    assert.equal(result.offset, 10);
  });

  it('throws QueryError(400) when limit exceeds 100', async () => {
    await assert.rejects(
      () => getAllUsers(101, 0),
      (err) => err instanceof QueryError && err.statusCode === 400,
    );
  });

  it('throws QueryError(400) for negative offset', async () => {
    await assert.rejects(
      () => getAllUsers(10, -1),
      (err) => err instanceof QueryError && err.statusCode === 400,
    );
  });

  it('throws QueryError(400) for limit = 0', async () => {
    await assert.rejects(
      () => getAllUsers(0, 0),
      (err) => err instanceof QueryError && err.statusCode === 400,
    );
  });
});

// ─────────────────────────────────────────────────────────────────────────────

describe('searchUsers', () => {
  it('passes the search term as a parameterised value, not inline SQL', async () => {
    let capturedDataParams;

    mockQueryFn = (sql, params) => {
      if (!sql.trim().startsWith('SELECT COUNT')) capturedDataParams = params;
      return sql.trim().startsWith('SELECT COUNT')
        ? Promise.resolve(mockResult([{ total: '1' }]))
        : Promise.resolve(mockResult([{ id: 1, name: 'Alice' }]));
    };

    await searchUsers('Alice', 10, 0);

    // The SQL placeholder must appear in the first position.
    assert.equal(capturedDataParams[0], '%Alice%');
    assert.equal(capturedDataParams[1], 10);
    assert.equal(capturedDataParams[2], 0);
  });

  it('escapes LIKE wildcards in the search term', async () => {
    let capturedPattern;

    mockQueryFn = (sql, params) => {
      if (!sql.trim().startsWith('SELECT COUNT')) capturedPattern = params[0];
      return sql.trim().startsWith('SELECT COUNT')
        ? Promise.resolve(mockResult([{ total: '0' }]))
        : Promise.resolve(mockResult([]));
    };

    await searchUsers('100%', 10, 0);
    assert.equal(capturedPattern, '%100\\%%', 'Percent sign must be escaped');

    await searchUsers('user_name', 10, 0);
    assert.equal(capturedPattern, '%user\\_name%', 'Underscore must be escaped');

    await searchUsers('C:\\path', 10, 0);
    assert.equal(capturedPattern, '%C:\\\\path%', 'Backslash must be escaped');
  });

  it('returns the original (unescaped) query in the response', async () => {
    mockQueryFn = (sql) =>
      sql.trim().startsWith('SELECT COUNT')
        ? Promise.resolve(mockResult([{ total: '0' }]))
        : Promise.resolve(mockResult([]));

    const result = await searchUsers('100%', 10, 0);
    assert.equal(result.query, '100%');
  });

  it('throws QueryError(400) for an empty search string', async () => {
    await assert.rejects(
      () => searchUsers(''),
      (err) => err instanceof QueryError && err.statusCode === 400,
    );
  });

  it('throws QueryError(400) for a whitespace-only search string', async () => {
    await assert.rejects(
      () => searchUsers('   '),
      (err) => err instanceof QueryError && err.statusCode === 400,
    );
  });

  it('throws QueryError(400) for a search term that exceeds 200 characters', async () => {
    await assert.rejects(
      () => searchUsers('a'.repeat(201)),
      (err) => err instanceof QueryError && err.statusCode === 400,
    );
  });

  it('throws QueryError(400) when limit exceeds 100', async () => {
    await assert.rejects(
      () => searchUsers('alice', 200),
      (err) => err instanceof QueryError && err.statusCode === 400,
    );
  });
});

// ─────────────────────────────────────────────────────────────────────────────

describe('QueryError', () => {
  it('is an instance of Error', () => {
    const err = new QueryError('oops', 404);
    assert.ok(err instanceof Error);
    assert.ok(err instanceof QueryError);
  });

  it('carries statusCode and name', () => {
    const err = new QueryError('not found', 404);
    assert.equal(err.statusCode, 404);
    assert.equal(err.name, 'QueryError');
  });

  it('optionally stores a cause', () => {
    const cause = new Error('original');
    const err   = new QueryError('wrapper', 500, cause);
    assert.equal(err.cause, cause);
  });
});

