/**
 * db.js — PostgreSQL connection pool
 *
 * Exports a single shared `pg.Pool` instance that is reused across every
 * module that requires this file.  Connection configuration is read
 * exclusively from environment variables so that no credentials ever appear
 * in source code.
 *
 * Environment variables (set these in .env / your deployment secrets):
 *   DATABASE_URL          — full connection string (takes priority)
 *   PGHOST / PGPORT / PGDATABASE / PGUSER / PGPASSWORD — individual fields
 *   DB_POOL_MAX           — maximum pool size            (default: 10)
 *   DB_POOL_IDLE_TIMEOUT  — ms before idle client closes (default: 30 000)
 *   DB_CONNECT_TIMEOUT    — ms before a connection attempt times out (default: 5 000)
 *   NODE_ENV              — set to 'production' to suppress verbose pool logs
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Pool configuration
// ---------------------------------------------------------------------------

const poolConfig = {
  // If DATABASE_URL is set it takes precedence over the individual PG* vars.
  // pg automatically reads PGHOST, PGPORT, PGDATABASE, PGUSER, PGPASSWORD
  // from the environment when connectionString is undefined, so both styles
  // work without any extra code here.
  connectionString: process.env.DATABASE_URL || undefined,

  // Maximum number of clients kept alive in the pool.
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

  // How long (ms) a client is allowed to sit idle before being closed.
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT ?? '30000', 10),

  // How long (ms) to wait for a new connection before throwing.
  connectionTimeoutMillis: parseInt(process.env.DB_CONNECT_TIMEOUT ?? '5000', 10),

  // SSL: require SSL in production unless explicitly disabled.
  ssl:
    process.env.DB_SSL === 'false'
      ? false
      : process.env.NODE_ENV === 'production'
        ? { rejectUnauthorized: true }
        : false,
};

const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// Pool-level event listeners
// ---------------------------------------------------------------------------

const isDev = process.env.NODE_ENV !== 'production';

pool.on('connect', (client) => {
  if (isDev) {
    console.log(
      `[db] New client connected — pool size: ${pool.totalCount} ` +
        `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`,
    );
  }
});

pool.on('acquire', () => {
  if (isDev) {
    console.log(
      `[db] Client acquired — pool size: ${pool.totalCount} ` +
        `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`,
    );
  }
});

pool.on('remove', () => {
  if (isDev) {
    console.log(
      `[db] Client removed — pool size: ${pool.totalCount} ` +
        `(idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`,
    );
  }
});

// A pool error means a background client threw — log it so the process does
// not crash silently.
pool.on('error', (err) => {
  console.error('[db] Unexpected pool error:', err.message);
});

// ---------------------------------------------------------------------------
// Graceful shutdown helper
// ---------------------------------------------------------------------------

/**
 * Drain the pool and release all connections.
 * Call this during SIGTERM / SIGINT handling.
 *
 * @returns {Promise<void>}
 */
async function closePool() {
  console.log('[db] Draining connection pool…');
  await pool.end();
  console.log('[db] Pool drained.');
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------

module.exports = { pool, closePool };

/**
 * queries.js — Parameterised query functions for the /users endpoint
 *
 * Design goals
 * ────────────
 * • SQL injection prevention — every piece of user-supplied data is passed as
 *   a parameterised value ($1, $2, …) and never interpolated into the SQL
 *   string.  Input validation adds a second line of defence.
 * • Connection pooling — all functions use the shared Pool from db.js, so
 *   clients are borrowed and returned automatically.
 * • Query timing — every query is wrapped in a timer that logs the SQL
 *   label, parameters (safe, no PII in production), and elapsed time.
 * • Structured errors — database errors are wrapped in a QueryError class
 *   that carries an HTTP-appropriate statusCode, letting route handlers stay
 *   clean.
 */

'use strict';

const { pool } = require('./db');

// ─── Constants ──────────────────────────────────────────────────────────────

const MAX_LIMIT = 100;          // hard ceiling to prevent runaway queries
const DEFAULT_LIMIT = 20;
const DEFAULT_OFFSET = 0;
const MAX_SEARCH_LENGTH = 200;  // prevents absurdly long LIKE patterns

const isDev = process.env.NODE_ENV !== 'production';

// ─── Custom error class ─────────────────────────────────────────────────────

/**
 * Wraps a database error with an HTTP status code so that route handlers can
 * respond appropriately without knowing about Postgres internals.
 */
class QueryError extends Error {
  /**
   * @param {string}  message    Human-readable description.
   * @param {number}  statusCode HTTP status code to return to the client.
   * @param {Error}  [cause]     Original error from pg.
   */
  constructor(message, statusCode = 500, cause = null) {
    super(message);
    this.name = 'QueryError';
    this.statusCode = statusCode;
    if (cause) this.cause = cause;
  }
}

// ─── Input validators ────────────────────────────────────────────────────────

/**
 * Validates and coerces a user ID.
 *
 * Accepts a string or number; rejects values that are not positive integers.
 * Using a strict allowlist (digits only) before the parseInt call means a
 * payload like "1; DROP TABLE users--" is rejected outright before it ever
 * reaches the query builder.
 *
 * @param  {string|number} id
 * @returns {number}
 * @throws {QueryError} 400 if invalid
 */
function validateId(id) {
  // Allow only strings that look like positive integers, or actual numbers.
  if (typeof id === 'number') {
    if (!Number.isInteger(id) || id <= 0) {
      throw new QueryError('ID must be a positive integer.', 400);
    }
    return id;
  }

  if (typeof id !== 'string' || !/^\d+$/.test(id.trim())) {
    throw new QueryError('ID must be a positive integer.', 400);
  }

  const parsed = parseInt(id.trim(), 10);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    throw new QueryError('ID must be a positive integer.', 400);
  }
  return parsed;
}

/**
 * Validates and coerces pagination parameters.
 *
 * @param  {string|number} rawLimit
 * @param  {string|number} rawOffset
 * @returns {{ limit: number, offset: number }}
 * @throws {QueryError} 400 if invalid
 */
function validatePagination(rawLimit, rawOffset) {
  const limit  = rawLimit  !== undefined ? parseInt(String(rawLimit),  10) : DEFAULT_LIMIT;
  const offset = rawOffset !== undefined ? parseInt(String(rawOffset), 10) : DEFAULT_OFFSET;

  if (!Number.isInteger(limit)  || limit  < 1)        throw new QueryError('limit must be a positive integer.',               400);
  if (!Number.isInteger(offset) || offset < 0)        throw new QueryError('offset must be a non-negative integer.',          400);
  if (limit > MAX_LIMIT)                              throw new QueryError(`limit must not exceed ${MAX_LIMIT}.`,             400);

  return { limit, offset };
}

/**
 * Validates a search query string.
 *
 * The search term is always passed as a parameterised value — this function
 * only performs allowlist-style length and character checking as a secondary
 * control, and sanitises LIKE wildcards so that a term like "100%" does not
 * accidentally match all rows.
 *
 * @param  {string} query  Raw search term from the request.
 * @returns {string}       Validated, LIKE-escaped search term.
 * @throws {QueryError}    400 if invalid.
 */
function validateAndEscapeSearch(query) {
  if (typeof query !== 'string') {
    throw new QueryError('Search query must be a string.', 400);
  }

  const trimmed = query.trim();

  if (trimmed.length === 0) {
    throw new QueryError('Search query must not be empty.', 400);
  }

  if (trimmed.length > MAX_SEARCH_LENGTH) {
    throw new QueryError(`Search query must not exceed ${MAX_SEARCH_LENGTH} characters.`, 400);
  }

  // Escape LIKE special characters (%, _, \) so the term is treated as a
  // literal substring.  The backslash escape character used here ('\\') is
  // passed as the ESCAPE clause in the SQL, keeping everything parameterised.
  const escaped = trimmed
    .replace(/\\/g, '\\\\')  // must come first
    .replace(/%/g,  '\\%')
    .replace(/_/g,  '\\_');

  return escaped;
}

// ─── Query timing helper ─────────────────────────────────────────────────────

/**
 * Executes a parameterised query against the shared pool, measures its wall-
 * clock duration, and emits a structured timing log.
 *
 * Parameters are NEVER interpolated into the SQL string; they are always
 * forwarded to pg as the second argument to `pool.query()`, so the driver
 * handles escaping and type binding at the protocol level.
 *
 * @param {string}   label    Short human label used in log output.
 * @param {string}   sql      Parameterised SQL string ($1, $2, …).
 * @param {Array}    params   Bound parameter values (never concatenated).
 * @returns {Promise<import('pg').QueryResult>}
 * @throws {QueryError}
 */
async function timedQuery(label, sql, params = []) {
  const start = process.hrtime.bigint();

  try {
    // pool.query() borrows a client, runs the query, and returns it to the
    // pool automatically — no manual client.release() needed.
    const result = await pool.query(sql, params);

    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    // In production, omit the param values to avoid leaking sensitive data
    // into logs.  In development, include them for debugging convenience.
    const logParams = isDev ? params : `[${params.length} param(s) redacted]`;

    console.log(
      `[query] ${label} | rows: ${result.rowCount} | ` +
        `time: ${elapsedMs.toFixed(2)} ms | params: ${JSON.stringify(logParams)}`,
    );

    return result;
  } catch (err) {
    const elapsedMs = Number(process.hrtime.bigint() - start) / 1_000_000;

    console.error(
      `[query] ${label} FAILED | time: ${elapsedMs.toFixed(2)} ms | ` +
        `pg code: ${err.code ?? 'n/a'} | message: ${err.message}`,
    );

    // Map well-known pg error codes to meaningful HTTP responses.
    // Full list: https://www.postgresql.org/docs/current/errcodes-appendix.html
    switch (err.code) {
      case '23505': throw new QueryError('A record with that value already exists.', 409, err);
      case '23503': throw new QueryError('Referenced record does not exist.',        404, err);
      case '42P01': throw new QueryError('Database table not found.',                500, err);
      case '28P01': // invalid_password
      case '28000': throw new QueryError('Database authentication failed.',          503, err);
      case '3D000': throw new QueryError('Database does not exist.',                 503, err);
      case '53300': throw new QueryError('Too many database connections.',           503, err);
