 * db/pool.js
 *
 * Creates and exports a single shared pg.Pool instance for the entire
 * application lifetime.  All query modules import this file — they never
 * create their own pools, which is the central rule that prevents connection
 * exhaustion.
 *
 * Configuration is read exclusively from environment variables so that no
 * credentials are ever hard-coded or logged.
 *
 * Environment variables (set via .env or the host OS):
 *   DATABASE_URL          – full connection string (takes priority when set)
 *   PGHOST / PGPORT / PGDATABASE / PGUSER / PGPASSWORD  – individual fields
 *   DB_POOL_MAX           – maximum number of clients (default: 10)
 *   DB_POOL_IDLE_TIMEOUT  – ms before an idle client is closed (default: 30 000)
 *   DB_POOL_CONN_TIMEOUT  – ms to wait for a client before erroring (default: 5 000)
 *   DB_SSL                – set to "true" to enable SSL (required for most
 *                           managed DB services; default: false)
 */

'use strict';

const { Pool } = require('pg');

// ─── Pool configuration ───────────────────────────────────────────────────────

const poolConfig = {
  // pg respects the standard PGHOST / PGPORT / PGDATABASE / PGUSER /
  // PGPASSWORD env vars automatically when connectionString is absent,
  // so we only need to set connectionString when DATABASE_URL is present.
  ...(process.env.DATABASE_URL && { connectionString: process.env.DATABASE_URL }),

  // Pool sizing
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

  // How long (ms) a client may sit idle before being destroyed
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT ?? '30000', 10),

  // How long (ms) pool.connect() will wait before throwing
  connectionTimeoutMillis: parseInt(process.env.DB_POOL_CONN_TIMEOUT ?? '5000', 10),

  // SSL — required for most cloud-hosted Postgres instances
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false,
};

const pool = new Pool(poolConfig);

// ─── Pool-level event listeners ──────────────────────────────────────────────

// Fires every time a new client is created inside the pool.
pool.on('connect', (client) => {
  console.log(
    `[pool] New client connected. ` +
    `Total pool size: ${pool.totalCount}, ` +
    `idle: ${pool.idleCount}, ` +
    `waiting: ${pool.waitingCount}`
