'use strict';

const pool = require('./pool');

// ─── Constants ────────────────────────────────────────────────────────────────

/** Maximum rows getAllUsers() will ever return in a single call. */
const MAX_LIMIT = 100;

/** Default page size when the caller omits `limit`. */
const DEFAULT_LIMIT = 20;

/** Maximum characters accepted in a search query string. */
const MAX_SEARCH_LENGTH = 200;

/**
 * Column names that callers are permitted to sort by.
 * Keeping an explicit allow-list is the only safe way to use a column name
 * inside ORDER BY because parameterised placeholders cannot represent
 * identifiers — only values.
 */
const ALLOWED_SORT_COLUMNS = new Set(['id', 'name', 'email', 'created_at']);

/** Allowed sort directions. */
const ALLOWED_SORT_DIRECTIONS = new Set(['ASC', 'DESC']);

// ─── Timing helper ────────────────────────────────────────────────────────────

/**
 * Logs a structured timing entry to stdout.
 *
 * @param {string} queryName  - Human-readable label (e.g. 'getUserById')
 * @param {bigint} startNs    - Value returned by process.hrtime.bigint() before the query
 * @param {number} rowCount   - Number of rows returned/affected
 */
function logQueryTiming(queryName, startNs, rowCount) {
  const elapsedNs  = process.hrtime.bigint() - startNs;
  const elapsedMs  = Number(elapsedNs) / 1_000_000;

  // Emit a single JSON-parseable line so log aggregators can index it.
  console.log(
    JSON.stringify({
      level:      'info',
      event:      'query_timing',
      query:      queryName,
      durationMs: parseFloat(elapsedMs.toFixed(3)),
      rowCount,
      timestamp:  new Date().toISOString(),
    })
  );
}

// ─── Validation helpers ───────────────────────────────────────────────────────

/**
 * Parses a value as a positive integer.  Throws a TypeError with a
 * descriptive message if the result is not a safe positive integer.
 *
 * @param {*}      value  - Raw input
 * @param {string} name   - Parameter name (used in error messages only)
 * @returns {number}
 */
function parsePositiveInt(value, name) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 1) {
    throw new TypeError(`${name} must be a positive integer, got: ${JSON.stringify(value)}`);
  }
  return n;
}

/**
 * Parses a value as a non-negative integer.
 *
 * @param {*}      value
 * @param {string} name
 * @returns {number}
 */
function parseNonNegativeInt(value, name) {
  const n = Number(value);
  if (!Number.isInteger(n) || n < 0) {
    throw new TypeError(`${name} must be a non-negative integer, got: ${JSON.stringify(value)}`);
  }
  return n;
}

/**
 * Validates a sort column name against the allow-list.
 * Throws a TypeError for any name not in ALLOWED_SORT_COLUMNS.
 *
 * @param {string} column
 * @returns {string}  The validated column name (safe to interpolate into SQL)
 */
function validateSortColumn(column) {
  const col = String(column).toLowerCase();
  if (!ALLOWED_SORT_COLUMNS.has(col)) {
    throw new TypeError(
      `Invalid sort column "${column}". ` +
      `Allowed values: ${[...ALLOWED_SORT_COLUMNS].join(', ')}`
    );
  }
  return col;
}

/**
 * Validates a sort direction string.
 *
 * @param {string} direction
 * @returns {'ASC'|'DESC'}
 */
function validateSortDirection(direction) {
  const dir = String(direction).toUpperCase();
  if (!ALLOWED_SORT_DIRECTIONS.has(dir)) {
    throw new TypeError(`Invalid sort direction "${direction}". Must be ASC or DESC.`);
  }
  return dir;
}

// ─── Query functions ──────────────────────────────────────────────────────────

/**
 * Retrieves a single user row by primary-key ID.
 *
 * @param {number|string} id  - The user's integer primary key.
 * @returns {Promise<object|null>}  The user row, or null if not found.
 * @throws {TypeError}  If `id` is not a positive integer.
 */
async function getUserById(id) {
  const safeId = parsePositiveInt(id, 'id');

  const query = {
    // Static SQL text — the only dynamic part is the $1 placeholder whose
    // value is transmitted out-of-band by the pg wire protocol.
    name: 'get-user-by-id',   // Enables pg's built-in prepared-statement cache
    text: `
      SELECT
        id,
        name,
        email,
        created_at
      FROM users
      WHERE id = $1
      LIMIT 1
    `,
    values: [safeId],
  };

  const startNs = process.hrtime.bigint();
  const result  = await pool.query(query);
  logQueryTiming('getUserById', startNs, result.rowCount);

  return result.rows[0] ?? null;
}

/**
 * Returns a paginated list of all users.
 *
 * @param {number} [limit=DEFAULT_LIMIT]  - Rows per page (1–MAX_LIMIT).
 * @param {number} [offset=0]             - Zero-based row offset.
 * @param {string} [sortBy='id']          - Column to sort by (allow-listed).
 * @param {string} [sortDir='ASC']        - 'ASC' or 'DESC'.
 * @returns {Promise<{ users: object[], total: number, limit: number, offset: number }>}
 * @throws {TypeError}  On invalid pagination / sort parameters.
 */
async function getAllUsers(
  limit   = DEFAULT_LIMIT,
  offset  = 0,
  sortBy  = 'id',
  sortDir = 'ASC'
) {
  // Validate and clamp numeric inputs
  const safeLimit  = Math.min(parsePositiveInt(limit, 'limit'), MAX_LIMIT);
  const safeOffset = parseNonNegativeInt(offset, 'offset');

  // Allow-list check — these are the only values that appear inline in SQL
  const safeColumn = validateSortColumn(sortBy);
  const safeDir    = validateSortDirection(sortDir);

  // ── Main data query ────────────────────────────────────────────────────
  // IMPORTANT: safeColumn and safeDir are interpolated into the SQL text
  // only after passing through the explicit allow-list check above.
  // They are identifiers/keywords — pg parameters cannot represent those.
  const dataQuery = {
    text: `
      SELECT
        id,
        name,
        email,
        created_at
      FROM users
      ORDER BY ${safeColumn} ${safeDir}
      LIMIT  $1
      OFFSET $2
    `,
    values: [safeLimit, safeOffset],
  };

  // ── Count query (for pagination metadata) ─────────────────────────────
  const countQuery = {
    name: 'count-all-users',
    text: `SELECT COUNT(*)::int AS total FROM users`,
    values: [],
  };

  const startNs = process.hrtime.bigint();

  // Run both queries concurrently — they are read-only and independent.
  const [dataResult, countResult] = await Promise.all([
    pool.query(dataQuery),
    pool.query(countQuery),
  ]);

  logQueryTiming('getAllUsers', startNs, dataResult.rowCount);

  return {
    users:  dataResult.rows,
    total:  countResult.rows[0].total,
    limit:  safeLimit,
    offset: safeOffset,
  };
}

/**
 * Full-text search across name and email columns.
 *
 * Uses ILIKE with parameterised placeholders so pg handles quoting.
 * The % wildcards are added in JavaScript (to the value string), never
 * in the SQL text — this is intentional and safe.
 *
 * @param {string} query              - Search term.
 * @param {number} [limit=DEFAULT_LIMIT]
 * @param {number} [offset=0]
 * @returns {Promise<{ users: object[], total: number, limit: number, offset: number, query: string }>}
 * @throws {TypeError}  If `query` is not a non-empty string, or pagination params are invalid.
 */
async function searchUsers(query, limit = DEFAULT_LIMIT, offset = 0) {
  // ── Input validation ───────────────────────────────────────────────────
  if (typeof query !== 'string') {
    throw new TypeError(`search query must be a string, got: ${typeof query}`);
  }

  const trimmedQuery = query.trim();

  if (trimmedQuery.length === 0) {
    throw new TypeError('search query must not be empty after trimming whitespace');
  }

  if (trimmedQuery.length > MAX_SEARCH_LENGTH) {
    throw new TypeError(
      `search query too long (${trimmedQuery.length} chars). ` +
      `Maximum is ${MAX_SEARCH_LENGTH}.`
    );
  }

  const safeLimit  = Math.min(parsePositiveInt(limit, 'limit'), MAX_LIMIT);
  const safeOffset = parseNonNegativeInt(offset, 'offset');

  // The wildcard characters are part of the *value* sent to the driver,
  // not concatenated into the SQL text.  pg transmits $1 out-of-band.
  const searchPattern = `%${trimmedQuery}%`;

  // ── Data query ─────────────────────────────────────────────────────────
  const dataQuery = {
    text: `
      SELECT
        id,
        name,
        email,
        created_at
      FROM users
      WHERE
        name  ILIKE $1
        OR email ILIKE $1
      ORDER BY id ASC
      LIMIT  $2
      OFFSET $3
    `,
    values: [searchPattern, safeLimit, safeOffset],
  };

  // ── Count query ────────────────────────────────────────────────────────
  const countQuery = {
    text: `
      SELECT COUNT(*)::int AS total
      FROM users
      WHERE
        name  ILIKE $1
        OR email ILIKE $1
    `,
    values: [searchPattern],
  };

  const startNs = process.hrtime.bigint();

  const [dataResult, countResult] = await Promise.all([
    pool.query(dataQuery),
    pool.query(countQuery),
  ]);

  logQueryTiming('searchUsers', startNs, dataResult.rowCount);

  return {
    users:  dataResult.rows,
    total:  countResult.rows[0].total,
    limit:  safeLimit,
    offset: safeOffset,
    query:  trimmedQuery,   // Echo back the sanitised term (useful for UI)
  };
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  getUserById,
  getAllUsers,
  searchUsers,
};

/**
 * app.js
 *
 * Entry point for the Users API.
 *
 * /users endpoints
 * ────────────────
 *  GET /users                   → getAllUsers   (supports limit, offset, sortBy, sortDir)
 *  GET /users/search?q=…        → searchUsers   (supports limit, offset)
 *  GET /users/:id               → getUserById
 *
 * The /users/search route is registered *before* /users/:id so that the
 * literal path segment "search" is never misinterpreted as a numeric id.
 *
 * All database interaction is delegated to db/queries.js.
 * This file only handles HTTP parsing, response shaping, and error mapping.
 */

'use strict';

// Load .env (if present) before anything else reads process.env.
// In production, environment variables are injected by the host/orchestrator
// and .env is absent — dotenv silently does nothing in that case.
require('dotenv').config();

const express = require('express');
const { getUserById, getAllUsers, searchUsers } = require('./db/queries');

const app  = express();
const PORT = parseInt(process.env.PORT ?? '3000', 10);

// ─── Middleware ───────────────────────────────────────────────────────────────

app.use(express.json());

// Simple request logger
app.use((req, _res, next) => {
  console.log(
    JSON.stringify({
      level:     'info',
      event:     'http_request',
      method:    req.method,
      path:      req.path,
      query:     req.query,
      timestamp: new Date().toISOString(),
    })
  );
  next();
});

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Converts a TypeError (input validation) into a 400 response and any other
 * error into a 500 response, so we never accidentally leak stack traces.
 */
function handleError(err, res) {
  if (err instanceof TypeError) {
    return res.status(400).json({ error: err.message });
  }

  // Log the full error server-side but return only a generic message to the client.
  console.error(
    JSON.stringify({
      level:     'error',
      event:     'unhandled_query_error',
      message:   err.message,
      timestamp: new Date().toISOString(),
    })
  );

  return res.status(500).json({ error: 'Internal server error' });
}

// ─── Routes ───────────────────────────────────────────────────────────────────

// Health check — no DB involvement so it remains usable even if the DB is down
app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ── GET /users ──────────────────────────────────────────────────────────────
// Query params:
//   limit   {number}  Rows per page   (default: 20, max: 100)
//   offset  {number}  Row offset       (default: 0)
//   sortBy  {string}  Column name      (default: 'id')
//   sortDir {string}  'ASC' or 'DESC'  (default: 'ASC')
app.get('/users', async (req, res) => {
  try {
    const { limit, offset, sortBy, sortDir } = req.query;

    const result = await getAllUsers(
      limit   !== undefined ? limit   : undefined,
      offset  !== undefined ? offset  : undefined,
      sortBy  !== undefined ? sortBy  : undefined,
      sortDir !== undefined ? sortDir : undefined,
    );

    res.json(result);
  } catch (err) {
    handleError(err, res);
  }
});

// ── GET /users/search ────────────────────────────────────────────────────────
// MUST be registered before /users/:id so "search" is not treated as an id.
//
// Query params:
//   q       {string}  Search term (required)
//   limit   {number}  Rows per page  (default: 20, max: 100)
//   offset  {number}  Row offset      (default: 0)
app.get('/users/search', async (req, res) => {
  try {
    const { q, limit, offset } = req.query;

    if (!q) {
      return res.status(400).json({ error: 'Missing required query parameter: q' });
    }

    const result = await searchUsers(
      q,
      limit  !== undefined ? limit  : undefined,
      offset !== undefined ? offset : undefined,
    );

    res.json(result);
  } catch (err) {
    handleError(err, res);
  }
});

// ── GET /users/:id ───────────────────────────────────────────────────────────
app.get('/users/:id', async (req, res) => {
  try {
    const user = await getUserById(req.params.id);

    if (!user) {
      return res.status(404).json({ error: `User with id ${req.params.id} not found` });
    }

    res.json(user);
  } catch (err) {
    handleError(err, res);
  }
});

// ─── 404 catch-all ────────────────────────────────────────────────────────────

app.use((_req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// ─── Start ────────────────────────────────────────────────────────────────────

// Only bind the server when this file is the entry point, not when it is
// require()'d by tests (which set module.parent / import it as a module).
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(
      JSON.stringify({
        level:     'info',
        event:     'server_start',
        port:      PORT,
        timestamp: new Date().toISOString(),
      })
    );
  });
}

module.exports = app;

/**
 * tests/queries.test.js
 *
 * Self-contained unit-test suite for db/queries.js.
 *
 * Uses Node's built-in assert module and a hand-rolled mock for the pg Pool
 * so zero external dependencies are required, and no real database is needed.
 *
 * Run with:
 *   node tests/queries.test.js
 *
 * Exit code 0 = all tests passed.
 * Exit code 1 = at least one failure.
 */

'use strict';

const assert = require('assert/strict');

// ─── Minimal test harness ─────────────────────────────────────────────────────

let passed  = 0;
let failed  = 0;
const failures = [];

async function test(label, fn) {
  try {
    await fn();
    console.log(`  ✓  ${label}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${label}`);
    console.error(`       ${err.message}`);
    failures.push({ label, err });
    failed++;
  }
}

function suite(name) {
  console.log(`\n${name}`);
}

// ─── pg Pool mock ─────────────────────────────────────────────────────────────
//
// We intercept require('pg') before queries.js loads it by placing a fake
// module into require.cache.  This avoids any need for a real database.

/** Tracks every call made to pool.query() during a test. */
const queryCalls = [];

/** Configures what pool.query() returns for the next N calls (FIFO). */
const queryResponses = [];

const mockPool = {
  query(queryObj) {
    queryCalls.push({
      text:   queryObj.text   ?? queryObj,
      values: queryObj.values ?? [],
      name:   queryObj.name,
    });

    const next = queryResponses.shift();
    if (next instanceof Error) return Promise.reject(next);
    return Promise.resolve(next ?? { rows: [], rowCount: 0 });
  },

  on() {},            // pool.on('connect', …) / pool.on('error', …)
  end() {},           // pool.end() during shutdown
  totalCount: 1,
  idleCount:  1,
  waitingCount: 0,
};

/** Reset call recorder and response queue between tests. */
function resetMock() {
  queryCalls.length    = 0;
  queryResponses.length = 0;
}

/** Queue a successful pg result. */
function mockResponse(rows, rowCount) {
  queryResponses.push({ rows, rowCount: rowCount ?? rows.length });
}

/** Queue a pg error. */
function mockError(message) {
  queryResponses.push(new Error(message));
}

// Inject the mock before any require('./db/queries') call resolves pg.
const Module = require('module');
const originalLoad = Module._load;
Module._load = function (request, parent, isMain) {
  if (request === 'pg') {
    return { Pool: function () { return mockPool; } };
  }
  // Stub out dotenv so .env.test is never loaded during tests.
  if (request === 'dotenv') {
    return { config: () => {} };
  }
  return originalLoad.apply(this, arguments);
};

// Now it's safe to load the modules under test.
const { getUserById, getAllUsers, searchUsers } = require('../db/queries');

// ═════════════════════════════════════════════════════════════════════════════
// getUserById
// ═════════════════════════════════════════════════════════════════════════════

suite('getUserById — validation');

await test('rejects a non-numeric id', async () => {
  await assert.rejects(
    () => getUserById('abc'),
    (err) => {
      assert.ok(err instanceof TypeError);
      assert.match(err.message, /id must be a positive integer/);
      return true;
    }
  );
});

await test('rejects id = 0', async () => {
  await assert.rejects(() => getUserById(0), TypeError);
});

await test('rejects negative id', async () => {
  await assert.rejects(() => getUserById(-5), TypeError);
});

await test('rejects float id', async () => {
  await assert.rejects(() => getUserById(1.5), TypeError);
});

await test('accepts a numeric string id', async () => {
  resetMock();
  const row = { id: 7, name: 'Carol', email: 'carol@example.com', created_at: null };
  mockResponse([row], 1);

  const result = await getUserById('7');
  assert.deepEqual(result, row);
});

suite('getUserById — SQL correctness');

await test('sends exactly one parameterised query', async () => {
  resetMock();
  mockResponse([{ id: 1, name: 'Alice', email: 'alice@example.com', created_at: null }], 1);

  await getUserById(1);

  assert.equal(queryCalls.length, 1);
});

await test('passes id as the sole parameter — never in SQL text', async () => {
  resetMock();
  mockResponse([{ id: 42, name: 'Dave', email: 'dave@example.com', created_at: null }], 1);

  await getUserById(42);

  const call = queryCalls[0];
  assert.deepEqual(call.values, [42]);
  // The SQL text must contain $1 but not the literal number
  assert.match(call.text, /\$1/);
  assert.doesNotMatch(call.text, /42/);
});

await test('returns null when the user is not found', async () => {
  resetMock();
  mockResponse([], 0);

  const result = await getUserById(99);
  assert.equal(result, null);
});

await test('uses a named prepared statement for caching', async () => {
  resetMock();
  mockResponse([{ id: 1, name: 'Alice', email: 'alice@example.com', created_at: null }], 1);

  await getUserById(1);

  assert.ok(queryCalls[0].name, 'expected a named prepared statement');
});

await test('propagates database errors', async () => {
  resetMock();
  mockError('connection refused');

  await assert.rejects(
    () => getUserById(1),
    (err) => {
      assert.match(err.message, /connection refused/);
      return true;
    }
  );
});

