suite('getAllUsers — validation');

await test('rejects limit = 0', async () => {
  await assert.rejects(() => getAllUsers(0), TypeError);
});

await test('rejects negative limit', async () => {
  await assert.rejects(() => getAllUsers(-1), TypeError);
});

await test('rejects negative offset', async () => {
  await assert.rejects(() => getAllUsers(10, -1), TypeError);
});

await test('rejects a non-allow-listed sortBy column', async () => {
  await assert.rejects(
    () => getAllUsers(10, 0, 'password'),
    (err) => {
      assert.ok(err instanceof TypeError);
      assert.match(err.message, /Invalid sort column/);
      return true;
    }
  );
});

await test('rejects SQL-injection-style column names', async () => {
  const injectionAttempts = [
    '1; DROP TABLE users --',
    'id OR 1=1',
    'UNION SELECT * FROM secrets',
    '; DELETE FROM users',
  ];

  for (const attempt of injectionAttempts) {
    await assert.rejects(
      () => getAllUsers(10, 0, attempt),
      TypeError,
      `Expected TypeError for: ${attempt}`
    );
  }
});

await test('rejects invalid sortDir values', async () => {
  await assert.rejects(
    () => getAllUsers(10, 0, 'id', 'SIDEWAYS'),
    (err) => {
      assert.ok(err instanceof TypeError);
      assert.match(err.message, /Invalid sort direction/);
      return true;
    }
  );
});

await test('clamps limit to MAX_LIMIT (100)', async () => {
  resetMock();
  mockResponse([], 0);   // data query
  mockResponse([{ total: 0 }], 1);  // count query

  const result = await getAllUsers(999);
  assert.equal(result.limit, 100);
});

suite('getAllUsers — SQL correctness');

await test('issues exactly two concurrent queries (data + count)', async () => {
  resetMock();
  const rows = [
    { id: 1, name: 'Alice', email: 'alice@example.com', created_at: null },
    { id: 2, name: 'Bob',   email: 'bob@example.com',   created_at: null },
  ];
  mockResponse(rows, 2);         // data query response
  mockResponse([{ total: 2 }], 1); // count query response

  await getAllUsers(20, 0);

  assert.equal(queryCalls.length, 2);
});

await test('passes limit and offset as parameterised values', async () => {
  resetMock();
  mockResponse([], 0);
  mockResponse([{ total: 0 }], 1);

  await getAllUsers(15, 30);

  const dataCall = queryCalls[0];
  assert.deepEqual(dataCall.values, [15, 30]);
  assert.doesNotMatch(dataCall.text, /15/);
  assert.doesNotMatch(dataCall.text, /30/);
});

await test('allow-listed sortBy/sortDir appear in SQL text, not as parameters', async () => {
  resetMock();
  mockResponse([], 0);
  mockResponse([{ total: 0 }], 1);

  await getAllUsers(10, 0, 'name', 'DESC');

  const dataCall = queryCalls[0];
  // The column and direction are embedded in the SQL (they are identifiers)
  assert.match(dataCall.text, /name/i);
  assert.match(dataCall.text, /DESC/i);
  // But they are NOT in the values array
  assert.ok(
    !dataCall.values.includes('name') && !dataCall.values.includes('DESC'),
    'sort column/direction should not be in the values array'
  );
});

await test('returns pagination metadata', async () => {
  resetMock();
  const rows = [{ id: 1, name: 'Alice', email: 'alice@example.com', created_at: null }];
  mockResponse(rows, 1);
  mockResponse([{ total: 50 }], 1);

  const result = await getAllUsers(10, 5);

  assert.equal(result.total,  50);
  assert.equal(result.limit,  10);
  assert.equal(result.offset,  5);
  assert.equal(result.users.length, 1);
});

