suite('searchUsers — validation');

await test('rejects a missing / empty query string', async () => {
  await assert.rejects(() => searchUsers(''), TypeError);
});

await test('rejects a whitespace-only query string', async () => {
  await assert.rejects(() => searchUsers('   '), TypeError);
});

await test('rejects a non-string query', async () => {
  await assert.rejects(() => searchUsers(42), TypeError);
