const originalLoad = Module._load;
Module._load = function (request, parent, isMain) {
  if (request === 'pg') {
    return { Pool: function () { return mockPool; } };
  }
  // Stub out dotenv so .env.test is never loaded during tests.
  if (request === 'dotenv') {
    return { config: () => {} };
