/**
 * db/pool.js
 *
 * Creates and exports a single shared pg.Pool instance for the entire
 * application lifetime.  All query modules import this file — they never
 * create their own pools, which is the central rule that prevents connection
 * exhaustion.
 *
 * Configuration is read exclusively from environment variables so that no
 * credentials are ever hard-coded or logged.
 *
 * Environment variables (set via .env or the host OS):
 *   DATABASE_URL          – full connection string (takes priority when set)
 *   PGHOST / PGPORT / PGDATABASE / PGUSER / PGPASSWORD  – individual fields
 *   DB_POOL_MAX           – maximum number of clients (default: 10)
 *   DB_POOL_IDLE_TIMEOUT  – ms before an idle client is closed (default: 30 000)
 *   DB_POOL_CONN_TIMEOUT  – ms to wait for a client before erroring (default: 5 000)
 *   DB_SSL                – set to "true" to enable SSL (required for most
 *                           managed DB services; default: false)
 */

'use strict';

const { Pool } = require('pg');

// ─── Pool configuration ───────────────────────────────────────────────────────

const poolConfig = {
  // pg respects the standard PGHOST / PGPORT / PGDATABASE / PGUSER /
  // PGPASSWORD env vars automatically when connectionString is absent,
  // so we only need to set connectionString when DATABASE_URL is present.
  ...(process.env.DATABASE_URL && { connectionString: process.env.DATABASE_URL }),

  // Pool sizing
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

  // How long (ms) a client may sit idle before being destroyed
  idleTimeoutMillis: parseInt(process.env.DB_POOL_IDLE_TIMEOUT ?? '30000', 10),

  // How long (ms) pool.connect() will wait before throwing
  connectionTimeoutMillis: parseInt(process.env.DB_POOL_CONN_TIMEOUT ?? '5000', 10),

  // SSL — required for most cloud-hosted Postgres instances
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false,
};

const pool = new Pool(poolConfig);

// ─── Pool-level event listeners ──────────────────────────────────────────────

// Fires every time a new client is created inside the pool.
pool.on('connect', (client) => {
  console.log(
    `[pool] New client connected. ` +
    `Total pool size: ${pool.totalCount}, ` +
    `idle: ${pool.idleCount}, ` +
    `waiting: ${pool.waitingCount}`
  );

  // Set a per-session application name visible in pg_stat_activity.
  // This helps DBAs identify traffic from this service without leaking
  // any sensitive config.
  client.query("SET application_name = 'users-api'").catch(() => {});
});

// Fires when a client experiences an unexpected error while sitting idle.
// Without this handler Node would crash with an unhandled-error event.
pool.on('error', (err) => {
  console.error('[pool] Unexpected idle-client error:', err.message);
});

// ─── Graceful shutdown ────────────────────────────────────────────────────────

/**
 * Drain the pool cleanly when the process exits so that in-flight queries
 * can complete and connections are closed properly server-side.
 */
async function shutdown() {
  try {
    await pool.end();
    console.log('[pool] All clients released. Pool closed.');
  } catch (err) {
    console.error('[pool] Error while closing pool:', err.message);
  }
}

process.once('SIGINT',  shutdown);
process.once('SIGTERM', shutdown);

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = pool;

/**
 * db/queries.js
 *
 * Parameterised query functions for the /users resource.
 *
 * Every public function:
 *   1. Validates and sanitises its inputs before touching the database.
 *   2. Uses pg's parameterised query syntax ($1, $2, …) so the driver
 *      handles all escaping — no string concatenation near SQL.
 *   3. Measures wall-clock execution time with process.hrtime.bigint()
 *      and emits a structured timing log entry.
 *   4. Returns plain objects; HTTP-layer concerns stay in app.js.
 *
 * ┌─────────────────────────────────────────────────────────────────────┐
 * │  SQL-injection prevention strategy (defence-in-depth)               │
 * │                                                                     │
 * │  Layer 1 – Parameterised queries                                    │
 * │    All dynamic values are passed as the `values` array to           │
 * │    pool.query({ text, values }).  The pg driver sends them as       │
 * │    separate wire-protocol parameters, never interpolated into the   │
 * │    SQL text.                                                        │
 * │                                                                     │
 * │  Layer 2 – Input validation before query execution                  │
 * │    IDs are coerced to integers and rejected if NaN.                 │
 * │    limit/offset are clamped to safe numeric ranges.                 │
 * │    Search queries are trimmed and length-bounded.                   │
 * │    Sort column names are checked against an explicit allow-list     │
 * │    (the only place an identifier must appear inline in SQL).        │
 * │                                                                     │
 * │  Layer 3 – No dynamic SQL construction                              │
 * │    SQL text strings are static template literals; values are never  │
 * │    concatenated into them.                                          │
 * └─────────────────────────────────────────────────────────────────────┘
 */

'use strict';

const pool = require('./pool');

// ─── Constants ────────────────────────────────────────────────────────────────

/** Maximum rows getAllUsers() will ever return in a single call. */
const MAX_LIMIT = 100;

/** Default page size when the caller omits `limit`. */
const DEFAULT_LIMIT = 20;

/** Maximum characters accepted in a search query string. */
const MAX_SEARCH_LENGTH = 200;

/**
 * Column names that callers are permitted to sort by.
 * Keeping an explicit allow-list is the only safe way to use a column name
 * inside ORDER BY because parameterised placeholders cannot represent
 * identifiers — only values.
 */
const ALLOWED_SORT_COLUMNS = new Set(['id', 'name', 'email', 'created_at']);

/** Allowed sort directions. */
const ALLOWED_SORT_DIRECTIONS = new Set(['ASC', 'DESC']);

// ─── Timing helper ────────────────────────────────────────────────────────────

/**
 * Logs a structured timing entry to stdout.
 *
 * @param {string} queryName  - Human-readable label (e.g. 'getUserById')
 * @param {bigint} startNs    - Value returned by process.hrtime.bigint() before the query
 * @param {number} rowCount   - Number of rows returned/affected
 */
function logQueryTiming(queryName, startNs, rowCount) {
  const elapsedNs  = process.hrtime.bigint() - startNs;
  const elapsedMs  = Number(elapsedNs) / 1_000_000;

  // Emit a single JSON-parseable line so log aggregators can index it.
  console.log(
    JSON.stringify({
      level:      'info',
      event:      'query_timing',
      query:      queryName,
      durationMs: parseFloat(elapsedMs.toFixed(3)),
      rowCount,
      timestamp:  new Date().toISOString(),
    })
