  }
  return col;
}

/**
 * Validates a sort direction string.
 *
 * @param {string} direction
 * @returns {'ASC'|'DESC'}
 */
function validateSortDirection(direction) {
  const dir = String(direction).toUpperCase();
  if (!ALLOWED_SORT_DIRECTIONS.has(dir)) {
    throw new TypeError(`Invalid sort direction "${direction}". Must be ASC or DESC.`);
  }
  return dir;
}

// ─── Query functions ──────────────────────────────────────────────────────────

/**
 * Retrieves a single user row by primary-key ID.
 *
 * @param {number|string} id  - The user's integer primary key.
 * @returns {Promise<object|null>}  The user row, or null if not found.
 * @throws {TypeError}  If `id` is not a positive integer.
