    // value is transmitted out-of-band by the pg wire protocol.
    name: 'get-user-by-id',   // Enables pg's built-in prepared-statement cache
    text: `
      SELECT
        id,
        name,
        email,
        created_at
      FROM users
      WHERE id = $1
      LIMIT 1
