'use strict';

// Load .env (if present) before anything else reads process.env.
// In production, environment variables are injected by the host/orchestrator
// and .env is absent — dotenv silently does nothing in that case.
require('dotenv').config();

const express = require('express');
const { getUserById, getAllUsers, searchUsers } = require('./db/queries');

const app  = express();
const PORT = parseInt(process.env.PORT ?? '3000', 10);

// ─── Middleware ───────────────────────────────────────────────────────────────

app.use(express.json());

// Simple request logger
app.use((req, _res, next) => {
  console.log(
    JSON.stringify({
      level:     'info',
      event:     'http_request',
      method:    req.method,
      path:      req.path,
      query:     req.query,
      timestamp: new Date().toISOString(),
    })
