// Tests are *registered* synchronously then *executed* sequentially inside
// the async main() runner at the bottom — this avoids top-level await while
// still keeping each test body async.

const registeredTests = [];   // [{ kind:'suite'|'test', label, fn }]

function suite(name)      { registeredTests.push({ kind: 'suite', label: name }); }
function test(label, fn)  { registeredTests.push({ kind: 'test',  label, fn  }); }

// ─── pg Pool mock ─────────────────────────────────────────────────────────────
//
// We intercept require('pg') before queries.js loads it so no real DB is needed.

/** Tracks every call made to pool.query() during a test. */
const queryCalls = [];

/** Configures what pool.query() returns for the next N calls (FIFO). */
const queryResponses = [];

const mockPool = {
  query(queryObj) {
    queryCalls.push({
      text:   queryObj.text   ?? queryObj,
      values: queryObj.values ?? [],
      name:   queryObj.name,
    });
    const next = queryResponses.shift();
    if (next instanceof Error) return Promise.reject(next);
    return Promise.resolve(next ?? { rows: [], rowCount: 0 });
  },
  on()  {},
  end() {},
  totalCount:   1,
  idleCount:    1,
  waitingCount: 0,
};

function resetMock() {
  queryCalls.length     = 0;
  queryResponses.length = 0;
}

function mockResponse(rows, rowCount) {
  queryResponses.push({ rows, rowCount: rowCount ?? rows.length });
}

function mockError(message) {
  queryResponses.push(new Error(message));
}

