// ═════════════════════════════════════════════════════════════════════════════

// ── getUserById ───────────────────────────────────────────────────────────────

suite('getUserById — validation');

test('rejects a non-numeric id', async () => {
  await assert.rejects(
    () => getUserById('abc'),
    (err) => { assert.ok(err instanceof TypeError); assert.match(err.message, /id must be a positive integer/); return true; }
  );
});

test('rejects id = 0', async () => {
  await assert.rejects(() => getUserById(0), TypeError);
});

test('rejects negative id', async () => {
  await assert.rejects(() => getUserById(-5), TypeError);
});

test('rejects float id', async () => {
  await assert.rejects(() => getUserById(1.5), TypeError);
});

test('accepts a numeric string id ("7")', async () => {
  resetMock();
  const row = { id: 7, name: 'Carol', email: 'carol@example.com', created_at: null };
  mockResponse([row], 1);
  const result = await getUserById('7');
  assert.deepEqual(result, row);
