  resetMock();
  mockResponse([{ id: 42, name: 'Dave', email: 'dave@example.com', created_at: null }], 1);
  await getUserById(42);
  const call = queryCalls[0];
  assert.deepEqual(call.values, [42]);
  assert.match(call.text, /\$1/);
  assert.doesNotMatch(call.text, /42/);
